function abCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDE6DA';
  const viva = t.vivid || '#D3222A';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('abwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.72;-webkit-font-smoothing:antialiased}
${s('abwrap')} *{box-sizing:border-box}
${s('abin')}{max-width:${fp.container || '1140px'};margin:0 auto;padding:0 26px;width:100%}
${s('abwrap')} h1,${s('abwrap')} h2,${s('abwrap')} h3,${s('abwrap')} h4{font-family:var(--fd);
  font-weight:400;letter-spacing:-.008em;line-height:1.1;margin:0}
${s('abwrap')} a{color:inherit;text-decoration:none}
${s('abwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho de uma linha: marca a esquerda, navegacao a direita ---------- */
${s('abtop')}{background:var(--paper);border-bottom:1px solid var(--ink)}
${s('abbar')}{display:flex;align-items:center;gap:26px;padding-block:20px 18px;flex-wrap:wrap}
${s('abmarca')}{display:inline-flex;align-items:baseline;gap:10px;font-family:var(--fd);
  font-weight:400;font-size:clamp(27px,3.4vw,38px);letter-spacing:-.018em;color:var(--ink);
  flex:none;margin-right:auto}
${s('abmarca')} svg{display:block;height:.78em;width:auto;flex:none;align-self:center}
${s('abnav')}{display:flex;gap:19px;align-items:center;flex-wrap:wrap}
${s('abnav')} a{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.04em;color:var(--ink);padding-bottom:3px;border-bottom:2px solid transparent}
${s('abnav')} a:hover{color:var(--viva);border-bottom-color:var(--viva)}
${s('abbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:12px;font-weight:600;letter-spacing:.05em;
  color:var(--paper);background:var(--ink);padding:9px 15px;min-height:40px}
${s('abbusca')}:hover{background:var(--viva)}
${s('abham')}{display:none;width:46px;height:46px;border:1px solid var(--ink);background:none;
  cursor:pointer;position:relative;padding:0}
${s('abham')} i,${s('abham')}::before,${s('abham')}::after{content:"";position:absolute;left:12px;
  right:12px;height:1.5px;background:var(--ink)}
${s('abham')}::before{top:15px}${s('abham')} i{top:22px}${s('abham')}::after{top:29px}

/* ---------- tarja de legenda: a assinatura do arquetipo ---------- */
${s('abfoto')}{display:block;border:1px solid var(--line);background:var(--surf);padding:7px}
${s('abfoto')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '3/2'};overflow:hidden;
  background:var(--ph)}
${s('abfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .55s ease}
${s('abtarja')}{display:flex;align-items:baseline;gap:9px;padding:8px 1px 1px;
  font-family:var(--fb);font-size:10.5px;font-weight:600;letter-spacing:${fp.kickerLs || '.1em'};color:var(--muted)}
${s('abtarja')} b{color:var(--viva);font-weight:700}
${s('abtarja')} span{margin-left:auto;letter-spacing:.06em}

/* ---------- abertura: texto a esquerda, prova a direita ---------- */
${s('ababre')}{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.06fr);
  gap:44px;align-items:center;padding:46px 0 40px;border-bottom:1px solid var(--line)}
${s('ababre')} h2{font-size:clamp(33px,4.4vw,53px);line-height:1.02;letter-spacing:-.02em}
${s('ababre')} h2 a:hover{color:var(--viva)}
${s('ababre')} p{color:var(--dek);font-size:17.5px;margin:17px 0 0;max-width:46ch}
${s('abkick')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.1em'};color:var(--viva);
  margin-bottom:14px}
${s('abkick')} a{color:inherit}
${s('abmm')}{margin-top:19px;font-family:var(--fb);font-size:12.5px;color:var(--muted);
  display:flex;gap:9px;align-items:center;flex-wrap:wrap}
${s('abmm')} b{color:var(--ink);font-weight:700}

/* ---------- secoes ---------- */
${s('absec')}{padding:36px 0 40px;border-bottom:1px solid var(--line)}
${s('absec')}:last-of-type{border-bottom:0}
${s('absh')}{display:flex;align-items:baseline;gap:14px;margin-bottom:24px}
${s('absh')} h2,${s('absh')} h1{font-family:var(--fb);font-size:13px;font-weight:700;
  letter-spacing:.14em;flex:none;color:var(--ink);order:1}
/* o filete e um ::after, que e sempre o ultimo filho: sem a propriedade order
   ele cairia depois do "ver tudo" e o link ficaria colado no titulo.
   Sem crase neste comentario: o CSS mora num template literal e a crase o fecha */
${s('absh')}::after{content:"";flex:1;height:1px;background:var(--ink);align-self:center;order:2}
${s('absh')} .more{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.06em;color:var(--muted);flex:none;order:3}
${s('absh')} .more:hover{color:var(--viva)}
${s('absh1')} h1{font-family:var(--fd);font-weight:400;font-size:clamp(28px,3.4vw,40px);
  letter-spacing:-.018em;text-transform:none}

${s('abdup')}{display:grid;grid-template-columns:minmax(0,1.32fr) minmax(0,1fr);gap:34px}
${s('abbig')}{display:block}
${s('abbig')}:hover ${s('abfoto')} [data-f] img{transform:scale(1.035)}
${s('abbig')} h3{font-size:27px;line-height:1.12;letter-spacing:-.014em;margin-top:14px}
${s('abbig')}:hover h3{color:var(--viva)}
${s('abbig')} p{color:var(--dek);font-size:15.5px;margin:9px 0 0;max-width:52ch}

${s('ablista')}{display:flex;flex-direction:column}
${s('abcard')}{display:grid;grid-template-columns:88px minmax(0,1fr);gap:15px;
  padding:15px 0;border-top:1px solid var(--line);align-items:start}
${s('abcard')}:first-child{border-top:0;padding-top:0}
${s('abcard')} [data-f]{display:block;aspect-ratio:1/1;overflow:hidden;background:var(--ph);
  border:1px solid var(--line)}
${s('abcard')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('abcard')} h3{font-size:16px;line-height:1.28;letter-spacing:-.004em}
${s('abcard')}:hover h3{color:var(--viva)}
${s('abcard')} em{display:block;font-family:var(--fb);font-style:normal;font-size:10.5px;
  font-weight:700;letter-spacing:.09em;color:var(--viva);margin-bottom:5px}
${s('abcard')} time{display:block;font-family:var(--fb);font-size:11.5px;color:var(--muted);margin-top:6px}

${s('abgrade')}{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px}
${s('abg2')}{grid-template-columns:repeat(2,minmax(0,1fr))}
${s('abg3')}{grid-template-columns:repeat(3,minmax(0,1fr))}
${s('abg4')}{grid-template-columns:repeat(4,minmax(0,1fr))}
${s('abg')}{display:block}
${s('abg')}:hover ${s('abfoto')} [data-f] img{transform:scale(1.035)}
${s('abg')} h2,${s('abg')} h3{font-size:18.5px;line-height:1.22;letter-spacing:-.008em;margin-top:12px}
${s('abg')}:hover h2,${s('abg')}:hover h3{color:var(--viva)}

/* ---------- artigo ---------- */
${s('abart')}{padding:36px 0 8px}
${s('abcol')}{max-width:${fp.medida || '720px'}}
${s('abwrap')} nav[aria-label="Trilha de navegação"]{font-family:var(--fb);font-size:12px;
  color:var(--muted);margin-bottom:18px;letter-spacing:.01em}
${s('abwrap')} nav[aria-label="Trilha de navegação"] a:hover{color:var(--viva)}
${s('abart')} h1{font-size:clamp(32px,4.2vw,48px);line-height:1.04;letter-spacing:-.02em;
  margin-bottom:16px}
${s('abdek')}{font-size:19.5px;line-height:1.55;color:var(--dek);margin:0 0 20px;max-width:58ch}
${s('abcapa')}{display:block;border:1px solid var(--line);background:var(--surf);padding:8px;
  margin:24px 0 0;max-width:${fp.medidaLarga || '860px'}}
${s('abcapa')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden;
  background:var(--ph)}
${s('abcapa')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('ableg')}{font-family:var(--fb);font-size:12px;color:var(--muted);margin:9px 0 30px;
  max-width:60ch;letter-spacing:.01em}

${s('abbody')}{font-size:${fp.corpoFs || '18.5px'};line-height:1.8;max-width:${fp.medida || '720px'}}
${s('abbody')} p{margin:0 0 24px}
${s('abbody')} h2{font-size:26px;margin:44px 0 16px;padding-top:15px;
  border-top:1px solid var(--ink);letter-spacing:-.012em}
${s('abbody')} h3{font-size:21px;margin:32px 0 12px}
${s('abbody')} a{color:var(--viva);text-decoration:underline;text-decoration-thickness:1px;
  text-underline-offset:2.5px}
${s('abbody')} a:hover{background:var(--wash)}
${s('abbody')} ul,${s('abbody')} ol{margin:0 0 24px;padding-left:22px}
${s('abbody')} li{margin-bottom:9px}
${s('abbody')} img{margin:24px 0;border:1px solid var(--line);padding:7px;background:var(--surf)}
${s('abbody')} blockquote{margin:28px 0;padding:2px 0 2px 22px;border-left:2px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.34;color:var(--ink)}
${s('abbody')} figure{margin:24px 0}
${s('abbody')} figcaption{font-family:var(--fb);font-size:12px;color:var(--muted);margin-top:8px}

${s('abbody')} table{width:100%;border-collapse:collapse;margin:26px 0;font-size:15.5px}
${s('abbody')} table caption{font-family:var(--fb);font-size:12px;color:var(--muted);
  text-align:left;margin-bottom:10px}
${s('abbody')} table th,${s('abbody')} table td{border:0;border-bottom:1px solid var(--line);
  padding:12px 14px 12px 0;text-align:left;vertical-align:top;background:transparent}
${s('abbody')} table thead th{font-family:var(--fb);font-size:11px;letter-spacing:.08em;color:var(--ink);border-bottom:1px solid var(--ink)}

${s('abveja')}{margin:32px 0;padding:20px 22px;border:1px solid var(--line);background:var(--surf)}
${s('abveja')} h2{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.14em;margin:0 0 12px;padding:0;border:0;color:var(--viva)}

${s('abass')}{display:grid;grid-template-columns:76px minmax(0,1fr);gap:18px;margin:38px 0 0;
  padding:20px;border-top:1px solid var(--ink);border-bottom:1px solid var(--line);
  max-width:${fp.medida || '720px'}}
${s('abass')} img{width:76px;height:76px;object-fit:cover;border:1px solid var(--line)}
${s('abass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.1em;color:var(--viva);margin-bottom:5px}
${s('abass')} .nm{font-family:var(--fd);font-weight:400;font-size:22px;letter-spacing:-.012em}
${s('abass')} p{margin:7px 0 0;font-size:14.5px;color:var(--dek);line-height:1.56}
${s('abass')} .go{display:inline-block;margin-top:11px;font-family:var(--fb);font-size:11.5px;
  font-weight:600;letter-spacing:.06em;color:var(--viva)}
${s('abass')} .go:hover{color:var(--ink)}

/* relacionados na mesma largura da coluna do artigo */
${s('abrel')}{padding:38px 0 8px;max-width:${fp.medida || '720px'}}
${s('abrel')} ${s('abgrade')}{gap:22px}

/* ---------- rodape ---------- */
${s('abfoot')}{background:${t.footerBg || '#191713'};color:${t.footerTx || '#A79C8C'};
  margin-top:54px;padding:48px 0 26px;font-family:var(--fb);font-size:14.5px}
${s('abfoot')} a{color:${t.footerTx || '#A79C8C'}}
${s('abfoot')} a:hover{color:#fff}
${s('abcols')}{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr) minmax(0,1fr);
  gap:36px;padding-bottom:28px;border-bottom:1px solid rgba(255,255,255,.13)}
${s('abfb')}{display:inline-flex;align-items:baseline;gap:10px;font-family:var(--fd);
  font-weight:400;font-size:27px;letter-spacing:-.018em;color:#fff}
${s('abfb')} svg{display:block;height:.78em;width:auto;flex:none;align-self:center}
${s('abfh')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.14em;color:#fff;margin-bottom:14px}
${s('abflist')}{display:flex;flex-direction:column;gap:9px;align-items:flex-start}
${s('abfim')}{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;
  padding-top:20px;font-size:12.5px;color:rgba(255,255,255,.45)}

${s('reveal')}{opacity:1}
@media(prefers-reduced-motion:reduce){${s('abwrap')} *{transition:none!important}}

/* ---------- tablet ---------- */
@media(max-width:1100px){
  ${s('ababre')}{grid-template-columns:1fr;gap:30px}
  ${s('abdup')}{grid-template-columns:1fr;gap:28px}
  ${s('abgrade')},${s('abg3')},${s('abg4')}{grid-template-columns:repeat(2,minmax(0,1fr))}
  ${s('abbusca')}{display:none}
  ${s('abnav')}{display:none;order:3;width:100%;flex-direction:column;gap:0;
    align-items:stretch;padding-bottom:8px}
  ${s('abnav')}[data-aberto="1"]{display:flex}
  ${s('abnav')} a{padding:14px 2px;border-bottom:1px solid var(--line);border-top:0}
  ${s('abham')}{display:block}
  ${s('abbar')}{padding-block:16px 12px}
}

/* ---------- celular ---------- */
@media(max-width:760px){
  ${s('ababre')}{padding:30px 0 28px;gap:26px}
  ${s('ababre')} h2{font-size:clamp(29px,7.8vw,38px)}
  ${s('abgrade')},${s('abg2')},${s('abg3')},${s('abg4')}{grid-template-columns:1fr;gap:26px}
  ${s('abcols')}{grid-template-columns:1fr;gap:28px}
  ${s('absec')}{padding:26px 0 30px}
  ${s('abbody')}{font-size:17.5px}
  ${s('abass')}{grid-template-columns:1fr}
  ${s('abass')} img{width:70px;height:70px}
  ${s('abcard')}{grid-template-columns:74px minmax(0,1fr)}
}

/* ---------- tabela vira cartao, com o rotulo da coluna acima do valor ---------- */
@media(max-width:640px){
  ${s('abbody')} table{min-width:0}
  ${s('abbody')} table caption{display:none}
  ${s('abbody')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('abbody')} table,${s('abbody')} table tbody,${s('abbody')} table tr,
  ${s('abbody')} table th,${s('abbody')} table td{display:block;width:auto}
  ${s('abbody')} table tbody tr{background:var(--surf);border:1px solid var(--line);
    padding:2px 18px 16px;margin-bottom:14px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('abbody')} table tbody th,${s('abbody')} table tbody td{border:0;background:transparent;padding:0}
  ${s('abbody')} table tbody th{border-bottom:1px solid var(--line);padding:15px 0 12px;
    font-family:var(--fd);font-weight:400;font-size:18px;text-transform:none;
    letter-spacing:0;color:var(--ink)}
  ${s('abbody')} table tbody td{padding:14px 0 0;text-align:left;line-height:1.5}
  ${s('abbody')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}`;
}

/* Simbolo geometrico, sem letra dentro: o quadro de uma prova de contato, com a
 * marca de enquadramento no canto. O nome vem como texto na fonte de titulo. */
const AB_SIMB = `<svg viewBox="0 0 30 30" role="img" aria-hidden="true" focusable="false"><rect x="1" y="1" width="28" height="28" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2"/><rect x="7" y="7" width="16" height="16" fill="var(--marca-2,currentColor)"/><rect x="12" y="12" width="6" height="6" fill="var(--marca-3,#fff)"/></svg>`;

const AB_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function abHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'abnav-' + (site.slug || 'p');
  // link de editoria por H.curl: montado a mao ele quebra quando ha categoryBase
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('abtop')}">
<div class="${c('abin')} ${c('abbar')}">
<a class="${c('abmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--ink);--marca-2:var(--viva);--marca-3:var(--paper)">${AB_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('abnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('abham')}" type="button" data-abham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('abbusca')}" href="/busca/">${AB_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-abham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function abFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('abfoot')}"><div class="${c('abin')}">
<div class="${c('abcols')}">
  <div><a class="${c('abfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva);--marca-3:#191713">${AB_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('abfh')}">Editorias</div><div class="${c('abflist')}">${cats}</div></div>
  <div><div class="${c('abfh')}">A revista</div><div class="${c('abflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('abfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A prova de contato: moldura fina, imagem dentro e tarja de legenda abaixo.
 * O `span` do retrato tem display:block, senao o aspect-ratio nao aplica e a
 * imagem passa por cima do titulo. */
function abProva(ctx, a, eager) {
  const { c, H } = ctx;
  return `<span class="${c('abfoto')}">
<span data-f>${H.pic(a, !!eager)}</span>
<span class="${c('abtarja')}"><b>${H.cat(a)}</b><span>${H.esc(H.dateShort(a.date))}</span></span>
</span>`;
}

/* O nivel de titulo vem de quem chama: h3 sob um h2 de secao na home, h2 na lista
 * de editoria, onde o titulo da pagina e h1. */
function abGrid(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('abg')} ${c('reveal')}" href="${H.url(a)}">
${abProva(ctx, a, eager)}
<h${n}>${H.esc(a.title)}</h${n}></a>`;
}

function abCard(ctx, a) {
  const { c, H } = ctx;
  return `<a class="${c('abcard')}" href="${H.url(a)}">
<span data-f>${H.pic(a, false)}</span>
<div><em>${H.cat(a)}</em><h3>${H.esc(a.title)}</h3>
<time datetime="${H.esc(a.date)}">${H.esc(H.dateShort(a.date))}</time></div></a>`;
}

function abHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre, ...resto] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('ababre')}">
<div><span class="${c('abkick')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 200))}</p>` : ''}
<div class="${c('abmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}">${abProva(ctx, abre, true)}</a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const topo = `<div class="${c('absh')}"><h2>${H.esc(nome)}</h2>
<a class="more" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>`;
      let corpo;
      if (v.length >= 5) {
        // destaque mais quatro compactos: consome exatamente 5, sem sobra
        const [d, ...r] = v;
        corpo = `<div class="${c('abdup')}">
<a class="${c('abbig')} ${c('reveal')}" href="${H.url(d)}">
${abProva(ctx, d, false)}
<h3>${H.esc(d.title)}</h3>
${d.dek ? `<p>${H.esc(H.clip(d.dek, 140))}</p>` : ''}</a>
<div class="${c('ablista')}">${r.slice(0, 4).map(a => abCard(ctx, a)).join('')}</div>
</div>`;
      } else {
        // 2, 3 ou 4 itens: a grade recebe exatamente esse numero de colunas e a
        // ultima linha fecha, sem buraco ao lado do ultimo cartao
        const n = v.length;
        corpo = `<div class="${c('abgrade')} ${c('abg' + n)}">
${v.slice(0, n).map(a => abGrid(ctx, a, false)).join('')}</div>`;
      }
      return `<section class="${c('absec')}">${topo}${corpo}</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${abHeader(ctx, menu)}
<main class="${c('abwrap')}"><div class="${c('abin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${abFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. Inventar `bio` ou `editorias` nao da erro em lugar
 * nenhum, so nao gera nada. */
function abAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('abass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="76" height="76" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

function abArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema. Nao ha helper para calcular isso na arquitetura.
  const rel = (related && related.length) ? `<section class="${c('abrel')}">
<div class="${c('absh')}"><h2>Leia também</h2></div>
<div class="${c('abgrade')} ${c('abg' + Math.min(related.length, 3))}">${related.slice(0, 3).map(a =>
    abGrid(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${abHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('abwrap')}"><div class="${c('abin')}">
<article class="${c('abart')}">
<div class="${c('abcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('abkick')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('abdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('abcapa')}"><span data-f>${H.pic(art, true)}</span></span>
<p class="${c('ableg')}">${H.esc(art.image && art.image.alt ? art.image.alt : art.title)}</p>` : ''}
<div class="${c('abbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${abAssinatura(ctx, art)}
${rel}
</div></main>
${abFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function abList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  return `${H.head(ctx, meta)}
${abHeader(ctx, menu)}
<main class="${c('abwrap')}"><div class="${c('abin')}">
<section class="${c('absec')}">
<div class="${c('absh')} ${c('absh1')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('abdek')}" style="max-width:66ch;margin-top:-10px">${H.esc(opts.desc)}</p>` : ''}
<div class="${c('abgrade')}">${itens.map((a, i) => abGrid(ctx, a, i === 0, 2)).join('')}</div>
</section>
</div></main>
${abFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AC, arquetipo ALMANAQUE. Feita para o curiosododia.com.br.
 *
 * ## De onde vem o desenho
 *
 * O nome promete uma curiosidade por dia, e o acervo preservado e de almanaque
 * mesmo: games, dicas, entretenimento, casa, curiosidades. O desenho pega esse
 * gesto: **entrada numerada**. Cada materia entra numa linha com o numero na
 * margem, editoria e data logo abaixo dele, miniatura no meio e o texto a
 * direita, do jeito que um almanaque lista verbete.
 *
 * ## O que a diferencia das 28 vizinhas da opengravity
 *
 *   - **linha numerada em vez de grade de cartoes.** Nenhuma vizinha lista por
 *     linha com numero na margem: a `AB` usa tarja de legenda, a `AA` bloco de
 *     cor, a `Z` faixa dupla, e as antigas usam grade. Aqui a home inteira,
 *     a editoria e o "leia tambem" sao a mesma linha numerada
 *   - **Petrona e Figtree**: nenhum portal da rede usa qualquer uma das duas
 *   - **indigo e magenta**: as vizinhas ja ocupam grafite, marinho, esmeralda,
 *     violeta claro, ocre, vinho, cobalto, terracota, petroleo, carmim, lima,
 *     turquesa, azul-ferrugem, azul-royal e sepia
 *   - **simbolo de marcador de pagina**, e nao quadro, pagina ou barra
 *   - **filete acima da linha**, e nao sombra nem cartao com borda: a pagina le
 *     como pauta de almanaque
 *
 * ## Por que linha e nao grade
 *
 * Grade de N colunas tem dois defeitos que ja custaram tempo na rede: a ultima
 * linha fica com buraco quando o numero de itens nao fecha, e a grade de duas
 * colunas preenchida por linha faz a data pular para quem le de cima para baixo.
 * A linha numerada nao tem nenhum dos dois: a ordem e sempre vertical e a
 * ultima entrada nunca deixa vao.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)`, nunca montado a mao
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` da linha tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e a linha dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento
 *     principal: cabecalho e rodape sao irmaos dele e nao enxergariam
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo, que zera
 *     o `padding-inline` do contentor e cola a marca na borda do celular
 *   - o cabecalho de secao usa `order`, senao o filete cai depois do "ver tudo"
 *   - nenhuma crase dentro de comentario do CSS: o CSS mora num template
 *     literal e a crase o fecha, derrubando o archs.js inteiro
 */

function acCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EAE4F2';
  const viva = t.vivid || '#CF2E7A';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('acwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.7;-webkit-font-smoothing:antialiased}
${s('acwrap')} *{box-sizing:border-box}
${s('acin')}{max-width:${fp.container || '1120px'};margin:0 auto;padding:0 24px;width:100%}
${s('acwrap')} h1,${s('acwrap')} h2,${s('acwrap')} h3,${s('acwrap')} h4{font-family:var(--fd);
  font-weight:600;letter-spacing:-.012em;line-height:1.14;margin:0}
${s('acwrap')} a{color:inherit;text-decoration:none}
${s('acwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: marca a esquerda, navegacao a direita, filete grosso ---------- */
${s('actop')}{background:var(--paper);border-bottom:3px solid var(--ink)}
${s('acbar')}{display:flex;align-items:center;gap:20px;padding-block:18px 16px;flex-wrap:wrap}
${s('acmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:800;font-size:clamp(25px,3.2vw,33px);letter-spacing:-.022em;color:var(--ink);
  flex:none}
${s('acmarca')} svg{display:block;height:.9em;width:auto;flex:none;align-self:center}
/* a navegacao e quem estica, e nao a marca: com margin-right auto na marca o
   botao de busca era empurrado para uma segunda linha assim que a lista de
   editorias crescia. Aqui ela ocupa a folga e encolhe antes de quebrar.
   Sem crase neste comentario: o CSS mora num template literal */
${s('acnav')}{display:flex;gap:15px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('acnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.04em;color:var(--ink);padding-bottom:3px;
  border-bottom:2px solid transparent;transition:border-color .2s ease}
${s('acnav')} a:hover{border-bottom-color:var(--viva)}
${s('acbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:12.5px;font-weight:600;letter-spacing:.045em;
  background:var(--ink);color:var(--paper);padding:9px 15px;flex:none}
${s('acham')}{display:none;width:46px;height:46px;border:2px solid var(--ink);background:none;
  cursor:pointer;padding:0;position:relative}
${s('acham')} i,${s('acham')} i::before,${s('acham')} i::after{position:absolute;left:11px;
  width:20px;height:2px;background:var(--ink);content:"";transition:transform .2s ease}
${s('acham')} i{top:21px}
${s('acham')} i::before{top:-6px;left:0}
${s('acham')} i::after{top:6px;left:0}
@media(max-width:1100px){
  ${s('acham')}{display:block;order:2}
  ${s('acbusca')}{order:3}
  ${s('acnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('acnav')}[data-aberto="1"]{display:flex}
  ${s('acnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('acabre')}{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:center;
  padding-block:38px 34px;border-bottom:3px solid var(--ink)}
${s('acabre')} h2{font-size:clamp(31px,4.3vw,50px);letter-spacing:-.026em;line-height:1.06;
  margin:11px 0 0;font-weight:800}
${s('acabre')} p{font-size:17.5px;line-height:1.62;color:var(--dek);margin:15px 0 0;
  max-width:46ch;text-align:left}
${s('acmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:17px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted);letter-spacing:.02em}
${s('acmm')} b{color:var(--ink);font-weight:600}
@media(max-width:820px){${s('acabre')}{grid-template-columns:1fr;gap:22px}}

/* ---------- cabecalho de secao: numero, nome, filete, ver tudo ---------- */
${s('acsec')}{padding-block:34px 8px}
${s('acsh')}{display:flex;align-items:baseline;gap:15px;margin-bottom:4px}
${s('acsh')} h2,${s('acsh')} h1{font-size:clamp(20px,2.5vw,27px);font-weight:800;
  letter-spacing:-.014em;order:1;flex:none}
/* o filete e um ::after e por isso e sempre o ultimo filho. Sem a propriedade
   order ele cairia depois do "ver tudo" e o link ficaria colado no titulo */
${s('acsh')}::after{content:"";flex:1;height:3px;background:var(--ink);align-self:center;order:2}
${s('acsh')} .more{order:3;flex:none;font-family:var(--fb);font-size:11.5px;font-weight:700;
  letter-spacing:.09em;color:var(--viva)}
${s('acsh')} .more:hover{text-decoration:underline}
${s('acsh1')} h1{font-size:clamp(26px,3.6vw,38px)}

/* ---------- a linha numerada, que e a assinatura desta arquitetura ---------- */
${s('aclinhas')}{display:block}
${s('aclinha')}{display:grid;grid-template-columns:46px 168px 1fr;gap:20px;align-items:start;
  padding-block:20px;border-top:1px solid var(--line)}
${s('aclinha')}:first-child{border-top:2px solid var(--ink)}
${s('aclinha')}:hover ${s('acti')}{color:var(--viva)}
${s('acnum')}{display:block;font-family:var(--fd);font-size:31px;font-weight:800;line-height:1;
  color:var(--viva);font-variant-numeric:tabular-nums;letter-spacing:-.03em}
/* editoria e data ficam na coluna do texto, e nao ao lado do numero: numa
   coluna de 46px uma palavra como "Entretenimento" quebra em tres pedacos e a
   linha inteira fica ilegivel */
${s('acmeta')}{display:block;margin:0 0 6px;font-family:var(--fb);font-size:10.5px;
  font-weight:700;letter-spacing:${fp.kickerLs || '.12em'};
  color:var(--muted);line-height:1.4}
${s('acmeta')} b{color:var(--viva);font-weight:700}
${s('acfoto')}{display:block;position:relative;overflow:hidden;background:var(--ph)}
${s('acfoto')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '16/10'};overflow:hidden}
${s('acfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;
  transition:transform .45s ease}
${s('aclinha')}:hover ${s('acfoto')} [data-f] img{transform:scale(1.045)}
${s('acti')}{display:block;font-family:var(--fd);font-weight:600;font-size:21px;line-height:1.2;
  letter-spacing:-.012em;color:var(--ink);margin:0;transition:color .2s ease}
${s('acdd')}{display:block;margin:9px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);
  max-width:62ch;text-align:left}
${s('acsel')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--viva)}
@media(max-width:760px){
  ${s('aclinha')}{grid-template-columns:30px 96px 1fr;gap:12px;padding-block:15px}
  ${s('acnum')}{font-size:19px}
  ${s('acmeta')}{font-size:9.5px;margin-bottom:4px}
  ${s('acti')}{font-size:16.5px}
  ${s('acdd')}{display:none}
}

/* ---------- chapeu, artigo, coluna medida ---------- */
${s('ackick')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--viva)}
${s('acart')}{padding-block:30px 8px}
${s('accol')}{max-width:${fp.medida || '700px'}}
${s('acart')} h1{font-size:clamp(29px,4.1vw,45px);font-weight:800;letter-spacing:-.026em;
  line-height:1.07;margin:12px 0 0}
${s('acdek')}{font-size:19px;line-height:1.56;color:var(--dek);margin:15px 0 0;
  max-width:58ch;text-align:left}
${s('accapa')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '840px'}}
${s('accapa')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/10'};overflow:hidden}
${s('accapa')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('acleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '840px'};line-height:1.5;text-align:left}
${s('acbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:28px}
${s('acbody')} p{margin:0 0 1.16em;text-align:left}
${s('acbody')} h2{font-size:26px;font-weight:800;letter-spacing:-.016em;margin:1.7em 0 .5em;
  padding-top:.5em;border-top:3px solid var(--ink)}
${s('acbody')} h3{font-size:20.5px;font-weight:600;margin:1.5em 0 .4em;color:var(--pri)}
${s('acbody')} ul,${s('acbody')} ol{margin:0 0 1.16em;padding-left:1.25em;text-align:left}
${s('acbody')} li{margin:0 0 .45em}
${s('acbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('acbody')} a:hover{color:var(--viva)}
${s('acbody')} img{margin:1.5em 0;background:var(--ph)}
${s('acbody')} blockquote{margin:1.5em 0;padding:2px 0 2px 20px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:21px;line-height:1.42;color:var(--ink)}
${s('acbody')} figure{margin:1.5em 0}
${s('acbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('acbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('acbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('acbody')} th,${s('acbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('acbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--ink)}
@media(max-width:640px){
  ${s('acbody')} table{min-width:0}
  ${s('acbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('acbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('acbody')} table,${s('acbody')} tbody,${s('acbody')} tr,${s('acbody')} th,
  ${s('acbody')} td{display:block;width:auto}
  ${s('acbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    padding:2px 18px 16px;margin-bottom:13px}
  ${s('acbody')} tbody th,${s('acbody')} tbody td{border:0;background:transparent}
  ${s('acbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:16px;
    font-family:var(--fd);font-weight:600;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('acbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('acbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('acass')}{display:grid;grid-template-columns:76px minmax(0,1fr);gap:17px;align-items:start;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;border-top:3px solid var(--ink)}
${s('acass')} img{width:76px;height:76px;object-fit:cover;background:var(--ph)}
${s('acass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--viva)}
${s('acass')} .nm{display:block;font-family:var(--fd);font-size:21px;font-weight:800;
  letter-spacing:-.014em;margin-top:3px}
${s('acass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('acass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('acass')} .go:hover{text-decoration:underline}
${s('acrel')}{max-width:${fp.medida || '700px'};padding-block:30px 10px}

/* ---------- rodape ---------- */
${s('acfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:46px;padding-block:44px 26px}
${s('accols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('acfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:800;font-size:26px;letter-spacing:-.022em;color:#fff}
${s('acfb')} svg{display:block;height:.9em;width:auto;flex:none;align-self:center}
${s('acfoot')} p{color:${t.footerTx || '#A9A2BA'};text-align:left}
${s('acfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.13em;color:${t.footerTx || '#A9A2BA'};margin-bottom:13px}
${s('acflist')}{display:flex;flex-direction:column;gap:9px}
${s('acflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('acflist')} a:hover{opacity:1;color:var(--viva)}
${s('acfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;color:${t.footerTx || '#A9A2BA'}}
@media(max-width:820px){
  ${s('accols')}{grid-template-columns:1fr;gap:26px}
  ${s('acfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Marcador de pagina, o gesto de almanaque: a fita que guarda o verbete do dia.
 * Sem letra dentro, porque o nome vem como texto na fonte de titulo ao lado. */
const AC_SIMB = `<svg viewBox="0 0 22 30" role="img" aria-hidden="true" focusable="false"><path d="M1 1h20v28l-10-7-10 7Z" fill="var(--marca-2,currentColor)"/><path d="M1 1h20v28l-10-7-10 7Z" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2"/><rect x="8" y="7" width="6" height="6" fill="var(--marca-3,#fff)"/></svg>`;

const AC_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function acHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'acnav-' + (site.slug || 'p');
  // link de editoria por H.curl: montado a mao ele quebra quando ha categoryBase
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('actop')}">
<div class="${c('acin')} ${c('acbar')}">
<a class="${c('acmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--ink);--marca-2:var(--viva);--marca-3:var(--paper)">${AC_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('acnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('acham')}" type="button" data-acham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('acbusca')}" href="/busca/">${AC_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-acham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function acFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('acfoot')}"><div class="${c('acin')}">
<div class="${c('accols')}">
  <div><a class="${c('acfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva);--marca-3:var(--ink)">${AC_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('acfh')}">Editorias</div><div class="${c('acflist')}">${cats}</div></div>
  <div><div class="${c('acfh')}">O almanaque</div><div class="${c('acflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('acfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A entrada numerada. O `span` do retrato tem display:block, senao o
 * aspect-ratio nao aplica e a imagem passa por cima do titulo.
 * O nivel do titulo vem de quem chama: h3 sob um h2 de secao na home, h2 na
 * lista de editoria, onde o titulo da pagina e h1. */
function acLinha(ctx, a, n, eager, nivel) {
  const { c, H } = ctx;
  const nv = nivel || 3;
  const num = String(n).padStart(2, '0');
  return `<a class="${c('aclinha')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('acnum')}">${num}</span>
<span class="${c('acfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('acmeta')}"><b>${H.cat(a)}</b> &middot; ${H.esc(H.dateShort(a.date))}</span>
<h${nv} class="${c('acti')}">${H.esc(a.title)}</h${nv}>
${a.dek ? `<span class="${c('acdd')}">${H.esc(H.clip(a.dek, 165))}</span>` : ''}</span>
</a>`;
}

function acHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('acabre')}">
<div><span class="${c('ackick')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 210))}</p>` : ''}
<div class="${c('acmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('acfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const topo = `<div class="${c('acsh')}"><h2>${H.esc(nome)}</h2>
<a class="more" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>`;
      // a lista nunca deixa vao na ultima linha, porque nao e grade
      const corpo = `<div class="${c('aclinhas')}">${v.slice(0, 5)
        .map((a, i) => acLinha(ctx, a, i + 1, false)).join('')}</div>`;
      return `<section class="${c('acsec')}">${topo}${corpo}</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${acHeader(ctx, menu)}
<main class="${c('acwrap')}"><div class="${c('acin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${acFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. Inventar `bio` ou `editorias` nao da erro em lugar
 * nenhum, so nao gera nada. */
function acAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('acass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="76" height="76" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

function acArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema. Nao ha helper para calcular isso na arquitetura.
  const rel = (related && related.length) ? `<section class="${c('acrel')}">
<div class="${c('acsh')}"><h2>Leia também</h2></div>
<div class="${c('aclinhas')}">${related.slice(0, 3)
    .map((a, i) => acLinha(ctx, a, i + 1, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${acHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('acwrap')}"><div class="${c('acin')}">
<article class="${c('acart')}">
<div class="${c('accol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('ackick')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('acdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('accapa')}"><span data-f>${H.pic(art, true)}</span></span>
<p class="${c('acleg')}">${H.esc(art.image && art.image.alt ? art.image.alt : art.title)}</p>` : ''}
<div class="${c('acbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${acAssinatura(ctx, art)}
${rel}
</div></main>
${acFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function acList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  return `${H.head(ctx, meta)}
${acHeader(ctx, menu)}
<main class="${c('acwrap')}"><div class="${c('acin')}">
<section class="${c('acsec')}">
<div class="${c('acsh')} ${c('acsh1')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('acdek')}" style="max-width:66ch;margin-top:2px">${H.esc(opts.desc)}</p>` : ''}
<div class="${c('aclinhas')}">${itens
    .map((a, i) => acLinha(ctx, a, i + 1, i === 0, 2)).join('')}</div>
</section>
</div></main>
${acFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AD, arquetipo ESTANTE. Feita para o ebookcult.com.br.
 *
 * ## De onde vem o desenho
 *
 * O nome e de livro, e o acervo preservado e de revista geral: dicas,
 * entretenimento, marketing, jogos. O desenho pega o **gesto** do nome, e nao o
 * assunto: capa em **retrato**, lado a lado, como lombada e capa numa estante.
 *
 * ## O que a diferencia das 29 vizinhas da opengravity
 *
 *   - **capa em retrato, 3 por 4.** Todas as vizinhas usam 16 por 9, 16 por 10
 *     ou 3 por 2. Uma parede de capas verticais nao se confunde com nenhuma
 *     delas nem de longe, e e o unico traco que se le antes de qualquer texto
 *   - **Lora e Mulish**: nenhum portal da rede usa qualquer uma das duas
 *   - **verde de encadernacao com latao**: as vizinhas ja ocupam grafite,
 *     marinho, esmeralda, violeta, ocre, vinho, cobalto, terracota, petroleo,
 *     carmim, lima, turquesa, azul-ferrugem, azul-royal, sepia e indigo
 *   - **chapeu de editoria dentro da capa**, no rodape da imagem, e nao acima do
 *     titulo nem em tarja separada
 *   - **cabecalho sem filete de largura inteira**: o filete acompanha so a
 *     largura do conteudo, e a navegacao se separa por divisor vertical
 *
 * ## Uma armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal tem `categoryBase`.** O arquivo de editoria mora em
 * `/categoria/<slug>/`, e nao em `/<slug>/`. Montar o link na mao com
 * `/${slug}/` derruba **o menu do topo inteiro, o menu do rodape e o chapeu de
 * cada artigo**, tudo em 404, e nao aparece em print nenhum porque o menu fica
 * bonito e so quebra no clique. Por isso todo link de editoria aqui sai de
 * `H.curl(slug)`, sem excecao.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)`, nunca montado a mao
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a secao da home consome exatamente o numero de itens da grade, entao a
 *     ultima linha nunca fica com buraco
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento
 *     principal: cabecalho e rodape sao irmaos dele e nao enxergariam
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - o cabecalho de secao usa a propriedade order, senao o filete cai depois do
 *     "ver tudo"
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS: o CSS
 *     mora num template literal, a crase o fecha e a chave interpola de verdade
 */

function adCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#E8E4D6';
  const viva = t.vivid || '#C9A227';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('adwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.72;-webkit-font-smoothing:antialiased}
${s('adwrap')} *{box-sizing:border-box}
${s('adin')}{max-width:${fp.container || '1160px'};margin:0 auto;padding:0 24px;width:100%}
${s('adwrap')} h1,${s('adwrap')} h2,${s('adwrap')} h3,${s('adwrap')} h4{font-family:var(--fd);
  font-weight:600;letter-spacing:-.006em;line-height:1.18;margin:0}
${s('adwrap')} a{color:inherit;text-decoration:none}
${s('adwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: filete so na largura do conteudo, nav com divisor ---------- */
${s('adtop')}{background:var(--paper)}
${s('adbar')}{display:flex;align-items:center;gap:22px;padding-block:20px 17px;
  flex-wrap:wrap;border-bottom:2px solid var(--ink)}
${s('admarca')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:700;font-size:clamp(24px,3.1vw,32px);letter-spacing:-.014em;color:var(--ink);
  flex:none}
${s('admarca')} svg{display:block;height:.96em;width:auto;flex:none;align-self:center}
${s('adnav')}{display:flex;align-items:center;flex-wrap:wrap;flex:1 1 auto;min-width:0;
  justify-content:flex-end;gap:0}
${s('adnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:700;letter-spacing:.05em;color:var(--ink);padding:2px 13px;border-left:1px solid var(--line)}
${s('adnav')} a:first-child{border-left:0}
${s('adnav')} a:hover{color:var(--pri)}
${s('adbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.05em;
  border:2px solid var(--ink);color:var(--ink);padding:8px 14px;flex:none;margin-left:16px}
${s('adbusca')}:hover{background:var(--ink);color:var(--paper)}
${s('adham')}{display:none;width:46px;height:46px;border:2px solid var(--ink);background:none;
  cursor:pointer;padding:0;position:relative}
${s('adham')} i,${s('adham')} i::before,${s('adham')} i::after{position:absolute;left:11px;
  width:20px;height:2px;background:var(--ink);content:""}
${s('adham')} i{top:21px}
${s('adham')} i::before{top:-6px;left:0}
${s('adham')} i::after{top:6px;left:0}
@media(max-width:1100px){
  ${s('adham')}{display:block;order:2}
  ${s('adbusca')}{order:3;margin-left:0}
  ${s('adnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    border-top:1px solid var(--line);margin-top:15px}
  ${s('adnav')}[data-aberto="1"]{display:flex}
  ${s('adnav')} a{width:100%;padding:13px 0;border-left:0;border-bottom:1px solid var(--line)}
}

/* ---------- a capa em retrato, que e a assinatura desta arquitetura ---------- */
${s('adcapa')}{display:block;position:relative;overflow:hidden;background:var(--ph)}
${s('adcapa')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '3/4'};overflow:hidden}
${s('adcapa')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('adcapa')} b{position:absolute;left:0;bottom:0;font-family:var(--fb);font-size:10px;
  font-weight:700;letter-spacing:${fp.kickerLs || '.11em'};
  background:var(--ink);color:var(--paper);padding:6px 11px}
${s('adlivro')}:hover ${s('adcapa')} [data-f] img{transform:scale(1.05)}
${s('adlivro')}{display:block}
${s('adti')}{display:block;font-family:var(--fd);font-weight:600;font-size:18px;line-height:1.28;
  color:var(--ink);margin:13px 0 0;transition:color .2s ease}
${s('adlivro')}:hover ${s('adti')}{color:var(--pri)}
${s('addt')}{display:block;font-family:var(--fb);font-size:11.5px;color:var(--muted);
  margin-top:7px;letter-spacing:.02em}

/* a estante: 4 colunas, e a secao da home consome exatamente 4, entao a ultima
   linha nunca fica com buraco */
${s('adestante')}{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px 22px}
${s('adg2')}{grid-template-columns:repeat(2,minmax(0,1fr))}
${s('adg3')}{grid-template-columns:repeat(3,minmax(0,1fr))}
@media(max-width:980px){${s('adestante')}{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:680px){
  ${s('adestante')}{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 16px}
  ${s('adti')}{font-size:15.5px;margin-top:10px}
}

/* ---------- chamada de abertura: texto a esquerda, capa a direita ---------- */
${s('adabre')}{display:grid;grid-template-columns:1.35fr .65fr;gap:38px;align-items:center;
  padding-block:40px 36px;border-bottom:1px solid var(--line)}
${s('adabre')} h2{font-size:clamp(30px,4.2vw,48px);letter-spacing:-.018em;line-height:1.1;
  margin:12px 0 0;font-weight:700}
${s('adabre')} p{font-size:17.5px;line-height:1.65;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('admm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:18px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('admm')} b{color:var(--ink);font-weight:700}
@media(max-width:820px){${s('adabre')}{grid-template-columns:1fr;gap:24px}}

/* ---------- cabecalho de secao ---------- */
${s('adsec')}{padding-block:36px 6px}
${s('adsh')}{display:flex;align-items:baseline;gap:16px;margin-bottom:22px}
${s('adsh')} h2,${s('adsh')} h1{font-size:clamp(20px,2.4vw,26px);font-weight:700;
  letter-spacing:-.01em;order:1;flex:none}
/* o filete e um ::after e por isso e sempre o ultimo filho. Sem a propriedade
   order ele cairia depois do "ver tudo" e o link ficaria colado no titulo */
${s('adsh')}::after{content:"";flex:1;height:1px;background:var(--line);align-self:center;order:2}
${s('adsh')} .more{order:3;flex:none;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.09em;color:var(--pri)}
${s('adsh')} .more:hover{color:var(--viva);text-decoration:underline}
${s('adsh1')} h1{font-size:clamp(26px,3.5vw,37px)}

/* ---------- chapeu, artigo, coluna medida ---------- */
${s('adkick')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--pri)}
${s('adart')}{padding-block:30px 8px}
${s('adcol')}{max-width:${fp.medida || '700px'}}
${s('adart')} h1{font-size:clamp(28px,4vw,44px);font-weight:700;letter-spacing:-.018em;
  line-height:1.12;margin:12px 0 0}
${s('addek')}{font-size:19px;line-height:1.58;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('adhero')}{display:block;margin:28px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '860px'}}
${s('adhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('adhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('adleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '860px'};line-height:1.5;text-align:left}
${s('adbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.8;margin-top:28px}
${s('adbody')} p{margin:0 0 1.15em;text-align:left}
${s('adbody')} h2{font-size:25px;font-weight:700;letter-spacing:-.01em;margin:1.7em 0 .5em;
  color:var(--pri)}
${s('adbody')} h3{font-size:20px;font-weight:600;margin:1.5em 0 .4em}
${s('adbody')} ul,${s('adbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('adbody')} li{margin:0 0 .45em}
${s('adbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('adbody')} a:hover{color:var(--viva)}
${s('adbody')} img{margin:1.5em 0;background:var(--ph)}
${s('adbody')} blockquote{margin:1.5em 0;padding:4px 0 4px 22px;border-left:3px solid var(--viva);
  font-family:var(--fd);font-size:20px;line-height:1.5;color:var(--ink);font-style:italic}
${s('adbody')} figure{margin:1.5em 0}
${s('adbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('adbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('adbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('adbody')} th,${s('adbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('adbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--ink)}
@media(max-width:640px){
  ${s('adbody')} table{min-width:0}
  ${s('adbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('adbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('adbody')} table,${s('adbody')} tbody,${s('adbody')} tr,${s('adbody')} th,
  ${s('adbody')} td{display:block;width:auto}
  ${s('adbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    padding:2px 18px 16px;margin-bottom:13px}
  ${s('adbody')} tbody th,${s('adbody')} tbody td{border:0;background:transparent}
  ${s('adbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:16px;
    font-family:var(--fd);font-weight:600;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('adbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('adbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('adass')}{display:grid;grid-template-columns:76px minmax(0,1fr);gap:17px;align-items:start;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;border-top:2px solid var(--ink)}
${s('adass')} img{width:76px;height:76px;object-fit:cover;background:var(--ph)}
${s('adass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--viva)}
${s('adass')} .nm{display:block;font-family:var(--fd);font-size:21px;font-weight:700;
  margin-top:3px}
${s('adass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('adass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('adass')} .go:hover{text-decoration:underline}
${s('adrel')}{max-width:${fp.medida || '700px'};padding-block:30px 10px}

/* ---------- rodape ---------- */
${s('adfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:48px;padding-block:44px 26px}
${s('adcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('adfb')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:700;font-size:25px;color:#fff}
${s('adfb')} svg{display:block;height:.96em;width:auto;flex:none;align-self:center}
${s('adfoot')} p{color:${t.footerTx || '#A7AE9F'};text-align:left}
${s('adfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.13em;color:${t.footerTx || '#A7AE9F'};margin-bottom:13px}
${s('adflist')}{display:flex;flex-direction:column;gap:9px}
${s('adflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('adflist')} a:hover{opacity:1;color:var(--viva)}
${s('adfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;color:${t.footerTx || '#A7AE9F'}}
@media(max-width:820px){
  ${s('adcols')}{grid-template-columns:1fr;gap:26px}
  ${s('adfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Livro aberto visto de topo: duas paginas e a lombada no meio. Sem letra
 * dentro, porque o nome vem como texto na fonte de titulo ao lado. */
const AD_SIMB = `<svg viewBox="0 0 32 26" role="img" aria-hidden="true" focusable="false"><path d="M2 3h12v20H2Z" fill="var(--marca-2,currentColor)"/><path d="M18 3h12v20H18Z" fill="var(--marca-2,currentColor)"/><rect x="14" y="1" width="4" height="24" fill="var(--marca-1,currentColor)"/><rect x="5" y="8" width="6" height="2" fill="var(--marca-3,#fff)"/><rect x="21" y="8" width="6" height="2" fill="var(--marca-3,#fff)"/></svg>`;

const AD_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function adHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'adnav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase: a editoria mora em /categoria/<slug>/.
  // H.curl resolve isso; montar o link a mao poe o menu inteiro em 404.
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('adtop')}">
<div class="${c('adin')} ${c('adbar')}">
<a class="${c('admarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--ink);--marca-2:var(--pri);--marca-3:var(--viva)">${AD_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('adnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('adham')}" type="button" data-adham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('adbusca')}" href="/busca/">${AD_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-adham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function adFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('adfoot')}"><div class="${c('adin')}">
<div class="${c('adcols')}">
  <div><a class="${c('adfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--pri);--marca-3:var(--viva)">${AD_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('adfh')}">Editorias</div><div class="${c('adflist')}">${cats}</div></div>
  <div><div class="${c('adfh')}">A casa</div><div class="${c('adflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('adfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A capa em retrato. O `span` do retrato tem display:block, senao o
 * aspect-ratio nao aplica e a imagem passa por cima do titulo.
 * O nivel do titulo vem de quem chama: h3 sob um h2 de secao na home, h2 na
 * lista de editoria, onde o titulo da pagina e h1. */
function adLivro(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('adlivro')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('adcapa')}"><span data-f>${H.pic(a, !!eager)}</span><b>${H.cat(a)}</b></span>
<h${n} class="${c('adti')}">${H.esc(a.title)}</h${n}>
<span class="${c('addt')}">${H.esc(H.dateShort(a.date))}</span></a>`;
}

function adHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('adabre')}">
<div><span class="${c('adkick')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('admm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('adcapa')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const topo = `<div class="${c('adsh')}"><h2>${H.esc(nome)}</h2>
<a class="more" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>`;
      // consome exatamente 4, 3 ou 2, e a grade recebe esse mesmo numero de
      // colunas: a ultima linha nunca fica com buraco ao lado do ultimo cartao
      const n = v.length >= 4 ? 4 : v.length;
      const extra = n === 4 ? '' : ' ' + c('adg' + n);
      const corpo = `<div class="${c('adestante')}${extra}">${v.slice(0, n)
        .map(a => adLivro(ctx, a, false)).join('')}</div>`;
      return `<section class="${c('adsec')}">${topo}${corpo}</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${adHeader(ctx, menu)}
<main class="${c('adwrap')}"><div class="${c('adin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${adFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. Inventar `bio` ou `editorias` nao da erro em lugar
 * nenhum, so nao gera nada. */
function adAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('adass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="76" height="76" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

function adArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema. Nao ha helper para calcular isso na arquitetura.
  const rel = (related && related.length) ? `<section class="${c('adrel')}">
<div class="${c('adsh')}"><h2>Leia também</h2></div>
<div class="${c('adestante')} ${c('adg' + Math.min(related.length, 3))}">${related.slice(0, 3)
    .map(a => adLivro(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${adHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('adwrap')}"><div class="${c('adin')}">
<article class="${c('adart')}">
<div class="${c('adcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('adkick')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('addek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('adhero')}"><span data-f>${H.pic(art, true)}</span></span>
<p class="${c('adleg')}">${H.esc(art.image && art.image.alt ? art.image.alt : art.title)}</p>` : ''}
<div class="${c('adbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${adAssinatura(ctx, art)}
${rel}
</div></main>
${adFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function adList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const extra = (itens.length && itens.length < 4) ? ' ' + c('adg' + itens.length) : '';
  return `${H.head(ctx, meta)}
${adHeader(ctx, menu)}
<main class="${c('adwrap')}"><div class="${c('adin')}">
<section class="${c('adsec')}">
<div class="${c('adsh')} ${c('adsh1')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('addek')}" style="max-width:66ch;margin:-12px 0 24px">${H.esc(opts.desc)}</p>` : ''}
<div class="${c('adestante')}${extra}">${itens
    .map((a, i) => adLivro(ctx, a, i === 0, 2)).join('')}</div>
</section>
</div></main>
${adFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AE, arquetipo SUMARIO. Feita para o revistadeducao.com.br.
 *
 * ## De onde vem o desenho
 *
 * O nome e de revista e o acervo preservado puxa para negocio, investimento e
 * dica pratica. O desenho pega o gesto de **sumario de revista**: a editoria nao
 * fica em cima do bloco, fica **numa coluna estreita a esquerda**, ao lado das
 * materias dela, como o indice impresso que lista a secao na margem.
 *
 * ## O que a diferencia das 30 vizinhas da opengravity
 *
 *   - **rotulo de secao na margem esquerda**, e nao acima do bloco. Todas as
 *     vizinhas poem o nome da editoria em cima, com filete: `AB`, `AC`, `AD`, e
 *     as antigas. Aqui a pagina inteira le como um sumario, e nao como uma pilha
 *     de secoes
 *   - **ficha horizontal**: miniatura a esquerda e texto a direita, com filete
 *     embaixo. A `AD` usa capa em retrato, a `AC` linha numerada, a `AB` grade
 *     com tarja
 *   - **Faustina e Sora**: nenhum portal da rede usa qualquer uma das duas
 *   - **ardosia com ambar**: as vizinhas ja ocupam grafite, marinho, esmeralda,
 *     violeta, ocre, vinho, cobalto, terracota, petroleo, carmim, lima,
 *     turquesa, azul-ferrugem, azul-royal, sepia, indigo e verde
 *   - **sem grade em nenhum caminho**: home, editoria e relacionados sao listas,
 *     entao nunca sobra buraco na ultima linha e a data nunca pula de coluna
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal tem `categoryBase`.** O arquivo de editoria mora em
 * `/categoria/<slug>/` e o artigo em `/<editoria>/<slug>/`. Montar o link de
 * editoria a mao com `/${slug}/` derruba **o menu do topo, o menu do rodape, o
 * rotulo de cada secao e o chapeu de cada artigo**, tudo em 404, e nao aparece em
 * print nenhum porque o menu fica bonito e so quebra no clique. Todo link de
 * editoria aqui sai de `H.curl(slug)`, sem excecao.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)`, nunca montado a mao
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` da ficha tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e a ficha dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS: o CSS
 *     mora num template literal, a crase o fecha e a chave interpola de verdade
 *   - titulo e linha fina saem escapados por `H.esc`, entao tag que tenha
 *     sobrado no dado apareceria: a limpeza tira antes, na Fase 7
 */

function aeCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#E7E3DB';
  const viva = t.vivid || '#D97A2B';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('aewrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.72;-webkit-font-smoothing:antialiased}
${s('aewrap')} *{box-sizing:border-box}
${s('aein')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('aewrap')} h1,${s('aewrap')} h2,${s('aewrap')} h3,${s('aewrap')} h4{font-family:var(--fd);
  font-weight:600;letter-spacing:-.008em;line-height:1.2;margin:0}
${s('aewrap')} a{color:inherit;text-decoration:none}
${s('aewrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: marca a esquerda, navegacao a direita ---------- */
${s('aetop')}{background:var(--paper);border-bottom:1px solid var(--line)}
${s('aebar')}{display:flex;align-items:center;gap:20px;padding-block:20px 18px;flex-wrap:wrap}
${s('aemarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:clamp(24px,3vw,32px);letter-spacing:-.016em;color:var(--ink);
  flex:none}
${s('aemarca')} svg{display:block;height:.94em;width:auto;flex:none;align-self:center}
${s('aenav')}{display:flex;gap:12px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('aenav')} a{font-family:var(--fb);font-size:11px;font-weight:600;letter-spacing:.04em;color:var(--muted);transition:color .2s ease}
${s('aenav')} a:hover{color:var(--pri)}
${s('aebusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.05em;
  background:var(--pri);color:var(--sob);padding:9px 13px;flex:none;margin-left:10px}
${s('aeham')}{display:none;width:46px;height:46px;border:1px solid var(--line);background:none;
  cursor:pointer;padding:0;position:relative}
${s('aeham')} i,${s('aeham')} i::before,${s('aeham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--ink);content:""}
${s('aeham')} i{top:22px}
${s('aeham')} i::before{top:-6px;left:0}
${s('aeham')} i::after{top:6px;left:0}
/* num celular de 360 a 412px a marca, o botao de menu e o de busca somados
   passam da largura, e o de busca cai sozinho numa segunda linha. A folga sai
   de marca menor e botao com menos respiro, e nao de esconder o rotulo */
@media(max-width:560px){
  ${s('aemarca')}{font-size:21px;gap:8px}
  ${s('aebar')}{gap:12px}
  ${s('aebusca')}{font-size:10.5px;padding:9px 11px;gap:6px}
}
@media(max-width:1100px){
  ${s('aeham')}{display:block;order:2}
  ${s('aebusca')}{order:3;margin-left:0}
  ${s('aenav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:15px}
  ${s('aenav')}[data-aberto="1"]{display:flex}
  ${s('aenav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('aeabre')}{display:grid;grid-template-columns:1fr 1fr;gap:36px;align-items:center;
  padding-block:40px 36px;border-bottom:1px solid var(--line)}
${s('aeabre')} h2{font-size:clamp(30px,4.2vw,48px);letter-spacing:-.02em;line-height:1.1;
  margin:12px 0 0;font-weight:700}
${s('aeabre')} p{font-size:17.5px;line-height:1.64;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('aemm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:18px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('aemm')} b{color:var(--ink);font-weight:700}
@media(max-width:820px){${s('aeabre')}{grid-template-columns:1fr;gap:22px}}

/* ---------- a secao com rotulo na margem, que e a assinatura desta arquitetura ---------- */
${s('aesec')}{display:grid;grid-template-columns:210px minmax(0,1fr);gap:34px;
  padding-block:34px;border-bottom:1px solid var(--line)}
${s('aerot')}{position:relative;padding-top:4px}
${s('aerot')} h2,${s('aerot')} h1{font-size:clamp(19px,2.2vw,23px);line-height:1.16;font-weight:700;
  letter-spacing:-.014em;color:var(--ink)}
${s('aerot')}::before{content:"";display:block;width:34px;height:3px;background:var(--viva);
  margin-bottom:13px}
${s('aerot')} .more{display:inline-block;margin-top:12px;font-family:var(--fb);font-size:11px;
  font-weight:700;letter-spacing:.09em;color:var(--pri)}
${s('aerot')} .more:hover{color:var(--viva);text-decoration:underline}
@media(max-width:900px){
  ${s('aesec')}{grid-template-columns:1fr;gap:18px;padding-block:26px}
  ${s('aerot')}::before{margin-bottom:9px}
}

/* ---------- a ficha: miniatura a esquerda, texto a direita ---------- */
${s('aelista')}{display:block}
${s('aeficha')}{display:grid;grid-template-columns:200px minmax(0,1fr);gap:20px;
  align-items:start;padding-block:18px;border-top:1px solid var(--line)}
${s('aelista')} ${s('aeficha')}:first-child{border-top:0;padding-top:0}
${s('aefoto')}{display:block;overflow:hidden;background:var(--ph)}
${s('aefoto')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '16/10'};overflow:hidden}
${s('aefoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .45s ease}
${s('aeficha')}:hover ${s('aefoto')} [data-f] img{transform:scale(1.045)}
${s('aekick')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--viva);
  margin-bottom:6px}
${s('aeti')}{display:block;font-family:var(--fd);font-weight:600;font-size:20px;line-height:1.26;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('aeficha')}:hover ${s('aeti')}{color:var(--pri)}
${s('aedd')}{display:block;margin:8px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);
  max-width:64ch;text-align:left}
${s('aedt')}{display:block;margin-top:8px;font-family:var(--fb);font-size:11.5px;
  color:var(--muted)}
@media(max-width:680px){
  ${s('aeficha')}{grid-template-columns:110px minmax(0,1fr);gap:14px;padding-block:15px}
  ${s('aeti')}{font-size:16.5px}
  ${s('aedd')}{display:none}
}

/* ---------- artigo ---------- */
${s('aeart')}{padding-block:30px 8px}
${s('aecol')}{max-width:${fp.medida || '710px'}}
${s('aechap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--viva)}
${s('aeart')} h1{font-size:clamp(28px,4vw,44px);font-weight:700;letter-spacing:-.02em;
  line-height:1.12;margin:12px 0 0}
${s('aedek')}{font-size:19px;line-height:1.58;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('aehero')}{display:block;margin:28px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'}}
${s('aehero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('aehero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('aeleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('aebody')}{max-width:${fp.medida || '710px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:28px}
${s('aebody')} p{margin:0 0 1.15em;text-align:left}
${s('aebody')} h2{font-size:25px;font-weight:700;letter-spacing:-.012em;margin:1.7em 0 .5em;
  padding-left:14px;border-left:4px solid var(--viva)}
${s('aebody')} h3{font-size:20px;font-weight:600;margin:1.5em 0 .4em;color:var(--pri)}
${s('aebody')} ul,${s('aebody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('aebody')} li{margin:0 0 .45em}
${s('aebody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('aebody')} a:hover{color:var(--viva)}
${s('aebody')} img{margin:1.5em 0;background:var(--ph)}
${s('aebody')} blockquote{margin:1.5em 0;padding:4px 0 4px 22px;border-left:3px solid var(--pri);
  font-family:var(--fd);font-size:20px;line-height:1.5;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do
   artigo, entao e literal de proposito, com o prefixo deste portal */
${s('aebody')} .rde-veja{margin:2.2em 0;padding:20px 24px 18px;
  background:var(--sur);border:1px solid var(--line);border-left:4px solid var(--viva)}
${s('aebody')} .rde-veja h2{font-family:var(--fb);font-size:11.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--muted);
  margin:0 0 11px}
${s('aebody')} .rde-veja ul{list-style:none;margin:0;padding:0}
${s('aebody')} .rde-veja li{margin:0;padding:9px 0;border-top:1px solid var(--line)}
${s('aebody')} .rde-veja li:first-child{border-top:0;padding-top:0}
${s('aebody')} .rde-veja a{font-family:var(--fd);font-size:17px;line-height:1.35;
  color:var(--ink);text-decoration:none;display:block}
${s('aebody')} .rde-veja a:hover{color:var(--viva)}
${s('aebody')} figure{margin:1.5em 0}
${s('aebody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('aebody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('aebody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('aebody')} th,${s('aebody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('aebody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--ink)}
@media(max-width:640px){
  ${s('aebody')} table{min-width:0}
  ${s('aebody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('aebody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('aebody')} table,${s('aebody')} tbody,${s('aebody')} tr,${s('aebody')} th,
  ${s('aebody')} td{display:block;width:auto}
  ${s('aebody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    padding:2px 18px 16px;margin-bottom:13px}
  ${s('aebody')} tbody th,${s('aebody')} tbody td{border:0;background:transparent}
  ${s('aebody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:16px;
    font-family:var(--fd);font-weight:600;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('aebody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('aebody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('aeass')}{display:grid;grid-template-columns:76px minmax(0,1fr);gap:17px;align-items:start;
  max-width:${fp.medida || '710px'};margin:34px 0 0;padding-top:22px;border-top:1px solid var(--line)}
${s('aeass')} img{width:76px;height:76px;object-fit:cover;background:var(--ph)}
${s('aeass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--viva)}
${s('aeass')} .nm{display:block;font-family:var(--fd);font-size:21px;font-weight:700;margin-top:3px}
${s('aeass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('aeass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('aeass')} .go:hover{text-decoration:underline}
${s('aerel')}{max-width:${fp.medida || '710px'};padding-block:28px 10px}
${s('aerel')} ${s('aerotb')}{margin-bottom:10px}
${s('aerotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.1em;color:var(--muted)}

/* ---------- rodape ---------- */
${s('aefoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('aecols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('aefb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:25px;color:#fff}
${s('aefb')} svg{display:block;height:.94em;width:auto;flex:none;align-self:center}
${s('aefoot')} p{color:${t.footerTx || '#A9AFB8'};text-align:left}
${s('aefh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.13em;color:${t.footerTx || '#A9AFB8'};margin-bottom:13px}
${s('aeflist')}{display:flex;flex-direction:column;gap:9px}
${s('aeflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('aeflist')} a:hover{opacity:1;color:var(--viva)}
${s('aefim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;color:${t.footerTx || '#A9AFB8'}}
@media(max-width:820px){
  ${s('aecols')}{grid-template-columns:1fr;gap:26px}
  ${s('aefoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Sumario: tres filetes de larguras diferentes, como as linhas de um indice, com
 * o marcador do topo em destaque. Sem letra dentro: o nome vem como texto ao lado. */
const AE_SIMB = `<svg viewBox="0 0 30 26" role="img" aria-hidden="true" focusable="false"><rect x="1" y="2" width="10" height="4" fill="var(--marca-2,currentColor)"/><rect x="13" y="2" width="16" height="4" fill="var(--marca-1,currentColor)"/><rect x="1" y="11" width="10" height="4" fill="var(--marca-1,currentColor)"/><rect x="13" y="11" width="11" height="4" fill="var(--marca-1,currentColor)"/><rect x="1" y="20" width="10" height="4" fill="var(--marca-1,currentColor)"/><rect x="13" y="20" width="16" height="4" fill="var(--marca-3,currentColor)"/></svg>`;

const AE_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function aeHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aenav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase: a editoria mora em /categoria/<slug>/.
  // H.curl resolve isso; montar o link a mao poe o menu inteiro em 404.
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aetop')}">
<div class="${c('aein')} ${c('aebar')}">
<a class="${c('aemarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--ink);--marca-2:var(--viva);--marca-3:var(--pri)">${AE_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('aenav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('aeham')}" type="button" data-aeham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('aebusca')}" href="/busca/">${AE_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-aeham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function aeFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('aefoot')}"><div class="${c('aein')}">
<div class="${c('aecols')}">
  <div><a class="${c('aefb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva);--marca-3:var(--viva)">${AE_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('aefh')}">Editorias</div><div class="${c('aeflist')}">${cats}</div></div>
  <div><div class="${c('aefh')}">A revista</div><div class="${c('aeflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('aefim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A ficha. O `span` do retrato tem display:block, senao o aspect-ratio nao aplica
 * e a imagem passa por cima do titulo.
 * O nivel do titulo vem de quem chama: h3 sob um h2 de secao na home, h2 na lista
 * de editoria, onde o titulo da pagina e h1. */
function aeFicha(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aeficha')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('aefoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('aekick')}">${H.cat(a)}</span>
<h${n} class="${c('aeti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('aedd')}">${H.esc(H.clip(a.dek, 160))}</span>` : ''}
<span class="${c('aedt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function aeHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('aeabre')}">
<div><span class="${c('aechap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('aemm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('aefoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      // lista, e nao grade: a ultima linha nunca fica com buraco
      return `<section class="${c('aesec')}">
<div class="${c('aerot')}"><h2>${H.esc(nome)}</h2>
<a class="more" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
<div class="${c('aelista')}">${v.slice(0, 4).map(a => aeFicha(ctx, a, false)).join('')}</div>
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${aeHeader(ctx, menu)}
<main class="${c('aewrap')}"><div class="${c('aein')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${aeFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. Inventar `bio` ou `editorias` nao da erro em lugar
 * nenhum, so nao gera nada. */
function aeAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('aeass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="76" height="76" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

function aeLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('aeleg')}">${H.esc(alt)}</p>`;
}

function aeArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema. Nao ha helper para calcular isso na arquitetura.
  const rel = (related && related.length) ? `<section class="${c('aerel')}">
<span class="${c('aerotb')}">Leia também</span>
<div class="${c('aelista')}">${related.slice(0, 3).map(a => aeFicha(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${aeHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('aewrap')}"><div class="${c('aein')}">
<article class="${c('aeart')}">
<div class="${c('aecol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('aechap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('aedek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('aehero')}"><span data-f>${H.pic(art, true)}</span></span>
${aeLegenda(ctx, art)}` : ''}
<div class="${c('aebody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${aeAssinatura(ctx, art)}
${rel}
</div></main>
${aeFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function aeList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  return `${H.head(ctx, meta)}
${aeHeader(ctx, menu)}
<main class="${c('aewrap')}"><div class="${c('aein')}">
<section class="${c('aesec')}">
<div class="${c('aerot')}"><h1>${H.esc(opts.title)}</h1>
${opts.desc ? `<p class="${c('aedd')}" style="margin-top:10px">${H.esc(opts.desc)}</p>` : ''}</div>
<div class="${c('aelista')}">${itens.map((a, i) => aeFicha(ctx, a, i === 0, 2)).join('')}</div>
</section>
</div></main>
${aeFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AF, arquetipo COMPENDIO. Feita para o sabedoriaglobal.com.br.
 *
 * ## De onde vem o desenho
 *
 * O nome promete saber reunido, e o acervo preservado e de almanaque largo:
 * dica, entretenimento, curiosidade, casa, saude, turismo. O desenho pega o
 * gesto do **compendio**: a secao abre como **titulo corrido de pagina**, com
 * filete que atravessa ate a borda e a contagem de verbetes na ponta, e cada
 * item e um **verbete**, com o texto mandando e a miniatura pequena na direita.
 *
 * ## O que a diferencia das 31 vizinhas da opengravity
 *
 *   - **titulo corrido com filete atravessado e contagem na ponta**. A `AE` poe
 *     o rotulo numa coluna de margem, a `AB`, a `AC` e a `AD` poem em cima com
 *     filete curto. Nenhuma leva o filete ate a borda nem conta os itens
 *   - **verbete com texto a esquerda e miniatura a direita**, o inverso da
 *     ficha da `AE`. A imagem vira apoio, e nao abertura de linha
 *   - **capitular na chamada de abertura**: a linha fina comeca com uma letra em
 *     corpo grande, na cor de acento, flutuando a esquerda. E gesto de livro, e
 *     nenhuma vizinha usa capitular em lugar nenhum
 *   - **Eczar e Lexend**: nenhuma das duas aparece nas 75 famílias em uso na rede
 *   - **ameixa-carvao com oliva**: as vizinhas ja ocupam grafite, marinho,
 *     esmeralda, violeta, ocre, vinho, cobalto, terracota, petroleo, carmim,
 *     turquesa, azul-ferrugem, azul-royal, sepia, indigo, verde e ardosia
 *   - **sem grade em nenhum caminho**: home, editoria e relacionados sao listas,
 *     entao nunca sobra buraco na ultima linha e a data nunca pula de coluna
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal tem `categoryBase`.** O WordPress servia o arquivo de editoria
 * em `/category/<slug>/`, porque `category_base` estava vazio e o padrao do
 * WordPress e `category`. O artigo mora em `/<editoria>/<slug>/`. Montar o link
 * de editoria a mao com `/${'$'}{slug}/` derruba **o menu do topo, o menu do
 * rodape, o titulo de cada secao e o chapeu de cada artigo**, tudo em 404, e nao
 * aparece em print nenhum porque o menu fica bonito e so quebra no clique. Todo
 * link de editoria aqui sai de `H.curl(slug)`, sem excecao.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)`, nunca montado a mao
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do verbete tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o verbete dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal,
 *     senao o botao do menu fica invisivel no celular
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS: o CSS
 *     mora num template literal, a crase o fecha e a chave interpola de verdade
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG: wordmark em SVG
 *     ja foi ao ar com letra faltando e nem leitor de tela acusou
 */

function afCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEAE4';
  const viva = t.vivid || '#6E8F2A';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('afwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.72;-webkit-font-smoothing:antialiased}
${s('afwrap')} *{box-sizing:border-box}
${s('afin')}{max-width:${fp.container || '1160px'};margin:0 auto;padding:0 24px;width:100%}
${s('afwrap')} h1,${s('afwrap')} h2,${s('afwrap')} h3,${s('afwrap')} h4{font-family:var(--fd);
  font-weight:600;letter-spacing:-.004em;line-height:1.2;margin:0}
${s('afwrap')} a{color:inherit;text-decoration:none}
${s('afwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: marca a esquerda, navegacao a direita ---------- */
${s('aftop')}{background:var(--paper);border-bottom:2px solid var(--ink)}
${s('afbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 17px;flex-wrap:wrap}
${s('afmarca')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:700;font-size:clamp(23px,2.9vw,31px);letter-spacing:-.012em;color:var(--ink);
  flex:none}
${s('afmarca')} svg{display:block;height:1em;width:auto;flex:none;align-self:center}
${s('afnav')}{display:flex;gap:12px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('afnav')} a{font-family:var(--fb);font-size:11px;font-weight:600;letter-spacing:.05em;color:var(--muted);transition:color .2s ease}
${s('afnav')} a:hover{color:var(--pri)}
${s('afbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  border:2px solid var(--ink);color:var(--ink);padding:8px 13px;flex:none;margin-left:10px}
${s('afbusca')}:hover{background:var(--ink);color:var(--paper)}
${s('afham')}{display:none;width:46px;height:46px;border:2px solid var(--ink);background:none;
  cursor:pointer;padding:0;position:relative}
${s('afham')} i,${s('afham')} i::before,${s('afham')} i::after{position:absolute;left:11px;
  width:20px;height:2px;background:var(--ink);content:""}
${s('afham')} i{top:21px}
${s('afham')} i::before{top:-6px;left:0}
${s('afham')} i::after{top:6px;left:0}
/* num celular de 360 a 412px a marca, o botao de menu e o de busca somados
   passam da largura e o de busca cai sozinho numa segunda linha */
@media(max-width:560px){
  ${s('afmarca')}{font-size:20px;gap:8px}
  ${s('afbar')}{gap:11px}
  ${s('afbusca')}{font-size:10px;padding:8px 10px;gap:6px}
}
@media(max-width:1100px){
  ${s('afham')}{display:block;order:2}
  ${s('afbusca')}{order:3;margin-left:0}
  ${s('afnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('afnav')}[data-aberto="1"]{display:flex}
  ${s('afnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('afabre')}{display:grid;grid-template-columns:1fr 1fr;gap:38px;align-items:center;
  padding-block:40px 34px;border-bottom:1px solid var(--line)}
${s('afabre')} h2{font-size:clamp(29px,4.1vw,46px);letter-spacing:-.014em;line-height:1.12;
  margin:11px 0 0;font-weight:700}
/* capitular: gesto de livro, e nenhuma vizinha usa em lugar nenhum */
${s('afcap')}{font-size:17.5px;line-height:1.64;color:var(--dek);margin:17px 0 0;
  max-width:48ch;text-align:left}
${s('afcap')}::first-letter{float:left;font-family:var(--fd);font-weight:700;font-size:3.1em;
  line-height:.84;color:var(--viva);padding:4px 11px 0 0}
${s('afmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('afmm')} b{color:var(--ink);font-weight:700}
@media(max-width:820px){
  ${s('afabre')}{grid-template-columns:1fr;gap:22px;padding-block:28px 24px}
  ${s('afcap')}::first-letter{font-size:2.7em}
}

/* ---------- titulo corrido da secao: a assinatura desta arquitetura ---------- */
${s('afsec')}{padding-block:32px;border-bottom:1px solid var(--line)}
${s('afcab')}{display:flex;align-items:baseline;gap:16px;margin-bottom:6px}
${s('afcab')} h1,${s('afcab')} h2{font-size:clamp(21px,2.5vw,27px);font-weight:700;
  letter-spacing:.01em;color:var(--ink);flex:none;}
${s('affilete')}{flex:1 1 auto;height:2px;background:var(--ink);min-width:20px}
${s('afconta')}{flex:none;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.1em;color:var(--viva)}
${s('afmais')}{display:inline-block;margin-top:4px;font-family:var(--fb);font-size:11px;
  font-weight:700;letter-spacing:.09em;color:var(--pri)}
${s('afmais')}:hover{color:var(--viva);text-decoration:underline}
${s('afdescr')}{margin:9px 0 0;font-size:15px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* ---------- o verbete: texto a esquerda, miniatura pequena a direita ---------- */
${s('aflista')}{display:block;margin-top:16px}
${s('afverb')}{display:grid;grid-template-columns:minmax(0,1fr) 168px;gap:22px;
  align-items:start;padding-block:17px;border-top:1px solid var(--line)}
${s('aflista')} ${s('afverb')}:first-child{border-top:0;padding-top:4px}
${s('affoto')}{display:block;overflow:hidden;background:var(--ph)}
${s('affoto')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '4/3'};overflow:hidden}
${s('affoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .45s ease}
${s('afverb')}:hover ${s('affoto')} [data-f] img{transform:scale(1.05)}
${s('afkick')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--viva);
  margin-bottom:6px}
${s('afti')}{display:block;font-family:var(--fd);font-weight:600;font-size:21px;line-height:1.25;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('afverb')}:hover ${s('afti')}{color:var(--pri)}
${s('afdd')}{display:block;margin:9px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);
  max-width:66ch;text-align:left}
${s('afdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  color:var(--muted)}
@media(max-width:680px){
  ${s('afverb')}{grid-template-columns:minmax(0,1fr) 96px;gap:14px;padding-block:15px}
  ${s('afti')}{font-size:16.5px}
  ${s('afdd')}{display:none}
  ${s('afcab')}{gap:11px}
}

/* ---------- artigo ---------- */
${s('afart')}{padding-block:28px 8px}
${s('afcol')}{max-width:${fp.medida || '700px'}}
${s('afchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--viva)}
${s('afart')} h1{font-size:clamp(28px,3.9vw,43px);font-weight:700;letter-spacing:-.014em;
  line-height:1.13;margin:12px 0 0}
${s('afdek')}{font-size:19px;line-height:1.58;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('afhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '870px'}}
${s('afhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('afhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('afleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '870px'};line-height:1.5;text-align:left}
${s('afbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('afbody')} p{margin:0 0 1.15em;text-align:left}
${s('afbody')} h2{font-size:25px;font-weight:700;letter-spacing:-.008em;margin:1.75em 0 .5em;
  padding-bottom:8px;border-bottom:2px solid var(--ink)}
${s('afbody')} h3{font-size:20px;font-weight:600;margin:1.5em 0 .4em;color:var(--pri)}
${s('afbody')} ul,${s('afbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('afbody')} li{margin:0 0 .45em}
${s('afbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('afbody')} a:hover{color:var(--viva)}
${s('afbody')} img{margin:1.5em 0;background:var(--ph)}
${s('afbody')} blockquote{margin:1.5em 0;padding:4px 0 4px 22px;border-left:3px solid var(--viva);
  font-family:var(--fd);font-size:20px;line-height:1.5;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('afbody')} .sab-veja{margin:2.2em 0;padding:19px 23px 17px;background:var(--wash);
  border-top:2px solid var(--ink)}
${s('afbody')} .sab-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--muted);
  margin:0 0 11px;padding:0;border:0}
${s('afbody')} .sab-veja ul{list-style:none;margin:0;padding:0}
${s('afbody')} .sab-veja li{margin:0;padding:9px 0;border-top:1px solid var(--line)}
${s('afbody')} .sab-veja li:first-child{border-top:0;padding-top:0}
${s('afbody')} .sab-veja a{font-family:var(--fd);font-size:17px;line-height:1.35;
  color:var(--ink);text-decoration:none;display:block}
${s('afbody')} .sab-veja a:hover{color:var(--viva)}
${s('afbody')} figure{margin:1.5em 0}
${s('afbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('afbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('afbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('afbody')} th,${s('afbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('afbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--ink)}
@media(max-width:640px){
  ${s('afbody')} table{min-width:0}
  ${s('afbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('afbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('afbody')} table,${s('afbody')} tbody,${s('afbody')} tr,${s('afbody')} th,
  ${s('afbody')} td{display:block;width:auto}
  ${s('afbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    padding:2px 18px 16px;margin-bottom:13px}
  ${s('afbody')} tbody th,${s('afbody')} tbody td{border:0;background:transparent}
  ${s('afbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:16px;
    font-family:var(--fd);font-weight:600;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('afbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('afbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('afass')}{display:grid;grid-template-columns:76px minmax(0,1fr);gap:17px;align-items:start;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;border-top:2px solid var(--ink)}
${s('afass')} img{width:76px;height:76px;object-fit:cover;background:var(--ph)}
${s('afass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--viva)}
${s('afass')} .nm{display:block;font-family:var(--fd);font-size:21px;font-weight:700;margin-top:3px}
${s('afass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('afass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('afass')} .go:hover{text-decoration:underline}
${s('afrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('afrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.11em;color:var(--muted);margin-bottom:8px}

/* ---------- rodape ---------- */
${s('affoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('afcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('affb')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:700;font-size:25px;color:#fff}
${s('affb')} svg{display:block;height:1em;width:auto;flex:none;align-self:center}
${s('affoot')} p{color:${t.footerTx || '#ABA3A9'};text-align:left}
${s('affh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.13em;color:${t.footerTx || '#ABA3A9'};margin-bottom:13px}
${s('afflist')}{display:flex;flex-direction:column;gap:9px}
${s('afflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('afflist')} a:hover{opacity:1;color:var(--viva)}
${s('affim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;color:${t.footerTx || '#ABA3A9'}}
@media(max-width:820px){
  ${s('afcols')}{grid-template-columns:1fr;gap:26px}
  ${s('affoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Compendio: tres cadernos empilhados de larguras iguais e alturas diferentes,
 * com o do meio em destaque. Sem letra dentro: o nome vem como texto ao lado, e
 * wordmark em SVG ja foi ao ar com letra faltando sem ninguem notar. */
const AF_SIMB = `<svg viewBox="0 0 26 26" role="img" aria-hidden="true" focusable="false"><rect x="1" y="3" width="7" height="20" fill="var(--marca-1,currentColor)"/><rect x="10" y="7" width="7" height="16" fill="var(--marca-2,currentColor)"/><rect x="19" y="11" width="6" height="12" fill="var(--marca-3,currentColor)"/></svg>`;

const AF_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function afHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'afnav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase: a editoria mora em /category/<slug>/.
  // H.curl resolve isso; montar o link a mao poe o menu inteiro em 404.
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aftop')}">
<div class="${c('afin')} ${c('afbar')}">
<a class="${c('afmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--ink);--marca-2:var(--viva);--marca-3:var(--pri)">${AF_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('afnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('afham')}" type="button" data-afham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('afbusca')}" href="/busca/">${AF_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-afham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function afFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('affoot')}"><div class="${c('afin')}">
<div class="${c('afcols')}">
  <div><a class="${c('affb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva);--marca-3:var(--viva)">${AF_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('affh')}">Editorias</div><div class="${c('afflist')}">${cats}</div></div>
  <div><div class="${c('affh')}">O compêndio</div><div class="${c('afflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('affim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* O verbete. O `span` da miniatura tem display:block, senao o aspect-ratio nao
 * aplica e a imagem passa por cima do titulo.
 * O nivel do titulo vem de quem chama: h3 sob um h2 de secao na home, h2 na
 * lista de editoria, onde o titulo da pagina e h1. */
function afVerbete(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('afverb')} ${c('reveal')}" href="${H.url(a)}">
<span><span class="${c('afkick')}">${H.cat(a)}</span>
<h${n} class="${c('afti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('afdd')}">${H.esc(H.clip(a.dek, 165))}</span>` : ''}
<span class="${c('afdt')}">${H.esc(H.dateShort(a.date))}</span></span>
<span class="${c('affoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
</a>`;
}

/* O titulo corrido da secao: nome, filete que atravessa ate a borda e a contagem
 * de verbetes na ponta. E a assinatura desta arquitetura. */
function afCabeca(ctx, nome, quantos, nivel) {
  const { c, H } = ctx;
  const n = nivel === 1 ? 'h1' : 'h2';
  const conta = quantos > 0
    ? `<span class="${c('afconta')}">${quantos} ${quantos === 1 ? 'verbete' : 'verbetes'}</span>`
    : '';
  return `<div class="${c('afcab')}"><${n}>${H.esc(nome)}</${n}>
<span class="${c('affilete')}"></span>${conta}</div>`;
}

function afHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('afabre')}">
<div><span class="${c('afchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p class="${c('afcap')}">${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('afmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('affoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      // lista, e nao grade: a ultima linha nunca fica com buraco
      return `<section class="${c('afsec')}">
${afCabeca(ctx, nome, v.length, 2)}
<a class="${c('afmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a>
<div class="${c('aflista')}">${v.slice(0, 4).map(a => afVerbete(ctx, a, false)).join('')}</div>
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${afHeader(ctx, menu)}
<main class="${c('afwrap')}"><div class="${c('afin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${afFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. Inventar `bio` ou `editorias` nao da erro em lugar
 * nenhum, so nao gera nada. */
function afAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('afass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="76" height="76" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

function afLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('afleg')}">${H.esc(alt)}</p>`;
}

function afArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema. Nao ha helper para calcular isso na arquitetura.
  const rel = (related && related.length) ? `<section class="${c('afrel')}">
<span class="${c('afrotb')}">Leia também</span>
<div class="${c('aflista')}">${related.slice(0, 3).map(a => afVerbete(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${afHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('afwrap')}"><div class="${c('afin')}">
<article class="${c('afart')}">
<div class="${c('afcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('afchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('afdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('afhero')}"><span data-f>${H.pic(art, true)}</span></span>
${afLegenda(ctx, art)}` : ''}
<div class="${c('afbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${afAssinatura(ctx, art)}
${rel}
</div></main>
${afFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function afList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  return `${H.head(ctx, meta)}
${afHeader(ctx, menu)}
<main class="${c('afwrap')}"><div class="${c('afin')}">
<section class="${c('afsec')}">
${afCabeca(ctx, opts.title, itens.length, 1)}
${opts.desc ? `<p class="${c('afdescr')}">${H.esc(opts.desc)}</p>` : ''}
<div class="${c('aflista')}">${itens.map((a, i) => afVerbete(ctx, a, i === 0, 2)).join('')}</div>
</section>
</div></main>
${afFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AG, arquetipo VITRINE. Feita para o exquisito.com.br.
 *
 * ## De onde vem o desenho
 *
 * O nome promete o que sai do comum, e o acervo preservado puxa forte para
 * **entretenimento**, que sozinho e 40% do que sobrou, seguido de marketing,
 * dica, viagem e estilo. O desenho pega o gesto da **vitrine**: cada secao abre
 * com **uma peca grande a esquerda e as menores empilhadas a direita**, como
 * montra de loja, em vez de lista corrida.
 *
 * ## O que a diferencia das 32 vizinhas da opengravity
 *
 *   - **secao em vitrine, com destaque grande ao lado dos menores**. A `AF` e a
 *     `AE` sao listas do comeco ao fim, a `AD` e capa em retrato, a `AC` e linha
 *     numerada, a `AB` e grade com tarja. Nenhuma abre a secao com um destaque
 *   - **etiqueta de editoria em tarja inclinada** sobre a foto do destaque, e
 *     nao acima do titulo
 *   - **numeracao romana na coluna dos menores**, que amarra a vitrine e nao se
 *     repete em vizinha nenhuma
 *   - **Yeseva One e Onest**: nenhuma das duas aparece nas 77 famílias em uso
 *   - **oceano profundo com coral**: as vizinhas ja ocupam grafite, marinho,
 *     esmeralda, violeta, ocre, vinho, cobalto, terracota, petroleo, carmim,
 *     turquesa, azul-ferrugem, azul-royal, sepia, indigo, verde, ardosia e
 *     ameixa
 *   - **a ultima linha nunca fica com buraco**: a vitrine consome exatamente
 *     1 + 3, e o que sobra vai para a lista abaixo dela
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal tem `categoryBase`.** O `category_base` da origem e
 * `categoria`, entao o arquivo de editoria mora em `/categoria/<slug>/` e o
 * artigo em `/<editoria>/<slug>/`. Montar o link de editoria a mao derruba **o
 * menu do topo, o menu do rodape, a etiqueta de cada destaque e o chapeu de cada
 * artigo**, tudo em 404, e nao aparece em print nenhum porque o menu fica bonito
 * e so quebra no clique. Todo link de editoria aqui sai de `H.curl(slug)`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)`, nunca montado a mao
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto, e nao
 *     quando ele e copia do titulo
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */

function agCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#E4EBEE';
  const viva = t.vivid || '#E4572E';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('agwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.7;-webkit-font-smoothing:antialiased}
${s('agwrap')} *{box-sizing:border-box}
${s('agin')}{max-width:${fp.container || '1200px'};margin:0 auto;padding:0 24px;width:100%}
${s('agwrap')} h1,${s('agwrap')} h2,${s('agwrap')} h3,${s('agwrap')} h4{font-family:var(--fd);
  font-weight:400;letter-spacing:0;line-height:1.16;margin:0}
${s('agwrap')} a{color:inherit;text-decoration:none}
${s('agwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('agtop')}{background:var(--pri);color:var(--sob)}
${s('agbar')}{display:flex;align-items:center;gap:18px;padding-block:17px;flex-wrap:wrap}
${s('agmarca')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:400;font-size:clamp(23px,2.9vw,31px);color:var(--sob);flex:none}
${s('agmarca')} svg{display:block;height:.92em;width:auto;flex:none;align-self:center}
${s('agnav')}{display:flex;gap:13px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('agnav')} a{font-family:var(--fb);font-size:11px;font-weight:600;letter-spacing:.05em;color:var(--sob);opacity:.82;transition:opacity .2s ease}
${s('agnav')} a:hover{opacity:1}
${s('agbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--viva);color:#fff;padding:9px 14px;flex:none;margin-left:8px}
${s('agham')}{display:none;width:46px;height:46px;border:1px solid rgba(255,255,255,.4);
  background:none;cursor:pointer;padding:0;position:relative}
${s('agham')} i,${s('agham')} i::before,${s('agham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--sob);content:""}
${s('agham')} i{top:22px}
${s('agham')} i::before{top:-6px;left:0}
${s('agham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('agmarca')}{font-size:20px;gap:8px}
  ${s('agbar')}{gap:11px}
  ${s('agbusca')}{font-size:10px;padding:8px 11px;gap:6px}
}
@media(max-width:1100px){
  ${s('agham')}{display:block;order:2}
  ${s('agbusca')}{order:3;margin-left:0}
  ${s('agnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid rgba(255,255,255,.22);margin-top:14px}
  ${s('agnav')}[data-aberto="1"]{display:flex}
  ${s('agnav')} a{width:100%;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.14);opacity:1}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('agabre')}{display:grid;grid-template-columns:1fr 1.1fr;gap:38px;align-items:center;
  padding-block:40px 34px;border-bottom:3px solid var(--ink)}
${s('agabre')} h2{font-size:clamp(30px,4.2vw,48px);line-height:1.1;margin:12px 0 0}
${s('agabre')} p{font-size:17.5px;line-height:1.62;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('agmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:18px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('agmm')} b{color:var(--ink);font-weight:700}
@media(max-width:820px){${s('agabre')}{grid-template-columns:1fr;gap:22px;padding-block:28px 24px}}

/* ---------- a vitrine: destaque grande a esquerda, menores a direita ---------- */
${s('agsec')}{padding-block:34px;border-bottom:1px solid var(--line)}
${s('agcab')}{display:flex;align-items:center;justify-content:space-between;gap:16px;
  margin-bottom:19px;flex-wrap:wrap}
${s('agcab')} h1,${s('agcab')} h2{font-size:clamp(22px,2.6vw,30px);color:var(--ink)}
${s('agmais')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.09em;color:var(--viva);flex:none}
${s('agmais')}:hover{text-decoration:underline}
${s('agdescr')}{margin:0 0 17px;font-size:15px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}
${s('agvit')}{display:grid;grid-template-columns:1.35fr 1fr;gap:30px;align-items:start}
@media(max-width:900px){${s('agvit')}{grid-template-columns:1fr;gap:22px}}

${s('agdest')}{display:block}
${s('agfoto')}{display:block;overflow:hidden;background:var(--ph);position:relative}
${s('agfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('agfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('agdest')}:hover ${s('agfoto')} [data-f] img{transform:scale(1.04)}
/* etiqueta em tarja inclinada sobre a foto: nenhuma vizinha poe a editoria ali */
${s('agtarja')}{position:absolute;left:0;top:15px;display:inline-block;background:var(--viva);
  color:#fff;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};padding:6px 15px 6px 12px;
  transform:skewX(-12deg);transform-origin:left center}
${s('agtarja')} span{display:block;transform:skewX(12deg)}
${s('agdt')}{display:block;margin-top:11px;font-family:var(--fb);font-size:11.5px;
  color:var(--muted)}
${s('agdest')} ${s('agti')}{font-size:26px;margin-top:9px}
${s('agti')}{display:block;font-family:var(--fd);font-weight:400;font-size:19px;line-height:1.22;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('agdd')}{display:block;margin:9px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);
  max-width:60ch;text-align:left}

${s('aglado')}{display:block;counter-reset:ag}
${s('agmini')}{display:grid;grid-template-columns:34px minmax(0,1fr);gap:14px;align-items:start;
  padding-block:15px;border-top:1px solid var(--line)}
${s('aglado')} ${s('agmini')}:first-child{border-top:0;padding-top:0}
/* numeracao romana, que amarra a vitrine */
${s('agnum')}{display:block;font-family:var(--fd);font-size:17px;color:var(--viva);
  line-height:1.1;padding-top:2px}
${s('agmini')}:hover ${s('agti')}{color:var(--pri)}
${s('agkick')}{display:block;font-family:var(--fb);font-size:10px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--muted);
  margin-bottom:5px}

/* a lista que recolhe o que sobra da vitrine */
${s('aglista')}{display:block;margin-top:22px;border-top:1px solid var(--line)}
${s('agitem')}{display:grid;grid-template-columns:132px minmax(0,1fr);gap:18px;align-items:start;
  padding-block:15px;border-bottom:1px solid var(--line)}
${s('agitem')}:hover ${s('agti')}{color:var(--pri)}
@media(max-width:680px){
  ${s('agitem')}{grid-template-columns:96px minmax(0,1fr);gap:13px}
  ${s('agdest')} ${s('agti')}{font-size:21px}
  ${s('agdd')}{display:none}
}

/* ---------- artigo ---------- */
${s('agart')}{padding-block:28px 8px}
${s('agcol')}{max-width:${fp.medida || '700px'}}
${s('agchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--viva)}
${s('agart')} h1{font-size:clamp(29px,4vw,45px);line-height:1.1;margin:12px 0 0}
${s('agdek')}{font-size:19px;line-height:1.56;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('aghero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'}}
${s('aghero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('aghero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('agleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('agbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('agbody')} p{margin:0 0 1.15em;text-align:left}
${s('agbody')} h2{font-family:var(--fd);font-size:26px;font-weight:400;margin:1.7em 0 .5em;
  color:var(--pri)}
${s('agbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--ink)}
${s('agbody')} ul,${s('agbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('agbody')} li{margin:0 0 .45em}
${s('agbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('agbody')} a:hover{color:var(--viva)}
${s('agbody')} img{margin:1.5em 0;background:var(--ph)}
${s('agbody')} blockquote{margin:1.5em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:21px;line-height:1.42;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('agbody')} .exq-veja{margin:2.2em 0;padding:19px 23px 17px;background:var(--wash)}
${s('agbody')} .exq-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--muted);
  margin:0 0 11px;color:var(--pri)}
${s('agbody')} .exq-veja ul{list-style:none;margin:0;padding:0}
${s('agbody')} .exq-veja li{margin:0;padding:9px 0;border-top:1px solid rgba(0,0,0,.09)}
${s('agbody')} .exq-veja li:first-child{border-top:0;padding-top:0}
${s('agbody')} .exq-veja a{font-family:var(--fd);font-size:17px;line-height:1.32;
  color:var(--ink);text-decoration:none;display:block}
${s('agbody')} .exq-veja a:hover{color:var(--viva)}
${s('agbody')} figure{margin:1.5em 0}
${s('agbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('agbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('agbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('agbody')} th,${s('agbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('agbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--ink)}
@media(max-width:640px){
  ${s('agbody')} table{min-width:0}
  ${s('agbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('agbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('agbody')} table,${s('agbody')} tbody,${s('agbody')} tr,${s('agbody')} th,
  ${s('agbody')} td{display:block;width:auto}
  ${s('agbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    padding:2px 18px 16px;margin-bottom:13px}
  ${s('agbody')} tbody th,${s('agbody')} tbody td{border:0;background:transparent}
  ${s('agbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:400;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('agbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('agbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('agass')}{display:grid;grid-template-columns:76px minmax(0,1fr);gap:17px;align-items:start;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;border-top:3px solid var(--ink)}
${s('agass')} img{width:76px;height:76px;object-fit:cover;background:var(--ph)}
${s('agass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--viva)}
${s('agass')} .nm{display:block;font-family:var(--fd);font-size:22px;margin-top:3px}
${s('agass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('agass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('agass')} .go:hover{text-decoration:underline}
${s('agrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('agrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.11em;color:var(--muted);margin-bottom:8px}

/* ---------- rodape ---------- */
${s('agfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('agcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('agfb')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-size:26px;color:#fff}
${s('agfb')} svg{display:block;height:.92em;width:auto;flex:none;align-self:center}
${s('agfoot')} p{color:${t.footerTx || '#9FB0B7'};text-align:left}
${s('agfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.13em;color:${t.footerTx || '#9FB0B7'};margin-bottom:13px}
${s('agflist')}{display:flex;flex-direction:column;gap:9px}
${s('agflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('agflist')} a:hover{opacity:1;color:var(--viva)}
${s('agfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;color:${t.footerTx || '#9FB0B7'}}
@media(max-width:820px){
  ${s('agcols')}{grid-template-columns:1fr;gap:26px}
  ${s('agfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Vitrine: um retangulo grande e tres pequenos ao lado, que e o proprio arranjo
 * da secao. Sem letra dentro: o nome vem como texto ao lado. */
const AG_SIMB = `<svg viewBox="0 0 30 26" role="img" aria-hidden="true" focusable="false"><rect x="1" y="3" width="15" height="20" fill="var(--marca-1,currentColor)"/><rect x="18" y="3" width="11" height="5" fill="var(--marca-2,currentColor)"/><rect x="18" y="10.5" width="11" height="5" fill="var(--marca-3,currentColor)"/><rect x="18" y="18" width="11" height="5" fill="var(--marca-2,currentColor)"/></svg>`;

const AG_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

const AG_ROMANO = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];

function agHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'agnav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase: a editoria mora em /categoria/<slug>/.
  // H.curl resolve isso; montar o link a mao poe o menu inteiro em 404.
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('agtop')}">
<div class="${c('agin')} ${c('agbar')}">
<a class="${c('agmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:#fff;--marca-2:var(--viva);--marca-3:rgba(255,255,255,.55)">${AG_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('agnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('agham')}" type="button" data-agham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('agbusca')}" href="/busca/">${AG_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-agham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function agFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('agfoot')}"><div class="${c('agin')}">
<div class="${c('agcols')}">
  <div><a class="${c('agfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva);--marca-3:rgba(255,255,255,.5)">${AG_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('agfh')}">Editorias</div><div class="${c('agflist')}">${cats}</div></div>
  <div><div class="${c('agfh')}">A vitrine</div><div class="${c('agflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('agfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* O destaque da vitrine. O `span` da foto tem display:block, senao o
 * aspect-ratio nao aplica e a imagem passa por cima do titulo. */
function agDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('agdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('agfoto')}"><span data-f>${H.pic(a, !!eager)}</span>
<span class="${c('agtarja')}"><span>${H.esc(H.cat(a))}</span></span></span>
<h${n} class="${c('agti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('agdd')}">${H.esc(H.clip(a.dek, 165))}</span>` : ''}
<span class="${c('agdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function agMini(ctx, a, i, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('agmini')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('agnum')}">${AG_ROMANO[i] || (i + 1)}</span>
<span><span class="${c('agkick')}">${H.cat(a)}</span>
<h${n} class="${c('agti')}">${H.esc(a.title)}</h${n}>
<span class="${c('agdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function agItem(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('agitem')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('agfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('agkick')}">${H.cat(a)}</span>
<h${n} class="${c('agti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('agdd')}">${H.esc(H.clip(a.dek, 150))}</span>` : ''}
<span class="${c('agdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function agHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('agabre')}">
<div><span class="${c('agchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('agmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('agfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a vitrine consome 1 + 3; o que sobra vai para a lista, entao a ultima
      // linha nunca fica com buraco
      const lado = resto.slice(0, 3);
      const sobra = resto.slice(3, 6);
      return `<section class="${c('agsec')}">
<div class="${c('agcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('agmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
<div class="${c('agvit')}">${agDestaque(ctx, d, false)}
<div class="${c('aglado')}">${lado.map((a, i) => agMini(ctx, a, i)).join('')}</div></div>
${sobra.length ? `<div class="${c('aglista')}">${sobra.map(a => agItem(ctx, a, false)).join('')}</div>` : ''}
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${agHeader(ctx, menu)}
<main class="${c('agwrap')}"><div class="${c('agin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${agFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function agAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('agass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="76" height="76" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`
 * palavra por palavra logo abaixo dele. */
function agLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('agleg')}">${H.esc(alt)}</p>`;
}

function agArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('agrel')}">
<span class="${c('agrotb')}">Leia também</span>
<div class="${c('aglista')}">${related.slice(0, 3).map(a => agItem(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${agHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('agwrap')}"><div class="${c('agin')}">
<article class="${c('agart')}">
<div class="${c('agcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('agchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('agdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('aghero')}"><span data-f>${H.pic(art, true)}</span></span>
${agLegenda(ctx, art)}` : ''}
<div class="${c('agbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${agAssinatura(ctx, art)}
${rel}
</div></main>
${agFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function agList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  return `${H.head(ctx, meta)}
${agHeader(ctx, menu)}
<main class="${c('agwrap')}"><div class="${c('agin')}">
<section class="${c('agsec')}">
<div class="${c('agcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('agdescr')}">${H.esc(opts.desc)}</p>` : ''}
<div class="${c('aglista')}">${itens.map((a, i) => agItem(ctx, a, i === 0, 2)).join('')}</div>
</section>
</div></main>
${agFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AH, arquetipo CADERNO. Feita para o desassossegada.com.br.
 *
 * ## De onde vem o desenho
 *
 * O nome vem do desassossego, e o acervo preservado e de caderno de revista:
 * entretenimento, dica, moda, saude, casa e beleza. O desenho pega o gesto do
 * **caderno**: cada secao abre com uma **etiqueta em pastilha cheia**, a materia
 * principal vem com a **faixa de imagem por cima do texto**, e as demais viram
 * **linhas com miniatura redonda**.
 *
 * ## O que a diferencia das 33 vizinhas da opengravity
 *
 *   - **miniatura redonda**. Todas as vizinhas usam retangulo com
 *     `aspect-ratio`: a `AD` em retrato, a `AE` e a `AF` deitada, a `AG` mista.
 *     Circulo nao aparece em nenhuma, e e o que mais muda a silhueta da pagina
 *   - **etiqueta de secao em pastilha cheia**, e nao filete, coluna de margem
 *     nem titulo corrido
 *   - **faixa de imagem por cima do texto** na materia principal de cada secao,
 *     em vez de imagem ao lado
 *   - **Bodoni Moda e Sen**: nenhuma das duas aparece nas 79 famílias em uso
 *   - **carvao com rosa-envelhecido**: os acentos das vizinhas sao todos quentes
 *     e saturados, ou frios e vivos. Um rosa dessaturado nao existe na rede
 *   - **sem grade em nenhum caminho**: home, editoria e relacionados sao listas
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal tem permalink PLANO e `categoryBase` ao mesmo tempo.** O
 * artigo mora em `/<slug>/`, na raiz, e o arquivo de editoria em
 * `/categoria/<slug>/`. E o unico par assim da maquina: os outros tem os dois
 * campos casados. Montar qualquer um dos dois a mao quebra metade do site sem
 * aparecer em print. O link de artigo sai de `H.url(a)` e o de editoria de
 * `H.curl(slug)`, sempre.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */

function ahCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#F0E9E6';
  const viva = t.vivid || '#A65A78';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('ahwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.7;-webkit-font-smoothing:antialiased}
${s('ahwrap')} *{box-sizing:border-box}
${s('ahin')}{max-width:${fp.container || '1140px'};margin:0 auto;padding:0 24px;width:100%}
${s('ahwrap')} h1,${s('ahwrap')} h2,${s('ahwrap')} h3,${s('ahwrap')} h4{font-family:var(--fd);
  font-weight:600;letter-spacing:-.006em;line-height:1.18;margin:0}
${s('ahwrap')} a{color:inherit;text-decoration:none}
${s('ahwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('ahtop')}{background:var(--paper);border-bottom:1px solid var(--line)}
${s('ahbar')}{display:flex;align-items:center;gap:18px;padding-block:20px 18px;flex-wrap:wrap}
${s('ahmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:600;font-size:clamp(24px,3vw,33px);letter-spacing:-.01em;color:var(--ink);flex:none}
${s('ahmarca')} svg{display:block;height:.9em;width:auto;flex:none;align-self:center}
${s('ahnav')}{display:flex;gap:13px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('ahnav')} a{font-family:var(--fb);font-size:11px;font-weight:600;letter-spacing:.05em;color:var(--muted);transition:color .2s ease}
${s('ahnav')} a:hover{color:var(--viva)}
${s('ahbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--viva);color:#fff;padding:9px 15px;border-radius:999px;flex:none;margin-left:8px}
${s('ahham')}{display:none;width:46px;height:46px;border:1px solid var(--line);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:999px}
${s('ahham')} i,${s('ahham')} i::before,${s('ahham')} i::after{position:absolute;left:13px;
  width:19px;height:2px;background:var(--ink);content:""}
${s('ahham')} i{top:22px}
${s('ahham')} i::before{top:-6px;left:0}
${s('ahham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('ahmarca')}{font-size:21px;gap:8px}
  ${s('ahbar')}{gap:11px}
  ${s('ahbusca')}{font-size:10px;padding:8px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('ahham')}{display:block;order:2}
  ${s('ahbusca')}{order:3;margin-left:0}
  ${s('ahnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('ahnav')}[data-aberto="1"]{display:flex}
  ${s('ahnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('ahabre')}{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;
  padding-block:42px 36px;border-bottom:1px solid var(--line)}
${s('ahabre')} h2{font-size:clamp(30px,4.3vw,50px);line-height:1.06;margin:13px 0 0;
  letter-spacing:-.018em}
${s('ahabre')} p{font-size:17.5px;line-height:1.62;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('ahmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('ahmm')} b{color:var(--ink);font-weight:700}
${s('ahabre')} ${s('ahfaixa')}{border-radius:${fp.radius === 'sharp' ? '0' : '18px'}}
@media(max-width:820px){${s('ahabre')}{grid-template-columns:1fr;gap:22px;padding-block:28px 24px}}

/* ---------- a secao: etiqueta em pastilha, materia principal e linhas ---------- */
${s('ahsec')}{padding-block:34px;border-bottom:1px solid var(--line)}
${s('ahcab')}{display:flex;align-items:center;justify-content:space-between;gap:16px;
  margin-bottom:20px;flex-wrap:wrap}
/* pastilha cheia: nenhuma vizinha usa etiqueta assim */
${s('ahpast')}{display:inline-block;background:var(--pri);color:var(--sob);border-radius:999px;
  padding:8px 19px}
${s('ahpast')} h1,${s('ahpast')} h2{font-family:var(--fb);font-size:12px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.13em'};color:var(--sob)}
${s('ahmais')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.09em;color:var(--viva);flex:none}
${s('ahmais')}:hover{text-decoration:underline}
${s('ahdescr')}{margin:0 0 18px;font-size:15px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia principal: faixa de imagem por cima do texto */
${s('ahdest')}{display:block;margin-bottom:6px}
${s('ahfaixa')}{display:block;overflow:hidden;background:var(--ph)}
${s('ahfaixa')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '21/9'};overflow:hidden}
${s('ahfaixa')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('ahdest')}:hover ${s('ahfaixa')} [data-f] img{transform:scale(1.03)}
${s('ahdest')} ${s('ahti')}{font-size:28px;margin-top:15px;max-width:24ch}
${s('ahkick')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.13em'};color:var(--viva);
  margin-bottom:6px}
${s('ahti')}{display:block;font-family:var(--fd);font-weight:600;font-size:19px;line-height:1.24;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('ahdd')}{display:block;margin:10px 0 0;font-size:15px;line-height:1.6;color:var(--dek);
  max-width:62ch;text-align:left}
${s('ahdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}

/* linha com miniatura redonda, que e a assinatura desta arquitetura */
${s('ahlista')}{display:block;margin-top:18px}
${s('ahrow')}{display:grid;grid-template-columns:92px minmax(0,1fr);gap:18px;align-items:center;
  padding-block:15px;border-top:1px solid var(--line)}
${s('ahredondo')}{display:block;width:92px;height:92px;border-radius:50%;overflow:hidden;
  background:var(--ph);flex:none}
${s('ahredondo')} [data-f]{display:block;width:92px;height:92px;overflow:hidden;border-radius:50%}
${s('ahredondo')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('ahrow')}:hover ${s('ahredondo')} [data-f] img{transform:scale(1.08)}
${s('ahrow')}:hover ${s('ahti')}{color:var(--viva)}
@media(max-width:680px){
  ${s('ahrow')}{grid-template-columns:66px minmax(0,1fr);gap:14px}
  ${s('ahredondo')},${s('ahredondo')} [data-f]{width:66px;height:66px}
  ${s('ahdest')} ${s('ahti')}{font-size:22px}
  ${s('ahdd')}{display:none}
}

/* ---------- artigo ---------- */
${s('ahart')}{padding-block:30px 8px}
${s('ahcol')}{max-width:${fp.medida || '700px'}}
${s('ahchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.13em'};color:var(--viva)}
${s('ahart')} h1{font-size:clamp(29px,4.1vw,46px);line-height:1.08;margin:13px 0 0;
  letter-spacing:-.018em}
${s('ahdek')}{font-size:19px;line-height:1.56;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('ahhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '870px'}}
${s('ahhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '21/9'};overflow:hidden}
${s('ahhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('ahleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '870px'};line-height:1.5;text-align:left}
${s('ahbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.8;margin-top:26px}
${s('ahbody')} p{margin:0 0 1.15em;text-align:left}
${s('ahbody')} h2{font-family:var(--fd);font-size:27px;font-weight:600;margin:1.75em 0 .5em}
${s('ahbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('ahbody')} ul,${s('ahbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('ahbody')} li{margin:0 0 .45em}
${s('ahbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('ahbody')} a:hover{color:var(--viva)}
${s('ahbody')} img{margin:1.5em 0;background:var(--ph)}
${s('ahbody')} blockquote{margin:1.6em 0;padding:2px 0 2px 24px;border-left:2px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.4;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('ahbody')} .des-veja{margin:2.2em 0;padding:20px 24px 18px;background:var(--wash);
  border-radius:${fp.radius === 'sharp' ? '0' : '16px'}}
${s('ahbody')} .des-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.13em'};color:var(--pri);
  margin:0 0 11px}
${s('ahbody')} .des-veja ul{list-style:none;margin:0;padding:0}
${s('ahbody')} .des-veja li{margin:0;padding:9px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('ahbody')} .des-veja li:first-child{border-top:0;padding-top:0}
${s('ahbody')} .des-veja a{font-family:var(--fd);font-size:17px;line-height:1.32;color:var(--ink);
  text-decoration:none;display:block}
${s('ahbody')} .des-veja a:hover{color:var(--viva)}
${s('ahbody')} figure{margin:1.5em 0}
${s('ahbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('ahbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('ahbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('ahbody')} th,${s('ahbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('ahbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--ink)}
@media(max-width:640px){
  ${s('ahbody')} table{min-width:0}
  ${s('ahbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('ahbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('ahbody')} table,${s('ahbody')} tbody,${s('ahbody')} tr,${s('ahbody')} th,
  ${s('ahbody')} td{display:block;width:auto}
  ${s('ahbody')} tbody tr{background:var(--surf);border:1px solid var(--line);border-radius:14px;
    padding:2px 18px 16px;margin-bottom:13px}
  ${s('ahbody')} tbody th,${s('ahbody')} tbody td{border:0;background:transparent}
  ${s('ahbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:600;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('ahbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('ahbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('ahass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;border-top:1px solid var(--line)}
${s('ahass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:50%}
${s('ahass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.13em;color:var(--viva)}
${s('ahass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:600;margin-top:3px}
${s('ahass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('ahass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('ahass')} .go:hover{text-decoration:underline}
${s('ahrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('ahrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.12em;color:var(--muted);margin-bottom:8px}

/* ---------- rodape ---------- */
${s('ahfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('ahcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('ahfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:600;font-size:26px;color:#fff}
${s('ahfb')} svg{display:block;height:.9em;width:auto;flex:none;align-self:center}
${s('ahfoot')} p{color:${t.footerTx || '#B3A7A4'};text-align:left}
${s('ahfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:${t.footerTx || '#B3A7A4'};margin-bottom:13px}
${s('ahflist')}{display:flex;flex-direction:column;gap:9px}
${s('ahflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('ahflist')} a:hover{opacity:1;color:var(--viva)}
${s('ahfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;color:${t.footerTx || '#B3A7A4'}}
@media(max-width:820px){
  ${s('ahcols')}{grid-template-columns:1fr;gap:26px}
  ${s('ahfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Caderno: tres circulos de tamanhos diferentes, que e o proprio gesto da lista.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AH_SIMB = `<svg viewBox="0 0 30 26" role="img" aria-hidden="true" focusable="false"><circle cx="8" cy="13" r="7" fill="var(--marca-1,currentColor)"/><circle cx="19" cy="13" r="5" fill="var(--marca-2,currentColor)"/><circle cx="27" cy="13" r="3" fill="var(--marca-3,currentColor)"/></svg>`;

const AH_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function ahHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'ahnav-' + (site.slug || 'p');
  // 🔴 permalink plano E categoryBase: o artigo mora em /<slug>/ e a editoria em
  // /categoria/<slug>/. H.curl resolve a editoria; montar a mao poe o menu em 404.
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('ahtop')}">
<div class="${c('ahin')} ${c('ahbar')}">
<a class="${c('ahmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--ink);--marca-2:var(--viva);--marca-3:var(--pri)">${AH_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('ahnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('ahham')}" type="button" data-ahham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('ahbusca')}" href="/busca/">${AH_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-ahham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function ahFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('ahfoot')}"><div class="${c('ahin')}">
<div class="${c('ahcols')}">
  <div><a class="${c('ahfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva);--marca-3:rgba(255,255,255,.5)">${AH_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('ahfh')}">Editorias</div><div class="${c('ahflist')}">${cats}</div></div>
  <div><div class="${c('ahfh')}">O caderno</div><div class="${c('ahflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('ahfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: faixa de imagem por cima do texto. O `span` da
 * faixa tem display:block, senao o aspect-ratio nao aplica. */
function ahDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('ahdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('ahfaixa')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('ahkick')}" style="margin-top:14px">${H.cat(a)}</span>
<h${n} class="${c('ahti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('ahdd')}">${H.esc(H.clip(a.dek, 175))}</span>` : ''}
<span class="${c('ahdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

/* A linha com miniatura redonda. */
function ahLinha(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('ahrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('ahredondo')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('ahkick')}">${H.cat(a)}</span>
<h${n} class="${c('ahti')}">${H.esc(a.title)}</h${n}>
<span class="${c('ahdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function ahHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('ahabre')}">
<div><span class="${c('ahchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('ahmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('ahfaixa')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // lista, e nao grade: a ultima linha nunca fica com buraco
      return `<section class="${c('ahsec')}">
<div class="${c('ahcab')}"><span class="${c('ahpast')}"><h2>${H.esc(nome)}</h2></span>
<a class="${c('ahmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${ahDestaque(ctx, d, false)}
<div class="${c('ahlista')}">${resto.slice(0, 4).map(a => ahLinha(ctx, a, false)).join('')}</div>
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${ahHeader(ctx, menu)}
<main class="${c('ahwrap')}"><div class="${c('ahin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${ahFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function ahAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('ahass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function ahLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('ahleg')}">${H.esc(alt)}</p>`;
}

function ahArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('ahrel')}">
<span class="${c('ahrotb')}">Leia também</span>
<div class="${c('ahlista')}">${related.slice(0, 3).map(a => ahLinha(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${ahHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('ahwrap')}"><div class="${c('ahin')}">
<article class="${c('ahart')}">
<div class="${c('ahcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('ahchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('ahdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('ahhero')}"><span data-f>${H.pic(art, true)}</span></span>
${ahLegenda(ctx, art)}` : ''}
<div class="${c('ahbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${ahAssinatura(ctx, art)}
${rel}
</div></main>
${ahFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function ahList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${ahHeader(ctx, menu)}
<main class="${c('ahwrap')}"><div class="${c('ahin')}">
<section class="${c('ahsec')}">
<div class="${c('ahcab')}"><span class="${c('ahpast')}"><h1>${H.esc(opts.title)}</h1></span></div>
${opts.desc ? `<p class="${c('ahdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? ahDestaque(ctx, primeiro, true, 2) : ''}
<div class="${c('ahlista')}">${resto.map(a => ahLinha(ctx, a, false, 2)).join('')}</div>
</section>
</div></main>
${ahFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AI, arquetipo BALCAO. Feita para o oiempreendedores.com.br.
 *
 * ## De onde vem o desenho
 *
 * O nome do portal e sobre quem empreende, e o acervo preservado e de balcao:
 * entretenimento, marketing, negocios, saude e dica pratica. O desenho pega o
 * gesto do **balcao de loja**: cada secao abre com o nome da editoria sob um
 * **filete grosso**, a materia principal vem com **texto a esquerda e imagem a
 * direita**, e as demais viram **linhas numeradas**, com o ordinal grande em
 * serifa a esquerda e a miniatura quadrada a direita.
 *
 * ## O que a diferencia das 34 vizinhas da opengravity
 *
 *   - **ordinal grande como ancora visual da linha** (01, 02, 03). Nenhuma
 *     vizinha numera item: a `AF` conta verbetes no cabecalho da secao, o que e
 *     outra coisa. E o ordinal que muda a leitura, porque vira indice
 *   - **miniatura a DIREITA do texto**, e nao a esquerda como em todas as outras
 *   - **filete grosso sob o nome da editoria**, em vez de pastilha cheia (`AH`),
 *     coluna de margem (`AE`), titulo corrido com regua (`AF`) ou etiqueta
 *     enviesada (`AG`)
 *   - **Fraunces e Archivo**: nenhuma das duas aparece nas 84 familias em uso
 *   - **bordo com dourado**: nenhuma vizinha usa vinho. Os acentos da rede sao
 *     ambar, oliva, coral e rosa
 *   - **quadrado de canto vivo** na miniatura, contra o circulo da `AH` e o
 *     retangulo deitado das demais
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal tem `flatUrl: false` E `categoryBase: "categoria"`.** O artigo
 * mora em `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`.
 * Os dois nao coincidem: montar o link de editoria como `/<slug>/` poe **o menu
 * do topo inteiro, o do rodape e o chapeu de cada artigo** em 404, e isso nao
 * aparece em print nenhum, porque o menu continua bonito. Editoria sai de
 * `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ E como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * **diretorio sem indice** e o nginx responde 403 nele: o vhost precisa do 301
 * de cada editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - o ordinal e decorativo: vai com aria-hidden, para o leitor de tela nao
 *     ouvir "zero um" antes de cada titulo
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */

function aiCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#F3EBE2';
  const viva = t.vivid || '#C9A227';
  const canto = fp.radius === 'sharp' ? '0' : '3px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('aiwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.68;-webkit-font-smoothing:antialiased}
${s('aiwrap')} *{box-sizing:border-box}
${s('aiin')}{max-width:${fp.container || '1160px'};margin:0 auto;padding:0 24px;width:100%}
${s('aiwrap')} h1,${s('aiwrap')} h2,${s('aiwrap')} h3,${s('aiwrap')} h4{font-family:var(--fd);
  font-weight:600;letter-spacing:-.008em;line-height:1.16;margin:0}
${s('aiwrap')} a{color:inherit;text-decoration:none}
${s('aiwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('aitop')}{background:var(--paper);border-bottom:2px solid var(--ink)}
${s('aibar')}{display:flex;align-items:center;gap:18px;padding-block:19px 17px;flex-wrap:wrap}
${s('aimarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:clamp(23px,3vw,32px);letter-spacing:-.015em;color:var(--ink);flex:none}
${s('aimarca')} svg{display:block;height:.82em;width:auto;flex:none;align-self:center}
${s('ainav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('ainav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.045em;color:var(--dek);transition:color .2s ease}
${s('ainav')} a:hover{color:var(--pri)}
${s('aibusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--ink);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('aibusca')}:hover{background:var(--pri)}
${s('aiham')}{display:none;width:46px;height:46px;border:2px solid var(--ink);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('aiham')} i,${s('aiham')} i::before,${s('aiham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--ink);content:""}
${s('aiham')} i{top:21px}
${s('aiham')} i::before{top:-6px;left:0}
${s('aiham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('aimarca')}{font-size:21px;gap:8px}
  ${s('aibar')}{gap:11px}
  ${s('aibusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('aiham')}{display:block;order:2}
  ${s('aibusca')}{order:3;margin-left:0}
  ${s('ainav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('ainav')}[data-aberto="1"]{display:flex}
  ${s('ainav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('aiabre')}{display:grid;grid-template-columns:1.05fr 1fr;gap:44px;align-items:center;
  padding-block:40px 34px;border-bottom:1px solid var(--line)}
${s('aiabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.04;margin:12px 0 0;
  letter-spacing:-.022em}
${s('aiabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('aimm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('aimm')} b{color:var(--ink);font-weight:700}
${s('aifoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('aifoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '4/3'};overflow:hidden}
${s('aifoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('aiabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: nome da editoria sob filete grosso ---------- */
${s('aisec')}{padding-block:34px}
${s('aisec')}+${s('aisec')}{border-top:1px solid var(--line)}
${s('aicab')}{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;
  margin-bottom:22px;flex-wrap:wrap;border-bottom:4px solid var(--ink);padding-bottom:9px}
${s('aicab')} h1,${s('aicab')} h2{font-family:var(--fd);font-size:clamp(22px,2.7vw,29px);
  font-weight:700;letter-spacing:-.015em;color:var(--ink)}
${s('aimais')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.09em;color:var(--pri);flex:none;padding-bottom:3px}
${s('aimais')}:hover{text-decoration:underline}
${s('aidescr')}{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia principal da secao: texto a esquerda, imagem a direita */
${s('aidest')}{display:grid;grid-template-columns:1fr .82fr;gap:30px;align-items:center;
  padding-bottom:22px}
${s('aidest')} ${s('aiti')}{font-size:clamp(23px,2.6vw,30px);line-height:1.14;margin-top:9px}
${s('aikick')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--pri)}
${s('aiti')}{display:block;font-family:var(--fd);font-weight:600;font-size:19.5px;line-height:1.22;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('aidd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.6;color:var(--dek);
  max-width:56ch;text-align:left}
${s('aidt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('aidest')}:hover ${s('aiti')}{color:var(--pri)}
${s('aidest')}:hover ${s('aifoto')} [data-f] img{transform:scale(1.03)}
@media(max-width:820px){${s('aidest')}{grid-template-columns:1fr;gap:18px}}

/* linha numerada: ordinal grande a esquerda, miniatura quadrada a direita.
   E a assinatura desta arquitetura. */
${s('ailista')}{display:block}
${s('airow')}{display:grid;grid-template-columns:58px minmax(0,1fr) 108px;gap:18px;
  align-items:center;padding-block:15px;border-top:1px solid var(--line)}
${s('ainum')}{display:block;font-family:var(--fd);font-size:30px;font-weight:600;
  line-height:1;color:var(--viva);letter-spacing:-.03em;font-variant-numeric:tabular-nums}
${s('aiquad')}{display:block;width:108px;overflow:hidden;background:var(--ph);
  border-radius:${canto}}
${s('aiquad')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '4/3'};overflow:hidden}
${s('aiquad')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('airow')}:hover ${s('aiquad')} [data-f] img{transform:scale(1.07)}
${s('airow')}:hover ${s('aiti')}{color:var(--pri)}
@media(max-width:680px){
  ${s('airow')}{grid-template-columns:38px minmax(0,1fr) 78px;gap:13px}
  ${s('ainum')}{font-size:21px}
  ${s('aiquad')}{width:78px}
  ${s('aidd')}{display:none}
}

/* ---------- artigo ---------- */
${s('aiart')}{padding-block:30px 8px}
${s('aicol')}{max-width:${fp.medida || '710px'}}
${s('aichap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--pri)}
${s('aiart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.06;margin:13px 0 0;
  letter-spacing:-.022em}
${s('aidek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('aihero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('aihero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '4/3'};overflow:hidden}
${s('aihero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('aileg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('aibody')}{max-width:${fp.medida || '710px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('aibody')} p{margin:0 0 1.15em;text-align:left}
${s('aibody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.015em}
${s('aibody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('aibody')} ul,${s('aibody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('aibody')} li{margin:0 0 .45em}
${s('aibody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('aibody')} a:hover{color:var(--viva)}
${s('aibody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('aibody')} blockquote{margin:1.6em 0;padding:14px 0 14px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('aibody')} .oie-veja{margin:2.2em 0;padding:20px 24px 18px;background:var(--wash);
  border-radius:${canto};border-left:4px solid var(--pri)}
${s('aibody')} .oie-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--pri);
  margin:0 0 11px}
${s('aibody')} .oie-veja ul{list-style:none;margin:0;padding:0}
${s('aibody')} .oie-veja li{margin:0;padding:9px 0;border-top:1px solid rgba(0,0,0,.09)}
${s('aibody')} .oie-veja li:first-child{border-top:0;padding-top:0}
${s('aibody')} .oie-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('aibody')} .oie-veja a:hover{color:var(--pri)}
${s('aibody')} figure{margin:1.5em 0}
${s('aibody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('aibody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('aibody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('aibody')} th,${s('aibody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('aibody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:3px solid var(--ink)}
@media(max-width:640px){
  ${s('aibody')} table{min-width:0}
  ${s('aibody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('aibody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('aibody')} table,${s('aibody')} tbody,${s('aibody')} tr,${s('aibody')} th,
  ${s('aibody')} td{display:block;width:auto}
  ${s('aibody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('aibody')} tbody th,${s('aibody')} tbody td{border:0;background:transparent}
  ${s('aibody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('aibody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('aibody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('aiass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '710px'};margin:34px 0 0;padding-top:22px;border-top:3px solid var(--ink)}
${s('aiass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('aiass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--pri)}
${s('aiass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('aiass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('aiass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('aiass')} .go:hover{text-decoration:underline}
${s('airel')}{max-width:${fp.medida || '710px'};padding-block:26px 10px}
${s('airotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.12em;color:var(--muted);
  border-bottom:3px solid var(--ink);padding-bottom:7px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('aifoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('aicols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('aifb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('aifb')} svg{display:block;height:.82em;width:auto;flex:none;align-self:center}
${s('aifoot')} p{color:${t.footerTx || '#B9AAA2'};text-align:left}
${s('aifh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:${t.footerTx || '#B9AAA2'};margin-bottom:13px}
${s('aiflist')}{display:flex;flex-direction:column;gap:9px}
${s('aiflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('aiflist')} a:hover{opacity:1;color:var(--viva)}
${s('aifim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#B9AAA2'}}
@media(max-width:820px){
  ${s('aicols')}{grid-template-columns:1fr;gap:26px}
  ${s('aifoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Balcao: dois quadrados deslocados, um cheio e um vazado, que e o gesto de
 * duas peças sobre o balcao. Sem letra dentro: o nome vem como texto ao lado. */
const AI_SIMB = `<svg viewBox="0 0 30 26" role="img" aria-hidden="true" focusable="false"><rect x="1" y="5" width="15" height="15" fill="var(--marca-1,currentColor)"/><rect x="14.5" y="9.5" width="14" height="14" fill="none" stroke="var(--marca-2,currentColor)" stroke-width="3"/></svg>`;

const AI_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function aiHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'ainav-' + (site.slug || 'p');
  // 🔴 flatUrl false COM categoryBase: o artigo mora em /<editoria>/<slug>/ e a
  // editoria em /categoria/<slug>/. H.curl resolve a editoria; montar a mao poe
  // o menu inteiro em 404 sem aparecer em print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aitop')}">
<div class="${c('aiin')} ${c('aibar')}">
<a class="${c('aimarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${AI_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('ainav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('aiham')}" type="button" data-aiham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('aibusca')}" href="/busca/">${AI_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-aiham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function aiFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('aifoot')}"><div class="${c('aiin')}">
<div class="${c('aicols')}">
  <div><a class="${c('aifb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${AI_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('aifh')}">Editorias</div><div class="${c('aiflist')}">${cats}</div></div>
  <div><div class="${c('aifh')}">O portal</div><div class="${c('aiflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('aifim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: texto a esquerda, imagem a direita. O `span` da
 * foto tem display:block, senao o aspect-ratio nao aplica. */
function aiDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aidest')} ${c('reveal')}" href="${H.url(a)}">
<span><span class="${c('aikick')}">${H.cat(a)}</span>
<h${n} class="${c('aiti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('aidd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('aidt')}">${H.esc(H.dateShort(a.date))}</span></span>
<span class="${c('aifoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
</a>`;
}

/* A linha numerada: ordinal a esquerda, miniatura quadrada a direita.
 * O ordinal e decorativo, entao vai com aria-hidden. */
function aiLinha(ctx, a, i, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  const ord = String(i + 1).padStart(2, '0');
  return `<a class="${c('airow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('ainum')}" aria-hidden="true">${ord}</span>
<span><span class="${c('aikick')}">${H.cat(a)}</span>
<h${n} class="${c('aiti')}">${H.esc(a.title)}</h${n}>
<span class="${c('aidt')}">${H.esc(H.dateShort(a.date))}</span></span>
<span class="${c('aiquad')}"><span data-f>${H.pic(a, !!eager)}</span></span>
</a>`;
}

function aiHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('aiabre')}">
<div><span class="${c('aichap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('aimm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('aifoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // lista numerada, e nao grade: a ultima linha nunca fica com buraco
      return `<section class="${c('aisec')}">
<div class="${c('aicab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('aimais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${aiDestaque(ctx, d, false)}
<div class="${c('ailista')}">${resto.slice(0, 4).map((a, i) => aiLinha(ctx, a, i, false)).join('')}</div>
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${aiHeader(ctx, menu)}
<main class="${c('aiwrap')}"><div class="${c('aiin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${aiFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function aiAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('aiass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function aiLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('aileg')}">${H.esc(alt)}</p>`;
}

function aiArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('airel')}">
<span class="${c('airotb')}">Leia também</span>
<div class="${c('ailista')}">${related.slice(0, 3).map((a, i) => aiLinha(ctx, a, i, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${aiHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('aiwrap')}"><div class="${c('aiin')}">
<article class="${c('aiart')}">
<div class="${c('aicol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('aichap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('aidek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('aihero')}"><span data-f>${H.pic(art, true)}</span></span>
${aiLegenda(ctx, art)}` : ''}
<div class="${c('aibody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${aiAssinatura(ctx, art)}
${rel}
</div></main>
${aiFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function aiList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${aiHeader(ctx, menu)}
<main class="${c('aiwrap')}"><div class="${c('aiin')}">
<section class="${c('aisec')}">
<div class="${c('aicab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('aidescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? aiDestaque(ctx, primeiro, true, 2) : ''}
<div class="${c('ailista')}">${resto.map((a, i) => aiLinha(ctx, a, i, false, 2)).join('')}</div>
</section>
</div></main>
${aiFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AJ, arquetipo GAZETA. Feita para o jornaldobairroalto.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal de bairro, e o acervo preservado e de servico: dica,
 * saude, negocio local, casa e entretenimento. O desenho pega o gesto da
 * **gazeta**: cada secao abre com **fio duplo** e o nome em versalete, as duas
 * materias principais vem **lado a lado separadas por um fio vertical**, e as
 * demais viram **teletipo**, com a data numa coluna a esquerda e **sem
 * miniatura nenhuma**.
 *
 * ## O que a diferencia das 35 vizinhas da opengravity
 *
 *   - **lista sem miniatura**, com coluna de data a esquerda. Todas as 35 usam
 *     imagem na lista: retangulo, circulo ou quadrado. Tirar a imagem muda a
 *     silhueta da pagina inteira, e e o que um jornal de bairro faz
 *   - **duas materias lado a lado com fio vertical** na abertura da secao, em
 *     vez de uma materia principal so
 *   - **fio duplo sobre o nome da secao**, contra o filete grosso da `AI`, a
 *     pastilha da `AH`, a regua da `AF` e a coluna de margem da `AE`
 *   - **Alegreya e Commissioner**: nenhuma das duas aparece nas 88 familias em
 *     uso na maquina
 *   - **musgo com telha**: nao existe verde escuro entre as 22 paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **A origem tem `category_base` VAZIO, e vazio significa `category`, em
 * ingles.** O arquivo de editoria mora em `/category/<slug>/`, e nao em
 * `/categoria/<slug>/`. Cravar "categoria" por analogia com os vizinhos poe a
 * editoria inteira em 404. O `categoryBase` deste portal e `category`, e todo
 * link de editoria sai de `H.curl(slug)`.
 *
 * ⚠️ Como o artigo mora em `/<editoria>/<slug>/`, `/<editoria>/` vira diretorio
 * sem indice e o nginx responde 403: o vhost precisa do 301 de cada editoria e
 * do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a grade de duas materias vira uma coluna abaixo de 820px, e o fio vertical
 *     vira fio horizontal, para nao sobrar risco solto
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */

function ajCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('ajwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('ajwrap')} *{box-sizing:border-box}
${s('ajin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('ajwrap')} h1,${s('ajwrap')} h2,${s('ajwrap')} h3,${s('ajwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('ajwrap')} a{color:inherit;text-decoration:none}
${s('ajwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('ajtop')}{background:var(--paper);border-bottom:3px double var(--ink)}
${s('ajbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('ajmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('ajmarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('ajnav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('ajnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('ajnav')} a:hover{color:var(--viva)}
${s('ajbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('ajbusca')}:hover{background:var(--viva)}
${s('ajham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('ajham')} i,${s('ajham')} i::before,${s('ajham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('ajham')} i{top:21px}
${s('ajham')} i::before{top:-6px;left:0}
${s('ajham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('ajmarca')}{font-size:21px;gap:8px}
  ${s('ajbar')}{gap:11px}
  ${s('ajbusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('ajham')}{display:block;order:2}
  ${s('ajbusca')}{order:3;margin-left:0}
  ${s('ajnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('ajnav')}[data-aberto="1"]{display:flex}
  ${s('ajnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('ajabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('ajabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('ajabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('ajmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('ajmm')} b{color:var(--ink);font-weight:700}
${s('ajfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('ajfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('ajfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('ajabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: fio duplo e nome em versalete ---------- */
${s('ajsec')}{padding-block:32px}
${s('ajsec')}+${s('ajsec')}{border-top:1px solid var(--line)}
${s('ajcab')}{display:flex;align-items:baseline;justify-content:space-between;gap:16px;
  margin-bottom:22px;flex-wrap:wrap;border-top:4px double var(--ink);padding-top:10px}
${s('ajcab')} h1,${s('ajcab')} h2{font-family:var(--fb);font-size:13px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri)}
${s('ajmais')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.09em;color:var(--viva);flex:none}
${s('ajmais')}:hover{text-decoration:underline}
${s('ajdescr')}{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* duas materias lado a lado, com fio vertical entre elas */
${s('ajduas')}{display:grid;grid-template-columns:1fr 1fr;gap:30px;padding-bottom:24px}
${s('ajduas')}>*+*{border-left:1px solid var(--line);padding-left:30px}
${s('ajdest')}{display:block}
${s('ajdest')} ${s('ajti')}{font-size:clamp(20px,2.2vw,25px);line-height:1.18;margin-top:11px}
${s('ajkick')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--viva)}
${s('ajti')}{display:block;font-family:var(--fd);font-weight:700;font-size:19.5px;line-height:1.2;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('ajdd')}{display:block;margin:10px 0 0;font-size:15.5px;line-height:1.58;color:var(--dek);
  max-width:52ch;text-align:left}
${s('ajdt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('ajdest')}:hover ${s('ajti')}{color:var(--pri)}
${s('ajdest')}:hover ${s('ajfoto')} [data-f] img{transform:scale(1.03)}
@media(max-width:820px){
  ${s('ajduas')}{grid-template-columns:1fr;gap:24px}
  /* o fio vertical vira horizontal, senao sobra um risco solto na coluna */
  ${s('ajduas')}>*+*{border-left:0;padding-left:0;border-top:1px solid var(--line);padding-top:24px}
}

/* teletipo: data na coluna da esquerda e NENHUMA miniatura.
   E a assinatura desta arquitetura: as 35 vizinhas todas usam imagem na lista. */
${s('ajlista')}{display:block;border-top:1px solid var(--ink)}
${s('ajrow')}{display:grid;grid-template-columns:96px minmax(0,1fr);gap:20px;
  align-items:baseline;padding-block:14px;border-bottom:1px solid var(--line)}
${s('ajquando')}{display:block;font-family:var(--fb);font-size:11.5px;font-weight:700;
  letter-spacing:.06em;color:var(--viva);
  font-variant-numeric:tabular-nums;padding-top:3px}
${s('ajrow')}:hover ${s('ajti')}{color:var(--pri)}
${s('ajrow')} ${s('ajti')}{font-size:18px}
${s('ajrow')} ${s('ajkick')}{color:var(--muted);margin-bottom:4px}
@media(max-width:680px){
  ${s('ajrow')}{grid-template-columns:1fr;gap:4px}
  ${s('ajquando')}{padding-top:0}
  ${s('ajdd')}{display:none}
}

/* ---------- artigo ---------- */
${s('ajart')}{padding-block:30px 8px}
${s('ajcol')}{max-width:${fp.medida || '700px'}}
${s('ajchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--viva)}
${s('ajart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('ajdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('ajhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('ajhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('ajhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('ajleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('ajbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('ajbody')} p{margin:0 0 1.15em;text-align:left}
${s('ajbody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('ajbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('ajbody')} ul,${s('ajbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('ajbody')} li{margin:0 0 .45em}
${s('ajbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('ajbody')} a:hover{color:var(--viva)}
${s('ajbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('ajbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:3px double var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('ajbody')} .jba-veja{margin:2.2em 0;padding:18px 0 16px;border-top:4px double var(--ink);
  border-bottom:1px solid var(--line)}
${s('ajbody')} .jba-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('ajbody')} .jba-veja ul{list-style:none;margin:0;padding:0}
${s('ajbody')} .jba-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('ajbody')} .jba-veja li:first-child{border-top:0;padding-top:0}
${s('ajbody')} .jba-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('ajbody')} .jba-veja a:hover{color:var(--viva)}
${s('ajbody')} figure{margin:1.5em 0}
${s('ajbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('ajbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('ajbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('ajbody')} th,${s('ajbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('ajbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:3px double var(--ink)}
@media(max-width:640px){
  ${s('ajbody')} table{min-width:0}
  ${s('ajbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('ajbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('ajbody')} table,${s('ajbody')} tbody,${s('ajbody')} tr,${s('ajbody')} th,
  ${s('ajbody')} td{display:block;width:auto}
  ${s('ajbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('ajbody')} tbody th,${s('ajbody')} tbody td{border:0;background:transparent}
  ${s('ajbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('ajbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('ajbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('ajass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:4px double var(--ink)}
${s('ajass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('ajass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('ajass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('ajass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('ajass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('ajass')} .go:hover{text-decoration:underline}
${s('ajrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('ajrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:4px double var(--ink);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('ajfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('ajcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('ajfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('ajfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('ajfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('ajfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('ajflist')}{display:flex;flex-direction:column;gap:9px}
${s('ajflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('ajflist')} a:hover{opacity:1;color:var(--viva)}
${s('ajfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('ajcols')}{grid-template-columns:1fr;gap:26px}
  ${s('ajfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Gazeta: duas colunas com um fio entre elas, que e o proprio arranjo da secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AJ_SIMB = `<svg viewBox="0 0 30 26" role="img" aria-hidden="true" focusable="false"><rect x="1" y="5" width="11" height="16" fill="var(--marca-1,currentColor)"/><rect x="14.5" y="5" width="2" height="16" fill="var(--marca-2,currentColor)"/><rect x="19" y="5" width="10" height="16" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2.5"/></svg>`;

const AJ_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function ajHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'ajnav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('ajtop')}">
<div class="${c('ajin')} ${c('ajbar')}">
<a class="${c('ajmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${AJ_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('ajnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('ajham')}" type="button" data-ajham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('ajbusca')}" href="/busca/">${AJ_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-ajham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function ajFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('ajfoot')}"><div class="${c('ajin')}">
<div class="${c('ajcols')}">
  <div><a class="${c('ajfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${AJ_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('ajfh')}">Editorias</div><div class="${c('ajflist')}">${cats}</div></div>
  <div><div class="${c('ajfh')}">O jornal</div><div class="${c('ajflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('ajfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* Uma das duas materias de abertura da secao: imagem em cima, texto abaixo. O
 * `span` da foto tem display:block, senao o aspect-ratio nao aplica. */
function ajDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('ajdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('ajfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('ajkick')}" style="margin-top:13px;display:block">${H.cat(a)}</span>
<h${n} class="${c('ajti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('ajdd')}">${H.esc(H.clip(a.dek, 165))}</span>` : ''}
<span class="${c('ajdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

/* O teletipo: data na coluna da esquerda e nenhuma miniatura. */
function ajLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('ajrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('ajquando')}">${H.esc(H.dateShort(a.date))}</span>
<span><span class="${c('ajkick')}">${H.cat(a)}</span>
<h${n} class="${c('ajti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('ajdd')}">${H.esc(H.clip(a.dek, 150))}</span>` : ''}</span>
</a>`;
}

function ajHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('ajabre')}">
<div><span class="${c('ajchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('ajmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('ajfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const duas = v.slice(0, 2);
      const resto = v.slice(2, 7);
      return `<section class="${c('ajsec')}">
<div class="${c('ajcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('ajmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
<div class="${c('ajduas')}">${duas.map(a => ajDestaque(ctx, a, false)).join('')}</div>
${resto.length ? `<div class="${c('ajlista')}">${resto.map(a => ajLinha(ctx, a)).join('')}</div>` : ''}
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${ajHeader(ctx, menu)}
<main class="${c('ajwrap')}"><div class="${c('ajin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${ajFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function ajAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('ajass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function ajLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('ajleg')}">${H.esc(alt)}</p>`;
}

function ajArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('ajrel')}">
<span class="${c('ajrotb')}">Leia também</span>
<div class="${c('ajlista')}">${related.slice(0, 3).map(a => ajLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${ajHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('ajwrap')}"><div class="${c('ajin')}">
<article class="${c('ajart')}">
<div class="${c('ajcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('ajchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('ajdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('ajhero')}"><span data-f>${H.pic(art, true)}</span></span>
${ajLegenda(ctx, art)}` : ''}
<div class="${c('ajbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${ajAssinatura(ctx, art)}
${rel}
</div></main>
${ajFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function ajList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const duas = itens.slice(0, 2);
  const resto = itens.slice(2);
  return `${H.head(ctx, meta)}
${ajHeader(ctx, menu)}
<main class="${c('ajwrap')}"><div class="${c('ajin')}">
<section class="${c('ajsec')}">
<div class="${c('ajcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('ajdescr')}">${H.esc(opts.desc)}</p>` : ''}
${duas.length ? `<div class="${c('ajduas')}">${duas.map((a, i) => ajDestaque(ctx, a, i === 0, 2)).join('')}</div>` : ''}
${resto.length ? `<div class="${c('ajlista')}">${resto.map(a => ajLinha(ctx, a, 2)).join('')}</div>` : ''}
</section>
</div></main>
${ajFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AK, arquetipo BOLETIM. Feita para o folhadonoroeste.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal regional do Noroeste, e o acervo preservado ficou
 * concentrado em entretenimento, dica e saude. O desenho pega o gesto do
 * **boletim**: cada secao e uma **faixa de fundo cheio**, alternando papel e
 * areia, a materia principal vem com a **imagem a ESQUERDA** e o texto a
 * direita, e as demais viram **duas colunas de itens com filete vertical**, cada
 * um com miniatura quadrada pequena.
 *
 * ## O que a diferencia das 36 vizinhas da opengravity
 *
 *   - **faixa de secao com fundo cheio, alternando**. Todas as 36 usam fundo
 *     unico com filete ou pastilha separando. Alternar o fundo da secao inteira
 *     muda a silhueta da pagina a distancia, que e o que primeiro se ve
 *   - **imagem a ESQUERDA na materia principal**. A `AE`, a `AG`, a `AI` e a
 *     `AJ` poem a imagem a direita ou por cima; nenhuma espelha
 *   - **lista em duas colunas**, e nao em coluna unica
 *   - **Vollkorn e Cabin**: nenhuma das duas aparece nas 90 familias em uso
 *   - **marinho com milho**: nao existe azul-marinho com amarelo entre as 23
 *     paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a faixa de fundo sangra ate a borda da tela, mas o conteudo continua no
 *     contentor: fundo cheio nao pode empurrar o texto para a borda
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */


function akCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('akwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('akwrap')} *{box-sizing:border-box}
${s('akin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('akwrap')} h1,${s('akwrap')} h2,${s('akwrap')} h3,${s('akwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('akwrap')} a{color:inherit;text-decoration:none}
${s('akwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('aktop')}{background:var(--paper);border-bottom:5px solid var(--pri)}
${s('akbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('akmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('akmarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('akmarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('akmarca')} img{height:31px}}
${s('akfb')} img{display:block;height:34px;width:auto}
${s('aknav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('aknav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('aknav')} a:hover{color:var(--tinta)}
${s('akbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('akbusca')}:hover{background:var(--viva)}
${s('akham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('akham')} i,${s('akham')} i::before,${s('akham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('akham')} i{top:21px}
${s('akham')} i::before{top:-6px;left:0}
${s('akham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('akmarca')}{font-size:21px;gap:8px}
  ${s('akbar')}{gap:11px}
  ${s('akbusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('akham')}{display:block;order:2}
  ${s('akbusca')}{order:3;margin-left:0}
  ${s('aknav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('aknav')}[data-aberto="1"]{display:flex}
  ${s('aknav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('akabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('akabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('akabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('akmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('akmm')} b{color:var(--ink);font-weight:700}
${s('akfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('akfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('akfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('akabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: faixa de fundo cheio, alternando ---------- */
/* ⚠️ a faixa sangra ate a borda da tela, mas o conteudo continua dentro do
   contentor: fundo cheio nao pode empurrar o texto para a borda no celular */
${s('aksec')}{padding-block:38px;background:var(--paper)}
/* a faixa cheia: uma secao sim, uma nao, em marinho. O bege lavado de antes
   quase nao aparecia, e a marca pede contraste */
${s('aksec')}[data-par="1"]{background:var(--pri);color:var(--sob)}
${s('aksec')}[data-par="1"] ${s('akcab')} h1,
${s('aksec')}[data-par="1"] ${s('akcab')} h2{color:var(--sob)}
${s('aksec')}[data-par="1"] ${s('akcab')} h1::before,
${s('aksec')}[data-par="1"] ${s('akcab')} h2::before{background:var(--viva)}
/* sobre o marinho a lima volta a ser texto: ali ela da 13,1:1 */
${s('aksec')}[data-par="1"] ${s('akmais')},
${s('aksec')}[data-par="1"] ${s('akkick')}{color:var(--viva)}
${s('aksec')}[data-par="1"] ${s('akti')},
${s('aksec')}[data-par="1"] ${s('akdescr')},
${s('aksec')}[data-par="1"] ${s('akdd')}{color:var(--sob)}
${s('aksec')}[data-par="1"] ${s('akdt')},
${s('aksec')}[data-par="1"] ${s('akrow')} ${s('akkick')}{color:rgba(255,255,255,.66)}
${s('aksec')}[data-par="1"] ${s('akrow')}{border-left-color:rgba(255,255,255,.24);
  border-top-color:rgba(255,255,255,.16)}
${s('aksec')}[data-par="1"] ${s('akrow')}:hover{border-left-color:var(--viva)}
${s('aksec')}[data-par="1"] ${s('akdest')}:hover ${s('akti')},
${s('aksec')}[data-par="1"] ${s('akrow')}:hover ${s('akti')}{color:var(--viva)}
${s('akcab')}{display:flex;align-items:baseline;justify-content:space-between;gap:16px;
  margin-bottom:24px;flex-wrap:wrap}
${s('akcab')} h1,${s('akcab')} h2{font-family:var(--fd);font-size:clamp(21px,2.5vw,27px);
  font-weight:700;letter-spacing:-.012em;color:var(--pri);display:flex;align-items:center;gap:11px}
/* o quadradinho cheio antes do nome, que e o marcador desta arquitetura */
${s('akcab')} h1::before,${s('akcab')} h2::before{content:"";display:block;width:13px;height:13px;
  background:var(--viva);flex:none}
${s('akmais')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.09em;color:var(--tinta);flex:none}
${s('akmais')}:hover{text-decoration:underline}
${s('akdescr')}{margin:0 0 22px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia principal: imagem a ESQUERDA e texto a direita, espelhando as vizinhas */
${s('akdest')}{display:grid;grid-template-columns:.92fr 1fr;gap:30px;align-items:center;
  padding-bottom:26px}
${s('akdest')} ${s('akti')}{font-size:clamp(21px,2.4vw,28px);line-height:1.16;margin-top:9px}
${s('akkick')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.14em'};color:var(--tinta)}
${s('akti')}{display:block;font-family:var(--fd);font-weight:700;font-size:18px;line-height:1.22;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('akdd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.58;color:var(--dek);
  max-width:54ch;text-align:left}
${s('akdt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('akfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('akfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '4/3'};overflow:hidden}
${s('akfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('akdest')}:hover ${s('akti')}{color:var(--pri)}
${s('akdest')}:hover ${s('akfoto')} [data-f] img{transform:scale(1.03)}
@media(max-width:820px){${s('akdest')}{grid-template-columns:1fr;gap:18px}}

/* lista em DUAS colunas, cada item com filete vertical e miniatura pequena */
${s('aklista')}{display:grid;grid-template-columns:1fr 1fr;gap:0 34px;grid-auto-flow:column;grid-template-rows:repeat(var(--l,3),auto)}
${s('akrow')}{display:grid;grid-template-columns:56px minmax(0,1fr);gap:14px;align-items:center;
  padding:13px 0 13px 15px;border-left:3px solid var(--line);
  border-top:1px solid rgba(0,0,0,.07)}
${s('akrow')}:hover{border-left-color:var(--viva)}
${s('akmini')}{display:block;width:56px;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('akmini')} [data-f]{display:block;aspect-ratio:1/1;overflow:hidden}
${s('akmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('akrow')}:hover ${s('akmini')} [data-f] img{transform:scale(1.08)}
${s('akrow')}:hover ${s('akti')}{color:var(--pri)}
${s('akrow')} ${s('akti')}{font-size:16.5px}
${s('akrow')} ${s('akkick')}{color:var(--muted);margin-bottom:3px}
@media(max-width:820px){
  ${s('aklista')}{grid-template-columns:1fr;grid-auto-flow:row;grid-template-rows:none}
}
@media(max-width:680px){
  ${s('akrow')}{grid-template-columns:46px minmax(0,1fr);gap:12px;padding-left:12px}
  ${s('akmini')}{width:46px}
  ${s('akdd')}{display:none}
}

/* ---------- artigo ---------- */
${s('akart')}{padding-block:30px 8px}
${s('akcol')}{max-width:${fp.medida || '700px'}}
${s('akchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
${s('akart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('akdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('akhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('akhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('akhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('akleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('akbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('akbody')} p{margin:0 0 1.15em;text-align:left}
${s('akbody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('akbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('akbody')} ul,${s('akbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('akbody')} li{margin:0 0 .45em}
${s('akbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('akbody')} a:hover{color:var(--tinta)}
${s('akbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('akbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('akbody')} .fnr-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('akbody')} .fnr-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('akbody')} .fnr-veja ul{list-style:none;margin:0;padding:0}
${s('akbody')} .fnr-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('akbody')} .fnr-veja li:first-child{border-top:0;padding-top:0}
${s('akbody')} .fnr-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('akbody')} .fnr-veja a:hover{color:var(--tinta)}
${s('akbody')} figure{margin:1.5em 0}
${s('akbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('akbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('akbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('akbody')} th,${s('akbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('akbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('akbody')} table{min-width:0}
  ${s('akbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('akbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('akbody')} table,${s('akbody')} tbody,${s('akbody')} tr,${s('akbody')} th,
  ${s('akbody')} td{display:block;width:auto}
  ${s('akbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('akbody')} tbody th,${s('akbody')} tbody td{border:0;background:transparent}
  ${s('akbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('akbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('akbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('akass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('akass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('akass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('akass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('akass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('akass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('akass')} .go:hover{text-decoration:underline}
${s('akrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('akrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('akfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('akcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('akfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('akfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('akfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('akfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('akflist')}{display:flex;flex-direction:column;gap:9px}
${s('akflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('akflist')} a:hover{opacity:1;color:var(--viva)}
${s('akfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('akcols')}{grid-template-columns:1fr;gap:26px}
  ${s('akfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AK_SIMB = `<svg viewBox="0 0 30 26" role="img" aria-hidden="true" focusable="false"><rect x="2" y="5" width="26" height="4" fill="var(--marca-1,currentColor)"/><rect x="2" y="11" width="19" height="4" fill="var(--marca-2,currentColor)"/><rect x="2" y="17" width="26" height="4" fill="var(--marca-1,currentColor)"/></svg>`;

const AK_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function akHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aknav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aktop')}">
<div class="${c('akin')} ${c('akbar')}">
<a class="${c('akmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AK_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('aknav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('akham')}" type="button" data-akham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('akbusca')}" href="/busca/">${AK_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-akham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function akFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('akfoot')}"><div class="${c('akin')}">
<div class="${c('akcols')}">
  <div><a class="${c('akfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AK_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('akfh')}">Editorias</div><div class="${c('akflist')}">${cats}</div></div>
  <div><div class="${c('akfh')}">O jornal</div><div class="${c('akflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('akfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function akDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('akdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('akfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('akkick')}">${H.cat(a)}</span>
<h${n} class="${c('akti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('akdd')}">${H.esc(H.clip(a.dek, 170))}</span>` : ''}
<span class="${c('akdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

/* O item da lista de duas colunas: filete vertical e miniatura quadrada. */
function akLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('akrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('akmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('akkick')}">${H.cat(a)}</span>
<h${n} class="${c('akti')}">${H.esc(a.title)}</h${n}>
<span class="${c('akdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function akHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('akabre')}">
<div><span class="${c('akchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('akmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('akfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('aksec')}" data-par="${idx % 2}">
<div class="${c('akin')}">
<div class="${c('akcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('akmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${akDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('aklista')}" style="--l:${Math.ceil(Math.min(resto.length, 6) / 2)}">${resto.slice(0, 6).map(a => akLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${akHeader(ctx, menu)}
<main class="${c('akwrap')}">
<div class="${c('akin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${akFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function akAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('akass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function akLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('akleg')}">${H.esc(alt)}</p>`;
}

function akArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('akrel')}">
<span class="${c('akrotb')}">Leia também</span>
<div class="${c('aklista')}" style="--l:${Math.ceil(Math.min(related.length, 3) / 2)}">${related.slice(0, 3).map(a => akLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${akHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('akwrap')}"><div class="${c('akin')}">
<article class="${c('akart')}">
<div class="${c('akcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('akchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('akdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('akhero')}"><span data-f>${H.pic(art, true)}</span></span>
${akLegenda(ctx, art)}` : ''}
<div class="${c('akbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${akAssinatura(ctx, art)}
${rel}
</div></main>
${akFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function akList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${akHeader(ctx, menu)}
<main class="${c('akwrap')}">
<section class="${c('aksec')}" data-par="0"><div class="${c('akin')}">
<div class="${c('akcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('akdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? akDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('aklista')}" style="--l:${Math.ceil(resto.length / 2)}">${resto.map(a => akLinha(ctx, a, 2)).join('')}</div>` : ''}
</div></section>
</main>
${akFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AL, arquetipo ALMANAQUE. Feita para o diariopernambucano.com.br.
 *
 * ## De onde vem o desenho
 *
 * O acervo preservado e de almanaque: dica, entretenimento, saude, negocio,
 * curso, turismo. O desenho pega esse gesto: cada secao tem o **nome da editoria
 * escrito na VERTICAL**, numa coluna estreita a esquerda, e o conteudo corre a
 * direita dela. A materia principal vem com texto a esquerda e imagem a direita,
 * e as demais viram **duas colunas de itens com miniatura em retrato**.
 *
 * ## O que a diferencia das 37 vizinhas da opengravity
 *
 *   - **nome da editoria na vertical**, com `writing-mode`. Nenhuma das 37 gira
 *     texto: a `AE` tem coluna de margem, mas com o rotulo deitado. E o que mais
 *     muda a pagina de longe, porque cria uma faixa vertical constante
 *   - **miniatura em RETRATO 3/4** na lista, contra o quadrado da `AK`, o
 *     circulo da `AH` e a ausencia de imagem na `AJ`
 *   - **Literata e Rubik**: nenhuma das duas aparece nas 92 familias em uso
 *   - **roxo-tinta com ambar**: nao existe roxo com amarelo entre as 24 paletas
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: true` MAIS `categoryBase: "categoria"`.** O artigo mora em
 * `/<slug>/`, na raiz, e o arquivo de editoria em `/categoria/<slug>/`. E o
 * segundo portal da maquina com esse par. Duas consequencias:
 *
 *   - **nao existe aqui o 403 de diretorio sem indice**: `/dicas/` nunca foi
 *     diretorio de artigo
 *   - ⚠️ **slug podado colide com pagina que o motor regenera**, porque tudo
 *     divide a raiz: `contato`, `politica-de-privacidade` e `termos-de-uso`
 *     precisam ficar fora do 410
 *
 * Editoria sai de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - ⚠️ **a coluna vertical desaparece abaixo de 900px**: texto girado em tela
 *     estreita rouba largura da materia e nao se le
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */

function alCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('alwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('alwrap')} *{box-sizing:border-box}
${s('alin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('alwrap')} h1,${s('alwrap')} h2,${s('alwrap')} h3,${s('alwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('alwrap')} a{color:inherit;text-decoration:none}
${s('alwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: mastro de jornal, em dois niveis ---------- */
/* ⚠️ nivel de baixo some abaixo de 1100px: editoria em faixa cheia quebra em
   tres linhas no celular e empurra a abertura para baixo da dobra */
${s('altop')}{background:var(--paper)}
${s('albar')}{display:flex;align-items:center;justify-content:space-between;gap:18px;
  padding-block:20px 17px}
${s('almarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:800;font-size:clamp(25px,3.4vw,36px);letter-spacing:-.01em;color:var(--pri);flex:none}
${s('almarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS */
${s('almarca')} img{display:block;height:44px;width:auto;flex:none}
@media(max-width:560px){${s('almarca')} img{height:34px}}
${s('alfb')} img{display:block;height:40px;width:auto}

${s('alfaixa')}{background:var(--pri)}
${s('alnav')}{display:flex;gap:26px;align-items:center;flex-wrap:wrap;padding-block:11px}
${s('alnav')} a{font-family:var(--fb);font-size:12px;font-weight:700;letter-spacing:.09em;color:rgba(255,255,255,.88);transition:color .2s ease}
${s('alnav')} a:hover{color:#fff;text-decoration:underline;text-underline-offset:4px}
${s('albusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.07em;
  color:var(--pri);border:2px solid var(--pri);padding:8px 15px;border-radius:${canto};flex:none;
  transition:background .2s ease,color .2s ease}
${s('albusca')}:hover{background:var(--pri);color:var(--sob)}
${s('albusca')} svg{display:block;width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2.2}
${s('alham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  border-radius:${canto};cursor:pointer;padding:0;flex:none}
${s('alham')} i,${s('alham')} i::before,${s('alham')} i::after{display:block;height:2.5px;
  background:var(--pri);border-radius:2px;content:""}
${s('alham')} i{position:relative;width:20px;margin:0 auto}
${s('alham')} i::before{position:absolute;left:0;right:0;top:-7px}
${s('alham')} i::after{position:absolute;left:0;right:0;top:7px}
@media(max-width:1100px){
  ${s('alfaixa')}{display:none}
  ${s('alham')}{display:block}
  ${s('albar')}{flex-wrap:wrap}
  /* o menu sanfonado do nivel de cima: papel, e nao a faixa carmim */
  ${s('almenu')}{flex:1 1 100%;display:none;padding-bottom:14px}
  ${s('almenu')}[data-aberto="1"]{display:block}
  ${s('almenu')} a{display:block;font-family:var(--fb);font-size:13px;font-weight:700;
    letter-spacing:.07em;color:var(--ink);
    padding:12px 2px;border-top:1px solid var(--line)}
  ${s('almenu')} a:hover{color:var(--pri)}
}
@media(min-width:1101px){${s('almenu')}{display:none}}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('alabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('alabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('alabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('almm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('almm')} b{color:var(--ink);font-weight:700}
${s('alfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('alfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('alfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('alabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: nome da editoria na VERTICAL ---------- */
/* ⚠️ a coluna girada desaparece abaixo de 900px: texto na vertical em tela
   estreita rouba largura da materia e ninguem le */
${s('alsec')}{display:grid;grid-template-columns:58px minmax(0,1fr);gap:26px;
  padding-block:36px;border-top:1px solid var(--line)}
${s('alrot')}{display:flex;flex-direction:column;align-items:center;gap:14px}
${s('alrot')} h1,${s('alrot')} h2{writing-mode:vertical-rl;transform:rotate(180deg);
  font-family:var(--fb);font-size:12.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.2em'};color:var(--pri);
  margin:0;white-space:nowrap}
/* o fio que desce sob o nome, e o que amarra a coluna vertical */
${s('alrot')}::after{content:"";display:block;width:2px;flex:1 1 auto;background:var(--viva);
  min-height:34px}
${s('alcab')}{display:flex;align-items:baseline;justify-content:flex-end;gap:16px;
  margin-bottom:18px}
${s('almais')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.09em;color:var(--viva);flex:none}
${s('almais')}:hover{text-decoration:underline}
${s('aldescr')}{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia principal: texto a esquerda, imagem a direita */
${s('aldest')}{display:grid;grid-template-columns:1fr .78fr;gap:28px;align-items:center;
  padding-bottom:24px}
${s('aldest')} ${s('alti')}{font-size:clamp(21px,2.4vw,28px);line-height:1.16;margin-top:9px}
${s('alkick')}{display:block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.2em'};color:var(--viva)}
${s('alti')}{display:block;font-family:var(--fd);font-weight:700;font-size:18px;line-height:1.24;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('aldd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.58;color:var(--dek);
  max-width:54ch;text-align:left}
${s('aldt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('alfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('alfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '4/3'};overflow:hidden}
${s('alfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('aldest')}:hover ${s('alti')}{color:var(--pri)}
${s('aldest')}:hover ${s('alfoto')} [data-f] img{transform:scale(1.03)}

/* lista em duas colunas, miniatura em RETRATO a esquerda de cada item */
${s('allista')}{display:grid;grid-template-columns:1fr 1fr;gap:0 30px;grid-auto-flow:column;grid-template-rows:repeat(var(--l,3),auto)}
${s('alrow')}{display:grid;grid-template-columns:64px minmax(0,1fr);gap:15px;align-items:center;
  padding-block:14px;border-top:1px solid var(--line)}
${s('almini')}{display:block;width:64px;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('almini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '3/4'};overflow:hidden}
${s('almini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('alrow')}:hover ${s('almini')} [data-f] img{transform:scale(1.07)}
${s('alrow')}:hover ${s('alti')}{color:var(--pri)}
${s('alrow')} ${s('alti')}{font-size:16.5px}
${s('alrow')} ${s('alkick')}{color:var(--muted);margin-bottom:3px}
@media(max-width:900px){
  ${s('alsec')}{grid-template-columns:1fr;gap:0}
  ${s('alrot')}{display:none}
  ${s('alcab')}{justify-content:space-between;border-top:3px solid var(--pri);padding-top:9px}
  /* sem a coluna vertical, o nome da editoria volta na horizontal */
  ${s('alcab')}::before{content:attr(data-nome);font-family:var(--fb);font-size:12.5px;
    font-weight:700;letter-spacing:.16em;color:var(--pri)}
  ${s('aldest')}{grid-template-columns:1fr;gap:18px}
  ${s('allista')}{grid-template-columns:1fr;grid-auto-flow:row;grid-template-rows:none}
}
@media(max-width:680px){
  ${s('alrow')}{grid-template-columns:54px minmax(0,1fr);gap:12px}
  ${s('almini')}{width:54px}
  ${s('aldd')}{display:none}
}

/* ---------- artigo ---------- */
${s('alart')}{padding-block:30px 8px}
${s('alcol')}{max-width:${fp.medida || '700px'}}
${s('alchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--viva)}
${s('alart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('aldek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('alhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('alhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('alhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('alleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('albody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('albody')} p{margin:0 0 1.15em;text-align:left}
${s('albody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('albody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('albody')} ul,${s('albody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('albody')} li{margin:0 0 .45em}
${s('albody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('albody')} a:hover{color:var(--viva)}
${s('albody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('albody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('albody')} .dpe-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('albody')} .dpe-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('albody')} .dpe-veja ul{list-style:none;margin:0;padding:0}
${s('albody')} .dpe-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('albody')} .dpe-veja li:first-child{border-top:0;padding-top:0}
${s('albody')} .dpe-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('albody')} .dpe-veja a:hover{color:var(--viva)}
${s('albody')} figure{margin:1.5em 0}
${s('albody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('albody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('albody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('albody')} th,${s('albody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('albody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('albody')} table{min-width:0}
  ${s('albody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('albody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('albody')} table,${s('albody')} tbody,${s('albody')} tr,${s('albody')} th,
  ${s('albody')} td{display:block;width:auto}
  ${s('albody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('albody')} tbody th,${s('albody')} tbody td{border:0;background:transparent}
  ${s('albody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('albody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('albody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('alass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('alass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('alass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('alass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('alass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('alass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('alass')} .go:hover{text-decoration:underline}
${s('alrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('alrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('alfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('alcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('alfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('alfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('alfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('alfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('alflist')}{display:flex;flex-direction:column;gap:9px}
${s('alflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('alflist')} a:hover{opacity:1;color:var(--viva)}
${s('alfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('alcols')}{grid-template-columns:1fr;gap:26px}
  ${s('alfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Almanaque: tres barras verticais de alturas diferentes, que e o proprio gesto
 * da coluna girada de cada secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AL_SIMB = `<svg viewBox="0 0 30 26" role="img" aria-hidden="true" focusable="false"><rect x="3" y="4" width="5" height="18" fill="var(--marca-1,currentColor)"/><rect x="11" y="8" width="5" height="14" fill="var(--marca-2,currentColor)"/><rect x="19" y="2" width="5" height="20" fill="var(--marca-1,currentColor)"/></svg>`;

const AL_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function alHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'alnav-' + (site.slug || 'p');
  // 🔴 o link de editoria sai de H.curl: este portal tem categoryBase, e a
  // lista mora em /categoria/<slug>/. Montar /<slug>/ a mao poe o menu inteiro
  // em 404 sem estragar nenhuma captura de tela
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  const marca = site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AL_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`;
  return `<body>
<header class="${c('altop')}">
<div class="${c('alin')} ${c('albar')}">
<a class="${c('almarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${marca}</a>
<a class="${c('albusca')}" href="/busca/">${AL_LUPA}Buscar</a>
<button class="${c('alham')}" type="button" data-alham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<nav class="${c('almenu')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
</div>
<div class="${c('alfaixa')}"><nav class="${c('alin')} ${c('alnav')}" aria-label="Editorias">${links}</nav></div>
</header>
<script>(function(){var b=document.querySelector('[data-alham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function alFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('alfoot')}"><div class="${c('alin')}">
<div class="${c('alcols')}">
  <div><a class="${c('alfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AL_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('alfh')}">Editorias</div><div class="${c('alflist')}">${cats}</div></div>
  <div><div class="${c('alfh')}">O jornal</div><div class="${c('alflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('alfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function alDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aldest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('alfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('alkick')}">${H.cat(a)}</span>
<h${n} class="${c('alti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('aldd')}">${H.esc(H.clip(a.dek, 170))}</span>` : ''}
<span class="${c('aldt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

/* O item da lista de duas colunas: miniatura em retrato a esquerda. */
function alLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('alrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('almini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('alkick')}">${H.cat(a)}</span>
<h${n} class="${c('alti')}">${H.esc(a.title)}</h${n}>
<span class="${c('aldt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function alHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('alabre')}">
<div><span class="${c('alchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('almm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('alfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v]) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // o nome da editoria fica na coluna girada; no celular ele volta pelo
      // data-nome do cabecalho, que o CSS imprime com ::before
      return `<section class="${c('alsec')}">
<div class="${c('alrot')}"><h2>${H.esc(nome)}</h2></div>
<div>
<div class="${c('alcab')}" data-nome="${H.esc(nome)}">
<a class="${c('almais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${alDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('allista')}" style="--l:${Math.ceil(Math.min(resto.length, 6) / 2)}">${resto.slice(0, 6).map(a => alLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${alHeader(ctx, menu)}
<main class="${c('alwrap')}"><div class="${c('alin')}">
${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${alFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function alAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('alass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function alLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('alleg')}">${H.esc(alt)}</p>`;
}

function alArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('alrel')}">
<span class="${c('alrotb')}">Leia também</span>
<div class="${c('allista')}" style="--l:${Math.ceil(Math.min(related.length, 3) / 2)}">${related.slice(0, 3).map(a => alLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${alHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('alwrap')}"><div class="${c('alin')}">
<article class="${c('alart')}">
<div class="${c('alcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('alchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('aldek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('alhero')}"><span data-f>${H.pic(art, true)}</span></span>
${alLegenda(ctx, art)}` : ''}
<div class="${c('albody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${alAssinatura(ctx, art)}
${rel}
</div></main>
${alFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function alList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${alHeader(ctx, menu)}
<main class="${c('alwrap')}"><div class="${c('alin')}">
<section class="${c('alsec')}">
<div class="${c('alrot')}"><h1>${H.esc(opts.title)}</h1></div>
<div>
<div class="${c('alcab')}" data-nome="${H.esc(opts.title)}"></div>
${opts.desc ? `<p class="${c('aldescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? alDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('allista')}" style="--l:${Math.ceil(resto.length / 2)}">${resto.map(a => alLinha(ctx, a, 2)).join('')}</div>` : ''}
</div></section>
</div></main>
${alFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AM, arquetipo BANCA. Feita para o df8.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal regional do Noroeste, e o acervo preservado ficou
 * concentrado em entretenimento, dica e saude. O desenho pega o gesto do
 * **boletim**: cada secao e uma **faixa de fundo cheio**, alternando papel e
 * areia, a materia principal vem com a **imagem a ESQUERDA** e o texto a
 * direita, e as demais viram **duas colunas de itens com filete vertical**, cada
 * um com miniatura quadrada pequena.
 *
 * ## O que a diferencia das 36 vizinhas da opengravity
 *
 *   - **faixa de secao com fundo cheio, alternando**. Todas as 36 usam fundo
 *     unico com filete ou pastilha separando. Alternar o fundo da secao inteira
 *     muda a silhueta da pagina a distancia, que e o que primeiro se ve
 *   - **imagem a ESQUERDA na materia principal**. A `AE`, a `AG`, a `AI` e a
 *     `AJ` poem a imagem a direita ou por cima; nenhuma espelha
 *   - **lista em duas colunas**, e nao em coluna unica
 *   - **Vollkorn e Cabin**: nenhuma das duas aparece nas 90 familias em uso
 *   - **marinho com milho**: nao existe azul-marinho com amarelo entre as 23
 *     paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a faixa de fundo sangra ate a borda da tela, mas o conteudo continua no
 *     contentor: fundo cheio nao pode empurrar o texto para a borda
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */


function amCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('amwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('amwrap')} *{box-sizing:border-box}
${s('amin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
/* ⚠️ a Anton tem UM peso so. Pedir 700 faz o navegador fabricar o negrito
   borrando o desenho, e o titulo sai com fantasma atras de cada letra */
${s('amwrap')} h1,${s('amwrap')} h2,${s('amwrap')} h3,${s('amwrap')} h4{font-family:var(--fd);
  font-weight:400;letter-spacing:.005em;line-height:1.1;margin:0}
${s('amwrap')} a{color:inherit;text-decoration:none}
${s('amwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('amtop')}{background:var(--paper);border-bottom:4px solid var(--ink);
  box-shadow:0 4px 0 var(--viva)}
${s('ambar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('ammarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('ammarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('ammarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('ammarca')} img{height:31px}}
${s('amfb')} img{display:block;height:34px;width:auto}
${s('amnav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('amnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('amnav')} a:hover{color:var(--tinta)}
${s('ambusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('ambusca')}:hover{background:var(--viva);border-color:var(--viva)}
${s('amham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('amham')} i,${s('amham')} i::before,${s('amham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('amham')} i{top:21px}
${s('amham')} i::before{top:-6px;left:0}
${s('amham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('ammarca')}{font-size:21px;gap:8px}
  ${s('ambar')}{gap:11px}
  ${s('ambusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('amham')}{display:block;order:2}
  ${s('ambusca')}{order:3;margin-left:0}
  ${s('amnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('amnav')}[data-aberto="1"]{display:flex}
  ${s('amnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('amabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('amabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('amabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('ammm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('ammm')} b{color:var(--ink);font-weight:700}
${s('amfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('amfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('amfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('amabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: o nome dentro de uma caixa cheia ---------- */
/* ⚠️ nada de faixa de fundo aqui: o ritmo desta arquitetura vem do peso do
   contorno, e uma faixa colorida brigaria com a marca, que e preto e branco */
${s('amsec')}{padding-block:34px;background:var(--paper)}
${s('amcab')}{display:flex;align-items:center;justify-content:space-between;gap:16px;
  margin-bottom:22px;flex-wrap:wrap;border-bottom:3px solid var(--ink);padding-bottom:0}
${s('amcab')} h1,${s('amcab')} h2{font-family:var(--fd);font-size:clamp(19px,2.3vw,25px);
  font-weight:400;letter-spacing:.02em;color:var(--sob);
  background:var(--ink);padding:7px 15px 6px;margin:0;line-height:1.14}
${s('ammais')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--ink);flex:none;padding-bottom:8px}
${s('ammais')}:hover{color:var(--viva)}
${s('amdescr')}{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia principal: imagem a esquerda, texto a direita */
${s('amdest')}{display:grid;grid-template-columns:.95fr 1fr;gap:28px;align-items:start;
  padding-bottom:24px}
${s('amdest')} ${s('amti')}{font-size:clamp(22px,2.6vw,31px);line-height:1.1;margin-top:10px}
/* o chapeu vai dentro de uma caixa de contorno, como o NEWS do logotipo */
${s('amkick')}{display:inline-block;font-family:var(--fb);font-size:9.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.16em'};color:var(--ink);
  border:1.5px solid var(--ink);padding:3px 7px 2px;line-height:1}
${s('amti')}{display:block;font-family:var(--fd);font-weight:400;font-size:19px;line-height:1.16;
  letter-spacing:.01em;color:var(--ink);margin:0;transition:color .2s ease}
${s('amdd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.58;color:var(--dek);
  max-width:54ch;text-align:left}
${s('amdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11px;
  letter-spacing:.04em;color:var(--muted)}
${s('amfoto')}{display:block;overflow:hidden;background:var(--ph);border:1px solid var(--ink)}
${s('amfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '4/3'};overflow:hidden}
${s('amfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('amdest')}:hover ${s('amti')}{color:var(--viva)}
${s('amdest')}:hover ${s('amfoto')} [data-f] img{transform:scale(1.03)}
@media(max-width:820px){${s('amdest')}{grid-template-columns:1fr;gap:16px}}

/* a grade: cartao com moldura de fio, miniatura em cima */
${s('amlista')}{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
${s('amrow')}{display:block;border:1px solid var(--line);padding:0 0 15px;
  transition:border-color .2s ease}
${s('amrow')}:hover{border-color:var(--ink)}
${s('ammini')}{display:block;overflow:hidden;background:var(--ph);
  border-bottom:1px solid var(--line);margin-bottom:13px}
${s('ammini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '3/2'};overflow:hidden}
${s('ammini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('amrow')}:hover ${s('ammini')} [data-f] img{transform:scale(1.06)}
${s('amrow')}:hover ${s('amti')}{color:var(--viva)}
${s('amrow')}>span{display:block}
${s('amrow')} ${s('amti')}{font-size:17.5px;padding:0 14px}
${s('amrow')} ${s('amkick')}{margin:0 14px 8px}
${s('amrow')} ${s('amdt')}{padding:0 14px}
@media(max-width:900px){${s('amlista')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){
  ${s('amlista')}{grid-template-columns:1fr}
  ${s('amdd')}{display:none}
}

/* ---------- artigo ---------- */
${s('amart')}{padding-block:30px 8px}
${s('amcol')}{max-width:${fp.medida || '700px'}}
${s('amchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
${s('amart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('amdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('amhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('amhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('amhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('amleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('ambody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('ambody')} p{margin:0 0 1.15em;text-align:left}
${s('ambody')} h2{font-family:var(--fd);font-size:27px;font-weight:400;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('ambody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('ambody')} ul,${s('ambody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('ambody')} li{margin:0 0 .45em}
${s('ambody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('ambody')} a:hover{color:var(--tinta)}
${s('ambody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('ambody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('ambody')} .df8-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('ambody')} .df8-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('ambody')} .df8-veja ul{list-style:none;margin:0;padding:0}
${s('ambody')} .df8-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('ambody')} .df8-veja li:first-child{border-top:0;padding-top:0}
${s('ambody')} .df8-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('ambody')} .df8-veja a:hover{color:var(--tinta)}
${s('ambody')} figure{margin:1.5em 0}
${s('ambody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('ambody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('ambody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('ambody')} th,${s('ambody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('ambody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('ambody')} table{min-width:0}
  ${s('ambody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('ambody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('ambody')} table,${s('ambody')} tbody,${s('ambody')} tr,${s('ambody')} th,
  ${s('ambody')} td{display:block;width:auto}
  ${s('ambody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('ambody')} tbody th,${s('ambody')} tbody td{border:0;background:transparent}
  ${s('ambody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:400;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('ambody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('ambody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('amass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('amass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('amass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('amass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:400;margin-top:3px}
${s('amass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('amass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('amass')} .go:hover{text-decoration:underline}
${s('amrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('amrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('amfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('amcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('amfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:26px;color:#fff}
${s('amfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('amfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('amfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('amflist')}{display:flex;flex-direction:column;gap:9px}
${s('amflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('amflist')} a:hover{opacity:1;color:var(--viva)}
${s('amfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('amcols')}{grid-template-columns:1fr;gap:26px}
  ${s('amfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AM_SIMB = `<svg viewBox="0 0 34 22" role="img" aria-hidden="true" focusable="false"><rect x="1" y="2" width="18" height="18" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="3"/><rect x="22" y="2" width="11" height="18" fill="var(--marca-2,currentColor)"/></svg>`;

const AM_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function amHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aknav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('amtop')}">
<div class="${c('amin')} ${c('ambar')}">
<a class="${c('ammarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AM_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('amnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('amham')}" type="button" data-akham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('ambusca')}" href="/busca/">${AM_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-akham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function amFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('amfoot')}"><div class="${c('amin')}">
<div class="${c('amcols')}">
  <div><a class="${c('amfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AM_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('amfh')}">Editorias</div><div class="${c('amflist')}">${cats}</div></div>
  <div><div class="${c('amfh')}">O jornal</div><div class="${c('amflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('amfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function amDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('amdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('amfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('amkick')}">${H.cat(a)}</span>
<h${n} class="${c('amti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('amdd')}">${H.esc(H.clip(a.dek, 170))}</span>` : ''}
<span class="${c('amdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

/* O item da lista de duas colunas: filete vertical e miniatura quadrada. */
function amLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('amrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('ammini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('amkick')}">${H.cat(a)}</span>
<h${n} class="${c('amti')}">${H.esc(a.title)}</h${n}>
<span class="${c('amdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function amHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('amabre')}">
<div><span class="${c('amchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('ammm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('amfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('amsec')}" data-par="${idx % 2}">
<div class="${c('amin')}">
<div class="${c('amcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('ammais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${amDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('amlista')}">${resto.slice(0, 6).map(a => amLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${amHeader(ctx, menu)}
<main class="${c('amwrap')}">
<div class="${c('amin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${amFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function amAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('amass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function amLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('amleg')}">${H.esc(alt)}</p>`;
}

function amArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('amrel')}">
<span class="${c('amrotb')}">Leia também</span>
<div class="${c('amlista')}">${related.slice(0, 3).map(a => amLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${amHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('amwrap')}"><div class="${c('amin')}">
<article class="${c('amart')}">
<div class="${c('amcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('amchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('amdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('amhero')}"><span data-f>${H.pic(art, true)}</span></span>
${amLegenda(ctx, art)}` : ''}
<div class="${c('ambody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${amAssinatura(ctx, art)}
${rel}
</div></main>
${amFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function amList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${amHeader(ctx, menu)}
<main class="${c('amwrap')}">
<section class="${c('amsec')}" data-par="0"><div class="${c('amin')}">
<div class="${c('amcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('amdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? amDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('amlista')}">${resto.map(a => amLinha(ctx, a, 2)).join('')}</div>` : ''}
</div></section>
</main>
${amFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AN, arquetipo MOSAICO. Feita para o divirto.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal regional do Noroeste, e o acervo preservado ficou
 * concentrado em entretenimento, dica e saude. O desenho pega o gesto do
 * **boletim**: cada secao e uma **faixa de fundo cheio**, alternando papel e
 * areia, a materia principal vem com a **imagem a ESQUERDA** e o texto a
 * direita, e as demais viram **duas colunas de itens com filete vertical**, cada
 * um com miniatura quadrada pequena.
 *
 * ## O que a diferencia das 36 vizinhas da opengravity
 *
 *   - **faixa de secao com fundo cheio, alternando**. Todas as 36 usam fundo
 *     unico com filete ou pastilha separando. Alternar o fundo da secao inteira
 *     muda a silhueta da pagina a distancia, que e o que primeiro se ve
 *   - **imagem a ESQUERDA na materia principal**. A `AE`, a `AG`, a `AI` e a
 *     `AJ` poem a imagem a direita ou por cima; nenhuma espelha
 *   - **lista em duas colunas**, e nao em coluna unica
 *   - **Vollkorn e Cabin**: nenhuma das duas aparece nas 90 familias em uso
 *   - **marinho com milho**: nao existe azul-marinho com amarelo entre as 23
 *     paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a faixa de fundo sangra ate a borda da tela, mas o conteudo continua no
 *     contentor: fundo cheio nao pode empurrar o texto para a borda
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */


function anCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('anwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('anwrap')} *{box-sizing:border-box}
${s('anin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
/* ⚠️ a Anton tem UM peso so. Pedir 700 faz o navegador fabricar o negrito
   borrando o desenho, e o titulo sai com fantasma atras de cada letra */
${s('anwrap')} h1,${s('anwrap')} h2,${s('anwrap')} h3,${s('anwrap')} h4{font-family:var(--fd);
  font-weight:400;letter-spacing:.005em;line-height:1.1;margin:0}
${s('anwrap')} a{color:inherit;text-decoration:none}
${s('anwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('antop')}{background:var(--paper);border-bottom:4px solid var(--ink);
  box-shadow:0 4px 0 var(--viva)}
${s('anbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('anmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('anmarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('anmarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('anmarca')} img{height:31px}}
${s('anfb')} img{display:block;height:34px;width:auto}
${s('annav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('annav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('annav')} a:hover{color:var(--tinta)}
${s('anbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('anbusca')}:hover{background:var(--viva);border-color:var(--viva)}
${s('anham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('anham')} i,${s('anham')} i::before,${s('anham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('anham')} i{top:21px}
${s('anham')} i::before{top:-6px;left:0}
${s('anham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('anmarca')}{font-size:21px;gap:8px}
  ${s('anbar')}{gap:11px}
  ${s('anbusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('anham')}{display:block;order:2}
  ${s('anbusca')}{order:3;margin-left:0}
  ${s('annav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('annav')}[data-aberto="1"]{display:flex}
  ${s('annav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('anabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('anabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('anabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('anmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('anmm')} b{color:var(--ink);font-weight:700}
${s('anfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('anfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('anfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('anabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: pastilha de editoria e mosaico ---------- */
${s('ansec')}{padding-block:34px;background:var(--paper)}
${s('ancab')}{display:flex;align-items:center;justify-content:space-between;gap:16px;
  margin-bottom:20px;flex-wrap:wrap;border-bottom:1px solid var(--line);padding-bottom:12px}
/* o nome da editoria vem numa pastilha, que e o eco da faixa do logotipo */
${s('ancab')} h1,${s('ancab')} h2{font-family:var(--fd);font-size:clamp(15px,1.7vw,18px);
  font-weight:800;letter-spacing:.06em;color:var(--paper);
  background:var(--viva);padding:7px 17px 6px;border-radius:999px;margin:0;line-height:1.1}
${s('anmais')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--muted);flex:none}
${s('anmais')}:hover{color:var(--viva)}
${s('andescr')}{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* ⚠️ o mosaico: a materia principal ocupa 2 colunas por 2 linhas, e os quatro
   menores se encaixam em volta. Abaixo de 900px vira uma coluna so, senao o
   cartao de duas linhas fica com foto gigante e titulo perdido */
${s('anmos')}{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:auto;gap:22px}
${s('anmos')}>*:first-child{grid-column:span 2;grid-row:span 2}
@media(max-width:1100px){
  ${s('anmos')}{grid-template-columns:repeat(2,1fr)}
  ${s('anmos')}>*:first-child{grid-column:span 2;grid-row:auto}
}
@media(max-width:640px){
  ${s('anmos')}{grid-template-columns:1fr}
  ${s('anmos')}>*:first-child{grid-column:auto}
}

/* o cartao: sem moldura, so a foto e o texto sobre a superficie */
${s('anrow')}{display:block;transition:transform .25s ease}
${s('anrow')}:hover{transform:translateY(-3px)}
${s('anmini')}{display:block;overflow:hidden;background:var(--ph);margin-bottom:12px;
  border-radius:${canto}}
${s('anmini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '3/2'};overflow:hidden}
${s('anmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('anrow')}:hover ${s('anmini')} [data-f] img{transform:scale(1.05)}
${s('anrow')}:hover ${s('anti')}{color:var(--viva)}
/* o chapeu ganha um fio ambar embaixo, que e o unico enfeite do cartao */
${s('ankick')}{display:inline-block;font-family:var(--fb);font-size:9.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.16em'};color:var(--viva);
  border-bottom:2px solid var(--viva);padding-bottom:3px;margin-bottom:8px;line-height:1}
${s('anti')}{display:block;font-family:var(--fd);font-weight:700;font-size:18px;line-height:1.22;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('andd')}{display:block;margin:10px 0 0;font-size:15px;line-height:1.58;color:var(--dek);
  max-width:54ch;text-align:left}
${s('andt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11px;
  letter-spacing:.04em;color:var(--muted)}
/* a materia principal do mosaico e maior em tudo */
${s('anmos')}>*:first-child ${s('anti')}{font-size:clamp(21px,2.3vw,28px);line-height:1.14}
${s('anmos')}>*:first-child ${s('anmini')} [data-f]{aspect-ratio:${fp.heroAr || '3/2'}}
@media(max-width:1100px){${s('anmos')}>*:not(:first-child) ${s('andd')}{display:none}}
/* os relacionados usam o mesmo cartao, mas em tres colunas iguais */
${s('anmosr')}{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
${s('anmosr')} ${s('andd')}{display:none}
@media(max-width:680px){${s('anmosr')}{grid-template-columns:1fr}}

/* ---------- artigo ---------- */
${s('anart')}{padding-block:30px 8px}
${s('ancol')}{max-width:${fp.medida || '700px'}}
${s('anchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
${s('anart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('andek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('anhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('anhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('anhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('anleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('anbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('anbody')} p{margin:0 0 1.15em;text-align:left}
${s('anbody')} h2{font-family:var(--fd);font-size:27px;font-weight:400;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('anbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('anbody')} ul,${s('anbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('anbody')} li{margin:0 0 .45em}
${s('anbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('anbody')} a:hover{color:var(--tinta)}
${s('anbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('anbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('anbody')} .dvt-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('anbody')} .dvt-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('anbody')} .dvt-veja ul{list-style:none;margin:0;padding:0}
${s('anbody')} .dvt-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('anbody')} .dvt-veja li:first-child{border-top:0;padding-top:0}
${s('anbody')} .dvt-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('anbody')} .dvt-veja a:hover{color:var(--tinta)}
${s('anbody')} figure{margin:1.5em 0}
${s('anbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('anbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('anbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('anbody')} th,${s('anbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('anbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('anbody')} table{min-width:0}
  ${s('anbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('anbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('anbody')} table,${s('anbody')} tbody,${s('anbody')} tr,${s('anbody')} th,
  ${s('anbody')} td{display:block;width:auto}
  ${s('anbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('anbody')} tbody th,${s('anbody')} tbody td{border:0;background:transparent}
  ${s('anbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:400;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('anbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('anbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('anass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('anass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('anass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('anass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:400;margin-top:3px}
${s('anass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('anass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('anass')} .go:hover{text-decoration:underline}
${s('anrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('anrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('anfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('ancols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('anfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:26px;color:#fff}
${s('anfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('anfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('anfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('anflist')}{display:flex;flex-direction:column;gap:9px}
${s('anflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('anflist')} a:hover{opacity:1;color:var(--viva)}
${s('anfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('ancols')}{grid-template-columns:1fr;gap:26px}
  ${s('anfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AN_SIMB = `<svg viewBox="0 0 26 26" role="img" aria-hidden="true" focusable="false"><circle cx="13" cy="13" r="11" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2.4"/><ellipse cx="13" cy="13" rx="5" ry="11" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2"/><rect x="0" y="10" width="26" height="6" fill="var(--marca-2,currentColor)"/></svg>`;

const AN_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function anHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aknav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('antop')}">
<div class="${c('anin')} ${c('anbar')}">
<a class="${c('anmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AN_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('annav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('anham')}" type="button" data-akham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('anbusca')}" href="/busca/">${AN_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-akham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function anFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('anfoot')}"><div class="${c('anin')}">
<div class="${c('ancols')}">
  <div><a class="${c('anfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AN_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('anfh')}">Editorias</div><div class="${c('anflist')}">${cats}</div></div>
  <div><div class="${c('anfh')}">O jornal</div><div class="${c('anflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('anfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function anDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('andest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('anfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('ankick')}">${H.cat(a)}</span>
<h${n} class="${c('anti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('andd')}">${H.esc(H.clip(a.dek, 170))}</span>` : ''}
<span class="${c('andt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

/* O item da lista de duas colunas: filete vertical e miniatura quadrada. */
function anLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('anrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('anmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('ankick')}">${H.cat(a)}</span>
<h${n} class="${c('anti')}">${H.esc(a.title)}</h${n}>
<span class="${c('andt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function anHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('anabre')}">
<div><span class="${c('anchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('anmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('anfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('ansec')}" data-par="${idx % 2}">
<div class="${c('anin')}">
<div class="${c('ancab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('anmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
<div class="${c('anmos')}">${anLinha(ctx, d)}${resto.slice(0, 4).map(a => anLinha(ctx, a)).join('')}</div>
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${anHeader(ctx, menu)}
<main class="${c('anwrap')}">
<div class="${c('anin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${anFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function anAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('anass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function anLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('anleg')}">${H.esc(alt)}</p>`;
}

function anArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('anrel')}">
<span class="${c('anrotb')}">Leia também</span>
<div class="${c('anmosr')}">${related.slice(0, 3).map(a => anLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${anHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('anwrap')}"><div class="${c('anin')}">
<article class="${c('anart')}">
<div class="${c('ancol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('anchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('andek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('anhero')}"><span data-f>${H.pic(art, true)}</span></span>
${anLegenda(ctx, art)}` : ''}
<div class="${c('anbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${anAssinatura(ctx, art)}
${rel}
</div></main>
${anFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function anList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${anHeader(ctx, menu)}
<main class="${c('anwrap')}">
<section class="${c('ansec')}" data-par="0"><div class="${c('anin')}">
<div class="${c('ancab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('andescr')}">${H.esc(opts.desc)}</p>` : ''}
${itens.length ? `<div class="${c('anmos')}">${itens.map(a => anLinha(ctx, a, 2)).join('')}</div>` : ''}
</div></section>
</main>
${anFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AO, arquetipo PAUTA. Feita para o incast.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal regional do Noroeste, e o acervo preservado ficou
 * concentrado em entretenimento, dica e saude. O desenho pega o gesto do
 * **boletim**: cada secao e uma **faixa de fundo cheio**, alternando papel e
 * areia, a materia principal vem com a **imagem a ESQUERDA** e o texto a
 * direita, e as demais viram **duas colunas de itens com filete vertical**, cada
 * um com miniatura quadrada pequena.
 *
 * ## O que a diferencia das 36 vizinhas da opengravity
 *
 *   - **faixa de secao com fundo cheio, alternando**. Todas as 36 usam fundo
 *     unico com filete ou pastilha separando. Alternar o fundo da secao inteira
 *     muda a silhueta da pagina a distancia, que e o que primeiro se ve
 *   - **imagem a ESQUERDA na materia principal**. A `AE`, a `AG`, a `AI` e a
 *     `AJ` poem a imagem a direita ou por cima; nenhuma espelha
 *   - **lista em duas colunas**, e nao em coluna unica
 *   - **Vollkorn e Cabin**: nenhuma das duas aparece nas 90 familias em uso
 *   - **marinho com milho**: nao existe azul-marinho com amarelo entre as 23
 *     paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a faixa de fundo sangra ate a borda da tela, mas o conteudo continua no
 *     contentor: fundo cheio nao pode empurrar o texto para a borda
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */


function aoCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('aowrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('aowrap')} *{box-sizing:border-box}
${s('aoin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
/* ⚠️ a Anton tem UM peso so. Pedir 700 faz o navegador fabricar o negrito
   borrando o desenho, e o titulo sai com fantasma atras de cada letra */
${s('aowrap')} h1,${s('aowrap')} h2,${s('aowrap')} h3,${s('aowrap')} h4{font-family:var(--fd);
  font-weight:400;letter-spacing:.005em;line-height:1.1;margin:0}
${s('aowrap')} a{color:inherit;text-decoration:none}
${s('aowrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('aotop')}{background:var(--paper);border-bottom:4px solid var(--ink);
  box-shadow:0 4px 0 var(--viva)}
${s('aobar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('aomarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('aomarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('aomarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('aomarca')} img{height:31px}}
${s('aofb')} img{display:block;height:34px;width:auto}
${s('aonav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('aonav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('aonav')} a:hover{color:var(--tinta)}
${s('aobusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('aobusca')}:hover{background:var(--viva);border-color:var(--viva)}
${s('aoham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('aoham')} i,${s('aoham')} i::before,${s('aoham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('aoham')} i{top:21px}
${s('aoham')} i::before{top:-6px;left:0}
${s('aoham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('aomarca')}{font-size:21px;gap:8px}
  ${s('aobar')}{gap:11px}
  ${s('aobusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('aoham')}{display:block;order:2}
  ${s('aobusca')}{order:3;margin-left:0}
  ${s('aonav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('aonav')}[data-aberto="1"]{display:flex}
  ${s('aonav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('aoabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('aoabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('aoabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('aomm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('aomm')} b{color:var(--ink);font-weight:700}
${s('aofoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('aofoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aofoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('aoabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: linha do tempo vertical ---------- */
${s('aosec')}{padding-block:34px;background:var(--paper)}
${s('aocab')}{display:flex;align-items:center;justify-content:space-between;gap:16px;
  margin-bottom:20px;flex-wrap:wrap}
/* o nome da editoria com o filete vermelho na frente, que e o inicio da linha */
${s('aocab')} h1,${s('aocab')} h2{display:flex;align-items:center;gap:12px;
  font-family:var(--fd);font-size:clamp(19px,2.2vw,25px);font-weight:700;
  letter-spacing:-.01em;color:var(--pri);margin:0;line-height:1.15}
${s('aocab')} h1::before,${s('aocab')} h2::before{content:"";display:block;width:7px;height:26px;
  background:var(--viva);border-radius:4px;flex:none}
${s('aomais')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--pri);flex:none}
${s('aomais')}:hover{color:var(--viva);text-decoration:underline}
${s('aodescr')}{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia principal: foto a esquerda, texto a direita */
${s('aodest')}{display:grid;grid-template-columns:.95fr 1fr;gap:28px;align-items:center;
  padding-bottom:26px}
${s('aodest')} ${s('aoti')}{font-size:clamp(21px,2.5vw,29px);line-height:1.14;margin-top:9px}
${s('aokick')}{display:block;font-family:var(--fb);font-size:10px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.15em'};color:var(--viva)}
${s('aoti')}{display:block;font-family:var(--fd);font-weight:700;font-size:18px;line-height:1.24;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('aodd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.58;color:var(--dek);
  max-width:54ch;text-align:left}
${s('aodt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('aofoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('aofoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aofoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('aodest')}:hover ${s('aoti')}{color:var(--pri)}
${s('aodest')}:hover ${s('aofoto')} [data-f] img{transform:scale(1.03)}
@media(max-width:820px){${s('aodest')}{grid-template-columns:1fr;gap:16px}}

/* ⚠️ a linha do tempo: o filete e um ::before do CONTENTOR, e nao borda de
   cada item, senao ele quebra entre um item e o outro.
   ⚠️ sem crase neste comentario: crase fecha o template literal do arquivo */
${s('aolinha')}{position:relative;padding-left:30px}
${s('aolinha')}::before{content:"";position:absolute;left:6px;top:10px;bottom:10px;width:2px;
  background:var(--line)}
${s('aorow')}{position:relative;display:grid;grid-template-columns:minmax(0,1fr) 96px;gap:18px;
  align-items:center;padding-block:15px;border-top:1px solid var(--line)}
${s('aolinha')}>${s('aorow')}:first-child{border-top:0}
/* o marcador redondo de cada materia, que e a marca do episodio */
${s('aorow')}::before{content:"";position:absolute;left:-30px;top:50%;transform:translateY(-50%);
  width:14px;height:14px;border-radius:50%;background:var(--paper);
  border:3px solid var(--line);transition:border-color .2s ease}
${s('aorow')}:hover::before{border-color:var(--viva)}
${s('aorow')}:hover ${s('aoti')}{color:var(--viva)}
${s('aomini')}{display:block;width:96px;overflow:hidden;background:var(--ph);
  border-radius:${canto};order:2}
${s('aomini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '4/3'};overflow:hidden}
${s('aomini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('aorow')}:hover ${s('aomini')} [data-f] img{transform:scale(1.07)}
${s('aorow')} ${s('aoti')}{font-size:17px}
${s('aorow')} ${s('aokick')}{color:var(--muted);margin-bottom:4px}
@media(max-width:680px){
  /* sem o filete: linha do tempo em tela estreita rouba largura do titulo */
  ${s('aolinha')}{padding-left:0}
  ${s('aolinha')}::before{display:none}
  ${s('aorow')}::before{position:static;transform:none;display:inline-block;
    width:16px;height:3px;border-radius:2px;border:0;background:var(--viva);
    margin-bottom:7px;vertical-align:middle}
  ${s('aorow')}{grid-template-columns:minmax(0,1fr) 74px;gap:13px}
  ${s('aomini')}{width:74px}
  ${s('aodd')}{display:none}
}

/* ---------- artigo ---------- */
${s('aoart')}{padding-block:30px 8px}
${s('aocol')}{max-width:${fp.medida || '700px'}}
${s('aochap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
${s('aoart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('aodek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('aohero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('aohero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aohero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('aoleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('aobody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('aobody')} p{margin:0 0 1.15em;text-align:left}
${s('aobody')} h2{font-family:var(--fd);font-size:27px;font-weight:400;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('aobody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('aobody')} ul,${s('aobody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('aobody')} li{margin:0 0 .45em}
${s('aobody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('aobody')} a:hover{color:var(--tinta)}
${s('aobody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('aobody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('aobody')} .inc-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('aobody')} .inc-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('aobody')} .inc-veja ul{list-style:none;margin:0;padding:0}
${s('aobody')} .inc-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('aobody')} .inc-veja li:first-child{border-top:0;padding-top:0}
${s('aobody')} .inc-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('aobody')} .inc-veja a:hover{color:var(--tinta)}
${s('aobody')} figure{margin:1.5em 0}
${s('aobody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('aobody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('aobody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('aobody')} th,${s('aobody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('aobody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('aobody')} table{min-width:0}
  ${s('aobody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('aobody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('aobody')} table,${s('aobody')} tbody,${s('aobody')} tr,${s('aobody')} th,
  ${s('aobody')} td{display:block;width:auto}
  ${s('aobody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('aobody')} tbody th,${s('aobody')} tbody td{border:0;background:transparent}
  ${s('aobody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:400;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('aobody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('aobody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('aoass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('aoass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('aoass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('aoass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:400;margin-top:3px}
${s('aoass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('aoass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('aoass')} .go:hover{text-decoration:underline}
${s('aorel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('aorotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('aofoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('aocols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('aofb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:26px;color:#fff}
${s('aofb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('aofoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('aofh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('aoflist')}{display:flex;flex-direction:column;gap:9px}
${s('aoflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('aoflist')} a:hover{opacity:1;color:var(--viva)}
${s('aofim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('aocols')}{grid-template-columns:1fr;gap:26px}
  ${s('aofoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AO_SIMB = `<svg viewBox="0 0 22 26" role="img" aria-hidden="true" focusable="false"><rect x="5" y="1" width="12" height="17" rx="6" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2.6"/><path d="M2 12 a9 9 0 0 0 18 0" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2.6" stroke-linecap="round"/><path d="M11 21 v3 l-4 2 v-5 Z" fill="var(--marca-2,currentColor)"/><path d="M8 6 h6 M8 10 h6" stroke="var(--marca-2,currentColor)" stroke-width="2.2" stroke-linecap="round"/></svg>`;

const AO_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function aoHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aknav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aotop')}">
<div class="${c('aoin')} ${c('aobar')}">
<a class="${c('aomarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AO_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('aonav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('aoham')}" type="button" data-akham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('aobusca')}" href="/busca/">${AO_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-akham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function aoFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('aofoot')}"><div class="${c('aoin')}">
<div class="${c('aocols')}">
  <div><a class="${c('aofb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AO_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('aofh')}">Editorias</div><div class="${c('aoflist')}">${cats}</div></div>
  <div><div class="${c('aofh')}">O jornal</div><div class="${c('aoflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('aofim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function aoDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aodest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('aofoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('aokick')}">${H.cat(a)}</span>
<h${n} class="${c('aoti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('aodd')}">${H.esc(H.clip(a.dek, 170))}</span>` : ''}
<span class="${c('aodt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

/* O item da lista de duas colunas: filete vertical e miniatura quadrada. */
function aoLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aorow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('aomini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('aokick')}">${H.cat(a)}</span>
<h${n} class="${c('aoti')}">${H.esc(a.title)}</h${n}>
<span class="${c('aodt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function aoHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('aoabre')}">
<div><span class="${c('aochap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('aomm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('aofoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('aosec')}" data-par="${idx % 2}">
<div class="${c('aoin')}">
<div class="${c('aocab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('aomais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${aoDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('aolinha')}">${resto.slice(0, 6).map(a => aoLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${aoHeader(ctx, menu)}
<main class="${c('aowrap')}">
<div class="${c('aoin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${aoFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function aoAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('aoass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function aoLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('aoleg')}">${H.esc(alt)}</p>`;
}

function aoArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('aorel')}">
<span class="${c('aorotb')}">Leia também</span>
<div class="${c('aolinha')}">${related.slice(0, 3).map(a => aoLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${aoHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('aowrap')}"><div class="${c('aoin')}">
<article class="${c('aoart')}">
<div class="${c('aocol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('aochap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('aodek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('aohero')}"><span data-f>${H.pic(art, true)}</span></span>
${aoLegenda(ctx, art)}` : ''}
<div class="${c('aobody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${aoAssinatura(ctx, art)}
${rel}
</div></main>
${aoFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function aoList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${aoHeader(ctx, menu)}
<main class="${c('aowrap')}">
<section class="${c('aosec')}" data-par="0"><div class="${c('aoin')}">
<div class="${c('aocab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('aodescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? aoDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('aolinha')}">${resto.map(a => aoLinha(ctx, a, 2)).join('')}</div>` : ''}
</div></section>
</main>
${aoFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AP, arquetipo TELA. Feita para o opopularjornal.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal regional do Noroeste, e o acervo preservado ficou
 * concentrado em entretenimento, dica e saude. O desenho pega o gesto do
 * **boletim**: cada secao e uma **faixa de fundo cheio**, alternando papel e
 * areia, a materia principal vem com a **imagem a ESQUERDA** e o texto a
 * direita, e as demais viram **duas colunas de itens com filete vertical**, cada
 * um com miniatura quadrada pequena.
 *
 * ## O que a diferencia das 36 vizinhas da opengravity
 *
 *   - **faixa de secao com fundo cheio, alternando**. Todas as 36 usam fundo
 *     unico com filete ou pastilha separando. Alternar o fundo da secao inteira
 *     muda a silhueta da pagina a distancia, que e o que primeiro se ve
 *   - **imagem a ESQUERDA na materia principal**. A `AE`, a `AG`, a `AI` e a
 *     `AJ` poem a imagem a direita ou por cima; nenhuma espelha
 *   - **lista em duas colunas**, e nao em coluna unica
 *   - **Vollkorn e Cabin**: nenhuma das duas aparece nas 90 familias em uso
 *   - **marinho com milho**: nao existe azul-marinho com amarelo entre as 23
 *     paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a faixa de fundo sangra ate a borda da tela, mas o conteudo continua no
 *     contentor: fundo cheio nao pode empurrar o texto para a borda
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */


function apCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('apwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('apwrap')} *{box-sizing:border-box}
${s('apin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
/* ⚠️ a Anton tem UM peso so. Pedir 700 faz o navegador fabricar o negrito
   borrando o desenho, e o titulo sai com fantasma atras de cada letra */
${s('apwrap')} h1,${s('apwrap')} h2,${s('apwrap')} h3,${s('apwrap')} h4{font-family:var(--fd);
  font-weight:400;letter-spacing:.005em;line-height:1.1;margin:0}
${s('apwrap')} a{color:inherit;text-decoration:none}
${s('apwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('aptop')}{background:var(--paper);border-bottom:5px solid var(--pri)}
${s('apbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('apmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('apmarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('apmarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('apmarca')} img{height:31px}}
${s('apfb')} img{display:block;height:34px;width:auto}
${s('apnav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('apnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('apnav')} a:hover{color:var(--tinta)}
${s('apbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('apbusca')}:hover{background:var(--viva);border-color:var(--viva)}
${s('apham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('apham')} i,${s('apham')} i::before,${s('apham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('apham')} i{top:21px}
${s('apham')} i::before{top:-6px;left:0}
${s('apham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('apmarca')}{font-size:21px;gap:8px}
  ${s('apbar')}{gap:11px}
  ${s('apbusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('apham')}{display:block;order:2}
  ${s('apbusca')}{order:3;margin-left:0}
  ${s('apnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('apnav')}[data-aberto="1"]{display:flex}
  ${s('apnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('apabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('apabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('apabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('apmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('apmm')} b{color:var(--ink);font-weight:700}
${s('apfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('apfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('apfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('apabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: o nome dentro de uma moldura de tela ---------- */
${s('apsec')}{padding-block:34px;background:var(--paper)}
${s('apcab')}{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;
  margin-bottom:24px;flex-wrap:wrap}
/* a moldura com pe: silhueta de monitor, que e o simbolo da marca */
${s('apcab')} h1,${s('apcab')} h2{position:relative;font-family:var(--fd);
  font-size:clamp(18px,2.1vw,23px);font-weight:600;letter-spacing:.01em;color:var(--pri);
  margin:0 0 12px;line-height:1.15;border:2.5px solid var(--pri);border-radius:5px;
  padding:9px 17px 8px}
${s('apcab')} h1::after,${s('apcab')} h2::after{content:"";position:absolute;left:50%;
  bottom:-12px;transform:translateX(-50%);width:34px;height:10px;
  border-bottom:2.5px solid var(--pri);border-left:2.5px solid transparent;
  border-right:2.5px solid transparent}
${s('apcab')} h1::before,${s('apcab')} h2::before{content:"";position:absolute;left:50%;
  bottom:-12px;transform:translateX(-50%);width:2.5px;height:9px;background:var(--pri)}
${s('apmais')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--viva);flex:none;padding-bottom:14px}
${s('apmais')}:hover{text-decoration:underline}
${s('apdescr')}{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia principal: foto a esquerda, texto a direita */
${s('apdest')}{display:grid;grid-template-columns:1fr .95fr;gap:28px;align-items:center;
  padding-bottom:26px}
${s('apdest')} ${s('apti')}{font-size:clamp(21px,2.5vw,29px);line-height:1.15;margin-top:9px}
${s('apkick')}{display:block;font-family:var(--fb);font-size:10px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.15em'};color:var(--viva)}
${s('apti')}{display:block;font-family:var(--fd);font-weight:600;font-size:18px;line-height:1.24;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('apdd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.58;color:var(--dek);
  max-width:54ch;text-align:left}
${s('apdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('apfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto};
  border-top:6px solid var(--pri)}
${s('apfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('apfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('apdest')}:hover ${s('apti')}{color:var(--pri)}
${s('apdest')}:hover ${s('apfoto')} [data-f] img{transform:scale(1.03)}
@media(max-width:820px){${s('apdest')}{grid-template-columns:1fr;gap:16px}}

/* a grade: quatro colunas, cartao com filete SO no topo */
${s('aplista')}{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
${s('aprow')}{display:block;border-top:5px solid var(--line);padding-top:13px;
  transition:border-color .2s ease}
${s('aprow')}:hover{border-top-color:var(--viva)}
${s('aprow')}>span{display:block}
${s('apmini')}{display:block;overflow:hidden;background:var(--ph);margin-bottom:12px;
  border-radius:${canto}}
${s('apmini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '16/9'};overflow:hidden}
${s('apmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('aprow')}:hover ${s('apmini')} [data-f] img{transform:scale(1.06)}
${s('aprow')}:hover ${s('apti')}{color:var(--pri)}
${s('aprow')} ${s('apti')}{font-size:16.5px}
${s('aprow')} ${s('apkick')}{margin-bottom:6px}
@media(max-width:1000px){${s('aplista')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){
  ${s('aplista')}{grid-template-columns:1fr}
  ${s('apdd')}{display:none}
}

/* ---------- artigo ---------- */
${s('apart')}{padding-block:30px 8px}
${s('apcol')}{max-width:${fp.medida || '700px'}}
${s('apchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
${s('apart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('apdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('aphero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('aphero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aphero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('apleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('apbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('apbody')} p{margin:0 0 1.15em;text-align:left}
${s('apbody')} h2{font-family:var(--fd);font-size:27px;font-weight:400;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('apbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('apbody')} ul,${s('apbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('apbody')} li{margin:0 0 .45em}
${s('apbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('apbody')} a:hover{color:var(--tinta)}
${s('apbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('apbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('apbody')} .pop-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('apbody')} .pop-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('apbody')} .pop-veja ul{list-style:none;margin:0;padding:0}
${s('apbody')} .pop-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('apbody')} .pop-veja li:first-child{border-top:0;padding-top:0}
${s('apbody')} .pop-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('apbody')} .pop-veja a:hover{color:var(--tinta)}
${s('apbody')} figure{margin:1.5em 0}
${s('apbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('apbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('apbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('apbody')} th,${s('apbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('apbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('apbody')} table{min-width:0}
  ${s('apbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('apbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('apbody')} table,${s('apbody')} tbody,${s('apbody')} tr,${s('apbody')} th,
  ${s('apbody')} td{display:block;width:auto}
  ${s('apbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('apbody')} tbody th,${s('apbody')} tbody td{border:0;background:transparent}
  ${s('apbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:400;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('apbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('apbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('apass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('apass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('apass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('apass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:400;margin-top:3px}
${s('apass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('apass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('apass')} .go:hover{text-decoration:underline}
${s('aprel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('aprotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('apfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('apcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('apfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:400;font-size:26px;color:#fff}
${s('apfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('apfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('apfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('apflist')}{display:flex;flex-direction:column;gap:9px}
${s('apflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('apflist')} a:hover{opacity:1;color:var(--viva)}
${s('apfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('apcols')}{grid-template-columns:1fr;gap:26px}
  ${s('apfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AP_SIMB = `<svg viewBox="0 0 28 26" role="img" aria-hidden="true" focusable="false"><rect x="1" y="3" width="26" height="18" rx="3" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2.6"/><path d="M10 25 h8 M14 21 v4" stroke="var(--marca-1,currentColor)" stroke-width="2.6" stroke-linecap="round"/><rect x="11" y="7" width="6" height="8" rx="3" fill="var(--marca-2,currentColor)"/></svg>`;

const AP_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function apHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aknav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aptop')}">
<div class="${c('apin')} ${c('apbar')}">
<a class="${c('apmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AP_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('apnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('apham')}" type="button" data-akham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('apbusca')}" href="/busca/">${AP_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-akham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function apFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('apfoot')}"><div class="${c('apin')}">
<div class="${c('apcols')}">
  <div><a class="${c('apfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AP_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('apfh')}">Editorias</div><div class="${c('apflist')}">${cats}</div></div>
  <div><div class="${c('apfh')}">O jornal</div><div class="${c('apflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('apfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function apDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('apdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('apfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('apkick')}">${H.cat(a)}</span>
<h${n} class="${c('apti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('apdd')}">${H.esc(H.clip(a.dek, 170))}</span>` : ''}
<span class="${c('apdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

/* O item da lista de duas colunas: filete vertical e miniatura quadrada. */
function apLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aprow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('apmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('apkick')}">${H.cat(a)}</span>
<h${n} class="${c('apti')}">${H.esc(a.title)}</h${n}>
<span class="${c('apdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function apHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('apabre')}">
<div><span class="${c('apchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('apmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('apfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('apsec')}" data-par="${idx % 2}">
<div class="${c('apin')}">
<div class="${c('apcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('apmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${apDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('aplista')}">${resto.slice(0, 8).map(a => apLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${apHeader(ctx, menu)}
<main class="${c('apwrap')}">
<div class="${c('apin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${apFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function apAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('apass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function apLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('apleg')}">${H.esc(alt)}</p>`;
}

function apArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('aprel')}">
<span class="${c('aprotb')}">Leia também</span>
<div class="${c('aplista')}">${related.slice(0, 4).map(a => apLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${apHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('apwrap')}"><div class="${c('apin')}">
<article class="${c('apart')}">
<div class="${c('apcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('apchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('apdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('aphero')}"><span data-f>${H.pic(art, true)}</span></span>
${apLegenda(ctx, art)}` : ''}
<div class="${c('apbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${apAssinatura(ctx, art)}
${rel}
</div></main>
${apFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function apList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${apHeader(ctx, menu)}
<main class="${c('apwrap')}">
<section class="${c('apsec')}" data-par="0"><div class="${c('apin')}">
<div class="${c('apcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('apdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? apDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('aplista')}">${resto.map(a => apLinha(ctx, a, 2)).join('')}</div>` : ''}
</div></section>
</main>
${apFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AQ, arquetipo REVISTA. Feita para o revistarumo.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal regional do Noroeste, e o acervo preservado ficou
 * concentrado em entretenimento, dica e saude. O desenho pega o gesto do
 * **boletim**: cada secao e uma **faixa de fundo cheio**, alternando papel e
 * areia, a materia principal vem com a **imagem a ESQUERDA** e o texto a
 * direita, e as demais viram **duas colunas de itens com filete vertical**, cada
 * um com miniatura quadrada pequena.
 *
 * ## O que a diferencia das 36 vizinhas da opengravity
 *
 *   - **faixa de secao com fundo cheio, alternando**. Todas as 36 usam fundo
 *     unico com filete ou pastilha separando. Alternar o fundo da secao inteira
 *     muda a silhueta da pagina a distancia, que e o que primeiro se ve
 *   - **imagem a ESQUERDA na materia principal**. A `AE`, a `AG`, a `AI` e a
 *     `AJ` poem a imagem a direita ou por cima; nenhuma espelha
 *   - **lista em duas colunas**, e nao em coluna unica
 *   - **Vollkorn e Cabin**: nenhuma das duas aparece nas 90 familias em uso
 *   - **marinho com milho**: nao existe azul-marinho com amarelo entre as 23
 *     paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a faixa de fundo sangra ate a borda da tela, mas o conteudo continua no
 *     contentor: fundo cheio nao pode empurrar o texto para a borda
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */


function aqCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('aqwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('aqwrap')} *{box-sizing:border-box}
${s('aqin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('aqwrap')} h1,${s('aqwrap')} h2,${s('aqwrap')} h3,${s('aqwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('aqwrap')} a{color:inherit;text-decoration:none}
${s('aqwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('aqtop')}{background:var(--paper);border-bottom:5px solid var(--pri)}
${s('aqbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('aqmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('aqmarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('aqmarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('aqmarca')} img{height:31px}}
${s('aqfb')} img{display:block;height:34px;width:auto}
${s('aqnav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('aqnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('aqnav')} a:hover{color:var(--tinta)}
${s('aqbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('aqbusca')}:hover{background:var(--viva)}
${s('aqham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('aqham')} i,${s('aqham')} i::before,${s('aqham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('aqham')} i{top:21px}
${s('aqham')} i::before{top:-6px;left:0}
${s('aqham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('aqmarca')}{font-size:21px;gap:8px}
  ${s('aqbar')}{gap:11px}
  ${s('aqbusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('aqham')}{display:block;order:2}
  ${s('aqbusca')}{order:3;margin-left:0}
  ${s('aqnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('aqnav')}[data-aberto="1"]{display:flex}
  ${s('aqnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('aqabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('aqabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('aqabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('aqmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('aqmm')} b{color:var(--ink);font-weight:700}
${s('aqfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('aqfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aqfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('aqabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: o cabecalho da capa da revista ---------- */
/* ⚠️ nada de faixa de fundo: a marca e clara e arejada, e faixa cheia brigaria
   com o italico serifado do logotipo */
${s('aqsec')}{padding-block:44px;background:var(--paper)}
${s('aqsec')}[data-par="1"]{background:var(--wash)}
/* o nome da editoria vem CENTRALIZADO, que aqui e a excecao permitida: e o
   proprio desenho da marca, o mesmo do logotipo, e nao texto corrido */
${s('aqcab')}{display:block;text-align:center;margin-bottom:30px}
${s('aqcab')} h1,${s('aqcab')} h2{font-family:var(--fd);font-style:italic;
  font-size:clamp(26px,3.3vw,38px);font-weight:500;letter-spacing:-.005em;color:var(--pri);
  margin:0;line-height:1.1}
/* o filete com o ponto coral no meio, tirado do logotipo */
${s('aqfio')}{display:flex;align-items:center;justify-content:center;gap:14px;
  margin:0 auto 9px;max-width:340px}
${s('aqfio')}::before,${s('aqfio')}::after{content:"";flex:1;height:1px;background:var(--line)}
${s('aqfio')} span{font-family:var(--fb);font-size:10.5px;font-weight:600;
  letter-spacing:${fp.kickerLs || '.34em'};color:var(--tinta);
  white-space:nowrap}
${s('aqponto')}{display:block;width:7px;height:7px;border-radius:50%;background:var(--viva);
  margin:11px auto 0}
${s('aqmais')}{display:inline-block;margin-top:13px;font-family:var(--fb);font-size:10.5px;
  font-weight:700;letter-spacing:.13em;color:var(--tinta)}
${s('aqmais')}:hover{text-decoration:underline;text-underline-offset:4px}
${s('aqdescr')}{margin:0 auto 26px;font-size:16px;line-height:1.65;color:var(--dek);
  max-width:64ch;text-align:left}

/* a materia de abertura da secao: foto larga em cima, texto embaixo, medida curta */
${s('aqdest')}{display:block;padding-bottom:30px}
${s('aqdest')} ${s('aqti')}{font-family:var(--fd);font-style:italic;font-weight:500;
  font-size:clamp(23px,2.9vw,34px);line-height:1.14;margin-top:13px;letter-spacing:-.008em}
${s('aqkick')}{display:block;font-family:var(--fb);font-size:10px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.2em'};color:var(--tinta)}
${s('aqti')}{display:block;font-family:var(--fd);font-weight:500;font-size:19px;line-height:1.2;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('aqdd')}{display:block;margin:12px 0 0;font-size:16px;line-height:1.62;color:var(--dek);
  max-width:60ch;text-align:left}
${s('aqdt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:11.5px;
  letter-spacing:.03em;color:var(--muted)}
${s('aqfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('aqfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '21/9'};overflow:hidden}
${s('aqfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .6s ease}
${s('aqdest')}:hover ${s('aqti')}{color:var(--pri)}
${s('aqdest')}:hover ${s('aqfoto')} [data-f] img{transform:scale(1.02)}

/* a grade: tres colunas, sem moldura, separadas so por respiro */
${s('aqlista')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 30px}
${s('aqrow')}{display:block}
${s('aqrow')}>span{display:block}
${s('aqmini')}{display:block;overflow:hidden;background:var(--ph);margin-bottom:14px;
  border-radius:${canto}}
${s('aqmini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '3/2'};overflow:hidden}
${s('aqmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .6s ease}
${s('aqrow')}:hover ${s('aqmini')} [data-f] img{transform:scale(1.04)}
${s('aqrow')}:hover ${s('aqti')}{color:var(--tinta)}
${s('aqrow')} ${s('aqti')}{font-size:18px;line-height:1.24}
${s('aqrow')} ${s('aqkick')}{margin-bottom:6px}
@media(max-width:900px){${s('aqlista')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){
  ${s('aqlista')}{grid-template-columns:1fr;gap:28px}
  ${s('aqdd')}{display:none}
}

/* ---------- artigo ---------- */
${s('aqart')}{padding-block:30px 8px}
${s('aqcol')}{max-width:${fp.medida || '700px'}}
${s('aqchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
${s('aqart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('aqdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('aqhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('aqhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aqhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('aqleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('aqbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('aqbody')} p{margin:0 0 1.15em;text-align:left}
${s('aqbody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('aqbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('aqbody')} ul,${s('aqbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('aqbody')} li{margin:0 0 .45em}
${s('aqbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('aqbody')} a:hover{color:var(--tinta)}
${s('aqbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('aqbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('aqbody')} .rev-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('aqbody')} .rev-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('aqbody')} .rev-veja ul{list-style:none;margin:0;padding:0}
${s('aqbody')} .rev-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('aqbody')} .rev-veja li:first-child{border-top:0;padding-top:0}
${s('aqbody')} .rev-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('aqbody')} .rev-veja a:hover{color:var(--tinta)}
${s('aqbody')} figure{margin:1.5em 0}
${s('aqbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('aqbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('aqbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('aqbody')} th,${s('aqbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('aqbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('aqbody')} table{min-width:0}
  ${s('aqbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('aqbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('aqbody')} table,${s('aqbody')} tbody,${s('aqbody')} tr,${s('aqbody')} th,
  ${s('aqbody')} td{display:block;width:auto}
  ${s('aqbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('aqbody')} tbody th,${s('aqbody')} tbody td{border:0;background:transparent}
  ${s('aqbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('aqbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('aqbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('aqass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('aqass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('aqass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('aqass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('aqass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('aqass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('aqass')} .go:hover{text-decoration:underline}
${s('aqrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('aqrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('aqfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('aqcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('aqfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('aqfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('aqfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('aqfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('aqflist')}{display:flex;flex-direction:column;gap:9px}
${s('aqflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('aqflist')} a:hover{opacity:1;color:var(--viva)}
${s('aqfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('aqcols')}{grid-template-columns:1fr;gap:26px}
  ${s('aqfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AQ_SIMB = `<svg viewBox="0 0 30 14" role="img" aria-hidden="true" focusable="false"><path d="M1 7 h10 M19 7 h10" stroke="var(--marca-1,currentColor)" stroke-width="1.6" stroke-linecap="round"/><circle cx="15" cy="7" r="3.4" fill="var(--marca-2,currentColor)"/></svg>`;

const AQ_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function aqHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aknav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aqtop')}">
<div class="${c('aqin')} ${c('aqbar')}">
<a class="${c('aqmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AQ_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('aqnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('aqham')}" type="button" data-akham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('aqbusca')}" href="/busca/">${AQ_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-akham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function aqFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('aqfoot')}"><div class="${c('aqin')}">
<div class="${c('aqcols')}">
  <div><a class="${c('aqfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AQ_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('aqfh')}">Editorias</div><div class="${c('aqflist')}">${cats}</div></div>
  <div><div class="${c('aqfh')}">O jornal</div><div class="${c('aqflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('aqfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function aqDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // foto larga em cima e texto embaixo, como abertura de materia de revista
  return `<a class="${c('aqdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('aqfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('aqkick')}">${H.cat(a)}</span>
<h${n} class="${c('aqti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('aqdd')}">${H.esc(H.clip(a.dek, 190))}</span>` : ''}
<span class="${c('aqdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function aqLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aqrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('aqmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('aqkick')}">${H.cat(a)}</span>
<h${n} class="${c('aqti')}">${H.esc(a.title)}</h${n}>
<span class="${c('aqdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function aqHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('aqabre')}">
<div><span class="${c('aqchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('aqmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('aqfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('aqsec')}" data-par="${idx % 2}">
<div class="${c('aqin')}">
<div class="${c('aqcab')}">
<div class="${c('aqfio')}"><span>Revista</span></div>
<h2>${H.esc(nome)}</h2><span class="${c('aqponto')}"></span>
<a class="${c('aqmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${aqDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('aqlista')}" style="--l:${Math.ceil(Math.min(resto.length, 6) / 2)}">${resto.slice(0, 6).map(a => aqLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${aqHeader(ctx, menu)}
<main class="${c('aqwrap')}">
<div class="${c('aqin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${aqFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function aqAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('aqass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function aqLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('aqleg')}">${H.esc(alt)}</p>`;
}

function aqArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('aqrel')}">
<span class="${c('aqrotb')}">Leia também</span>
<div class="${c('aqlista')}" style="--l:${Math.ceil(Math.min(related.length, 3) / 2)}">${related.slice(0, 3).map(a => aqLinha(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${aqHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('aqwrap')}"><div class="${c('aqin')}">
<article class="${c('aqart')}">
<div class="${c('aqcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('aqchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('aqdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('aqhero')}"><span data-f>${H.pic(art, true)}</span></span>
${aqLegenda(ctx, art)}` : ''}
<div class="${c('aqbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${aqAssinatura(ctx, art)}
${rel}
</div></main>
${aqFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function aqList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${aqHeader(ctx, menu)}
<main class="${c('aqwrap')}">
<section class="${c('aqsec')}" data-par="0"><div class="${c('aqin')}">
<div class="${c('aqcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('aqdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? aqDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('aqlista')}" style="--l:${Math.ceil(resto.length / 2)}">${resto.map(a => aqLinha(ctx, a, 2)).join('')}</div>` : ''}
</div></section>
</main>
${aqFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AR, arquetipo MODULO. Feita para o universoneo.com.br.
 *
 * ## De onde vem o desenho
 *
 * O portal e um jornal regional do Noroeste, e o acervo preservado ficou
 * concentrado em entretenimento, dica e saude. O desenho pega o gesto do
 * **boletim**: cada secao e uma **faixa de fundo cheio**, alternando papel e
 * areia, a materia principal vem com a **imagem a ESQUERDA** e o texto a
 * direita, e as demais viram **duas colunas de itens com filete vertical**, cada
 * um com miniatura quadrada pequena.
 *
 * ## O que a diferencia das 36 vizinhas da opengravity
 *
 *   - **faixa de secao com fundo cheio, alternando**. Todas as 36 usam fundo
 *     unico com filete ou pastilha separando. Alternar o fundo da secao inteira
 *     muda a silhueta da pagina a distancia, que e o que primeiro se ve
 *   - **imagem a ESQUERDA na materia principal**. A `AE`, a `AG`, a `AI` e a
 *     `AJ` poem a imagem a direita ou por cima; nenhuma espelha
 *   - **lista em duas colunas**, e nao em coluna unica
 *   - **Vollkorn e Cabin**: nenhuma das duas aparece nas 90 familias em uso
 *   - **marinho com milho**: nao existe azul-marinho com amarelo entre as 23
 *     paletas da rede
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e rotulo
 *     que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca, e a chamada de abertura tem texto a
 *     esquerda e imagem a direita
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - a faixa de fundo sangra ate a borda da tela, mas o conteudo continua no
 *     contentor: fundo cheio nao pode empurrar o texto para a borda
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 */


function arCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('arwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('arwrap')} *{box-sizing:border-box}
${s('arin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('arwrap')} h1,${s('arwrap')} h2,${s('arwrap')} h3,${s('arwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('arwrap')} a{color:inherit;text-decoration:none}
${s('arwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('artop')}{background:var(--paper);border-bottom:5px solid var(--pri)}
${s('arbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('armarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('armarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('armarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('armarca')} img{height:31px}}
${s('arfb')} img{display:block;height:34px;width:auto}
${s('arnav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('arnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('arnav')} a:hover{color:var(--tinta)}
${s('arbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('arbusca')}:hover{background:var(--viva)}
${s('arham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('arham')} i,${s('arham')} i::before,${s('arham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('arham')} i{top:21px}
${s('arham')} i::before{top:-6px;left:0}
${s('arham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('armarca')}{font-size:21px;gap:8px}
  ${s('arbar')}{gap:11px}
  ${s('arbusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('arham')}{display:block;order:2}
  ${s('arbusca')}{order:3;margin-left:0}
  ${s('arnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('arnav')}[data-aberto="1"]{display:flex}
  ${s('arnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('arabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('arabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('arabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('armm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('armm')} b{color:var(--ink);font-weight:700}
${s('arfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('arfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('arfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('arabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: o modulo assimetrico ---------- */
${s('arsec')}{padding-block:38px;background:var(--paper)}
${s('arsec')}[data-par="1"]{background:var(--wash)}
/* o nome da editoria num bloco cheio, herdando o peso do logotipo */
${s('arcab')}{display:flex;align-items:center;justify-content:space-between;gap:16px;
  margin-bottom:24px;flex-wrap:wrap}
${s('arcab')} h1,${s('arcab')} h2{font-family:var(--fd);font-size:clamp(17px,2vw,21px);
  font-weight:800;letter-spacing:.02em;color:var(--sob);
  background:var(--pri);padding:8px 18px 7px;margin:0;line-height:1.15;
  border-radius:${canto}}
${s('armais')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.11em;color:var(--tinta);flex:none}
${s('armais')}:hover{text-decoration:underline;text-underline-offset:4px}
${s('ardescr')}{margin:0 0 22px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* ⚠️ o modulo: coluna larga a esquerda, tres empilhadas a direita */
${s('armod')}{display:grid;grid-template-columns:1.35fr 1fr;gap:32px;align-items:start}
@media(max-width:900px){${s('armod')}{grid-template-columns:1fr;gap:26px}}

/* a materia principal: foto em cima, texto embaixo */
${s('ardest')}{display:block}
${s('ardest')} ${s('arti')}{font-size:clamp(21px,2.5vw,29px);line-height:1.14;margin-top:12px}
${s('arkick')}{display:inline-block;font-family:var(--fb);font-size:9.5px;font-weight:800;
  letter-spacing:${fp.kickerLs || '.16em'};color:var(--tinta);
  border-bottom:3px solid var(--viva);padding-bottom:2px}
${s('arti')}{display:block;font-family:var(--fd);font-weight:700;font-size:18px;line-height:1.22;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('ardd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.6;color:var(--dek);
  max-width:56ch;text-align:left}
${s('ardt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('arfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('arfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('arfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('ardest')}:hover ${s('arti')}{color:var(--pri)}
${s('ardest')}:hover ${s('arfoto')} [data-f] img{transform:scale(1.03)}

/* as tres da direita: miniatura quadrada e filete entre elas */
${s('arlista')}{display:flex;flex-direction:column}
${s('arrow')}{display:grid;grid-template-columns:minmax(0,1fr) 88px;gap:16px;align-items:center;
  padding-block:16px;border-top:1px solid var(--line)}
${s('arlista')}>${s('arrow')}:first-child{border-top:0;padding-top:0}
${s('armini')}{display:block;width:88px;overflow:hidden;background:var(--ph);
  border-radius:${canto};order:2}
${s('armini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '1/1'};overflow:hidden}
${s('armini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('arrow')}:hover ${s('armini')} [data-f] img{transform:scale(1.07)}
${s('arrow')}:hover ${s('arti')}{color:var(--pri)}
${s('arrow')} ${s('arti')}{font-size:16.5px}
${s('arrow')} ${s('arkick')}{border-bottom-width:2px;margin-bottom:6px}
${s('arrow')} ${s('ardd')}{display:none}
@media(max-width:560px){
  ${s('arrow')}{grid-template-columns:minmax(0,1fr) 70px;gap:12px}
  ${s('armini')}{width:70px}
}
/* a listagem e os relacionados usam grade de tres, e nao o modulo */
${s('argrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 28px}
${s('argrade')} ${s('arti')}{font-size:19px;line-height:1.22}
${s('argrade')} ${s('ardd')}{display:none}
@media(max-width:900px){${s('argrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){${s('argrade')}{grid-template-columns:1fr}}

/* ---------- artigo ---------- */
${s('arart')}{padding-block:30px 8px}
${s('arcol')}{max-width:${fp.medida || '700px'}}
${s('archap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
${s('arart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.07;margin:13px 0 0;
  letter-spacing:-.02em}
${s('ardek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('arhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('arhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('arhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('arleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('arbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('arbody')} p{margin:0 0 1.15em;text-align:left}
${s('arbody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('arbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('arbody')} ul,${s('arbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('arbody')} li{margin:0 0 .45em}
${s('arbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('arbody')} a:hover{color:var(--tinta)}
${s('arbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('arbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('arbody')} .uni-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('arbody')} .uni-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('arbody')} .uni-veja ul{list-style:none;margin:0;padding:0}
${s('arbody')} .uni-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('arbody')} .uni-veja li:first-child{border-top:0;padding-top:0}
${s('arbody')} .uni-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('arbody')} .uni-veja a:hover{color:var(--tinta)}
${s('arbody')} figure{margin:1.5em 0}
${s('arbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('arbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('arbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('arbody')} th,${s('arbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('arbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('arbody')} table{min-width:0}
  ${s('arbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('arbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('arbody')} table,${s('arbody')} tbody,${s('arbody')} tr,${s('arbody')} th,
  ${s('arbody')} td{display:block;width:auto}
  ${s('arbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('arbody')} tbody th,${s('arbody')} tbody td{border:0;background:transparent}
  ${s('arbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('arbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('arbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('arass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('arass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('arass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('arass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('arass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('arass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('arass')} .go:hover{text-decoration:underline}
${s('arrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('arrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('arfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('arcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('arfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('arfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('arfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('arfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('arflist')}{display:flex;flex-direction:column;gap:9px}
${s('arflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('arflist')} a:hover{opacity:1;color:var(--viva)}
${s('arfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('arcols')}{grid-template-columns:1fr;gap:26px}
  ${s('arfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AR_SIMB = `<svg viewBox="0 0 26 20" role="img" aria-hidden="true" focusable="false"><circle cx="13" cy="8" r="6.6" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="3"/><path d="M1 17 h8 M17 17 h8" stroke="var(--marca-2,currentColor)" stroke-width="2.6" stroke-linecap="round"/></svg>`;

const AR_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function arHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aknav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('artop')}">
<div class="${c('arin')} ${c('arbar')}">
<a class="${c('armarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AR_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('arnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('arham')}" type="button" data-akham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('arbusca')}" href="/busca/">${AR_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-akham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function arFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('arfoot')}"><div class="${c('arin')}">
<div class="${c('arcols')}">
  <div><a class="${c('arfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AR_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('arfh')}">Editorias</div><div class="${c('arflist')}">${cats}</div></div>
  <div><div class="${c('arfh')}">O jornal</div><div class="${c('arflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('arfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function arDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // foto em cima e texto embaixo: e a coluna larga do modulo
  return `<a class="${c('ardest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('arfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('arkick')}">${H.cat(a)}</span>
<h${n} class="${c('arti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('ardd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('ardt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function arLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('arrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('armini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('arkick')}">${H.cat(a)}</span>
<h${n} class="${c('arti')}">${H.esc(a.title)}</h${n}>
<span class="${c('ardt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function arHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('arabre')}">
<div><span class="${c('archap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('armm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('arfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('arsec')}" data-par="${idx % 2}">
<div class="${c('arin')}">
<div class="${c('arcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('armais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
<div class="${c('armod')}">${arDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('arlista')}">${resto.slice(0, 3).map(a => arLinha(ctx, a)).join('')}</div>` : ''}</div>
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${arHeader(ctx, menu)}
<main class="${c('arwrap')}">
<div class="${c('arin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${arFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function arAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('arass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function arLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('arleg')}">${H.esc(alt)}</p>`;
}

function arArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('arrel')}">
<span class="${c('arrotb')}">Leia também</span>
<div class="${c('argrade')}">${related.slice(0, 3).map(a => arDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${arHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('arwrap')}"><div class="${c('arin')}">
<article class="${c('arart')}">
<div class="${c('arcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('archap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('ardek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('arhero')}"><span data-f>${H.pic(art, true)}</span></span>
${arLegenda(ctx, art)}` : ''}
<div class="${c('arbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${arAssinatura(ctx, art)}
${rel}
</div></main>
${arFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function arList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${arHeader(ctx, menu)}
<main class="${c('arwrap')}">
<section class="${c('arsec')}" data-par="0"><div class="${c('arin')}">
<div class="${c('arcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('ardescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? arDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('argrade')}">${resto.map(a => arDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${arFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AS, arquetipo SINAL. Feita para o pontonaturalbrasil.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca e a palavra PN BRASIL em grotesco geometrico pesado, com tres arcos
 * concentricos e um ponto a esquerda: o desenho de um sinal irradiando. O
 * favicon da origem e so esse simbolo, em verde vivo sobre branco.
 *
 * O gesto da arquitetura sai dai: cada secao ganha um rotulo lateral estreito
 * que acompanha a rolagem, com os arcos por cima do nome da editoria, e a
 * coluna de materias corre a direita. O sinal fica parado enquanto o conteudo
 * passa por ele.
 *
 * ## O que a diferencia das 44 vizinhas da opengravity
 *
 *   - rotulo de secao horizontal, estreito e preso na rolagem. A AL gira o
 *     texto na vertical, a AK usa faixa cheia, a AM caixas, a AN mosaico, a AO
 *     linha do tempo, a AP moldura de tela, a AQ cabecalho de revista e a AR
 *     modulo assimetrico. Nenhuma prende o rotulo
 *   - trio de colunas separadas por filete vertical embaixo da materia de
 *     abertura, e nao lista com miniatura ao lado
 *   - Darker Grotesque e Rubik: nenhuma das duas esta nas 55 familias em uso
 *   - verde profundo com verde vivo: a unica paleta verde da maquina, e o vivo
 *     vem medido do favicon da origem
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 flatUrl false COM categoryBase "categoria". O artigo mora em
 * /<editoria>/<slug>/ e o arquivo de editoria em /categoria/<slug>/. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do
 * rodape e o chapeu de cada artigo em 404, sem aparecer em print nenhum.
 * Editoria sai de H.curl(slug), artigo de H.url(a), sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, /<editoria>/ vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do error_page 403 =404.
 *
 * ⚠️ O verde vivo #00FF30 da 1,4:1 sobre branco. Ele e filete, arco e bloco,
 * nunca texto. Chapeu e etiqueta usam --tinta, com 5,4:1.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por H.curl(slug) e de artigo por H.url(a)
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo span com aspect-ratio tem display block, e o a do cartao tem display
 *   - body aberto no cabecalho e H.bodyEnd() nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o alt descreve a foto
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no :root, e nao no seletor do elemento principal
 *   - o respiro lateral usa padding-block, nunca padding completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 *   - a classe do bloco "Veja tambem" leva o prefixo DESTE portal
 */


function asCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};--fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('aswrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('aswrap')} *{box-sizing:border-box}
${s('asin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('aswrap')} h1,${s('aswrap')} h2,${s('aswrap')} h3,${s('aswrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('aswrap')} a{color:inherit;text-decoration:none}
${s('aswrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('astop')}{background:var(--paper);border-bottom:5px solid var(--pri)}
${s('asbar')}{display:flex;align-items:center;gap:18px;padding-block:19px 16px;flex-wrap:wrap}
${s('asmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:clamp(23px,3vw,32px);letter-spacing:-.018em;color:var(--pri);flex:none}
${s('asmarca')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('asmarca')} img{display:block;height:38px;width:auto;flex:none}
@media(max-width:560px){${s('asmarca')} img{height:31px}}
${s('asfb')} img{display:block;height:34px;width:auto}
${s('asnav')}{display:flex;gap:14px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('asnav')} a{font-family:var(--fb);font-size:11.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('asnav')} a:hover{color:var(--tinta)}
${s('asbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;margin-left:8px}
${s('asbusca')}:hover{background:var(--viva)}
${s('asham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('asham')} i,${s('asham')} i::before,${s('asham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('asham')} i{top:21px}
${s('asham')} i::before{top:-6px;left:0}
${s('asham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('asmarca')}{font-size:21px;gap:8px}
  ${s('asbar')}{gap:11px}
  ${s('asbusca')}{font-size:10px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('asham')}{display:block;order:2}
  ${s('asbusca')}{order:3;margin-left:0}
  ${s('asnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('asnav')}[data-aberto="1"]{display:flex}
  ${s('asnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink)}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('asabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('asabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('asabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('asmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('asmm')} b{color:var(--ink);font-weight:700}
${s('asfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('asfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('asfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('asabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: o rotulo lateral que acompanha a rolagem ---------- */
${s('assec')}{padding-block:44px;background:var(--paper);border-top:1px solid var(--line)}
${s('assec')}[data-par="1"]{background:var(--wash)}

/* ⚠️ o modulo: rotulo estreito a esquerda, coluna de materias a direita */
${s('asmod')}{display:grid;grid-template-columns:212px minmax(0,1fr);gap:46px;align-items:start}
@media(max-width:900px){${s('asmod')}{grid-template-columns:1fr;gap:20px}}

${s('ascab')}{position:sticky;top:20px;display:block}
/* ⚠️ a Darker Grotesque tem ascendente alto: com line-height abaixo de 1,1 o
   texto transborda a caixa e encosta na linha seguinte */
${s('ascab')} h1,${s('ascab')} h2{font-family:var(--fd);font-weight:800;
  font-size:clamp(25px,2.8vw,35px);line-height:1.12;letter-spacing:-.026em;
  color:var(--pri);margin:0 0 2px}
/* os arcos da marca viram o marcador de editoria */
${s('asarco')}{display:block;width:40px;height:40px;margin-bottom:15px;color:var(--viva)}
${s('asarco')} svg{display:block;width:100%;height:100%}
${s('asmais')}{display:inline-block;margin-top:15px;font-family:var(--fb);font-size:10.5px;
  font-weight:700;letter-spacing:.13em;color:var(--tinta);
  border-bottom:2px solid var(--viva);padding-bottom:3px}
${s('asmais')}:hover{color:var(--pri)}
@media(max-width:900px){
  ${s('ascab')}{position:static;display:flex;align-items:center;gap:14px;flex-wrap:wrap}
  ${s('asarco')}{width:27px;height:27px;margin-bottom:0}
  ${s('asmais')}{margin-top:0;margin-left:auto}
}
${s('asdescr')}{margin:0 0 22px;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:70ch;text-align:left}

/* a materia de abertura da secao: foto larga em cima, texto embaixo */
${s('asdest')}{display:block}
${s('asdest')} ${s('asti')}{font-size:clamp(21px,2.5vw,30px);line-height:1.12;margin-top:13px}
${s('askick')}{display:inline-block;font-family:var(--fb);font-size:9.5px;font-weight:800;
  letter-spacing:${fp.kickerLs || '.15em'};color:var(--tinta)}
${s('asti')}{display:block;font-family:var(--fd);font-weight:700;font-size:18px;line-height:1.2;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('asdd')}{display:block;margin:12px 0 0;font-size:15.5px;line-height:1.6;color:var(--dek);
  max-width:58ch;text-align:left}
${s('asdt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('asfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('asfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('asfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('asdest')}:hover ${s('asti')}{color:var(--pri)}
${s('asdest')}:hover ${s('asfoto')} [data-f] img{transform:scale(1.03)}

/* o trio de baixo: tres colunas separadas por filete vertical */
${s('aslista')}{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:32px;
  padding-top:24px;border-top:1px solid var(--line)}
${s('asrow')}{display:block;padding:0 22px;border-left:1px solid var(--line)}
${s('aslista')}>${s('asrow')}:first-child{border-left:0;padding-left:0}
${s('aslista')}>${s('asrow')}:last-child{padding-right:0}
${s('asmini')}{display:block;overflow:hidden;background:var(--ph);margin-bottom:12px;
  border-radius:${canto}}
${s('asmini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '3/2'};overflow:hidden}
${s('asmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('asrow')}:hover ${s('asmini')} [data-f] img{transform:scale(1.05)}
${s('asrow')}:hover ${s('asti')}{color:var(--pri)}
${s('asrow')} ${s('asti')}{font-size:16.5px;margin-top:7px}
${s('asrow')} ${s('asdd')}{display:none}
@media(max-width:760px){
  ${s('aslista')}{grid-template-columns:1fr 1fr}
  ${s('asrow')}{padding:0 16px}
  ${s('aslista')}>${s('asrow')}:nth-child(3){border-left:0;padding-left:0;margin-top:22px}
}
@media(max-width:520px){
  ${s('aslista')}{grid-template-columns:1fr;gap:22px}
  ${s('asrow')}{padding:0;border-left:0}
  ${s('aslista')}>${s('asrow')}:nth-child(3){margin-top:0}
}

/* a listagem de editoria e os relacionados usam grade de tres cartoes */
${s('asgrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 28px}
${s('asgrade')} ${s('asti')}{font-size:19px;line-height:1.22}
${s('asgrade')} ${s('asdd')}{display:none}
@media(max-width:900px){${s('asgrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){${s('asgrade')}{grid-template-columns:1fr}}

/* ---------- artigo ---------- */
${s('asart')}{padding-block:30px 8px}
${s('ascol')}{max-width:${fp.medida || '700px'}}
${s('aschap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
/* ⚠️ a Darker Grotesque tem ascendente alto: abaixo de 1,16 o titulo de duas
   linhas encosta na assinatura, que vem logo abaixo e nao tem margem propria */
${s('asart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.16;margin:13px 0 15px;
  letter-spacing:-.02em}
${s('asdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('ashero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('ashero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('ashero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('asleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('asbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('asbody')} p{margin:0 0 1.15em;text-align:left}
${s('asbody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('asbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('asbody')} ul,${s('asbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('asbody')} li{margin:0 0 .45em}
${s('asbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('asbody')} a:hover{color:var(--tinta)}
${s('asbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('asbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('asbody')} .pnb-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('asbody')} .pnb-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('asbody')} .pnb-veja ul{list-style:none;margin:0;padding:0}
${s('asbody')} .pnb-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('asbody')} .pnb-veja li:first-child{border-top:0;padding-top:0}
${s('asbody')} .pnb-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('asbody')} .pnb-veja a:hover{color:var(--tinta)}
${s('asbody')} figure{margin:1.5em 0}
${s('asbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('asbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('asbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('asbody')} th,${s('asbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('asbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('asbody')} table{min-width:0}
  ${s('asbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('asbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('asbody')} table,${s('asbody')} tbody,${s('asbody')} tr,${s('asbody')} th,
  ${s('asbody')} td{display:block;width:auto}
  ${s('asbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('asbody')} tbody th,${s('asbody')} tbody td{border:0;background:transparent}
  ${s('asbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('asbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('asbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('asass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('asass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('asass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('asass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('asass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('asass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('asass')} .go:hover{text-decoration:underline}
${s('asrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('asrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('asfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('ascols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('asfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('asfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('asfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('asfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('asflist')}{display:flex;flex-direction:column;gap:9px}
${s('asflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('asflist')} a:hover{opacity:1;color:var(--viva)}
${s('asfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('ascols')}{grid-template-columns:1fr;gap:26px}
  ${s('asfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AS_SIMB = `<svg viewBox="0 0 28 28" role="img" aria-hidden="true" focusable="false" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2.6" stroke-linecap="round"><path d="M13 22 A6 6 0 0 0 7 16"/><path d="M18 22 A11 11 0 0 0 7 11"/><path d="M23 22 A16 16 0 0 0 7 6"/><circle cx="7" cy="22" r="2"/></svg>`;

const AS_ARCO = `<svg viewBox="0 0 40 40" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"><path d="M17 31 A7 7 0 0 0 10 24"/><path d="M23 31 A13 13 0 0 0 10 18"/><path d="M29 31 A19 19 0 0 0 10 12"/><circle cx="10" cy="31" r="2.4"/></svg>`;

const AS_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function asHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'asnav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('astop')}">
<div class="${c('asin')} ${c('asbar')}">
<a class="${c('asmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AS_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('asnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('asham')}" type="button" data-asham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('asbusca')}" href="/busca/">${AS_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-asham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function asFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('asfoot')}"><div class="${c('asin')}">
<div class="${c('ascols')}">
  <div><a class="${c('asfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AS_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('asfh')}">Editorias</div><div class="${c('asflist')}">${cats}</div></div>
  <div><div class="${c('asfh')}">O jornal</div><div class="${c('asflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('asfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function asDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // foto em cima e texto embaixo: e a coluna larga do modulo
  return `<a class="${c('asdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('asfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('askick')}">${H.cat(a)}</span>
<h${n} class="${c('asti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('asdd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('asdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function asLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // miniatura em cima e texto embaixo: e uma das tres colunas do trio
  return `<a class="${c('asrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('asmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span class="${c('askick')}">${H.cat(a)}</span>
<h${n} class="${c('asti')}">${H.esc(a.title)}</h${n}>
<span class="${c('asdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function asHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('asabre')}">
<div><span class="${c('aschap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('asmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('asfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('assec')}" data-par="${idx % 2}">
<div class="${c('asin')}">
<div class="${c('asmod')}">
<div class="${c('ascab')}"><span class="${c('asarco')}">${AS_ARCO}</span>
<h2>${H.esc(nome)}</h2>
<a class="${c('asmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
<div>${asDestaque(ctx, d, false)}
${resto.length ? `<div class="${c('aslista')}">${resto.slice(0, 3).map(a => asLinha(ctx, a)).join('')}</div>` : ''}</div>
</div>
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${asHeader(ctx, menu)}
<main class="${c('aswrap')}">
<div class="${c('asin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${asFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function asAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('asass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function asLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('asleg')}">${H.esc(alt)}</p>`;
}

function asArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('asrel')}">
<span class="${c('asrotb')}">Leia também</span>
<div class="${c('asgrade')}">${related.slice(0, 3).map(a => asDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${asHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('aswrap')}"><div class="${c('asin')}">
<article class="${c('asart')}">
<div class="${c('ascol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('aschap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('asdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('ashero')}"><span data-f>${H.pic(art, true)}</span></span>
${asLegenda(ctx, art)}` : ''}
<div class="${c('asbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${asAssinatura(ctx, art)}
${rel}
</div></main>
${asFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function asList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${asHeader(ctx, menu)}
<main class="${c('aswrap')}">
<section class="${c('assec')}" data-par="0"><div class="${c('asin')}">
<div class="${c('ascab')}"><span class="${c('asarco')}">${AS_ARCO}</span>
<h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('asdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? asDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('asgrade')}">${resto.map(a => asDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${asFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AT, arquetipo MANCHETE. Feita para o folhar.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca do Folha R e a palavra FOLHA em grotesco pesado com extrusao, e um R
 * atravessado por uma seta que sobe. A assinatura da origem e "noticias e
 * conteudos 24 horas". O favicon dela e so esse R, branco sobre preto.
 *
 * Dois gestos saem dai: a **barra chumbo** no topo e no rodape, e a **lista
 * numerada** de cada secao, com o numeral grande em contorno prata a esquerda do
 * titulo, que le como ordem de chegada.
 *
 * ## O que a diferencia das 45 vizinhas da opengravity
 *
 *   - 🔴 **cabecalho e rodape escuros**. Todas as 45 tem barra clara. Aqui nao e
 *     escolha estetica: a versao "preta" do logotipo da origem tem a palavra
 *     preta mas **o R continua branco**, e sobre papel branco o simbolo some.
 *     A barra escura e o que deixa a marca aparecer inteira
 *   - **lista numerada sem miniatura**. A AO usa marcador redondo de linha do
 *     tempo, a AS arcos, a AM caixas: nenhuma numera
 *   - **manchete horizontal com imagem a esquerda**, e o filete que corre da
 *     editoria ate a borda do contentor
 *   - **Oswald e Barlow**: nenhuma das duas esta nas 55 familias em uso
 *   - **chumbo com brasa**: nao existe quase-preto com laranja-brasa na maquina
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: true` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<slug>/`, na raiz, e a editoria em `/categoria/<slug>/`. Montar o link de
 * editoria a mao poe o menu do topo, o do rodape e o chapeu de cada artigo em
 * 404. Editoria sai de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como tudo divide a raiz, **slug podado colide com pagina que o motor
 * regenera**: contato, politica-de-privacidade, termos-de-uso e quem-somos ficam
 * fora do 410.
 *
 * ⚠️ **O `--barbg` e o `--bartx` sao declarados no `:root`.** Variavel de cor
 * definida no seletor do elemento principal nao alcanca o cabecalho, e o botao
 * do menu fica invisivel no celular.
 *
 * ⚠️ **O numeral da lista sai de `counter` em `::before`**, e nao de texto no
 * HTML: assim leitor de tela nao anuncia "zero dois" no meio do titulo. O
 * contorno usa `-webkit-text-stroke`, com reserva para quem nao tem suporte.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 *   - a classe do bloco "Veja tambem" leva o prefixo DESTE portal
 */


function atCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --barbg:${t.barBg || t.ink};--bartx:${t.barTx || '#fff'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('atwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('atwrap')} *{box-sizing:border-box}
${s('atin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('atwrap')} h1,${s('atwrap')} h2,${s('atwrap')} h3,${s('atwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('atwrap')} a{color:inherit;text-decoration:none}
${s('atwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: barra chumbo, que e onde a marca da origem vive ---------- */
/* 🔴 a marca do portal e branca com o R branco: sobre papel ela some. A barra
   escura nao e enfeite, e o que deixa o simbolo aparecer */
${s('attop')}{background:var(--barbg);color:var(--bartx);
  border-bottom:4px solid var(--viva)}
${s('atbar')}{display:flex;align-items:center;gap:18px;padding-block:16px;flex-wrap:wrap}
${s('atmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:600;font-size:clamp(23px,3vw,31px);letter-spacing:.02em;color:var(--bartx);flex:none}
${s('atmarca')} svg{display:block;height:.7em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
/* ⚠️ o logotipo tem a assinatura "noticias e conteudos 24 horas" embaixo do
   nome, em corpo pequeno: abaixo de 46px ela vira borrao */
${s('atmarca')} img{display:block;height:46px;width:auto;flex:none}
@media(max-width:560px){${s('atmarca')} img{height:36px}}
${s('atfb')} img{display:block;height:36px;width:auto}
${s('atnav')}{display:flex;gap:16px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('atnav')} a{font-family:var(--fd);font-size:13.5px;font-weight:500;letter-spacing:.06em;color:var(--bartx);opacity:.82;transition:opacity .2s ease}
${s('atnav')} a:hover{opacity:1;text-decoration:underline;text-underline-offset:5px;
  text-decoration-color:var(--viva);text-decoration-thickness:2px}
${s('atbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fd);
  font-size:12.5px;font-weight:600;letter-spacing:.08em;
  background:var(--viva);color:#fff;padding:10px 16px;border-radius:${canto};flex:none;
  margin-left:8px}
${s('atbusca')}:hover{filter:brightness(1.08)}
${s('atham')}{display:none;width:46px;height:46px;border:2px solid rgba(255,255,255,.5);
  background:none;cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('atham')} i,${s('atham')} i::before,${s('atham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--bartx);content:""}
${s('atham')} i{top:21px}
${s('atham')} i::before{top:-6px;left:0}
${s('atham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('atmarca')}{font-size:21px;gap:8px}
  ${s('atbar')}{gap:11px}
  ${s('atbusca')}{font-size:11px;padding:9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('atham')}{display:block;order:2}
  ${s('atbusca')}{order:3;margin-left:0}
  ${s('atnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid rgba(255,255,255,.18);margin-top:14px}
  ${s('atnav')}[data-aberto="1"]{display:flex}
  ${s('atnav')} a{width:100%;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.14);
    opacity:1;font-size:14.5px}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('atabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('atabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('atabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('atmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('atmm')} b{color:var(--ink);font-weight:700}
${s('atfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('atfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('atfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('atabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: manchete larga e lista numerada ---------- */
${s('atsec')}{padding-block:38px;background:var(--paper)}
${s('atsec')}[data-par="1"]{background:var(--wash)}

/* o nome da editoria com a seta da marca e o filete que corre ate a borda */
${s('atcab')}{display:flex;align-items:center;gap:14px;margin-bottom:24px}
${s('atcab')} h1,${s('atcab')} h2{font-family:var(--fd);font-weight:600;
  font-size:clamp(19px,2.2vw,25px);letter-spacing:.06em;
  color:var(--ink);margin:0;line-height:1.2;flex:none}
${s('atseta')}{display:block;width:30px;height:23px;color:var(--viva);flex:none}
${s('atseta')} svg{display:block;width:100%;height:100%}
/* o filete come o espaco que sobra: e o que da a silhueta de manchete */
${s('atfio')}{flex:1 1 auto;height:3px;background:var(--viva);min-width:24px}
${s('atmais')}{font-family:var(--fd);font-size:12px;font-weight:600;letter-spacing:.1em;color:var(--tinta);flex:none}
${s('atmais')}:hover{text-decoration:underline;text-underline-offset:4px}
${s('atdescr')}{margin:0 0 24px;font-size:15.5px;line-height:1.64;color:var(--dek);
  max-width:72ch;text-align:left}

/* ⚠️ a manchete e horizontal: imagem a ESQUERDA e texto a direita */
${s('atdest')}{display:grid;grid-template-columns:1.15fr 1fr;gap:28px;align-items:center;
  padding-bottom:26px;border-bottom:1px solid var(--line)}
${s('atdest')} ${s('atti')}{font-size:clamp(22px,2.7vw,33px);line-height:1.1;margin-top:11px;
  letter-spacing:-.012em}
${s('atkick')}{display:inline-block;font-family:var(--fd);font-size:11.5px;font-weight:600;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--tinta)}
${s('atti')}{display:block;font-family:var(--fd);font-weight:600;font-size:18px;
  line-height:1.18;color:var(--ink);margin:0;transition:color .2s ease;
  letter-spacing:-.004em}
${s('atdd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.6;color:var(--dek);
  max-width:52ch;text-align:left}
${s('atdt')}{display:block;margin-top:10px;font-family:var(--fb);font-size:12px;color:var(--muted)}
${s('atfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('atfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('atfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('atdest')}:hover ${s('atti')}{color:var(--tinta)}
${s('atdest')}:hover ${s('atfoto')} [data-f] img{transform:scale(1.03)}
@media(max-width:820px){
  ${s('atdest')}{grid-template-columns:1fr;gap:16px;align-items:start}
}

/* a lista numerada: o "24 horas" da marca vira ordem de chegada */
${s('atlista')}{counter-reset:at;display:grid;grid-template-columns:1fr 1fr;gap:0 40px;
  margin-top:6px}
${s('atrow')}{counter-increment:at;display:grid;grid-template-columns:58px minmax(0,1fr);
  gap:14px;align-items:start;padding-block:18px;border-bottom:1px solid var(--line)}
/* ⚠️ o numeral e decoracao: sai de counter em ::before, e nao de texto no HTML,
   para o leitor de tela nao anunciar "zero dois" no meio do titulo */
${s('atrow')}::before{content:counter(at,decimal-leading-zero);font-family:var(--fd);
  font-size:34px;font-weight:600;line-height:.9;color:transparent;
  -webkit-text-stroke:1.5px var(--ph);letter-spacing:-.04em}
@supports not ((-webkit-text-stroke:1px red)){
  ${s('atrow')}::before{color:var(--ph);-webkit-text-stroke:0}
}
${s('atrow')}:hover::before{-webkit-text-stroke-color:var(--viva);color:transparent}
${s('atrow')}:hover ${s('atti')}{color:var(--tinta)}
${s('atrow')} ${s('atti')}{font-size:17px;line-height:1.24}
${s('atrow')} ${s('atkick')}{font-size:10.5px;margin-bottom:5px}
${s('atrow')} ${s('atdd')}{display:none}
@media(max-width:760px){
  ${s('atlista')}{grid-template-columns:1fr;gap:0}
  ${s('atrow')}{grid-template-columns:46px minmax(0,1fr);gap:12px}
  ${s('atrow')}::before{font-size:27px}
}

/* a listagem de editoria e os relacionados usam grade de tres cartoes */
${s('atgrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 28px}
${s('atgrade')} ${s('atdest')}{display:block;padding-bottom:0;border-bottom:0}
${s('atgrade')} ${s('atti')}{font-size:19px;line-height:1.2;margin-top:10px}
${s('atgrade')} ${s('atdd')}{display:none}
@media(max-width:900px){${s('atgrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){${s('atgrade')}{grid-template-columns:1fr}}

/* ---------- artigo ---------- */
${s('atart')}{padding-block:30px 8px}
${s('atcol')}{max-width:${fp.medida || '700px'}}
${s('atchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
/* ⚠️ a Darker Grotesque tem ascendente alto: abaixo de 1,16 o titulo de duas
   linhas encosta na assinatura, que vem logo abaixo e nao tem margem propria */
${s('atart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.16;margin:13px 0 15px;
  letter-spacing:-.02em}
${s('atdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('athero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('athero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('athero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('atleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('atbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('atbody')} p{margin:0 0 1.15em;text-align:left}
${s('atbody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('atbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('atbody')} ul,${s('atbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('atbody')} li{margin:0 0 .45em}
${s('atbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('atbody')} a:hover{color:var(--tinta)}
${s('atbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('atbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('atbody')} .flr-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('atbody')} .flr-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('atbody')} .flr-veja ul{list-style:none;margin:0;padding:0}
${s('atbody')} .flr-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('atbody')} .flr-veja li:first-child{border-top:0;padding-top:0}
${s('atbody')} .flr-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('atbody')} .flr-veja a:hover{color:var(--tinta)}
${s('atbody')} figure{margin:1.5em 0}
${s('atbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('atbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('atbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('atbody')} th,${s('atbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('atbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('atbody')} table{min-width:0}
  ${s('atbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('atbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('atbody')} table,${s('atbody')} tbody,${s('atbody')} tr,${s('atbody')} th,
  ${s('atbody')} td{display:block;width:auto}
  ${s('atbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('atbody')} tbody th,${s('atbody')} tbody td{border:0;background:transparent}
  ${s('atbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('atbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('atbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('atass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('atass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('atass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('atass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('atass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('atass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('atass')} .go:hover{text-decoration:underline}
${s('atrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('atrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('atfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('atcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('atfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('atfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('atfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('atfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('atflist')}{display:flex;flex-direction:column;gap:9px}
${s('atflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('atflist')} a:hover{opacity:1;color:var(--viva)}
${s('atfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('atcols')}{grid-template-columns:1fr;gap:26px}
  ${s('atfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AT_SIMB = `<svg viewBox="0 0 30 24" role="img" aria-hidden="true" focusable="false" fill="none" stroke="var(--marca-1,currentColor)" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 19 C10 19 19 14 26 5"/><path d="M19 4.5 L26.5 4 L26 11.5"/></svg>`;

const AT_SETA = `<svg viewBox="0 0 40 30" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 25 C13 25 25 18 34 5"/><path d="M25 3.5 L35 3 L34.5 13"/></svg>`;

const AT_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function atHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'atnav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('attop')}">
<div class="${c('atin')} ${c('atbar')}">
<a class="${c('atmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AT_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('atnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('atham')}" type="button" data-atham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('atbusca')}" href="/busca/">${AT_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-atham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function atFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('atfoot')}"><div class="${c('atin')}">
<div class="${c('atcols')}">
  <div><a class="${c('atfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#fff;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AT_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('atfh')}">Editorias</div><div class="${c('atflist')}">${cats}</div></div>
  <div><div class="${c('atfh')}">O jornal</div><div class="${c('atflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('atfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function atDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // manchete horizontal: imagem a esquerda, texto a direita. Na grade da
  // listagem o CSS desmancha o grid e ela vira cartao de coluna
  return `<a class="${c('atdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('atfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('atkick')}">${H.cat(a)}</span>
<h${n} class="${c('atti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('atdd')}">${H.esc(H.clip(a.dek, 175))}</span>` : ''}
<span class="${c('atdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function atLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // sem miniatura de proposito: o numeral e a coluna da esquerda, e e ele que
  // da a leitura de lista de plantao
  return `<a class="${c('atrow')} ${c('reveal')}" href="${H.url(a)}">
<span><span class="${c('atkick')}">${H.cat(a)}</span>
<h${n} class="${c('atti')}">${H.esc(a.title)}</h${n}>
<span class="${c('atdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function atHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('atabre')}">
<div><span class="${c('atchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('atmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('atfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('atsec')}" data-par="${idx % 2}">
<div class="${c('atin')}">
<div class="${c('atcab')}"><span class="${c('atseta')}">${AT_SETA}</span>
<h2>${H.esc(nome)}</h2><span class="${c('atfio')}"></span>
<a class="${c('atmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${atDestaque(ctx, d, true)}
${resto.length ? `<div class="${c('atlista')}">${resto.slice(0, 6).map(a => atLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${atHeader(ctx, menu)}
<main class="${c('atwrap')}">
<div class="${c('atin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${atFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function atAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('atass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function atLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('atleg')}">${H.esc(alt)}</p>`;
}

function atArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('atrel')}">
<span class="${c('atrotb')}">Leia também</span>
<div class="${c('atgrade')}">${related.slice(0, 3).map(a => atDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${atHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('atwrap')}"><div class="${c('atin')}">
<article class="${c('atart')}">
<div class="${c('atcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('atchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('atdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('athero')}"><span data-f>${H.pic(art, true)}</span></span>
${atLegenda(ctx, art)}` : ''}
<div class="${c('atbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${atAssinatura(ctx, art)}
${rel}
</div></main>
${atFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function atList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${atHeader(ctx, menu)}
<main class="${c('atwrap')}">
<section class="${c('atsec')}" data-par="0"><div class="${c('atin')}">
<div class="${c('atcab')}"><span class="${c('atseta')}">${AT_SETA}</span>
<h1>${H.esc(opts.title)}</h1><span class="${c('atfio')}"></span></div>
${opts.desc ? `<p class="${c('atdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? atDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('atgrade')}">${resto.map(a => atDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${atFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AU, arquetipo ANEL. Feita para o publisherbrasil.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca do Publisher Brasil e um **anel de crescente verde-limao** sobre
 * preto, com um segundo crescente cinza por dentro e a palavra Publisher em
 * branco. O favicon da origem e uma lampada acesa segurada por uma mao.
 *
 * Dois gestos saem dai: o **anel abre cada secao**, ao lado do nome da
 * editoria, e as **miniaturas da lista sao circulares**, com um anel limao em
 * volta.
 *
 * ## O que a diferencia das 46 vizinhas da opengravity
 *
 *   - **foto redonda**. Nenhuma das 46 usa miniatura circular: e o que muda a
 *     silhueta da secao a distancia
 *   - **anel desenhado abrindo a editoria**, e nao pastilha, faixa ou filete
 *   - o "ver tudo" e uma **pilula limao cheia**, e nao texto sublinhado
 *   - **Bricolage Grotesque e Public Sans**: as duas ja existem na maquina, mas
 *     nunca juntas, e nenhuma outra combina display variavel com grotesca de
 *     interface
 *   - **preto com limao**: o folhadonoroeste tem lima, mas sobre marinho. Preto
 *     com limao nao existe na maquina
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: false` COM `categoryBase: "categoria"`.** O artigo mora em
 * `/<editoria>/<slug>/` e o arquivo de editoria em `/categoria/<slug>/`. Os dois
 * nao coincidem: montar o link de editoria a mao poe o menu do topo, o do rodape
 * e o chapeu de cada artigo em 404, sem aparecer em print nenhum. Editoria sai
 * de `H.curl(slug)`, artigo de `H.url(a)`, sempre.
 *
 * ⚠️ Como o artigo mora dentro da pasta da editoria, `/<editoria>/` vira
 * diretorio sem indice e o nginx responde 403: o vhost precisa do 301 de cada
 * editoria e do `error_page 403 =404`.
 *
 * ⚠️ **O limao `#DFFB00` da 1,1:1 sobre branco.** Ele e anel, filete e pilula,
 * nunca texto. Chapeu, link e etiqueta usam o `--tinta`, uma azeitona escura.
 *
 * ⚠️ **A miniatura redonda precisa de `border-radius` no `span` E no `[data-f]`**:
 * o `overflow:hidden` do pai nao recorta o filho que tem `aspect-ratio` proprio
 * em todos os navegadores.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 *   - a classe do bloco "Veja tambem" leva o prefixo DESTE portal
 */


function auCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --barbg:${t.barBg || t.ink};--bartx:${t.barTx || '#fff'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('auwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('auwrap')} *{box-sizing:border-box}
${s('auin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('auwrap')} h1,${s('auwrap')} h2,${s('auwrap')} h3,${s('auwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('auwrap')} a{color:inherit;text-decoration:none}
${s('auwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: papel claro com o filete limao da marca ---------- */
${s('autop')}{background:var(--paper);border-bottom:6px solid var(--viva)}
${s('aubar')}{display:flex;align-items:center;gap:18px;padding-block:18px 15px;flex-wrap:wrap}
${s('aumarca')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:700;font-size:clamp(22px,3vw,30px);letter-spacing:-.02em;color:var(--ink);flex:none}
${s('aumarca')} svg{display:block;height:1em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('aumarca')} img{display:block;height:42px;width:auto;flex:none}
@media(max-width:560px){${s('aumarca')} img{height:33px}}
${s('aufb')} img{display:block;height:38px;width:auto}
${s('aunav')}{display:flex;gap:15px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('aunav')} a{font-family:var(--fb);font-size:12px;font-weight:600;letter-spacing:.06em;color:var(--dek);padding-bottom:3px;
  border-bottom:2px solid transparent;transition:border-color .2s ease,color .2s ease}
${s('aunav')} a:hover{color:var(--ink);border-bottom-color:var(--viva)}
${s('aubusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.07em;
  background:var(--ink);color:var(--paper);padding:10px 17px;border-radius:999px;flex:none;
  margin-left:8px}
${s('aubusca')}:hover{background:var(--tinta)}
${s('auham')}{display:none;width:46px;height:46px;border:2px solid var(--ink);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:999px}
${s('auham')} i,${s('auham')} i::before,${s('auham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--ink);content:""}
${s('auham')} i{top:21px}
${s('auham')} i::before{top:-6px;left:0}
${s('auham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('aumarca')}{font-size:20px;gap:8px}
  ${s('aubar')}{gap:11px}
  ${s('aubusca')}{font-size:10.5px;padding:9px 13px;gap:6px}
}
@media(max-width:1100px){
  ${s('auham')}{display:block;order:2}
  ${s('aubusca')}{order:3;margin-left:0}
  ${s('aunav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('aunav')}[data-aberto="1"]{display:flex}
  ${s('aunav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink);
    border-left:0;font-size:13px}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('auabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('auabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('auabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('aumm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('aumm')} b{color:var(--ink);font-weight:700}
${s('aufoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('aufoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aufoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('auabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: o anel da marca abre, a lista vem em circulos ---------- */
${s('ausec')}{padding-block:40px;background:var(--paper)}
${s('ausec')}[data-par="1"]{background:var(--wash)}

${s('aucab')}{display:flex;align-items:center;gap:13px;margin-bottom:26px;flex-wrap:wrap}
${s('auanel')}{display:block;width:34px;height:34px;color:var(--viva);flex:none}
${s('auanel')} svg{display:block;width:100%;height:100%}
${s('aucab')} h1,${s('aucab')} h2{font-family:var(--fd);font-weight:700;
  font-size:clamp(21px,2.4vw,28px);letter-spacing:-.018em;color:var(--ink);margin:0;
  line-height:1.18;flex:none}
${s('aumais')}{margin-left:auto;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.1em;color:var(--tinta);flex:none;
  background:var(--viva);padding:7px 14px;border-radius:999px}
${s('aumais')}:hover{filter:brightness(.94)}
${s('audescr')}{margin:0 0 24px;font-size:15.5px;line-height:1.64;color:var(--dek);
  max-width:72ch;text-align:left}

/* a materia de abertura: foto larga em cima, texto embaixo */
${s('audest')}{display:block;padding-bottom:28px;border-bottom:1px solid var(--line)}
${s('audest')} ${s('auti')}{font-size:clamp(22px,2.7vw,32px);line-height:1.12;margin-top:13px;
  letter-spacing:-.014em}
${s('aukick')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.13em'};color:var(--tinta)}
${s('auti')}{display:block;font-family:var(--fd);font-weight:700;font-size:18px;line-height:1.2;
  color:var(--ink);margin:0;transition:color .2s ease;letter-spacing:-.008em}
${s('audd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:60ch;text-align:left}
${s('audt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('aufoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('aufoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('aufoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('audest')}:hover ${s('auti')}{color:var(--tinta)}
${s('audest')}:hover ${s('aufoto')} [data-f] img{transform:scale(1.03)}

/* a lista: duas colunas, miniatura REDONDA com anel limao */
${s('aulista')}{display:grid;grid-template-columns:1fr 1fr;gap:0 40px;margin-top:8px}
${s('aurow')}{display:grid;grid-template-columns:88px minmax(0,1fr);gap:16px;align-items:center;
  padding-block:18px;border-bottom:1px solid var(--line)}
${s('aumini')}{display:block;width:88px;height:88px;overflow:hidden;background:var(--ph);
  border-radius:50%;box-shadow:0 0 0 3px var(--viva);flex:none}
${s('aumini')} [data-f]{display:block;aspect-ratio:1/1;overflow:hidden;border-radius:50%}
${s('aumini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('aurow')}:hover ${s('aumini')} [data-f] img{transform:scale(1.08)}
${s('aurow')}:hover ${s('auti')}{color:var(--tinta)}
${s('aurow')} ${s('auti')}{font-size:16.5px;line-height:1.26;margin-top:5px}
${s('aurow')} ${s('audd')}{display:none}
@media(max-width:760px){
  ${s('aulista')}{grid-template-columns:1fr;gap:0}
  ${s('aurow')}{grid-template-columns:72px minmax(0,1fr);gap:14px}
  ${s('aumini')}{width:72px;height:72px}
}

/* a listagem de editoria e os relacionados usam grade de tres cartoes */
${s('augrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 28px}
${s('augrade')} ${s('audest')}{padding-bottom:0;border-bottom:0}
${s('augrade')} ${s('auti')}{font-size:19px;line-height:1.22;margin-top:11px}
${s('augrade')} ${s('audd')}{display:none}
@media(max-width:900px){${s('augrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){${s('augrade')}{grid-template-columns:1fr}}

/* ---------- artigo ---------- */
${s('auart')}{padding-block:30px 8px}
${s('aucol')}{max-width:${fp.medida || '700px'}}
${s('auchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
/* ⚠️ a Darker Grotesque tem ascendente alto: abaixo de 1,16 o titulo de duas
   linhas encosta na assinatura, que vem logo abaixo e nao tem margem propria */
${s('auart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.16;margin:13px 0 15px;
  letter-spacing:-.02em}
${s('audek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('auhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('auhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('auhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('auleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('aubody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('aubody')} p{margin:0 0 1.15em;text-align:left}
${s('aubody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('aubody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('aubody')} ul,${s('aubody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('aubody')} li{margin:0 0 .45em}
${s('aubody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('aubody')} a:hover{color:var(--tinta)}
${s('aubody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('aubody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('aubody')} .pub-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('aubody')} .pub-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('aubody')} .pub-veja ul{list-style:none;margin:0;padding:0}
${s('aubody')} .pub-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('aubody')} .pub-veja li:first-child{border-top:0;padding-top:0}
${s('aubody')} .pub-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('aubody')} .pub-veja a:hover{color:var(--tinta)}
${s('aubody')} figure{margin:1.5em 0}
${s('aubody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('aubody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('aubody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('aubody')} th,${s('aubody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('aubody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('aubody')} table{min-width:0}
  ${s('aubody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('aubody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('aubody')} table,${s('aubody')} tbody,${s('aubody')} tr,${s('aubody')} th,
  ${s('aubody')} td{display:block;width:auto}
  ${s('aubody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('aubody')} tbody th,${s('aubody')} tbody td{border:0;background:transparent}
  ${s('aubody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('aubody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('aubody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('auass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('auass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('auass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('auass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('auass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('auass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('auass')} .go:hover{text-decoration:underline}
${s('aurel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('aurotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('aufoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('aucols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('aufb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('aufb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('aufoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('aufh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('auflist')}{display:flex;flex-direction:column;gap:9px}
${s('auflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('auflist')} a:hover{opacity:1;color:var(--viva)}
${s('aufim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('aucols')}{grid-template-columns:1fr;gap:26px}
  ${s('aufoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AU_SIMB = `<svg viewBox="0 0 26 26" role="img" aria-hidden="true" focusable="false"><circle cx="13" cy="13" r="12" fill="var(--marca-1,currentColor)"/><circle cx="16.5" cy="15" r="9.6" fill="var(--marca-2,#fff)"/></svg>`;

const AU_ANEL = `<svg viewBox="0 0 34 34" aria-hidden="true" focusable="false"><circle cx="17" cy="17" r="14" fill="none" stroke="currentColor" stroke-width="5"/><circle cx="17" cy="17" r="5" fill="currentColor"/></svg>`;

const AU_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function auHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aunav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('autop')}">
<div class="${c('auin')} ${c('aubar')}">
<a class="${c('aumarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--viva);--marca-2:var(--paper)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AU_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('aunav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('auham')}" type="button" data-auham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('aubusca')}" href="/busca/">${AU_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-auham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function auFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('aufoot')}"><div class="${c('auin')}">
<div class="${c('aucols')}">
  <div><a class="${c('aufb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:var(--viva);--marca-2:var(--ink)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AU_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('aufh')}">Editorias</div><div class="${c('auflist')}">${cats}</div></div>
  <div><div class="${c('aufh')}">O jornal</div><div class="${c('auflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('aufim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function auDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // foto larga em cima e texto embaixo. Na grade da listagem o CSS so tira o
  // filete de baixo, e o mesmo cartao serve nos dois lugares
  return `<a class="${c('audest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('aufoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('aukick')}">${H.cat(a)}</span>
<h${n} class="${c('auti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('audd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('audt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function auLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // miniatura redonda com anel limao: e o gesto da marca, e nenhuma vizinha usa
  // foto circular
  return `<a class="${c('aurow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('aumini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('aukick')}">${H.cat(a)}</span>
<h${n} class="${c('auti')}">${H.esc(a.title)}</h${n}>
<span class="${c('audt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function auHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('auabre')}">
<div><span class="${c('auchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('aumm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('aufoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('ausec')}" data-par="${idx % 2}">
<div class="${c('auin')}">
<div class="${c('aucab')}"><span class="${c('auanel')}">${AU_ANEL}</span>
<h2>${H.esc(nome)}</h2>
<a class="${c('aumais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${auDestaque(ctx, d, true)}
${resto.length ? `<div class="${c('aulista')}">${resto.slice(0, 6).map(a => auLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${auHeader(ctx, menu)}
<main class="${c('auwrap')}">
<div class="${c('auin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${auFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function auAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('auass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function auLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('auleg')}">${H.esc(alt)}</p>`;
}

function auArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('aurel')}">
<span class="${c('aurotb')}">Leia também</span>
<div class="${c('augrade')}">${related.slice(0, 3).map(a => auDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${auHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('auwrap')}"><div class="${c('auin')}">
<article class="${c('auart')}">
<div class="${c('aucol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('auchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('audek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('auhero')}"><span data-f>${H.pic(art, true)}</span></span>
${auLegenda(ctx, art)}` : ''}
<div class="${c('aubody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${auAssinatura(ctx, art)}
${rel}
</div></main>
${auFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function auList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${auHeader(ctx, menu)}
<main class="${c('auwrap')}">
<section class="${c('ausec')}" data-par="0"><div class="${c('auin')}">
<div class="${c('aucab')}"><span class="${c('auanel')}">${AU_ANEL}</span>
<h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('audescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? auDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('augrade')}">${resto.map(a => auDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${auFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AV, arquetipo SELO. Feita para o saberdefato.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca do Saber de Fato e um **mascote de oculos e gravata-borboleta
 * apontando**, dentro de um circulo laranja, ao lado de SABER DE FATO em
 * grotesco pesado marinho, com o "DE" em laranja.
 *
 * O gesto que sai dai e o **selo**: o nome de cada editoria vem dentro de um
 * bloco laranja **levemente girado**, como carimbo de conferido, que e o que o
 * nome do portal promete.
 *
 * ## O que a diferencia das 47 vizinhas da opengravity
 *
 *   - **bloco girado**. Nenhuma das 47 usa rotacao: a AL gira texto na vertical,
 *     que e outra coisa. Um grau e meio muda a leitura da pagina inteira
 *   - **dois cartoes grandes por linha**, cada um com filete marinho grosso no
 *     topo. A AK usa lista de duas colunas, a AQ grade de tres, a AN mosaico
 *   - **Rokkitt e Cabin**: nenhuma das duas esta nas 55 familias em uso
 *   - **marinho quase preto com laranja-mel**: os outros azuis da maquina sao
 *     bem mais claros
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`flatUrl: true` COM `categoryBase: "category"`, em INGLES.** Na origem o
 * `category_base` estava **vazio**, e vazio significa `category`. Cravar
 * "categoria" por analogia com os vizinhos poria a editoria inteira em 404.
 * Artigo em `/<slug>/`, na raiz; listagem em `/category/<slug>/`.
 *
 * ⚠️ Como tudo divide a raiz, **slug podado colide com pagina que o motor
 * regenera**: contato, politica-de-privacidade, termos-de-uso e quem-somos ficam
 * fora do 410.
 *
 * ⚠️ **O selo gira pela ESQUERDA** (`transform-origin: left center`). Girado
 * pelo centro, ele avanca sobre o texto vizinho em tela estreita.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *
 * ## Defeitos de vizinhas que aqui ja nascem resolvidos
 *
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a marca do cabecalho e desenho, e nao texto dentro de SVG
 *   - a classe do bloco "Veja tambem" leva o prefixo DESTE portal
 */


function avCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EDEDE3';
  const viva = t.vivid || '#B4482B';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --barbg:${t.barBg || t.ink};--bartx:${t.barTx || '#fff'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('avwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('avwrap')} *{box-sizing:border-box}
${s('avin')}{max-width:${fp.container || '1180px'};margin:0 auto;padding:0 24px;width:100%}
${s('avwrap')} h1,${s('avwrap')} h2,${s('avwrap')} h3,${s('avwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.004em;line-height:1.17;margin:0}
${s('avwrap')} a{color:inherit;text-decoration:none}
${s('avwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: papel claro com o filete laranja da marca ---------- */
${s('avtop')}{background:var(--paper);border-bottom:1px solid var(--line);
  box-shadow:inset 0 -6px 0 var(--viva)}
${s('avbar')}{display:flex;align-items:center;gap:18px;padding-block:17px 20px;flex-wrap:wrap}
${s('avmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:800;font-size:clamp(23px,3vw,32px);letter-spacing:-.015em;color:var(--pri);flex:none}
${s('avmarca')} svg{display:block;height:.92em;width:auto;flex:none;align-self:center}
/* ⚠️ o logotipo e imagem, e imagem sem medida derruba o CLS. A altura manda e a
   largura sai da proporcao do arquivo */
${s('avmarca')} img{display:block;height:48px;width:auto;flex:none}
@media(max-width:560px){${s('avmarca')} img{height:37px}}
${s('avfb')} img{display:block;height:42px;width:auto}
${s('avnav')}{display:flex;gap:16px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('avnav')} a{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.04em;color:var(--dek);transition:color .2s ease}
${s('avnav')} a:hover{color:var(--tinta)}
${s('avbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:#fff;padding:10px 17px;border-radius:${canto};flex:none;
  margin-left:8px}
${s('avbusca')}:hover{background:var(--tinta)}
${s('avham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('avham')} i,${s('avham')} i::before,${s('avham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('avham')} i{top:21px}
${s('avham')} i::before{top:-6px;left:0}
${s('avham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('avmarca')}{font-size:21px;gap:8px}
  ${s('avbar')}{gap:11px}
  ${s('avbusca')}{font-size:10.5px;padding:9px 13px;gap:6px}
}
@media(max-width:1100px){
  ${s('avham')}{display:block;order:2}
  ${s('avbusca')}{order:3;margin-left:0}
  ${s('avnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('avnav')}[data-aberto="1"]{display:flex}
  ${s('avnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink);
    font-size:13.5px}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('avabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:44px;align-items:center;
  padding-block:38px 32px;border-bottom:1px solid var(--line)}
${s('avabre')} h2{font-size:clamp(31px,4.4vw,52px);line-height:1.05;margin:12px 0 0;
  letter-spacing:-.02em}
${s('avabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('avmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('avmm')} b{color:var(--ink);font-weight:700}
${s('avfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('avfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('avfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
@media(max-width:820px){${s('avabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 22px}}

/* ---------- a secao: o selo carimbado e a grade de dois ---------- */
${s('avsec')}{padding-block:42px;background:var(--paper)}
${s('avsec')}[data-par="1"]{background:var(--wash)}

${s('avcab')}{display:flex;align-items:center;gap:16px;margin-bottom:26px;flex-wrap:wrap}
/* ⚠️ o selo gira pela ESQUERDA: girado pelo centro ele avanca sobre o texto
   vizinho em tela estreita */
${s('avcab')} h1,${s('avcab')} h2{font-family:var(--fd);font-weight:800;
  font-size:clamp(19px,2.2vw,26px);letter-spacing:-.005em;
  color:var(--pri);margin:0;line-height:1.1;flex:none;
  background:var(--viva);padding:9px 18px 8px;border-radius:${canto};
  transform:rotate(-1.6deg);transform-origin:left center}
${s('avmais')}{margin-left:auto;font-family:var(--fb);font-size:11.5px;font-weight:700;
  letter-spacing:.09em;color:var(--tinta);flex:none;
  border-bottom:2px solid var(--viva);padding-bottom:3px}
${s('avmais')}:hover{color:var(--pri)}
${s('avdescr')}{margin:0 0 26px;font-size:15.5px;line-height:1.64;color:var(--dek);
  max-width:72ch;text-align:left}

/* a materia de abertura: foto larga em cima, texto embaixo */
${s('avdest')}{display:block}
${s('avdest')} ${s('avti')}{font-size:clamp(21px,2.6vw,30px);line-height:1.14;margin-top:12px;
  letter-spacing:-.012em}
${s('avkick')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.12em'};color:var(--tinta)}
${s('avti')}{display:block;font-family:var(--fd);font-weight:700;font-size:19px;line-height:1.22;
  color:var(--ink);margin:0;transition:color .2s ease;letter-spacing:-.006em}
${s('avdd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:58ch;text-align:left}
${s('avdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('avfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('avfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('avfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('avdest')}:hover ${s('avti')}{color:var(--tinta)}
${s('avdest')}:hover ${s('avfoto')} [data-f] img{transform:scale(1.03)}

/* a lista: DOIS cartoes grandes por linha, cada um com filete marinho no topo */
${s('avlista')}{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:34px}
${s('avrow')}{display:block;border-top:4px solid var(--pri);padding-top:16px}
${s('avmini')}{display:block;overflow:hidden;background:var(--ph);margin-bottom:13px;
  border-radius:${canto}}
${s('avmini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '16/9'};overflow:hidden}
${s('avmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('avrow')}:hover ${s('avmini')} [data-f] img{transform:scale(1.05)}
${s('avrow')}:hover ${s('avti')}{color:var(--tinta)}
${s('avrow')} ${s('avti')}{font-size:18px;line-height:1.24;margin-top:7px}
${s('avrow')} ${s('avdd')}{display:none}
@media(max-width:700px){
  ${s('avlista')}{grid-template-columns:1fr;gap:26px;margin-top:28px}
}

/* a listagem de editoria e os relacionados usam grade de tres cartoes */
${s('avgrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 28px}
${s('avgrade')} ${s('avti')}{font-size:19px;line-height:1.22;margin-top:11px}
${s('avgrade')} ${s('avdd')}{display:none}
@media(max-width:900px){${s('avgrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:560px){${s('avgrade')}{grid-template-columns:1fr}}

/* ---------- artigo ---------- */
${s('avart')}{padding-block:30px 8px}
${s('avcol')}{max-width:${fp.medida || '700px'}}
${s('avchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--tinta)}
/* ⚠️ a Darker Grotesque tem ascendente alto: abaixo de 1,16 o titulo de duas
   linhas encosta na assinatura, que vem logo abaixo e nao tem margem propria */
${s('avart')} h1{font-size:clamp(30px,4.2vw,47px);line-height:1.16;margin:13px 0 15px;
  letter-spacing:-.02em}
${s('avdek')}{font-size:19px;line-height:1.54;color:var(--dek);margin:16px 0 0;
  max-width:58ch;text-align:left}
${s('avhero')}{display:block;margin:26px 0 0;background:var(--ph);overflow:hidden;
  max-width:${fp.medidaLarga || '880px'};border-radius:${canto}}
${s('avhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('avhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('avleg')}{font-family:var(--fb);font-size:12.5px;color:var(--muted);margin:9px 0 0;
  max-width:${fp.medidaLarga || '880px'};line-height:1.5;text-align:left}
${s('avbody')}{max-width:${fp.medida || '700px'};font-size:${fp.corpoFs || '18.5px'};
  line-height:1.78;margin-top:26px}
${s('avbody')} p{margin:0 0 1.15em;text-align:left}
${s('avbody')} h2{font-family:var(--fd);font-size:27px;font-weight:700;margin:1.75em 0 .5em;
  letter-spacing:-.012em}
${s('avbody')} h3{font-size:20px;margin:1.5em 0 .4em;color:var(--pri)}
${s('avbody')} ul,${s('avbody')} ol{margin:0 0 1.15em;padding-left:1.25em;text-align:left}
${s('avbody')} li{margin:0 0 .45em}
${s('avbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:2px}
${s('avbody')} a:hover{color:var(--tinta)}
${s('avbody')} img{margin:1.5em 0;background:var(--ph);border-radius:${canto}}
${s('avbody')} blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:22px;line-height:1.38;color:var(--ink)}
/* bloco Veja tambem da malha interna: a classe vem gravada no corpo do artigo,
   entao e literal de proposito, com o prefixo deste portal */
${s('avbody')} .sdf-veja{margin:2.2em 0;padding:18px 0 16px;border-top:3px solid var(--pri);
  border-bottom:1px solid var(--line)}
${s('avbody')} .sdf-veja h2{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.19em'};color:var(--pri);
  margin:0 0 11px}
${s('avbody')} .sdf-veja ul{list-style:none;margin:0;padding:0}
${s('avbody')} .sdf-veja li{margin:0;padding:8px 0;border-top:1px solid rgba(0,0,0,.08)}
${s('avbody')} .sdf-veja li:first-child{border-top:0;padding-top:0}
${s('avbody')} .sdf-veja a{font-family:var(--fd);font-size:17px;line-height:1.3;color:var(--ink);
  text-decoration:none;display:block}
${s('avbody')} .sdf-veja a:hover{color:var(--tinta)}
${s('avbody')} figure{margin:1.5em 0}
${s('avbody')} figcaption{font-size:13px;color:var(--muted);margin-top:7px;text-align:left}

/* ---------- tabela: vira cartao no celular, com rotulo de coluna ---------- */
${s('avbody')} table{width:100%;border-collapse:collapse;margin:1.6em 0;font-size:15.5px}
${s('avbody')} caption{font-size:13px;color:var(--muted);text-align:left;padding-bottom:8px}
${s('avbody')} th,${s('avbody')} td{border:0;background:transparent;text-align:left;
  padding:12px 14px 12px 0;border-bottom:1px solid var(--line);vertical-align:top}
${s('avbody')} thead th{font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.07em;color:var(--muted);
  border-bottom:2px solid var(--pri)}
@media(max-width:640px){
  ${s('avbody')} table{min-width:0}
  ${s('avbody')} caption{display:none}
  /* o cabecalho sai da tela mas continua no DOM, acessivel ao leitor de tela */
  ${s('avbody')} thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  ${s('avbody')} table,${s('avbody')} tbody,${s('avbody')} tr,${s('avbody')} th,
  ${s('avbody')} td{display:block;width:auto}
  ${s('avbody')} tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  ${s('avbody')} tbody th,${s('avbody')} tbody td{border:0;background:transparent}
  ${s('avbody')} tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;font-size:17px;
    font-family:var(--fd);font-weight:700;letter-spacing:normal;text-transform:none;color:var(--ink)}
  ${s('avbody')} tbody td{padding:14px 0 0;line-height:1.55}
  ${s('avbody')} tbody td::before{content:attr(data-rotulo);display:block;font-weight:700;
    font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
    margin-bottom:3px}
}

/* ---------- ficha de assinatura ---------- */
${s('avass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:center;
  max-width:${fp.medida || '700px'};margin:34px 0 0;padding-top:22px;
  border-top:3px solid var(--pri)}
${s('avass')} img{width:84px;height:84px;object-fit:cover;background:var(--ph);border-radius:${canto}}
${s('avass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.14em;color:var(--viva)}
${s('avass')} .nm{display:block;font-family:var(--fd);font-size:22px;font-weight:700;margin-top:3px}
${s('avass')} p{margin:7px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek);text-align:left}
${s('avass')} .go{display:inline-block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri)}
${s('avass')} .go:hover{text-decoration:underline}
${s('avrel')}{max-width:${fp.medida || '700px'};padding-block:26px 10px}
${s('avrotb')}{display:block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.16em;color:var(--pri);
  border-top:3px solid var(--pri);padding-top:9px;margin-bottom:2px}

/* ---------- rodape ---------- */
${s('avfoot')}{background:${t.footerBg || 'var(--ink)'};color:${t.footerTx || 'var(--sob)'};margin-top:44px;padding-block:44px 26px}
${s('avcols')}{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:34px}
${s('avfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:700;font-size:26px;color:#fff}
${s('avfb')} svg{display:block;height:.84em;width:auto;flex:none;align-self:center}
${s('avfoot')} p{color:${t.footerTx || '#AFBCAF'};text-align:left}
${s('avfh')}{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.16em;color:${t.footerTx || '#AFBCAF'};margin-bottom:13px}
${s('avflist')}{display:flex;flex-direction:column;gap:9px}
${s('avflist')} a{font-size:14.5px;color:#fff;opacity:.9}
${s('avflist')} a:hover{opacity:1;color:var(--viva)}
${s('avfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:34px;padding-top:17px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;color:${t.footerTx || '#AFBCAF'}}
@media(max-width:820px){
  ${s('avcols')}{grid-template-columns:1fr;gap:26px}
  ${s('avfoot')}{padding-block:34px 22px}
}

/* ---------- animacao de entrada, respeitando quem pediu menos movimento ---------- */
@media(prefers-reduced-motion:no-preference){
  ${s('reveal')}{opacity:0;transform:translateY(12px);
    transition:opacity .5s ease,transform .5s ease}
  ${s('reveal')}[data-vis="1"]{opacity:1;transform:none}
}`;
}

/* Boletim: tres faixas empilhadas de larguras diferentes, que e o proprio ritmo
 * das faixas de secao.
 * Sem letra dentro: o nome vem como texto ao lado. */
const AV_SIMB = `<svg viewBox="0 0 26 26" role="img" aria-hidden="true" focusable="false"><circle cx="13" cy="13" r="12" fill="var(--marca-1,currentColor)"/><path d="M7.5 16.5 L12 8.5 L16.5 16.5" fill="none" stroke="var(--marca-2,#fff)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="19" cy="9" r="2.1" fill="var(--marca-2,#fff)"/></svg>`;


const AV_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function avHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'avnav-' + (site.slug || 'p');
  // 🔴 este portal tem categoryBase "category", em INGLES, porque na origem o
  // campo estava vazio e vazio significa `category`. Montar /categoria/ a mao
  // poe o menu inteiro em 404, e o menu continua bonito no print
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('avtop')}">
<div class="${c('avin')} ${c('avbar')}">
<a class="${c('avmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--viva);--marca-2:var(--paper)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AV_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('avnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('avham')}" type="button" data-avham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('avbusca')}" href="/busca/">${AV_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-avham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function avFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('avfoot')}"><div class="${c('avin')}">
<div class="${c('avcols')}">
  <div><a class="${c('avfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:var(--viva);--marca-2:var(--ink)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AV_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('avfh')}">Editorias</div><div class="${c('avflist')}">${cats}</div></div>
  <div><div class="${c('avfh')}">O jornal</div><div class="${c('avflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('avfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia principal da secao: imagem a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. */
function avDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // foto larga em cima e texto embaixo. Na grade da listagem o CSS so tira o
  // filete de baixo, e o mesmo cartao serve nos dois lugares
  return `<a class="${c('avdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('avfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('avkick')}">${H.cat(a)}</span>
<h${n} class="${c('avti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('avdd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('avdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function avLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  // cartao grande com filete marinho no topo: dois por linha
  return `<a class="${c('avrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('avmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span class="${c('avkick')}">${H.cat(a)}</span>
<h${n} class="${c('avti')}">${H.esc(a.title)}</h${n}>
<span class="${c('avdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function avHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('avabre')}">
<div><span class="${c('avchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('avmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('avfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('avsec')}" data-par="${idx % 2}">
<div class="${c('avin')}">
<div class="${c('avcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('avmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${avDestaque(ctx, d, true)}
${resto.length ? `<div class="${c('avlista')}">${resto.slice(0, 4).map(a => avLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${avHeader(ctx, menu)}
<main class="${c('avwrap')}">
<div class="${c('avin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${avFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function avAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('avass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, e ai a legenda repetiria o `h1`. */
function avLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const _chato = x => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  // ⚠️ tambem some quando o alt reproduz o SLUG: titulo reescrito deixa o alt
  // com o titulo velho, que e o que gerou o slug, e a legenda volta a aparecer
  const _slug = _chato(art.slug), _alt = _chato(alt);
  // ⚠️ o slug do segundo de um par repetido termina em "-2": a comparacao
  // tem que tolerar a sobra, senao a legenda volta justo onde o titulo foi trocado
  const _pref = _alt.length >= 25 && (_slug.indexOf(_alt) === 0 || _alt.indexOf(_slug) === 0);
  const igual = _chato(alt) === _chato(t) || _alt === _slug || _pref;
  if (!alt || igual) return '';
  return `<p class="${c('avleg')}">${H.esc(alt)}</p>`;
}

function avArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema.
  const rel = (related && related.length) ? `<section class="${c('avrel')}">
<span class="${c('avrotb')}">Leia também</span>
<div class="${c('avgrade')}">${related.slice(0, 3).map(a => avDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${avHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('avwrap')}"><div class="${c('avin')}">
<article class="${c('avart')}">
<div class="${c('avcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('avchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${art.dek ? `<p class="${c('avdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('avhero')}"><span data-f>${H.pic(art, true)}</span></span>
${avLegenda(ctx, art)}` : ''}
<div class="${c('avbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${avAssinatura(ctx, art)}
${rel}
</div></main>
${avFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function avList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${avHeader(ctx, menu)}
<main class="${c('avwrap')}">
<section class="${c('avsec')}" data-par="0"><div class="${c('avin')}">
<div class="${c('avcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('avdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? avDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('avgrade')}">${resto.map(a => avDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${avFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AW, arquetipo CAPSULA. Feita para o saudeacessivel.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca do Saude Acessivel e uma **capsula deitada, meio verde e meio azul**,
 * ao lado de SAUDE em verde pesado com "acessivel" em azul, menor, embaixo.
 *
 * O gesto que sai dai e a **capsula**: raio de canto assimetrico, redondo de um
 * lado e quase reto do outro. Ele aparece no rotulo de editoria, na miniatura de
 * cada linha e no botao de busca. Nenhuma das 48 vizinhas da opengravity usa
 * raio assimetrico: elas escolhem entre canto reto e canto redondo, dos dois
 * lados.
 *
 * ## O que a diferencia das 48 vizinhas
 *
 *   - **raio assimetrico** (`border-radius:999px 8px 8px 999px`), que e a
 *     silhueta da capsula da marca
 *   - **linha de cartao horizontal**: miniatura quadrada a esquerda e texto a
 *     direita, uma por linha. A AV usa dois cartoes grandes, a AK lista de duas
 *     colunas, a AQ grade de tres
 *   - **a materia de abertura da secao tem foto a ESQUERDA**, e nao em cima
 *   - **Wittgenstein e Gantari**: nenhuma das duas esta nas 86 familias em uso
 *   - verde-folha escuro com azul-clinico, os dois tirados dos pixels do
 *     logotipo
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **O portal NAO e plano, e o `category_base` da origem estava VAZIO.** Vazio
 * significa `category`, em ingles. O artigo mora em `/<editoria>/<slug>/` e a
 * listagem em `/category/<slug>/`. Montar `/categoria/` a mao poe o menu do
 * topo, o do rodape e o chapeu de cada artigo em 404, e nada disso aparece em
 * captura de tela: o menu continua bonito e so quebra no clique. Por isso todo
 * link de editoria sai de `H.curl(slug)`.
 *
 * ⚠️ **O raio assimetrico precisa da mesma mao nos dois lados.** Miniatura
 * redonda a esquerda com texto colado nela fica ilegivel: o `gap` da linha nunca
 * pode ser menor que o raio.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 *   - a classe do bloco "Leia tambem" leva o prefixo DESTE portal
 */

function awCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#F0F6F1';
  const viva = t.vivid || '#0A5AA0';
  const capsula = '999px 8px 8px 999px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --footer-bg:${t.footerBg || '#12351C'};--footer-tx:${t.footerTx || '#D8E6DA'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('awwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('awwrap')} *{box-sizing:border-box}
${s('awin')}{max-width:${fp.container || '1170px'};margin:0 auto;padding:0 24px;width:100%}
${s('awwrap')} h1,${s('awwrap')} h2,${s('awwrap')} h3,${s('awwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.006em;line-height:1.16;margin:0}
${s('awwrap')} a{color:inherit;text-decoration:none}
${s('awwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho: papel claro, filete verde fino, marca a esquerda ---------- */
${s('awtop')}{background:var(--paper);border-bottom:3px solid var(--pri)}
${s('awbar')}{display:flex;align-items:center;gap:18px;padding-block:16px 18px;flex-wrap:wrap}
${s('awmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:800;font-size:clamp(22px,2.9vw,31px);letter-spacing:-.02em;color:var(--pri);flex:none}
${s('awmarca')} svg{display:block;height:.9em;width:auto;flex:none;align-self:center}
/* o logotipo e imagem, e imagem sem medida derruba o CLS: a altura manda e a
   largura sai da proporcao do arquivo */
${s('awmarca')} img{display:block;height:46px;width:auto;flex:none}
@media(max-width:560px){${s('awmarca')} img{height:36px}}
${s('awfb')} img{display:block;height:40px;width:auto}
${s('awnav')}{display:flex;gap:17px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('awnav')} a{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.045em;color:var(--dek);transition:color .2s ease}
${s('awnav')} a:hover{color:var(--pri)}
${s('awbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.06em;
  background:var(--pri);color:var(--sob);padding:10px 19px 10px 15px;
  border-radius:${capsula};flex:none;margin-left:8px}
${s('awbusca')}:hover{background:var(--viva)}
${s('awham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${capsula}}
${s('awham')} i,${s('awham')} i::before,${s('awham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('awham')} i{top:21px}
${s('awham')} i::before{top:-6px;left:0}
${s('awham')} i::after{top:6px;left:0}
@media(max-width:560px){
  ${s('awmarca')}{font-size:20px;gap:8px}
  ${s('awbar')}{gap:11px}
  ${s('awbusca')}{font-size:10.5px;padding:9px 15px 9px 12px;gap:6px}
}
@media(max-width:1100px){
  ${s('awham')}{display:block;order:2}
  ${s('awbusca')}{order:3;margin-left:0}
  ${s('awnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('awnav')}[data-aberto="1"]{display:flex}
  ${s('awnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink);
    font-size:13.5px}
}

/* ---------- chamada de abertura: texto a esquerda, imagem a direita ---------- */
${s('awabre')}{display:grid;grid-template-columns:1.04fr 1fr;gap:44px;align-items:center;
  padding-block:38px 34px;border-bottom:1px solid var(--line)}
${s('awabre')} h2{font-size:clamp(30px,4.3vw,50px);line-height:1.06;margin:12px 0 0;
  letter-spacing:-.024em}
${s('awabre')} h2 a:hover{color:var(--pri)}
${s('awabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('awmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:19px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('awmm')} b{color:var(--ink);font-weight:700}
${s('awchap')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:.13em;color:var(--sob);background:var(--pri);
  padding:6px 15px 6px 12px;border-radius:${capsula}}
${s('awchap')} a{color:var(--sob)}
@media(max-width:820px){${s('awabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 24px}}

/* ---------- secao: rotulo em capsula e linhas horizontais ---------- */
${s('awsec')}{padding-block:42px;background:var(--paper)}
${s('awsec')}[data-par="1"]{background:var(--wash)}
${s('awcab')}{display:flex;align-items:center;gap:16px;margin-bottom:24px;flex-wrap:wrap}
${s('awcab')} h1,${s('awcab')} h2{font-family:var(--fd);font-weight:800;
  font-size:clamp(17px,2vw,23px);letter-spacing:.005em;
  color:var(--sob);margin:0;line-height:1.1;flex:none;background:var(--pri);
  padding:9px 22px 9px 16px;border-radius:${capsula}}
${s('awmais')}{margin-left:auto;font-family:var(--fb);font-size:11.5px;font-weight:700;
  letter-spacing:.09em;color:var(--viva);flex:none;
  border-bottom:2px solid var(--viva);padding-bottom:3px}
${s('awmais')}:hover{color:var(--pri);border-bottom-color:var(--pri)}
${s('awdescr')}{margin:0 0 26px;font-size:15.5px;line-height:1.64;color:var(--dek);
  max-width:72ch;text-align:left}

/* materia de abertura da secao: foto a ESQUERDA, texto a direita */
${s('awdest')}{display:grid;grid-template-columns:1.02fr 1fr;gap:30px;align-items:center}
${s('awdest')} ${s('awti')}{font-size:clamp(21px,2.6vw,31px);line-height:1.13;
  letter-spacing:-.015em;margin-top:11px}
${s('awkick')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.13em'};color:var(--viva)}
${s('awti')}{display:block;font-family:var(--fd);font-weight:700;font-size:19px;line-height:1.2;
  color:var(--ink);margin:0;transition:color .2s ease;letter-spacing:-.008em}
${s('awdd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:56ch;text-align:left}
${s('awdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
/* ⚠️ a capsula recorta meia foto grande num semicirculo: em foto ela vira um
   raio discreto, e a capsula fica no rotulo, no botao e na miniatura quadrada */
${s('awfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:14px}
${s('awfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '4/3'};overflow:hidden}
${s('awfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('awdest')}:hover ${s('awti')}{color:var(--pri)}
${s('awdest')}:hover ${s('awfoto')} [data-f] img{transform:scale(1.04)}
@media(max-width:780px){${s('awdest')}{grid-template-columns:1fr;gap:16px}}

/* a lista: UMA linha por item, miniatura quadrada a esquerda em capsula.
   O gap nunca pode ser menor que o raio, senao o texto cola no arredondado */
${s('awlista')}{display:flex;flex-direction:column;gap:0;margin-top:32px;
  border-top:1px solid var(--line)}
${s('awrow')}{display:grid;grid-template-columns:118px minmax(0,1fr);gap:22px;
  align-items:center;padding-block:18px;border-bottom:1px solid var(--line)}
${s('awmini')}{display:block;overflow:hidden;background:var(--ph);border-radius:${capsula}}
${s('awmini')} [data-f]{display:block;aspect-ratio:1/1;overflow:hidden}
${s('awmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('awrow')}:hover ${s('awmini')} [data-f] img{transform:scale(1.06)}
${s('awrow')}:hover ${s('awti')}{color:var(--pri)}
${s('awrow')} ${s('awti')}{font-size:18.5px;line-height:1.22;margin-top:6px}
${s('awrow')} ${s('awdd')}{display:none}
@media(max-width:620px){
  ${s('awrow')}{grid-template-columns:84px minmax(0,1fr);gap:16px;padding-block:15px}
  ${s('awrow')} ${s('awti')}{font-size:16.5px}
}

/* a listagem de editoria e os relacionados usam grade de tres cartoes */
${s('awgrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 28px}
${s('awgrade')} ${s('awdest')}{display:block}
${s('awgrade')} ${s('awti')}{font-size:19px;line-height:1.22;margin-top:11px}
${s('awgrade')} ${s('awdd')}{display:none}
${s('awgrade')} ${s('awfoto')} [data-f]{aspect-ratio:${fp.cardAr || '16/10'}}
@media(max-width:900px){${s('awgrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:600px){${s('awgrade')}{grid-template-columns:1fr;gap:28px}}

/* ---------- artigo ---------- */
${s('awart')}{padding-block:30px 12px}
${s('awcol')}{max-width:70ch}
${s('awart')} h1{font-size:clamp(28px,4vw,44px);line-height:1.08;letter-spacing:-.026em;
  margin:14px 0 0}
${s('awdek')}{font-size:19px;line-height:1.55;color:var(--dek);margin:16px 0 0;max-width:62ch}
${s('awhero')}{display:block;overflow:hidden;background:var(--ph);border-radius:14px;
  margin-top:26px}
${s('awhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('awhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('awleg')}{margin:10px 0 0;font-size:12.5px;line-height:1.5;color:var(--muted);
  max-width:70ch;text-align:left}
${s('awbody')}{max-width:70ch;margin-top:26px;font-size:calc(${fp.baseFs || '17px'} + 1px);
  line-height:1.78}
${s('awbody')} p{margin:0 0 21px}
${s('awbody')} a{color:var(--viva);text-decoration:underline;text-underline-offset:3px}
${s('awbody')} a:hover{color:var(--pri)}
${s('awbody')} h2{font-family:var(--fd);font-weight:800;font-size:25px;letter-spacing:-.014em;
  margin:36px 0 12px;padding-left:14px;border-left:5px solid var(--pri)}
${s('awbody')} h3{font-family:var(--fd);font-weight:700;font-size:20px;margin:28px 0 10px}
${s('awbody')} ul,${s('awbody')} ol{margin:0 0 21px;padding-left:22px}
${s('awbody')} li{margin:0 0 9px}
${s('awbody')} img{max-width:100%;height:auto;border-radius:12px;margin:8px 0}
${s('awbody')} figure{margin:22px 0}
${s('awbody')} figcaption{font-size:12.5px;color:var(--muted);margin-top:8px}
${s('awbody')} blockquote{margin:28px 0;padding:4px 0 4px 22px;border-left:5px solid var(--viva);
  font-family:var(--fd);font-size:21px;line-height:1.42;color:var(--ink)}
${s('awbody')} table{width:100%;border-collapse:collapse;margin:0 0 24px;font-size:14.5px}
${s('awbody')} th,${s('awbody')} td{border:0;border-bottom:1px solid var(--line);
  padding:11px 12px 11px 0;text-align:left;vertical-align:top}
${s('awbody')} th{font-family:var(--fb);font-weight:700;background:transparent}
${s('awbody')} caption{text-align:left;font-size:13px;color:var(--muted);padding-bottom:8px}

/* a tabela vira cartao no celular: sem isto ela sai da tela e o gesto de
   arrastar nao e descoberto. O thead sai da tela mas continua no DOM */
@media(max-width:640px){
  ${s('awbody')} .tabwrap{overflow:visible;border:0;background:transparent}
  ${s('awbody')} table{min-width:0;display:block;width:auto;overflow:visible}
  ${s('awbody')} table caption{display:none}
  ${s('awbody')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;
    clip:rect(0 0 0 0)}
  ${s('awbody')} table tbody,${s('awbody')} table tr,
  ${s('awbody')} table th,${s('awbody')} table td{display:block;width:auto}
  ${s('awbody')} table tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:14px;padding:2px 18px 16px;margin-bottom:13px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('awbody')} table tbody th,${s('awbody')} table tbody td{border:0;background:transparent;
    padding:0}
  ${s('awbody')} table tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;
    font-weight:700;text-align:left}
  ${s('awbody')} table tbody td{padding:13px 0 0;text-align:left;line-height:1.55}
  ${s('awbody')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);
    margin-bottom:2px}
}

${s('awass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:start;
  max-width:70ch;margin-top:38px;padding:20px;background:var(--wash);border-radius:16px}
${s('awass')} img{border-radius:${capsula}}
${s('awass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--viva)}
${s('awass')} .nm{display:block;font-family:var(--fd);font-weight:700;font-size:19px;margin-top:4px}
${s('awass')} p{margin:8px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek)}
${s('awass')} .go{display:inline-block;margin-top:10px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--pri);
  border-bottom:2px solid var(--pri);padding-bottom:2px}
@media(max-width:560px){${s('awass')}{grid-template-columns:1fr;gap:12px}}

/* o bloco de relacionados tem a MESMA largura da coluna do artigo */
${s('awrel')}{max-width:70ch;margin-top:44px;padding-top:24px;border-top:3px solid var(--pri)}
${s('awrotb')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.13em;color:var(--sob);background:var(--pri);
  padding:6px 16px 6px 12px;border-radius:${capsula};margin-bottom:20px}
${s('awrel')} ${s('awgrade')}{grid-template-columns:1fr 1fr;gap:26px 22px}
@media(max-width:600px){${s('awrel')} ${s('awgrade')}{grid-template-columns:1fr}}

/* ---------- rodape ---------- */
${s('awfoot')}{background:var(--footer-bg);color:var(--footer-tx);margin-top:56px;
  padding-block:38px 22px}
${s('awcols')}{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:34px}
${s('awfoot')} p{font-size:14.5px;color:var(--footer-tx)}
${s('awfb')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:800;font-size:23px;letter-spacing:-.02em;color:#fff}
${s('awfh')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.14em;color:#fff;margin-bottom:12px}
${s('awflist')} a{display:block;font-size:14.5px;padding:4px 0;color:var(--footer-tx)}
${s('awflist')} a:hover{color:#fff}
${s('awfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:28px;padding-top:15px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;opacity:.85}
@media(max-width:820px){${s('awcols')}{grid-template-columns:1fr;gap:26px}}

${s('reveal')}{opacity:1}
@media(prefers-reduced-motion:reduce){
  ${s('awwrap')} *{transition:none !important;animation:none !important}
}`;
}

/* A capsula da marca, desenhada. So entra quando o portal nao tem arquivo de
 * logotipo: com arquivo, quem manda e a imagem da origem. */
const AW_SIMB = `<svg viewBox="0 0 40 24" width="40" height="24" aria-hidden="true">
<rect x="1" y="1" width="38" height="22" rx="11" fill="var(--marca-1,#0A5AA0)"/>
<path d="M20 1h8a11 11 0 0 1 0 22h-8z" fill="var(--marca-2,#2F7D3E)"/>
<rect x="1" y="1" width="38" height="22" rx="11" fill="none" stroke="rgba(0,0,0,.14)"/>
</svg>`;

const AW_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function awHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'awnav-' + (site.slug || 'p');
  // 🔴 este portal serve a listagem em /category/<slug>/, em INGLES, porque o
  // `category_base` da origem estava vazio. Montar o caminho a mao poe o menu
  // inteiro em 404 e o print continua bonito
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('awtop')}">
<div class="${c('awin')} ${c('awbar')}">
<a class="${c('awmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--viva);--marca-2:var(--pri)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AW_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('awnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('awham')}" type="button" data-awham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('awbusca')}" href="/busca/">${AW_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-awham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function awFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('awfoot')}"><div class="${c('awin')}">
<div class="${c('awcols')}">
  <div><a class="${c('awfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:var(--viva);--marca-2:#7FBF8C">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AW_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('awfh')}">Editorias</div><div class="${c('awflist')}">${cats}</div></div>
  <div><div class="${c('awfh')}">O portal</div><div class="${c('awflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('awfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* A materia de abertura da secao: foto a ESQUERDA e texto a direita. O `span`
 * da foto tem display:block, senao o aspect-ratio nao aplica. Dentro da grade
 * de tres o CSS troca para empilhado, e o mesmo cartao serve nos dois lugares. */
function awDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('awdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('awfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span><span class="${c('awkick')}">${H.cat(a)}</span>
<h${n} class="${c('awti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('awdd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('awdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

/* Linha horizontal: miniatura quadrada em capsula a esquerda, texto a direita. */
function awLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('awrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('awmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span><span class="${c('awkick')}">${H.cat(a)}</span>
<h${n} class="${c('awti')}">${H.esc(a.title)}</h${n}>
<span class="${c('awdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function awHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('awabre')}">
<div><span class="${c('awchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('awmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('awfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      // a faixa alterna o fundo: e o que muda a silhueta da pagina a distancia
      return `<section class="${c('awsec')}" data-par="${idx % 2}">
<div class="${c('awin')}">
<div class="${c('awcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('awmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${awDestaque(ctx, d, idx === 0)}
${resto.length ? `<div class="${c('awlista')}">${resto.slice(0, 4).map(a => awLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${awHeader(ctx, menu)}
<main class="${c('awwrap')}">
<div class="${c('awin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${awFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/* Ficha do autor no fim da materia. Os campos sao os do motor: `nome`, `slug`,
 * `editoria` e `lead`. */
function awAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('awass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` da imagem descreve a FOTO. Em metade do
 * acervo importado ele e copia do titulo, ou do slug, e ai a legenda repetiria
 * o `h1` logo abaixo dele. */
function awLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const chato = (x) => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const cSlug = chato(art.slug), cAlt = chato(alt);
  const pref = cAlt.length >= 25 && (cSlug.indexOf(cAlt) === 0 || cAlt.indexOf(cSlug) === 0);
  const igual = cAlt === chato(t) || cAlt === cSlug || pref;
  if (!alt || igual) return '';
  return `<p class="${c('awleg')}">${H.esc(alt)}</p>`;
}

/* A linha fina do artigo so aparece quando NAO esta no corpo. A limpeza da
 * importacao tira a frase do proprio texto quando o `excerpt` da origem vem
 * vazio, o que salva o cartao da home; aqui o mesmo campo seria repeticao. */
function awDekVale(art) {
  const d = String(art.dek || '').trim();
  if (!d) return false;
  const nu = (x) => String(x || '').toLowerCase().replace(/<[^>]+>/g, ' ')
    .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const chave = nu(d).slice(0, 60);
  return !!chave && nu(art.content).indexOf(chave) < 0;
}

function awArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  // o P vem pronto do motor: url, imgUrl, desc, readMin, catSlug, catName e os
  // blocos de schema
  const rel = (related && related.length) ? `<section class="${c('awrel')}">
<h2 class="${c('awrotb')}">Leia também</h2>
<div class="${c('awgrade')}">${related.slice(0, 4).map(a => awDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${awHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('awwrap')}"><div class="${c('awin')}">
<article class="${c('awart')}">
<div class="${c('awcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('awchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${awDekVale(art) ? `<p class="${c('awdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('awhero')}"><span data-f>${H.pic(art, true)}</span></span>
${awLegenda(ctx, art)}` : ''}
<div class="${c('awbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${awAssinatura(ctx, art)}
${rel}
</div></main>
${awFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function awList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  // a grade pula o destaque, e nao o repete: `resto`, nunca `itens`
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${awHeader(ctx, menu)}
<main class="${c('awwrap')}">
<section class="${c('awsec')}" data-par="0"><div class="${c('awin')}">
<div class="${c('awcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('awdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? awDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('awgrade')}" style="margin-top:34px">${resto.map(a => awDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${awFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AX, arquetipo NUMERAL. Feita para o saudicas.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca do Saude Dicas e uma **lampada acesa com uma cruz dentro**, em ciano e
 * verde, ao lado de SAUDEDICAS em duas cores: SAUDE em ciano, DICAS em verde.
 *
 * O que o nome promete e **dica**, e dica se conta. O gesto que sai dai e o
 * **numeral**: cada linha da secao carrega um numero grande em contorno, vazado,
 * como item de lista. O numero e desenhado pelo CSS com `counter`, entao ele
 * acompanha a ordem real e nunca sai errado ao reordenar.
 *
 * ## O que a diferencia das 49 vizinhas da opengravity
 *
 *   - **numeral vazado grande** (`-webkit-text-stroke`) como ancora visual de
 *     cada linha. A AT numera com `counter` mas em numero cheio e pequeno, dentro
 *     do ::before de um item de lista escura
 *   - **grade de duas colunas que preenche por COLUNA**, com o numero de linhas
 *     calculado no render. Ler descendo a coluna mantem a data em ordem
 *   - **cabecalho de secao com a lampada de contorno** ao lado do nome
 *   - **Reddit Sans e Sarabun**: nenhuma das duas esta nas 86 familias em uso
 *   - ciano-clinico com verde-folha, os dois tirados dos pixels do logotipo
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **O `--l` da grade de duas colunas NAO da para cravar no CSS.** Ele muda de
 * 3, no bloco da home, para dezenas, na listagem de editoria. Sem ele o
 * `grid-auto-flow:column` nao tem quantas linhas usar e a grade volta a
 * preencher por linha: o segundo item mais recente vai para o topo da coluna da
 * direita e quem le descendo ve a data pular. O HTML fica identico nos dois
 * casos, entao **so a captura de tela mostra**. Cada chamada passa o proprio
 * valor no atributo `style`.
 *
 * 🔴 **O portal NAO e plano, e o `category_base` da origem estava VAZIO**, o que
 * no WordPress significa `category`, em ingles. Artigo em `/<editoria>/<slug>/`,
 * listagem em `/category/<slug>/`, e todo link de editoria sai de `H.curl`.
 *
 * ⚠️ **O numeral vazado precisa de cor de traco propria.** Herdando `--muted`
 * ele some no fundo lavado das secoes pares.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - as variaveis de cor vao no `:root`, e nao no seletor do elemento principal
 *   - o respiro lateral usa `padding-block`, nunca `padding` completo
 *   - nenhuma crase e nenhum cifrao com chave dentro de comentario do CSS
 */

function axCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#EEF7FA';
  const viva = t.vivid || '#4C8A2E';
  const canto = fp.radius === 'sharp' ? '0' : '10px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --num:${t.numeral || t.line};
  --footer-bg:${t.footerBg || '#0B3A4A'};--footer-tx:${t.footerTx || '#CFE4EC'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('axwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.68;-webkit-font-smoothing:antialiased}
${s('axwrap')} *{box-sizing:border-box}
${s('axin')}{max-width:${fp.container || '1150px'};margin:0 auto;padding:0 24px;width:100%}
${s('axwrap')} h1,${s('axwrap')} h2,${s('axwrap')} h3,${s('axwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.014em;line-height:1.15;margin:0}
${s('axwrap')} a{color:inherit;text-decoration:none}
${s('axwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('axtop')}{background:var(--paper);border-bottom:1px solid var(--line)}
${s('axbar')}{display:flex;align-items:center;gap:18px;padding-block:15px 17px;flex-wrap:wrap}
${s('axmarca')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:800;font-size:clamp(21px,2.8vw,30px);letter-spacing:-.026em;color:var(--pri);flex:none}
${s('axmarca')} svg{display:block;height:1.05em;width:auto;flex:none;align-self:center}
/* imagem sem medida derruba o CLS: a altura manda e a largura sai da proporcao */
${s('axmarca')} img{display:block;height:44px;width:auto;flex:none}
@media(max-width:560px){${s('axmarca')} img{height:34px}}
${s('axfb')} img{display:block;height:40px;width:auto}
${s('axnav')}{display:flex;gap:18px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('axnav')} a{font-family:var(--fb);font-size:13px;font-weight:600;color:var(--dek);
  transition:color .2s ease;position:relative;padding-bottom:3px}
${s('axnav')} a::after{content:"";position:absolute;left:0;right:100%;bottom:0;height:2px;
  background:var(--viva);transition:right .25s ease}
${s('axnav')} a:hover{color:var(--pri)}
${s('axnav')} a:hover::after{right:0}
${s('axbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:12px;font-weight:700;background:var(--pri);color:var(--sob);padding:10px 16px;
  border-radius:${canto};flex:none;margin-left:6px}
${s('axbusca')}:hover{background:var(--viva)}
${s('axham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('axham')} i,${s('axham')} i::before,${s('axham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('axham')} i{top:21px}
${s('axham')} i::before{top:-6px;left:0}
${s('axham')} i::after{top:6px;left:0}
@media(max-width:560px){${s('axmarca')}{font-size:19.5px;gap:8px}${s('axbar')}{gap:11px}
  ${s('axbusca')}{font-size:11px;padding:9px 13px;gap:6px}}
@media(max-width:1100px){
  ${s('axham')}{display:block;order:2}
  ${s('axbusca')}{order:3;margin-left:0}
  ${s('axnav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:13px}
  ${s('axnav')}[data-aberto="1"]{display:flex}
  ${s('axnav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink);
    font-size:14px}
  ${s('axnav')} a::after{display:none}
}

/* ---------- abertura: texto a esquerda, imagem a direita ---------- */
${s('axabre')}{display:grid;grid-template-columns:1.02fr 1fr;gap:42px;align-items:center;
  padding-block:36px 32px;border-bottom:1px solid var(--line)}
${s('axabre')} h2{font-size:clamp(29px,4.2vw,49px);line-height:1.05;margin:13px 0 0;
  letter-spacing:-.03em}
${s('axabre')} h2 a:hover{color:var(--pri)}
${s('axabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('axmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:18px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('axmm')} b{color:var(--ink);font-weight:700}
${s('axchap')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.11em;color:var(--pri);border:2px solid var(--pri);
  padding:5px 12px;border-radius:${canto}}
${s('axchap')} a{color:var(--pri)}
@media(max-width:820px){${s('axabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 24px}}

/* ---------- secao ---------- */
${s('axsec')}{padding-block:44px;background:var(--paper)}
${s('axsec')}[data-par="1"]{background:var(--wash)}
${s('axcab')}{display:flex;align-items:center;gap:14px;margin-bottom:26px;flex-wrap:wrap}
${s('axcab')} svg{flex:none;width:30px;height:30px;color:var(--viva)}
${s('axcab')} h1,${s('axcab')} h2{font-family:var(--fd);font-weight:800;
  font-size:clamp(22px,2.6vw,31px);letter-spacing:-.028em;color:var(--pri);margin:0;
  line-height:1.08;flex:none}
${s('axmais')}{margin-left:auto;font-family:var(--fb);font-size:12px;font-weight:700;
  color:var(--viva);flex:none;border-bottom:2px solid var(--viva);padding-bottom:3px}
${s('axmais')}:hover{color:var(--pri);border-bottom-color:var(--pri)}
${s('axdescr')}{margin:0 0 28px;font-size:15.5px;line-height:1.66;color:var(--dek);
  max-width:72ch;text-align:left}

/* materia de abertura da secao: foto larga em cima, texto embaixo */
${s('axdest')}{display:block}
${s('axdest')} ${s('axti')}{font-size:clamp(21px,2.5vw,30px);line-height:1.12;margin-top:13px;
  letter-spacing:-.022em}
${s('axkick')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.11em'};color:var(--viva)}
${s('axti')}{display:block;font-family:var(--fd);font-weight:700;font-size:19px;line-height:1.2;
  color:var(--ink);margin:0;transition:color .2s ease;letter-spacing:-.018em}
${s('axdd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:58ch;text-align:left}
${s('axdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:12px;color:var(--muted)}
${s('axfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('axfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('axfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('axdest')}:hover ${s('axti')}{color:var(--pri)}
${s('axdest')}:hover ${s('axfoto')} [data-f] img{transform:scale(1.04)}

/* a lista numerada, em DUAS colunas preenchidas por COLUNA. O numero de linhas
   vem no atributo style de cada chamada: cravado no CSS ele erraria em todo
   lugar menos num */
${s('axlista')}{display:grid;grid-template-columns:1fr 1fr;gap:0 40px;margin-top:34px;
  grid-auto-flow:column;grid-template-rows:repeat(var(--l,3),auto);counter-reset:ax}
${s('axrow')}{display:grid;grid-template-columns:auto minmax(0,1fr);gap:18px;align-items:start;
  padding-block:17px;border-top:1px solid var(--line);counter-increment:ax}
${s('axrow')}::before{content:counter(ax,decimal-leading-zero);font-family:var(--fd);
  font-weight:800;font-size:34px;line-height:1;color:transparent;
  -webkit-text-stroke:1.5px var(--num);letter-spacing:-.04em;padding-top:2px}
${s('axrow')}:hover::before{-webkit-text-stroke-color:var(--viva)}
${s('axrow')}:hover ${s('axti')}{color:var(--pri)}
${s('axrow')} ${s('axti')}{font-size:17.5px;line-height:1.26;margin-top:2px}
${s('axrow')} ${s('axdd')}{display:none}
@media(max-width:820px){
  ${s('axlista')}{grid-template-columns:1fr;grid-auto-flow:row;grid-template-rows:none;
    gap:0;margin-top:28px}
}

/* listagem de editoria e relacionados: grade de tres cartoes */
${s('axgrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:36px 28px}
${s('axgrade')} ${s('axti')}{font-size:19px;line-height:1.22;margin-top:12px}
${s('axgrade')} ${s('axdd')}{display:none}
${s('axgrade')} ${s('axfoto')} [data-f]{aspect-ratio:${fp.cardAr || '16/9'}}
@media(max-width:900px){${s('axgrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:600px){${s('axgrade')}{grid-template-columns:1fr;gap:28px}}

/* ---------- artigo ---------- */
${s('axart')}{padding-block:30px 12px}
${s('axcol')}{max-width:${fp.medida || '70ch'}}
${s('axart')} h1{font-size:clamp(28px,4vw,44px);line-height:1.07;letter-spacing:-.032em;
  margin:14px 0 0}
${s('axdek')}{font-size:19px;line-height:1.55;color:var(--dek);margin:16px 0 0;max-width:62ch}
${s('axhero')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto};
  margin-top:26px}
${s('axhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('axhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('axleg')}{margin:10px 0 0;font-size:12.5px;line-height:1.5;color:var(--muted);
  max-width:70ch;text-align:left}
${s('axbody')}{max-width:70ch;margin-top:26px;font-size:${fp.corpoFs || '18px'};line-height:1.8}
${s('axbody')} p{margin:0 0 21px}
${s('axbody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:3px}
${s('axbody')} a:hover{color:var(--viva)}
${s('axbody')} h2{font-family:var(--fd);font-weight:800;font-size:25px;letter-spacing:-.026em;
  margin:36px 0 12px;color:var(--pri)}
${s('axbody')} h3{font-family:var(--fd);font-weight:700;font-size:20px;margin:28px 0 10px}
${s('axbody')} ul,${s('axbody')} ol{margin:0 0 21px;padding-left:22px}
${s('axbody')} li{margin:0 0 9px}
${s('axbody')} img{max-width:100%;height:auto;border-radius:${canto};margin:8px 0}
${s('axbody')} figure{margin:22px 0}
${s('axbody')} figcaption{font-size:12.5px;color:var(--muted);margin-top:8px}
${s('axbody')} blockquote{margin:28px 0;padding:18px 22px;background:var(--wash);
  border-radius:${canto};border-left:5px solid var(--viva);font-family:var(--fd);
  font-size:20px;line-height:1.45}
${s('axbody')} table{width:100%;border-collapse:collapse;margin:0 0 24px;font-size:14.5px}
${s('axbody')} th,${s('axbody')} td{border:0;border-bottom:1px solid var(--line);
  padding:11px 12px 11px 0;text-align:left;vertical-align:top}
${s('axbody')} th{font-family:var(--fb);font-weight:700;background:transparent}
${s('axbody')} caption{text-align:left;font-size:13px;color:var(--muted);padding-bottom:8px}

/* a tabela vira cartao no celular: sem isto ela sai da tela e o gesto de
   arrastar nao e descoberto. O thead sai da tela mas continua no DOM */
@media(max-width:640px){
  ${s('axbody')} .tabwrap{overflow:visible;border:0;background:transparent}
  ${s('axbody')} table{min-width:0;display:block;width:auto;overflow:visible}
  ${s('axbody')} table caption{display:none}
  ${s('axbody')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;
    clip:rect(0 0 0 0)}
  ${s('axbody')} table tbody,${s('axbody')} table tr,
  ${s('axbody')} table th,${s('axbody')} table td{display:block;width:auto}
  ${s('axbody')} table tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:14px;padding:2px 18px 16px;margin-bottom:13px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('axbody')} table tbody th,${s('axbody')} table tbody td{border:0;background:transparent;
    padding:0}
  ${s('axbody')} table tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;
    font-weight:700;text-align:left}
  ${s('axbody')} table tbody td{padding:13px 0 0;text-align:left;line-height:1.55}
  ${s('axbody')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);
    margin-bottom:2px}
}

${s('axass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:start;
  max-width:70ch;margin-top:38px;padding:20px;border:2px solid var(--line);
  border-radius:${canto}}
${s('axass')} img{border-radius:${canto}}
${s('axass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--viva)}
${s('axass')} .nm{display:block;font-family:var(--fd);font-weight:700;font-size:19px;margin-top:4px}
${s('axass')} p{margin:8px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek)}
${s('axass')} .go{display:inline-block;margin-top:10px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;color:var(--pri);border-bottom:2px solid var(--pri);padding-bottom:2px}
@media(max-width:560px){${s('axass')}{grid-template-columns:1fr;gap:12px}}

/* relacionados com a MESMA largura da coluna do artigo */
${s('axrel')}{max-width:70ch;margin-top:44px;padding-top:24px;border-top:3px solid var(--pri)}
${s('axrotb')}{display:inline-block;font-family:var(--fd);font-weight:800;font-size:20px;
  letter-spacing:-.024em;color:var(--pri);margin-bottom:20px}
${s('axrel')} ${s('axgrade')}{grid-template-columns:1fr 1fr;gap:26px 22px}
@media(max-width:600px){${s('axrel')} ${s('axgrade')}{grid-template-columns:1fr}}

/* ---------- rodape ---------- */
${s('axfoot')}{background:var(--footer-bg);color:var(--footer-tx);margin-top:56px;
  padding-block:38px 22px}
${s('axcols')}{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:34px}
${s('axfoot')} p{font-size:14.5px;color:var(--footer-tx)}
${s('axfb')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:800;font-size:23px;letter-spacing:-.026em;color:#fff}
${s('axfh')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.14em;color:#fff;margin-bottom:12px}
${s('axflist')} a{display:block;font-size:14.5px;padding:4px 0;color:var(--footer-tx)}
${s('axflist')} a:hover{color:#fff}
${s('axfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:28px;padding-top:15px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;opacity:.85}
@media(max-width:820px){${s('axcols')}{grid-template-columns:1fr;gap:26px}}

${s('reveal')}{opacity:1}
@media(prefers-reduced-motion:reduce){
  ${s('axwrap')} *{transition:none !important;animation:none !important}
}`;
}

/* A lampada da marca, desenhada. So entra quando o portal nao tem arquivo de
 * logotipo: com arquivo, quem manda e a imagem da origem. */
const AX_SIMB = `<svg viewBox="0 0 24 30" width="24" height="30" aria-hidden="true" fill="none"
 stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
<path d="M12 2a8 8 0 0 0-4.6 14.6c.6.5.9 1.2.9 2V20h7.4v-1.4c0-.8.3-1.5.9-2A8 8 0 0 0 12 2Z"/>
<path d="M9 24h6M10 27h4"/><path d="M12 9v5M9.5 11.5h5" stroke="var(--marca-2,currentColor)"/>
</svg>`;

const AX_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function axHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'axnav-' + (site.slug || 'p');
  // 🔴 a listagem mora em /category/<slug>/, em INGLES: na origem o
  // `category_base` estava vazio, e vazio significa `category`
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('axtop')}">
<div class="${c('axin')} ${c('axbar')}">
<a class="${c('axmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AX_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('axnav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('axham')}" type="button" data-axham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('axbusca')}" href="/busca/">${AX_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-axham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function axFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('axfoot')}"><div class="${c('axin')}">
<div class="${c('axcols')}">
  <div><a class="${c('axfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-2:#8CC63F">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AX_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('axfh')}">Editorias</div><div class="${c('axflist')}">${cats}</div></div>
  <div><div class="${c('axfh')}">O portal</div><div class="${c('axflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('axfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* Cartao com foto em cima. O `span` da foto tem display:block, senao o
 * aspect-ratio nao aplica. */
function axDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('axdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('axfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('axkick')}">${H.cat(a)}</span>
<h${n} class="${c('axti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('axdd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('axdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

/* Linha numerada. O numeral sai do `counter` do CSS, entao acompanha a ordem
 * real e nunca sai errado ao reordenar. */
function axLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('axrow')} ${c('reveal')}" href="${H.url(a)}">
<span><span class="${c('axkick')}">${H.cat(a)}</span>
<h${n} class="${c('axti')}">${H.esc(a.title)}</h${n}>
<span class="${c('axdt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function axHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('axabre')}">
<div><span class="${c('axchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('axmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('axfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      const lista = resto.slice(0, 6);
      // 🔴 o numero de linhas vai no style: cravado no CSS a grade volta a
      // preencher por linha e a data pula ao ler descendo a coluna
      const linhas = Math.max(1, Math.ceil(lista.length / 2));
      return `<section class="${c('axsec')}" data-par="${idx % 2}">
<div class="${c('axin')}">
<div class="${c('axcab')}">${AX_SIMB}<h2>${H.esc(nome)}</h2>
<a class="${c('axmais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${axDestaque(ctx, d, idx === 0)}
${lista.length ? `<div class="${c('axlista')}" style="--l:${linhas}">${lista.map(a => axLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${axHeader(ctx, menu)}
<main class="${c('axwrap')}">
<div class="${c('axin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${axFooter(ctx, menu)}
${H.bodyEnd()}`;
}

function axAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('axass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` descreve a FOTO. Em metade do acervo
 * importado ele e copia do titulo, ou do slug, e ai repetiria o `h1`. */
function axLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const chato = (x) => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const cSlug = chato(art.slug), cAlt = chato(alt);
  const pref = cAlt.length >= 25 && (cSlug.indexOf(cAlt) === 0 || cAlt.indexOf(cSlug) === 0);
  if (!alt || cAlt === chato(t) || cAlt === cSlug || pref) return '';
  return `<p class="${c('axleg')}">${H.esc(alt)}</p>`;
}

/* A linha fina do artigo so aparece quando NAO esta no corpo. A limpeza da
 * importacao tira a frase do proprio texto quando o `excerpt` da origem vem
 * vazio, o que salva o cartao da home; aqui o mesmo campo seria repeticao. */
function axDekVale(art) {
  const d = String(art.dek || '').trim();
  if (!d) return false;
  const nu = (x) => String(x || '').toLowerCase().replace(/<[^>]+>/g, ' ')
    .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const chave = nu(d).slice(0, 60);
  return !!chave && nu(art.content).indexOf(chave) < 0;
}

function axArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  const rel = (related && related.length) ? `<section class="${c('axrel')}">
<h2 class="${c('axrotb')}">Leia também</h2>
<div class="${c('axgrade')}">${related.slice(0, 4).map(a => axDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${axHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('axwrap')}"><div class="${c('axin')}">
<article class="${c('axart')}">
<div class="${c('axcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('axchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${axDekVale(art) ? `<p class="${c('axdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('axhero')}"><span data-f>${H.pic(art, true)}</span></span>
${axLegenda(ctx, art)}` : ''}
<div class="${c('axbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${axAssinatura(ctx, art)}
${rel}
</div></main>
${axFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function axList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  // a grade pula o destaque, e nao o repete: `resto`, nunca `itens`
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${axHeader(ctx, menu)}
<main class="${c('axwrap')}">
<section class="${c('axsec')}" data-par="0"><div class="${c('axin')}">
<div class="${c('axcab')}">${AX_SIMB}<h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('axdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? axDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('axgrade')}" style="margin-top:36px">${resto.map(a => axDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${axFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AY, arquetipo ESCUDO. Feita para o saudeemalta.net.br.
 *
 * ## De onde vem o desenho
 *
 * A marca do Saude em Alta e **so simbolo, sem palavra**: um escudo vermelho com
 * a linha de batimento cardiaco atravessando, contornado de azul, com uma folha
 * verde saindo do canto de baixo. Nao existe wordmark, entao o cabecalho
 * desenha o simbolo e escreve o nome ao lado.
 *
 * O gesto que sai dai e a **ponta do escudo**: uma faixa que fecha em bico para
 * baixo. Ela aparece no cabecalho de cada editoria e no pe da foto de abertura
 * do artigo, por `clip-path`.
 *
 * ## O que a diferencia das 50 vizinhas da opengravity
 *
 *   - **faixa em bico** por `clip-path` no rotulo de editoria e no pe da foto de
 *     abertura. Nenhuma das 50 corta forma com clip-path
 *   - **lista sem miniatura**: depois da materia de abertura vem uma lista densa
 *     so de manchetes, com marcador em bico. A AV usa dois cartoes grandes, a AW
 *     linha com miniatura, a AX lista numerada
 *   - **materia de abertura horizontal**, foto a direita, com o bico no pe
 *   - **Hepta Slab e Prompt**: nenhuma das duas esta nas 86 familias em uso
 *   - vermelho-escudo com verde-folha, tirados dos pixels do simbolo
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal e PLANO e a listagem mora em `/categoria/<slug>/`, em
 * portugues.** E o inverso dos vizinhos saudeacessivel e saudicas, cujo
 * `category_base` estava vazio e por isso responde em ingles. Copiar a
 * configuracao de um para o outro poe a editoria inteira em 404. Como tudo
 * divide a raiz, **slug podado colide com pagina que o motor regenera**:
 * contato, politica-de-privacidade, termos-de-uso e quem-somos ficam fora do 410.
 *
 * ⚠️ **`clip-path` no pe da foto come altura de verdade.** O `padding-bottom` do
 * bloco seguinte tem que compensar o bico, senao o texto sobe para dentro do
 * corte.
 *
 * ⚠️ **A marca nao tem wordmark**, entao o `logoImg` da origem e apenas o
 * simbolo: o nome do portal continua sendo texto ao lado dele, e nao pode sumir
 * quando o arquivo existe.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - as variaveis de cor vao no `:root`, e o respiro usa `padding-block`
 */

function ayCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#F6F1EF';
  const viva = t.vivid || '#3C7A1E';
  const canto = fp.radius === 'sharp' ? '0' : '4px';
  const bico = 'polygon(0 0,100% 0,100% calc(100% - 26px),50% 100%,0 calc(100% - 26px))';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --footer-bg:${t.footerBg || '#3A0D08'};--footer-tx:${t.footerTx || '#E6CFCB'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('aywrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.7;-webkit-font-smoothing:antialiased}
${s('aywrap')} *{box-sizing:border-box}
${s('ayin')}{max-width:${fp.container || '1140px'};margin:0 auto;padding:0 24px;width:100%}
${s('aywrap')} h1,${s('aywrap')} h2,${s('aywrap')} h3,${s('aywrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.002em;line-height:1.16;margin:0}
${s('aywrap')} a{color:inherit;text-decoration:none}
${s('aywrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('aytop')}{background:var(--paper);border-bottom:1px solid var(--line);
  box-shadow:inset 0 -5px 0 var(--pri)}
${s('aybar')}{display:flex;align-items:center;gap:18px;padding-block:15px 19px;flex-wrap:wrap}
${s('aymarca')}{display:inline-flex;align-items:center;gap:12px;font-family:var(--fd);
  font-weight:800;font-size:clamp(21px,2.7vw,29px);letter-spacing:-.01em;color:var(--pri);flex:none}
${s('aymarca')} svg{display:block;height:1.35em;width:auto;flex:none;align-self:center}
/* o simbolo da origem nao tem palavra: a imagem entra ao lado do nome, nunca no
   lugar dele. Imagem sem medida derruba o CLS */
${s('aymarca')} img{display:block;height:46px;width:auto;flex:none}
@media(max-width:560px){${s('aymarca')} img{height:36px}}
${s('ayfb')} img{display:block;height:42px;width:auto}
/* ⚠️ com oito editorias o botao Buscar quebrava para a segunda linha e o
   cabecalho ficava com duas alturas. O menu encolhe, o botao fica */
${s('aynav')}{display:flex;gap:15px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
@media(min-width:1101px){${s('aynav')} a{font-size:11.5px;letter-spacing:.02em}}
${s('aynav')} a{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.03em;color:var(--dek);transition:color .2s ease}
${s('aynav')} a:hover{color:var(--pri)}
${s('aybusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.05em;
  background:var(--pri);color:var(--sob);padding:10px 17px;border-radius:${canto};
  flex:none;margin-left:6px}
${s('aybusca')}:hover{background:var(--viva)}
${s('ayham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('ayham')} i,${s('ayham')} i::before,${s('ayham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('ayham')} i{top:21px}
${s('ayham')} i::before{top:-6px;left:0}
${s('ayham')} i::after{top:6px;left:0}
@media(max-width:560px){${s('aymarca')}{font-size:19px;gap:9px}${s('aybar')}{gap:11px}
  ${s('aybusca')}{font-size:10.5px;padding:9px 13px;gap:6px}}
@media(max-width:1100px){
  ${s('ayham')}{display:block;order:2}
  ${s('aybusca')}{order:3;margin-left:0}
  ${s('aynav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('aynav')}[data-aberto="1"]{display:flex}
  ${s('aynav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink);
    font-size:13.5px}
}

/* ---------- abertura: texto a esquerda, imagem a direita ---------- */
${s('ayabre')}{display:grid;grid-template-columns:1.05fr 1fr;gap:42px;align-items:center;
  padding-block:38px 34px;border-bottom:1px solid var(--line)}
${s('ayabre')} h2{font-size:clamp(30px,4.2vw,50px);line-height:1.06;margin:14px 0 0;
  letter-spacing:-.014em}
${s('ayabre')} h2 a:hover{color:var(--pri)}
${s('ayabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('aymm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:18px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('aymm')} b{color:var(--ink);font-weight:700}
${s('aychap')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:.13em;color:var(--sob);background:var(--pri);
  padding:6px 14px;border-radius:${canto}}
${s('aychap')} a{color:var(--sob)}
@media(max-width:820px){${s('ayabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 24px}}

/* ---------- secao: rotulo em faixa de bico ---------- */
${s('aysec')}{padding-block:42px;background:var(--paper)}
${s('aysec')}[data-par="1"]{background:var(--wash)}
${s('aycab')}{display:flex;align-items:flex-start;gap:16px;margin-bottom:26px;flex-wrap:wrap}
/* a faixa fecha em bico para baixo: e a ponta do escudo da marca. O bico come
   altura de verdade, entao o padding de baixo compensa */
${s('aycab')} h1,${s('aycab')} h2{font-family:var(--fd);font-weight:800;
  font-size:clamp(18px,2.1vw,25px);letter-spacing:.004em;
  color:var(--sob);margin:0;line-height:1.1;flex:none;background:var(--pri);
  padding:11px 24px 34px;clip-path:${bico}}
${s('aymais')}{margin-left:auto;margin-top:10px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--viva);flex:none;
  border-bottom:2px solid var(--viva);padding-bottom:3px}
${s('aymais')}:hover{color:var(--pri);border-bottom-color:var(--pri)}
${s('aydescr')}{margin:0 0 26px;font-size:15.5px;line-height:1.66;color:var(--dek);
  max-width:72ch;text-align:left}

/* materia de abertura da secao: texto a esquerda, foto a direita com bico no pe */
${s('aydest')}{display:grid;grid-template-columns:1fr 1.02fr;gap:32px;align-items:center}
${s('aydest')} ${s('ayti')}{font-size:clamp(21px,2.5vw,30px);line-height:1.14;margin-top:11px;
  letter-spacing:-.01em}
${s('aykick')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.13em'};color:var(--viva)}
${s('ayti')}{display:block;font-family:var(--fd);font-weight:700;font-size:19px;line-height:1.22;
  color:var(--ink);margin:0;transition:color .2s ease}
${s('aydd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:56ch;text-align:left}
${s('aydt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('ayfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('ayfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '4/3'};overflow:hidden}
${s('ayfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('aydest')}:hover ${s('ayti')}{color:var(--pri)}
${s('aydest')}:hover ${s('ayfoto')} [data-f] img{transform:scale(1.04)}
@media(max-width:780px){${s('aydest')}{grid-template-columns:1fr;gap:16px}
  ${s('aydest')} ${s('ayfoto')}{order:-1}}

/* a lista: densa, so manchete, com marcador em bico. Sem miniatura de proposito */
${s('aylista')}{margin-top:32px;border-top:2px solid var(--pri);
  display:grid;grid-template-columns:1fr 1fr;gap:0 44px;
  grid-auto-flow:column;grid-template-rows:repeat(var(--l,3),auto)}
${s('ayrow')}{display:grid;grid-template-columns:auto minmax(0,1fr);gap:13px;align-items:start;
  padding-block:15px;border-bottom:1px solid var(--line)}
${s('ayrow')}::before{content:"";width:11px;height:13px;margin-top:6px;flex:none;
  background:var(--viva);clip-path:polygon(0 0,100% 0,100% 58%,50% 100%,0 58%)}
${s('ayrow')}:hover::before{background:var(--pri)}
${s('ayrow')}:hover ${s('ayti')}{color:var(--pri)}
${s('ayrow')} ${s('ayti')}{font-size:17px;line-height:1.28}
${s('ayrow')} ${s('aydd')}{display:none}
@media(max-width:820px){
  ${s('aylista')}{grid-template-columns:1fr;grid-auto-flow:row;grid-template-rows:none;
    gap:0;margin-top:26px}
}

/* listagem de editoria e relacionados: grade de tres cartoes empilhados */
${s('aygrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 28px}
${s('aygrade')} ${s('aydest')}{display:block}
${s('aygrade')} ${s('ayti')}{font-size:19px;line-height:1.24;margin-top:11px}
${s('aygrade')} ${s('aydd')}{display:none}
${s('aygrade')} ${s('ayfoto')} [data-f]{aspect-ratio:${fp.cardAr || '16/10'}}
@media(max-width:900px){${s('aygrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:600px){${s('aygrade')}{grid-template-columns:1fr;gap:28px}}

/* ---------- artigo ---------- */
${s('ayart')}{padding-block:30px 12px}
${s('aycol')}{max-width:70ch}
${s('ayart')} h1{font-size:clamp(28px,4vw,44px);line-height:1.1;letter-spacing:-.016em;
  margin:14px 0 0}
${s('aydek')}{font-size:19px;line-height:1.55;color:var(--dek);margin:16px 0 0;max-width:62ch}
/* o bico no pe da foto de abertura: o padding do bloco seguinte compensa a
   altura comida pelo corte */
${s('ayhero')}{display:block;overflow:hidden;background:var(--ph);margin-top:26px;
  clip-path:${bico}}
${s('ayhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '3/2'};overflow:hidden}
${s('ayhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('ayleg')}{margin:6px 0 0;font-size:12.5px;line-height:1.5;color:var(--muted);
  max-width:70ch;text-align:left}
${s('aybody')}{max-width:70ch;margin-top:22px;font-size:${fp.corpoFs || '18px'};line-height:1.8}
${s('aybody')} p{margin:0 0 21px}
${s('aybody')} a{color:var(--pri);text-decoration:underline;text-underline-offset:3px}
${s('aybody')} a:hover{color:var(--viva)}
${s('aybody')} h2{font-family:var(--fd);font-weight:800;font-size:25px;letter-spacing:-.008em;
  margin:36px 0 12px;color:var(--pri);padding-bottom:8px;border-bottom:2px solid var(--line)}
${s('aybody')} h3{font-family:var(--fd);font-weight:700;font-size:20px;margin:28px 0 10px}
${s('aybody')} ul,${s('aybody')} ol{margin:0 0 21px;padding-left:22px}
${s('aybody')} li{margin:0 0 9px}
${s('aybody')} img{max-width:100%;height:auto;border-radius:${canto};margin:8px 0}
${s('aybody')} figure{margin:22px 0}
${s('aybody')} figcaption{font-size:12.5px;color:var(--muted);margin-top:8px}
${s('aybody')} blockquote{margin:28px 0;padding:4px 0 4px 22px;border-left:5px solid var(--pri);
  font-family:var(--fd);font-size:21px;line-height:1.44}
${s('aybody')} table{width:100%;border-collapse:collapse;margin:0 0 24px;font-size:14.5px}
${s('aybody')} th,${s('aybody')} td{border:0;border-bottom:1px solid var(--line);
  padding:11px 12px 11px 0;text-align:left;vertical-align:top}
${s('aybody')} th{font-family:var(--fb);font-weight:700;background:transparent}
${s('aybody')} caption{text-align:left;font-size:13px;color:var(--muted);padding-bottom:8px}

/* a tabela vira cartao no celular: sem isto ela sai da tela e o gesto de
   arrastar nao e descoberto. O thead sai da tela mas continua no DOM */
@media(max-width:640px){
  ${s('aybody')} .tabwrap{overflow:visible;border:0;background:transparent}
  ${s('aybody')} table{min-width:0;display:block;width:auto;overflow:visible}
  ${s('aybody')} table caption{display:none}
  ${s('aybody')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;
    clip:rect(0 0 0 0)}
  ${s('aybody')} table tbody,${s('aybody')} table tr,
  ${s('aybody')} table th,${s('aybody')} table td{display:block;width:auto}
  ${s('aybody')} table tbody tr{background:var(--surf);border:1px solid var(--line);
    border-radius:12px;padding:2px 18px 16px;margin-bottom:13px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('aybody')} table tbody th,${s('aybody')} table tbody td{border:0;background:transparent;
    padding:0}
  ${s('aybody')} table tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;
    font-weight:700;text-align:left}
  ${s('aybody')} table tbody td{padding:13px 0 0;text-align:left;line-height:1.55}
  ${s('aybody')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);
    margin-bottom:2px}
}

${s('ayass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:start;
  max-width:70ch;margin-top:38px;padding:20px;background:var(--wash);border-radius:${canto};
  border-left:5px solid var(--pri)}
${s('ayass')} img{border-radius:${canto}}
${s('ayass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--viva)}
${s('ayass')} .nm{display:block;font-family:var(--fd);font-weight:700;font-size:19px;margin-top:4px}
${s('ayass')} p{margin:8px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek)}
${s('ayass')} .go{display:inline-block;margin-top:10px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.07em;color:var(--pri);
  border-bottom:2px solid var(--pri);padding-bottom:2px}
@media(max-width:560px){${s('ayass')}{grid-template-columns:1fr;gap:12px}}

/* relacionados com a MESMA largura da coluna do artigo */
${s('ayrel')}{max-width:70ch;margin-top:44px;padding-top:24px;border-top:2px solid var(--pri)}
${s('ayrotb')}{display:inline-block;font-family:var(--fb);font-size:11px;font-weight:700;
  letter-spacing:.13em;color:var(--sob);background:var(--pri);
  padding:8px 18px 22px;clip-path:${bico};margin-bottom:14px}
${s('ayrel')} ${s('aygrade')}{grid-template-columns:1fr 1fr;gap:26px 22px}
@media(max-width:600px){${s('ayrel')} ${s('aygrade')}{grid-template-columns:1fr}}

/* ---------- rodape ---------- */
${s('ayfoot')}{background:var(--footer-bg);color:var(--footer-tx);margin-top:56px;
  padding-block:38px 22px}
${s('aycols')}{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:34px}
${s('ayfoot')} p{font-size:14.5px;color:var(--footer-tx)}
${s('ayfb')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:800;font-size:23px;letter-spacing:-.01em;color:#fff}
${s('ayfh')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.14em;color:#fff;margin-bottom:12px}
${s('ayflist')} a{display:block;font-size:14.5px;padding:4px 0;color:var(--footer-tx)}
${s('ayflist')} a:hover{color:#fff}
${s('ayfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:28px;padding-top:15px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;opacity:.85}
@media(max-width:820px){${s('aycols')}{grid-template-columns:1fr;gap:26px}}

${s('reveal')}{opacity:1}
@media(prefers-reduced-motion:reduce){
  ${s('aywrap')} *{transition:none !important;animation:none !important}
}`;
}

/* O escudo da marca, desenhado. Ele acompanha o nome mesmo quando existe arquivo
 * de logotipo, porque o arquivo da origem e SO o simbolo, sem palavra. */
const AY_SIMB = `<svg viewBox="0 0 26 30" width="26" height="30" aria-hidden="true">
<path d="M13 1 2 5v11c0 7 5 11.4 11 13 6-1.6 11-6 11-13V5Z" fill="var(--marca-1,#B81C10)"/>
<path d="M13 1 2 5v11c0 7 5 11.4 11 13 6-1.6 11-6 11-13V5Z" fill="none"
  stroke="var(--marca-3,#124A80)" stroke-width="2"/>
<path d="M6 15h3.4l2-4.2 2.6 8 2.2-5.4 1.4 1.6H20" fill="none" stroke="#fff"
  stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M24 20c0 4-3.6 7.4-7.6 8.6 1-4.4 4-7.6 7.6-8.6Z" fill="var(--marca-2,#3C7A1E)"/>
</svg>`;

const AY_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function ayHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aynav-' + (site.slug || 'p');
  // 🔴 aqui a listagem e /categoria/<slug>/, em PORTUGUES, ao contrario dos
  // vizinhos saudeacessivel e saudicas. Quem monta o caminho e o H.curl
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aytop')}">
<div class="${c('ayin')} ${c('aybar')}">
<a class="${c('aymarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial">${site.logoImg
    ? `<img src="${site.logoImg}" alt="" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : AY_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
<nav class="${c('aynav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('ayham')}" type="button" data-ayham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('aybusca')}" href="/busca/">${AY_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-ayham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function ayFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('ayfoot')}"><div class="${c('ayin')}">
<div class="${c('aycols')}">
  <div><a class="${c('ayfb')}" href="/" aria-label="${H.esc(site.name)}">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : AY_SIMB}<span>${H.esc(site.shortName || site.name)}</span></a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('ayfh')}">Editorias</div><div class="${c('ayflist')}">${cats}</div></div>
  <div><div class="${c('ayfh')}">O portal</div><div class="${c('ayflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('ayfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* Materia de abertura: texto a esquerda, foto a direita. Dentro da grade de tres
 * o CSS troca para empilhado, e o mesmo cartao serve nos dois lugares. */
function ayDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('aydest')} ${c('reveal')}" href="${H.url(a)}">
<span><span class="${c('aykick')}">${H.cat(a)}</span>
<h${n} class="${c('ayti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('aydd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('aydt')}">${H.esc(H.dateShort(a.date))}</span></span>
<span class="${c('ayfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
</a>`;
}

/* Linha densa, so manchete, com marcador em bico. Sem miniatura de proposito. */
function ayLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('ayrow')} ${c('reveal')}" href="${H.url(a)}">
<span><span class="${c('aykick')}">${H.cat(a)}</span>
<h${n} class="${c('ayti')}">${H.esc(a.title)}</h${n}>
<span class="${c('aydt')}">${H.esc(H.dateShort(a.date))}</span></span>
</a>`;
}

function ayHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('ayabre')}">
<div><span class="${c('aychap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('aymm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('ayfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data, e nao por fatia de N
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 7)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      const lista = resto.slice(0, 8);
      // o numero de linhas vai no style: cravado no CSS a grade volta a
      // preencher por linha e a data pula ao ler descendo a coluna
      const linhas = Math.max(1, Math.ceil(lista.length / 2));
      return `<section class="${c('aysec')}" data-par="${idx % 2}">
<div class="${c('ayin')}">
<div class="${c('aycab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('aymais')}" href="${H.curl(cs)}">Ver tudo de ${H.esc(nome)}</a></div>
${ayDestaque(ctx, d, idx === 0)}
${lista.length ? `<div class="${c('aylista')}" style="--l:${linhas}">${lista.map(a => ayLinha(ctx, a)).join('')}</div>` : ''}
</div></section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${ayHeader(ctx, menu)}
<main class="${c('aywrap')}">
<div class="${c('ayin')}">${H.h1(ctx)}
${abertura}</div>
${secoes}
</main>
${ayFooter(ctx, menu)}
${H.bodyEnd()}`;
}

function ayAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('ayass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` descreve a FOTO. Em metade do acervo
 * importado ele e copia do titulo, ou do slug, e ai repetiria o `h1`. */
function ayLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const chato = (x) => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const cSlug = chato(art.slug), cAlt = chato(alt);
  const pref = cAlt.length >= 25 && (cSlug.indexOf(cAlt) === 0 || cAlt.indexOf(cSlug) === 0);
  if (!alt || cAlt === chato(t) || cAlt === cSlug || pref) return '';
  return `<p class="${c('ayleg')}">${H.esc(alt)}</p>`;
}

/* A linha fina do artigo so aparece quando NAO esta no corpo. A limpeza da
 * importacao tira a frase do proprio texto quando o `excerpt` da origem vem
 * vazio, o que salva o cartao da home; aqui o mesmo campo seria repeticao. */
function ayDekVale(art) {
  const d = String(art.dek || '').trim();
  if (!d) return false;
  const nu = (x) => String(x || '').toLowerCase().replace(/<[^>]+>/g, ' ')
    .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const chave = nu(d).slice(0, 60);
  return !!chave && nu(art.content).indexOf(chave) < 0;
}

function ayArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  const rel = (related && related.length) ? `<section class="${c('ayrel')}">
<h2 class="${c('ayrotb')}">Leia também</h2>
<div class="${c('aygrade')}">${related.slice(0, 4).map(a => ayDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${ayHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('aywrap')}"><div class="${c('ayin')}">
<article class="${c('ayart')}">
<div class="${c('aycol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('aychap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${ayDekVale(art) ? `<p class="${c('aydek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('ayhero')}"><span data-f>${H.pic(art, true)}</span></span>
${ayLegenda(ctx, art)}` : ''}
<div class="${c('aybody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${ayAssinatura(ctx, art)}
${rel}
</div></main>
${ayFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function ayList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  // a grade pula o destaque, e nao o repete: `resto`, nunca `itens`
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${ayHeader(ctx, menu)}
<main class="${c('aywrap')}">
<section class="${c('aysec')}" data-par="0"><div class="${c('ayin')}">
<div class="${c('aycab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('aydescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? ayDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('aygrade')}" style="margin-top:34px">${resto.map(a => ayDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</div></section>
</main>
${ayFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura AZ, arquetipo RAIL. Feita para o revistatopsaude.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca da Revista Top Saude e um **documento azul com linhas de texto**, com
 * uma lupa vermelha de cruz medica no canto, ao lado de "revista" em cursiva e
 * TOP SAUDE em grotesco pesado, TOP em vermelho e SAUDE em azul-marinho.
 *
 * O que o nome promete e **revista**, e revista tem sumario. O gesto que sai dai
 * e o **rail**: uma coluna estreita a direita, grudada na rolagem, com a lista
 * do que mais se le, numerada em vermelho. A home vira duas colunas de verdade,
 * e nao uma pilha de faixas.
 *
 * ## O que a diferencia das 51 vizinhas da opengravity
 *
 *   - **home em duas colunas com rail grudado** (`position:sticky`). A AD tem
 *     rail de "ultimas", mas solto e sem sticky, e a coluna principal dela e
 *     faixa cheia
 *   - **numeracao do rail em vermelho cheio, grande, a esquerda do titulo**
 *   - **serifada de revista no titulo** (Piazzolla) contra grotesca estreita no
 *     corpo (Encode Sans): nenhuma das duas esta nas 86 familias em uso
 *   - marinho com vermelho-tijolo, tirados dos pixels do logotipo
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **`position:sticky` so gruda se o PAI nao tiver `overflow` escondido e
 * tiver altura maior que o rail.** Numa grade de duas colunas o pai e a celula,
 * e ela cresce com o conteudo: o rail gruda. Mas basta alguem por
 * `overflow:hidden` no wrapper para o sticky virar `static` **sem nenhum aviso**,
 * e a coluna passa a rolar junto. Por isso o wrapper desta arquitetura nao tem
 * `overflow` em lugar nenhum.
 *
 * 🔴 **O portal NAO e plano e o `category_base` da origem estava VAZIO**, o que
 * significa `category`, em ingles. Artigo em `/<editoria>/<slug>/`, listagem em
 * `/category/<slug>/`, e todo link de editoria sai de `H.curl`.
 *
 * ⚠️ **Abaixo de 1000px o rail vira uma faixa comum**, embaixo da coluna
 * principal, e o `sticky` sai: grudado em tela estreita ele cobre o texto.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - as variaveis de cor vao no `:root`, e o respiro usa `padding-block`
 */

function azCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#F2F3F9';
  const viva = t.vivid || '#B01C28';
  const canto = fp.radius === 'sharp' ? '0' : '3px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --footer-bg:${t.footerBg || '#141A48'};--footer-tx:${t.footerTx || '#BEC4E4'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('azwrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.66;-webkit-font-smoothing:antialiased}
${s('azwrap')} *{box-sizing:border-box}
${s('azin')}{max-width:${fp.container || '1200px'};margin:0 auto;padding:0 24px;width:100%}
${s('azwrap')} h1,${s('azwrap')} h2,${s('azwrap')} h3,${s('azwrap')} h4{font-family:var(--fd);
  font-weight:700;letter-spacing:-.006em;line-height:1.14;margin:0}
${s('azwrap')} a{color:inherit;text-decoration:none}
${s('azwrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('aztop')}{background:var(--paper);border-bottom:3px double var(--pri)}
${s('azbar')}{display:flex;align-items:center;gap:18px;padding-block:16px 18px;flex-wrap:wrap}
${s('azmarca')}{display:inline-flex;align-items:center;gap:11px;font-family:var(--fd);
  font-weight:800;font-size:clamp(22px,2.9vw,32px);letter-spacing:-.02em;color:var(--pri);flex:none}
${s('azmarca')} svg{display:block;height:1.15em;width:auto;flex:none;align-self:center}
/* imagem sem medida derruba o CLS: a altura manda, a largura sai da proporcao */
${s('azmarca')} img{display:block;height:46px;width:auto;flex:none}
@media(max-width:560px){${s('azmarca')} img{height:36px}}
${s('azfb')} img{display:block;height:42px;width:auto}
${s('aznav')}{display:flex;gap:17px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('aznav')} a{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('aznav')} a:hover{color:var(--viva)}
${s('azbusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.06em;
  background:var(--viva);color:#fff;padding:10px 17px;border-radius:${canto};
  flex:none;margin-left:6px}
${s('azbusca')}:hover{background:var(--pri)}
${s('azham')}{display:none;width:46px;height:46px;border:2px solid var(--pri);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('azham')} i,${s('azham')} i::before,${s('azham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--pri);content:""}
${s('azham')} i{top:21px}
${s('azham')} i::before{top:-6px;left:0}
${s('azham')} i::after{top:6px;left:0}
@media(max-width:560px){${s('azmarca')}{font-size:20px;gap:8px}${s('azbar')}{gap:11px}
  ${s('azbusca')}{font-size:10.5px;padding:9px 13px;gap:6px}}
@media(max-width:1100px){
  ${s('azham')}{display:block;order:2}
  ${s('azbusca')}{order:3;margin-left:0}
  ${s('aznav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('aznav')}[data-aberto="1"]{display:flex}
  ${s('aznav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink);
    font-size:13.5px}
}

/* ---------- home em duas colunas: miolo e rail grudado ----------
   nenhum overflow no caminho: basta um overflow:hidden no pai para o sticky
   virar static, sem aviso nenhum */
${s('azduas')}{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:46px;
  padding-block:34px 12px;align-items:start}
${s('azrail')}{position:sticky;top:22px;border-top:3px solid var(--viva);padding-top:16px}
${s('azrailh')}{font-family:var(--fd);font-weight:800;font-size:19px;letter-spacing:-.014em;
  color:var(--pri);margin:0 0 14px}
${s('azrail')} ol{list-style:none;margin:0;padding:0;counter-reset:az}
${s('azrail')} li{counter-increment:az;border-bottom:1px solid var(--line)}
${s('azrail')} li a{display:grid;grid-template-columns:auto minmax(0,1fr);gap:13px;
  align-items:start;padding-block:13px}
${s('azrail')} li a::before{content:counter(az);font-family:var(--fd);font-weight:800;
  font-size:25px;line-height:1;color:var(--viva);letter-spacing:-.03em;padding-top:1px}
${s('azrail')} li a span{font-family:var(--fd);font-weight:700;font-size:15.5px;line-height:1.3;
  color:var(--ink);transition:color .2s ease}
${s('azrail')} li a:hover span{color:var(--viva)}
@media(max-width:1000px){
  ${s('azduas')}{grid-template-columns:1fr;gap:34px}
  /* grudado em tela estreita ele cobre o texto */
  ${s('azrail')}{position:static}
}

/* ---------- abertura: texto a esquerda, imagem a direita ---------- */
${s('azabre')}{display:grid;grid-template-columns:1.04fr 1fr;gap:36px;align-items:center;
  padding-bottom:30px;border-bottom:1px solid var(--line)}
${s('azabre')} h2{font-size:clamp(29px,3.9vw,46px);line-height:1.05;margin:13px 0 0;
  letter-spacing:-.022em}
${s('azabre')} h2 a:hover{color:var(--viva)}
${s('azabre')} p{font-size:17px;line-height:1.6;color:var(--dek);margin:15px 0 0;
  max-width:46ch;text-align:left}
${s('azmm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:17px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('azmm')} b{color:var(--ink);font-weight:700}
${s('azchap')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:.14em;color:#fff;background:var(--viva);
  padding:6px 13px;border-radius:${canto}}
${s('azchap')} a{color:#fff}
@media(max-width:820px){${s('azabre')}{grid-template-columns:1fr;gap:20px}}

/* ---------- secao dentro do miolo ---------- */
${s('azsec')}{padding-block:34px 0}
${s('azcab')}{display:flex;align-items:baseline;gap:14px;margin-bottom:22px;flex-wrap:wrap;
  border-bottom:2px solid var(--pri);padding-bottom:9px}
${s('azcab')} h1,${s('azcab')} h2{font-family:var(--fd);font-weight:800;
  font-size:clamp(21px,2.4vw,28px);letter-spacing:-.02em;color:var(--pri);margin:0;
  line-height:1.1;flex:none}
${s('azmais')}{margin-left:auto;font-family:var(--fb);font-size:11.5px;font-weight:700;
  letter-spacing:.08em;color:var(--viva);flex:none}
${s('azmais')}:hover{color:var(--pri)}
${s('azdescr')}{margin:0 0 24px;font-size:15.5px;line-height:1.64;color:var(--dek);
  max-width:70ch;text-align:left}

/* materia de abertura da secao: foto larga em cima, texto embaixo */
${s('azdest')}{display:block}
${s('azdest')} ${s('azti')}{font-size:clamp(20px,2.4vw,28px);line-height:1.13;margin-top:12px;
  letter-spacing:-.018em}
${s('azkick')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.14em'};color:var(--viva)}
${s('azti')}{display:block;font-family:var(--fd);font-weight:700;font-size:19px;line-height:1.2;
  color:var(--ink);margin:0;transition:color .2s ease;letter-spacing:-.01em}
${s('azdd')}{display:block;margin:10px 0 0;font-size:15.5px;line-height:1.62;color:var(--dek);
  max-width:56ch;text-align:left}
${s('azdt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;color:var(--muted)}
${s('azfoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('azfoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('azfoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('azdest')}:hover ${s('azti')}{color:var(--viva)}
${s('azdest')}:hover ${s('azfoto')} [data-f] img{transform:scale(1.04)}

/* a lista do miolo: dois cartoes por linha, com filete marinho fino em cima */
${s('azlista')}{display:grid;grid-template-columns:1fr 1fr;gap:28px 26px;margin-top:26px}
${s('azrow')}{display:block;border-top:2px solid var(--line);padding-top:13px}
${s('azrow')}:hover{border-top-color:var(--viva)}
${s('azmini')}{display:block;overflow:hidden;background:var(--ph);margin-bottom:11px;
  border-radius:${canto}}
${s('azmini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '16/9'};overflow:hidden}
${s('azmini')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('azrow')}:hover ${s('azmini')} [data-f] img{transform:scale(1.05)}
${s('azrow')}:hover ${s('azti')}{color:var(--viva)}
${s('azrow')} ${s('azti')}{font-size:17.5px;line-height:1.24;margin-top:6px}
${s('azrow')} ${s('azdd')}{display:none}
@media(max-width:640px){${s('azlista')}{grid-template-columns:1fr;gap:24px}}

/* listagem de editoria e relacionados: grade de tres cartoes */
${s('azgrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 26px}
${s('azgrade')} ${s('azti')}{font-size:18.5px;line-height:1.22;margin-top:11px}
${s('azgrade')} ${s('azdd')}{display:none}
${s('azgrade')} ${s('azfoto')} [data-f]{aspect-ratio:${fp.cardAr || '16/9'}}
@media(max-width:900px){${s('azgrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:600px){${s('azgrade')}{grid-template-columns:1fr;gap:28px}}

/* ---------- artigo ---------- */
${s('azart')}{padding-block:28px 12px}
${s('azcol')}{max-width:70ch}
${s('azart')} h1{font-size:clamp(28px,3.9vw,43px);line-height:1.08;letter-spacing:-.024em;
  margin:14px 0 0}
${s('azdek')}{font-size:19px;line-height:1.55;color:var(--dek);margin:16px 0 0;max-width:62ch}
${s('azhero')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto};
  margin-top:26px}
${s('azhero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('azhero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('azleg')}{margin:10px 0 0;font-size:12.5px;line-height:1.5;color:var(--muted);
  max-width:70ch;text-align:left}
${s('azbody')}{max-width:70ch;margin-top:26px;font-size:${fp.corpoFs || '18px'};line-height:1.78}
${s('azbody')} p{margin:0 0 21px}
${s('azbody')} a{color:var(--viva);text-decoration:underline;text-underline-offset:3px}
${s('azbody')} a:hover{color:var(--pri)}
${s('azbody')} h2{font-family:var(--fd);font-weight:800;font-size:25px;letter-spacing:-.02em;
  margin:36px 0 12px;color:var(--pri)}
${s('azbody')} h3{font-family:var(--fd);font-weight:700;font-size:20px;margin:28px 0 10px}
${s('azbody')} ul,${s('azbody')} ol{margin:0 0 21px;padding-left:22px}
${s('azbody')} li{margin:0 0 9px}
${s('azbody')} img{max-width:100%;height:auto;border-radius:${canto};margin:8px 0}
${s('azbody')} figure{margin:22px 0}
${s('azbody')} figcaption{font-size:12.5px;color:var(--muted);margin-top:8px}
${s('azbody')} blockquote{margin:28px 0;padding:0 0 0 22px;border-left:4px solid var(--viva);
  font-family:var(--fd);font-size:21px;line-height:1.44;font-style:italic}
${s('azbody')} table{width:100%;border-collapse:collapse;margin:0 0 24px;font-size:14.5px}
${s('azbody')} th,${s('azbody')} td{border:0;border-bottom:1px solid var(--line);
  padding:11px 12px 11px 0;text-align:left;vertical-align:top}
${s('azbody')} th{font-family:var(--fb);font-weight:700;background:transparent}
${s('azbody')} caption{text-align:left;font-size:13px;color:var(--muted);padding-bottom:8px}

/* a tabela vira cartao no celular: sem isto ela sai da tela e o gesto de
   arrastar nao e descoberto. O thead sai da tela mas continua no DOM */
@media(max-width:640px){
  ${s('azbody')} .tabwrap{overflow:visible;border:0;background:transparent}
  ${s('azbody')} table{min-width:0;display:block;width:auto;overflow:visible}
  ${s('azbody')} table caption{display:none}
  ${s('azbody')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;
    clip:rect(0 0 0 0)}
  ${s('azbody')} table tbody,${s('azbody')} table tr,
  ${s('azbody')} table th,${s('azbody')} table td{display:block;width:auto}
  ${s('azbody')} table tbody tr{background:var(--wash);border:1px solid var(--line);
    border-radius:10px;padding:2px 18px 16px;margin-bottom:13px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('azbody')} table tbody th,${s('azbody')} table tbody td{border:0;background:transparent;
    padding:0}
  ${s('azbody')} table tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;
    font-weight:700;text-align:left}
  ${s('azbody')} table tbody td{padding:13px 0 0;text-align:left;line-height:1.55}
  ${s('azbody')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);
    margin-bottom:2px}
}

${s('azass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:start;
  max-width:70ch;margin-top:38px;padding:20px;background:var(--wash);border-radius:${canto}}
${s('azass')} img{border-radius:${canto}}
${s('azass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--viva)}
${s('azass')} .nm{display:block;font-family:var(--fd);font-weight:700;font-size:19px;margin-top:4px}
${s('azass')} p{margin:8px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek)}
${s('azass')} .go{display:inline-block;margin-top:10px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.07em;color:var(--pri);
  border-bottom:2px solid var(--viva);padding-bottom:2px}
@media(max-width:560px){${s('azass')}{grid-template-columns:1fr;gap:12px}}

/* relacionados com a MESMA largura da coluna do artigo */
${s('azrel')}{max-width:70ch;margin-top:44px;padding-top:22px;border-top:3px double var(--pri)}
${s('azrotb')}{display:inline-block;font-family:var(--fd);font-weight:800;font-size:20px;
  letter-spacing:-.02em;color:var(--pri);margin-bottom:18px}
${s('azrel')} ${s('azgrade')}{grid-template-columns:1fr 1fr;gap:26px 22px}
@media(max-width:600px){${s('azrel')} ${s('azgrade')}{grid-template-columns:1fr}}

/* ---------- rodape ---------- */
${s('azfoot')}{background:var(--footer-bg);color:var(--footer-tx);margin-top:56px;
  padding-block:38px 22px}
${s('azcols')}{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:34px}
${s('azfoot')} p{font-size:14.5px;color:var(--footer-tx)}
${s('azfb')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:800;font-size:23px;letter-spacing:-.02em;color:#fff}
${s('azfh')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.14em;color:#fff;margin-bottom:12px}
${s('azflist')} a{display:block;font-size:14.5px;padding:4px 0;color:var(--footer-tx)}
${s('azflist')} a:hover{color:#fff}
${s('azfim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:28px;padding-top:15px;border-top:1px solid rgba(255,255,255,.16);
  font-size:12.5px;opacity:.85}
@media(max-width:820px){${s('azcols')}{grid-template-columns:1fr;gap:26px}}

${s('reveal')}{opacity:1}
@media(prefers-reduced-motion:reduce){
  ${s('azwrap')} *{transition:none !important;animation:none !important}
}`;
}

/* O documento com a lupa da marca, desenhado. So entra quando o portal nao tem
 * arquivo de logotipo. */
const AZ_SIMB = `<svg viewBox="0 0 26 30" width="26" height="30" aria-hidden="true">
<path d="M4 2h11l7 7v19H4Z" fill="none" stroke="var(--marca-1,#232E86)" stroke-width="2"
  stroke-linejoin="round"/>
<path d="M15 2v7h7" fill="none" stroke="var(--marca-1,#232E86)" stroke-width="2"
  stroke-linejoin="round"/>
<path d="M8 14h10M8 18h10M8 22h6" stroke="var(--marca-1,#232E86)" stroke-width="1.6"
  stroke-linecap="round"/>
<circle cx="19" cy="21" r="6" fill="var(--marca-2,#B01C28)"/>
<path d="M19 18v6M16 21h6" stroke="#fff" stroke-width="2" stroke-linecap="round"/>
</svg>`;

const AZ_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function azHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'aznav-' + (site.slug || 'p');
  // 🔴 a listagem mora em /category/<slug>/, em INGLES: o `category_base` da
  // origem estava vazio, e vazio significa `category`
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('aztop')}">
<div class="${c('azin')} ${c('azbar')}">
<a class="${c('azmarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--pri);--marca-2:var(--viva)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${AZ_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('aznav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('azham')}" type="button" data-azham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('azbusca')}" href="/busca/">${AZ_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-azham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function azFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('azfoot')}"><div class="${c('azin')}">
<div class="${c('azcols')}">
  <div><a class="${c('azfb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#8E97D8;--marca-2:var(--viva)">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${AZ_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('azfh')}">Editorias</div><div class="${c('azflist')}">${cats}</div></div>
  <div><div class="${c('azfh')}">A revista</div><div class="${c('azflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('azfim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* Cartao com foto em cima. O `span` da foto tem display:block, senao o
 * aspect-ratio nao aplica. */
function azDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('azdest')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('azfoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
<span class="${c('azkick')}">${H.cat(a)}</span>
<h${n} class="${c('azti')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('azdd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('azdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function azLinha(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('azrow')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('azmini')}"><span data-f>${H.pic(a, false)}</span></span>
<span class="${c('azkick')}">${H.cat(a)}</span>
<h${n} class="${c('azti')}">${H.esc(a.title)}</h${n}>
<span class="${c('azdt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function azHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('azabre')}">
<div><span class="${c('azchap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('azmm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('azfoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // o rail pega os mais recentes que nao entraram na abertura. Nao e "mais
  // lidas" de verdade: o motor nao guarda audiencia, e inventar numero seria
  // mentir para o leitor. O rotulo diz o que e
  const rail = arts.filter(a => !usados.has(a.slug)).slice(0, 8);
  const railHtml = rail.length ? `<aside class="${c('azrail')}">
<div class="${c('azrailh')}">Publicado agora</div>
<ol>${rail.map(a => `<li><a href="${H.url(a)}"><span>${H.esc(a.title)}</span></a></li>`).join('')}</ol>
</aside>` : '';

  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 6)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      return `<section class="${c('azsec')}">
<div class="${c('azcab')}"><h2>${H.esc(nome)}</h2>
<a class="${c('azmais')}" href="${H.curl(cs)}">Ver tudo</a></div>
${azDestaque(ctx, d, idx === 0)}
${resto.length ? `<div class="${c('azlista')}">${resto.slice(0, 4).map(a => azLinha(ctx, a)).join('')}</div>` : ''}
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${azHeader(ctx, menu)}
<main class="${c('azwrap')}">
<div class="${c('azin')}">${H.h1(ctx)}
<div class="${c('azduas')}">
<div>${abertura}${secoes}</div>
${railHtml}
</div></div>
</main>
${azFooter(ctx, menu)}
${H.bodyEnd()}`;
}

function azAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('azass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` descreve a FOTO. Em metade do acervo
 * importado ele e copia do titulo, ou do slug, e ai repetiria o `h1`. */
function azLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const chato = (x) => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const cSlug = chato(art.slug), cAlt = chato(alt);
  const pref = cAlt.length >= 25 && (cSlug.indexOf(cAlt) === 0 || cAlt.indexOf(cSlug) === 0);
  if (!alt || cAlt === chato(t) || cAlt === cSlug || pref) return '';
  return `<p class="${c('azleg')}">${H.esc(alt)}</p>`;
}

/* A linha fina do artigo so aparece quando NAO esta no corpo. A limpeza da
 * importacao tira a frase do proprio texto quando o `excerpt` da origem vem
 * vazio, o que salva o cartao da home; aqui o mesmo campo seria repeticao. */
function azDekVale(art) {
  const d = String(art.dek || '').trim();
  if (!d) return false;
  const nu = (x) => String(x || '').toLowerCase().replace(/<[^>]+>/g, ' ')
    .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const chave = nu(d).slice(0, 60);
  return !!chave && nu(art.content).indexOf(chave) < 0;
}

function azArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  const rel = (related && related.length) ? `<section class="${c('azrel')}">
<h2 class="${c('azrotb')}">Leia também</h2>
<div class="${c('azgrade')}">${related.slice(0, 4).map(a => azDestaque(ctx, a, false)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${azHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('azwrap')}"><div class="${c('azin')}">
<article class="${c('azart')}">
<div class="${c('azcol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('azchap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${azDekVale(art) ? `<p class="${c('azdek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('azhero')}"><span data-f>${H.pic(art, true)}</span></span>
${azLegenda(ctx, art)}` : ''}
<div class="${c('azbody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${azAssinatura(ctx, art)}
${rel}
</div></main>
${azFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function azList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  // a grade pula o destaque, e nao o repete: `resto`, nunca `itens`
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${azHeader(ctx, menu)}
<main class="${c('azwrap')}"><div class="${c('azin')}">
<section class="${c('azsec')}">
<div class="${c('azcab')}"><h1>${H.esc(opts.title)}</h1></div>
${opts.desc ? `<p class="${c('azdescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? azDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('azgrade')}" style="margin-top:32px">${resto.map(a => azDestaque(ctx, a, false, 2)).join('')}</div>` : ''}
</section>
</div></main>
${azFooter(ctx, menu)}
${H.bodyEnd()}`;
}

/*
 * Arquitetura BA, arquetipo CAIXA. Feita para o matogrossosaude.com.br.
 *
 * ## De onde vem o desenho
 *
 * A marca do Mato Grosso Saude e **MATO GROSSO em grotesco preto muito pesado**
 * e, embaixo, **SAUDE em letra vazada de contorno azul**, cada letra desenhada
 * como uma caixa com fio de 2px. Nao ha simbolo nenhum: a palavra e a marca.
 *
 * O gesto que sai dai e a **caixa de fio**: todo cartao mora dentro de um
 * retangulo de contorno, com uma marca quadrada azul no canto de cima. Ao passar
 * o mouse a caixa se preenche de azul e o texto inverte, que e a mesma troca que
 * a marca faz entre a linha preta cheia e a linha azul vazada.
 *
 * ## O que a diferencia das 52 vizinhas da opengravity
 *
 *   - **contorno em todo cartao, sem sombra e sem preenchimento**, e inversao no
 *     hover. As vizinhas usam filete de topo, fundo lavado ou sombra
 *   - **quadrado de canto** no alto de cada caixa, que e a citacao direta da
 *     letra vazada do logotipo
 *   - **preto puro com azul de engenharia**, tirados dos pixels do arquivo. As
 *     paletas escuras vizinhas sao marinho ou chumbo, nunca preto
 *   - **Anybody e Overpass**: nenhuma das duas esta nas 86 familias em uso
 *
 * ## A armadilha desta arquitetura, dita por extenso
 *
 * 🔴 **Este portal responde no `www`, e nao no apex.** O `siteurl` da origem e
 * `https://www.matogrossosaude.com.br`, e cada backlink e cada URL indexada
 * aponta para essa forma. Trocar para o apex invalida tudo: o `baseUrl` do
 * `sites.json` tem que trazer o `www`, e quem redireciona e o apex, ao contrario
 * de todos os outros portais da rede.
 *
 * 🔴 **O acervo deste portal e pequeno e foi RECUPERADO de backup.** As paginas
 * que ranqueavam tinham sido apagadas na origem e respondiam 404; voltaram do
 * dump de 23/04/2026. A home nunca tera muitas secoes, entao a arquitetura
 * precisa ficar boa com uma so, e nao contar com faixa atras de faixa.
 *
 * ⚠️ **Inversao no hover exige contraste nos DOIS estados.** O azul de fundo com
 * texto branco e o branco com texto preto passam; azul com preto, que seria o
 * meio-termo preguicoso, nao passa.
 *
 * ## O que o checklist exige e esta aqui
 *
 *   - link de editoria por `H.curl(slug)` e de artigo por `H.url(a)`
 *   - menu sanfonado abaixo de 1100px, com aria-expanded, aria-controls e
 *     rotulo que muda ao abrir
 *   - todo `span` com aspect-ratio tem `display:block`, e o `a` do cartao tem
 *     `display`
 *   - body aberto no cabecalho e `H.bodyEnd()` nos tres caminhos de pagina
 *   - nada centralizado alem da marca
 *   - lista de editoria abre em h1, e o cartao dela sobe para h2
 *   - a grade da listagem pula o destaque, e nao o repete
 *   - bloco de relacionados com a mesma largura da coluna do artigo
 *   - tabela vira cartao abaixo de 640px, com rotulo de coluna
 *   - a legenda da imagem so aparece quando o `alt` descreve a foto
 *   - as variaveis de cor vao no `:root`, e o respiro usa `padding-block`
 */

function baCss(ctx) {
  const { s, fp, site } = ctx;
  const t = site.theme || {};
  const wash = t.accent2 || '#F1F5F9';
  const viva = t.vivid || '#00549C';
  const canto = fp.radius === 'sharp' ? '0' : '2px';
  return `
:root{--pri:${t.primary};--ink:${t.ink};--paper:${t.paper};--surf:${t.surface};
  --ph:${t.ph};--dek:${t.dek};--muted:${t.muted};--line:${t.line};--wash:${wash};
  --viva:${viva};--tinta:${t.tinta || t.primary};--sob:${t.onPrimary || '#fff'};
  --footer-bg:${t.footerBg || '#0B0B0B'};--footer-tx:${t.footerTx || '#C6CDD4'};
  --fd:${t.fontDisplay};--fb:${t.fontBody}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--fb)}

${s('bawrap')}{background:var(--paper);color:var(--ink);font-family:var(--fb);
  font-size:${fp.baseFs || '17px'};line-height:1.68;-webkit-font-smoothing:antialiased}
${s('bawrap')} *{box-sizing:border-box}
${s('bain')}{max-width:${fp.container || '1130px'};margin:0 auto;padding:0 24px;width:100%}
${s('bawrap')} h1,${s('bawrap')} h2,${s('bawrap')} h3,${s('bawrap')} h4{font-family:var(--fd);
  font-weight:800;letter-spacing:-.026em;line-height:1.1;margin:0}
${s('bawrap')} a{color:inherit;text-decoration:none}
${s('bawrap')} img{max-width:100%;height:auto;display:block}

/* ---------- cabecalho ---------- */
${s('batop')}{background:var(--paper);border-bottom:2px solid var(--ink)}
${s('babar')}{display:flex;align-items:center;gap:18px;padding-block:16px 18px;flex-wrap:wrap}
${s('bamarca')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:900;font-size:clamp(20px,2.7vw,29px);letter-spacing:-.042em;
  color:var(--ink);flex:none}
${s('bamarca')} svg{display:block;height:1em;width:auto;flex:none;align-self:center}
/* imagem sem medida derruba o CLS: a altura manda, a largura sai da proporcao */
${s('bamarca')} img{display:block;height:44px;width:auto;flex:none}
@media(max-width:560px){${s('bamarca')} img{height:34px}}
${s('bafb')} img{display:block;height:40px;width:auto}
${s('banav')}{display:flex;gap:16px;align-items:center;flex-wrap:wrap;flex:1 1 auto;
  min-width:0;justify-content:flex-end}
${s('banav')} a{font-family:var(--fb);font-size:12.5px;font-weight:600;letter-spacing:.05em;color:var(--dek);transition:color .2s ease}
${s('banav')} a:hover{color:var(--viva)}
${s('babusca')}{display:inline-flex;align-items:center;gap:7px;font-family:var(--fb);
  font-size:11.5px;font-weight:700;letter-spacing:.06em;
  border:2px solid var(--ink);color:var(--ink);padding:8px 15px;border-radius:${canto};
  flex:none;margin-left:6px;transition:background .2s ease,color .2s ease}
${s('babusca')}:hover{background:var(--viva);border-color:var(--viva);color:#fff}
${s('baham')}{display:none;width:46px;height:46px;border:2px solid var(--ink);background:none;
  cursor:pointer;padding:0;position:relative;border-radius:${canto}}
${s('baham')} i,${s('baham')} i::before,${s('baham')} i::after{position:absolute;left:12px;
  width:20px;height:2px;background:var(--ink);content:""}
${s('baham')} i{top:21px}
${s('baham')} i::before{top:-6px;left:0}
${s('baham')} i::after{top:6px;left:0}
@media(max-width:560px){${s('bamarca')}{font-size:18.5px;gap:8px}${s('babar')}{gap:11px}
  ${s('babusca')}{font-size:10.5px;padding:8px 12px;gap:6px}}
@media(max-width:1100px){
  ${s('baham')}{display:block;order:2}
  ${s('babusca')}{order:3;margin-left:0}
  ${s('banav')}{order:4;flex-basis:100%;display:none;flex-direction:column;align-items:flex-start;
    gap:0;border-top:1px solid var(--line);margin-top:14px}
  ${s('banav')}[data-aberto="1"]{display:flex}
  ${s('banav')} a{width:100%;padding:13px 0;border-bottom:1px solid var(--line);color:var(--ink);
    font-size:13.5px}
}

/* ---------- abertura: texto a esquerda, imagem a direita ---------- */
${s('baabre')}{display:grid;grid-template-columns:1.06fr 1fr;gap:42px;align-items:center;
  padding-block:38px 34px;border-bottom:2px solid var(--ink)}
${s('baabre')} h2{font-size:clamp(30px,4.4vw,52px);line-height:1.02;margin:14px 0 0;
  letter-spacing:-.044em;}
${s('baabre')} h2 a:hover{color:var(--viva)}
${s('baabre')} p{font-size:17.5px;line-height:1.6;color:var(--dek);margin:16px 0 0;
  max-width:48ch;text-align:left}
${s('bamm')}{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:18px;
  font-family:var(--fb);font-size:12.5px;color:var(--muted)}
${s('bamm')} b{color:var(--ink);font-weight:700}
${s('bachap')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:.14em;color:var(--viva);border:2px solid var(--viva);
  padding:5px 12px;border-radius:${canto}}
${s('bachap')} a{color:var(--viva)}
@media(max-width:820px){${s('baabre')}{grid-template-columns:1fr;gap:22px;padding-block:26px 24px}}

/* ---------- secao ---------- */
${s('basec')}{padding-block:40px}
${s('bacab')}{display:flex;align-items:center;gap:16px;margin-bottom:24px;flex-wrap:wrap}
${s('bacab')} h1,${s('bacab')} h2{font-family:var(--fd);font-weight:900;
  font-size:clamp(19px,2.2vw,26px);letter-spacing:-.034em;
  color:var(--ink);margin:0;line-height:1.05;flex:none;border:2px solid var(--ink);
  padding:8px 16px;border-radius:${canto}}
${s('bafio')}{flex:1 1 60px;height:2px;background:var(--ink);min-width:30px}
${s('bamais')}{font-family:var(--fb);font-size:11.5px;font-weight:700;letter-spacing:.09em;color:var(--viva);flex:none;border-bottom:2px solid var(--viva);
  padding-bottom:3px}
${s('bamais')}:hover{color:var(--ink);border-bottom-color:var(--ink)}
${s('badescr')}{margin:0 0 26px;font-size:15.5px;line-height:1.64;color:var(--dek);
  max-width:72ch;text-align:left}

/* a CAIXA: contorno, quadrado azul no canto, e inversao no hover. O contraste
   passa nos dois estados: branco sobre azul e preto sobre branco */
${s('bacx')}{display:block;position:relative;border:2px solid var(--ink);border-radius:${canto};
  padding:16px 18px 18px;background:var(--paper);transition:background .22s ease,
  border-color .22s ease}
${s('bacx')}::before{content:"";position:absolute;top:-2px;left:22px;width:16px;height:7px;
  background:var(--viva)}
${s('bacx')}:hover{background:var(--viva);border-color:var(--viva)}
${s('bacx')}:hover ${s('bati')},${s('bacx')}:hover ${s('badd')},
${s('bacx')}:hover ${s('badt')},${s('bacx')}:hover ${s('bakick')}{color:#fff}
${s('bacx')}:hover::before{background:#fff}

${s('badest')}{display:grid;grid-template-columns:1fr 1.04fr;gap:26px;align-items:center}
${s('badest')} ${s('bati')}{font-size:clamp(21px,2.6vw,31px);line-height:1.06;margin-top:11px;
  letter-spacing:-.04em;}
${s('bakick')}{display:inline-block;font-family:var(--fb);font-size:10.5px;font-weight:700;
  letter-spacing:${fp.kickerLs || '.14em'};color:var(--viva);
  transition:color .22s ease}
${s('bati')}{display:block;font-family:var(--fd);font-weight:800;font-size:19px;line-height:1.14;
  color:var(--ink);margin:0;transition:color .22s ease;letter-spacing:-.03em}
${s('badd')}{display:block;margin:11px 0 0;font-size:15.5px;line-height:1.6;color:var(--dek);
  max-width:56ch;text-align:left;transition:color .22s ease}
${s('badt')}{display:block;margin-top:9px;font-family:var(--fb);font-size:11.5px;
  color:var(--muted);transition:color .22s ease}
${s('bafoto')}{display:block;overflow:hidden;background:var(--ph);border-radius:${canto}}
${s('bafoto')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('bafoto')} [data-f] img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
${s('badest')}:hover ${s('bafoto')} [data-f] img{transform:scale(1.04)}
@media(max-width:780px){${s('badest')}{grid-template-columns:1fr;gap:16px}
  ${s('badest')} ${s('bafoto')}{order:-1}}

/* a grade da secao: tres caixas por linha */
${s('bagrade')}{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:26px}
${s('bagrade')} ${s('bamini')}{display:block;overflow:hidden;background:var(--ph);
  margin-bottom:12px;border-radius:${canto}}
${s('bagrade')} ${s('bamini')} [data-f]{display:block;aspect-ratio:${fp.cardAr || '16/9'};
  overflow:hidden}
${s('bagrade')} ${s('bamini')} [data-f] img{width:100%;height:100%;object-fit:cover;
  transition:transform .5s ease}
${s('bagrade')} ${s('bacx')}:hover ${s('bamini')} [data-f] img{transform:scale(1.05)}
${s('bagrade')} ${s('bati')}{font-size:18px;line-height:1.16;margin-top:7px}
${s('bagrade')} ${s('badd')}{display:none}
@media(max-width:900px){${s('bagrade')}{grid-template-columns:1fr 1fr}}
@media(max-width:600px){${s('bagrade')}{grid-template-columns:1fr;gap:20px}}

/* ---------- artigo ---------- */
${s('baart')}{padding-block:30px 12px}
${s('bacol')}{max-width:70ch}
${s('baart')} h1{font-size:clamp(28px,4.1vw,45px);line-height:1.04;letter-spacing:-.044em;
  margin:14px 0 0;}
${s('badek')}{font-size:19px;line-height:1.55;color:var(--dek);margin:16px 0 0;max-width:62ch}
${s('bahero')}{display:block;overflow:hidden;background:var(--ph);border:2px solid var(--ink);
  border-radius:${canto};margin-top:26px}
${s('bahero')} [data-f]{display:block;aspect-ratio:${fp.heroAr || '16/9'};overflow:hidden}
${s('bahero')} [data-f] img{width:100%;height:100%;object-fit:cover}
${s('baleg')}{margin:10px 0 0;font-size:12.5px;line-height:1.5;color:var(--muted);
  max-width:70ch;text-align:left}
${s('babody')}{max-width:70ch;margin-top:26px;font-size:${fp.corpoFs || '18px'};line-height:1.78}
${s('babody')} p{margin:0 0 21px}
${s('babody')} a{color:var(--viva);text-decoration:underline;text-underline-offset:3px}
${s('babody')} a:hover{color:var(--ink)}
${s('babody')} h2{font-family:var(--fd);font-weight:900;font-size:25px;letter-spacing:-.036em;margin:36px 0 12px;padding-bottom:8px;border-bottom:2px solid var(--ink)}
${s('babody')} h3{font-family:var(--fd);font-weight:800;font-size:20px;margin:28px 0 10px;
  letter-spacing:-.028em}
${s('babody')} ul,${s('babody')} ol{margin:0 0 21px;padding-left:22px}
${s('babody')} li{margin:0 0 9px}
${s('babody')} img{max-width:100%;height:auto;border-radius:${canto};margin:8px 0}
${s('babody')} figure{margin:22px 0}
${s('babody')} figcaption{font-size:12.5px;color:var(--muted);margin-top:8px}
${s('babody')} blockquote{margin:28px 0;padding:18px 20px;border:2px solid var(--ink);
  border-radius:${canto};font-family:var(--fd);font-size:20px;line-height:1.36;
  letter-spacing:-.024em}
${s('babody')} table{width:100%;border-collapse:collapse;margin:0 0 24px;font-size:14.5px}
${s('babody')} th,${s('babody')} td{border:0;border-bottom:1px solid var(--line);
  padding:11px 12px 11px 0;text-align:left;vertical-align:top}
${s('babody')} th{font-family:var(--fb);font-weight:700;background:transparent}
${s('babody')} caption{text-align:left;font-size:13px;color:var(--muted);padding-bottom:8px}

/* a tabela vira cartao no celular: sem isto ela sai da tela e o gesto de
   arrastar nao e descoberto. O thead sai da tela mas continua no DOM */
@media(max-width:640px){
  ${s('babody')} .tabwrap{overflow:visible;border:0;background:transparent}
  ${s('babody')} table{min-width:0;display:block;width:auto;overflow:visible}
  ${s('babody')} table caption{display:none}
  ${s('babody')} table thead{position:absolute;width:1px;height:1px;overflow:hidden;
    clip:rect(0 0 0 0)}
  ${s('babody')} table tbody,${s('babody')} table tr,
  ${s('babody')} table th,${s('babody')} table td{display:block;width:auto}
  ${s('babody')} table tbody tr{background:var(--paper);border:2px solid var(--ink);
    border-radius:${canto};padding:2px 18px 16px;margin-bottom:13px}
  /* zerar borda e fundo herdados, senao sobra risco cortando o cartao */
  ${s('babody')} table tbody th,${s('babody')} table tbody td{border:0;background:transparent;
    padding:0}
  ${s('babody')} table tbody th{border-bottom:1px solid var(--line);padding:14px 0 12px;
    font-weight:700;text-align:left}
  ${s('babody')} table tbody td{padding:13px 0 0;text-align:left;line-height:1.55}
  ${s('babody')} table tbody td::before{content:attr(data-rotulo);display:block;font-weight:600;
    font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);
    margin-bottom:2px}
}

${s('baass')}{display:grid;grid-template-columns:84px minmax(0,1fr);gap:18px;align-items:start;
  max-width:70ch;margin-top:38px;padding:20px;border:2px solid var(--ink);border-radius:${canto}}
${s('baass')} img{border-radius:${canto}}
${s('baass')} .ed{font-family:var(--fb);font-size:10.5px;font-weight:700;letter-spacing:.12em;color:var(--viva)}
${s('baass')} .nm{display:block;font-family:var(--fd);font-weight:800;font-size:19px;
  margin-top:4px;letter-spacing:-.028em}
${s('baass')} p{margin:8px 0 0;font-size:14.5px;line-height:1.6;color:var(--dek)}
${s('baass')} .go{display:inline-block;margin-top:10px;font-family:var(--fb);font-size:11.5px;
  font-weight:700;letter-spacing:.08em;color:var(--viva);
  border-bottom:2px solid var(--viva);padding-bottom:2px}
@media(max-width:560px){${s('baass')}{grid-template-columns:1fr;gap:12px}}

/* relacionados com a MESMA largura da coluna do artigo */
${s('barel')}{max-width:70ch;margin-top:44px;padding-top:22px;border-top:2px solid var(--ink)}
${s('barotb')}{display:inline-block;font-family:var(--fd);font-weight:900;font-size:19px;
  letter-spacing:-.034em;color:var(--ink);border:2px solid var(--ink);
  padding:7px 14px;border-radius:${canto};margin-bottom:20px}
${s('barel')} ${s('bagrade')}{grid-template-columns:1fr 1fr;gap:20px;margin-top:0}
@media(max-width:600px){${s('barel')} ${s('bagrade')}{grid-template-columns:1fr}}

/* ---------- rodape ---------- */
${s('bafoot')}{background:var(--footer-bg);color:var(--footer-tx);margin-top:56px;
  padding-block:38px 22px}
${s('bacols')}{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:34px}
${s('bafoot')} p{font-size:14.5px;color:var(--footer-tx)}
${s('bafb')}{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);
  font-weight:900;font-size:22px;letter-spacing:-.042em;color:#fff}
${s('bafh')}{font-family:var(--fb);font-size:11px;font-weight:700;letter-spacing:.14em;color:#fff;margin-bottom:12px}
${s('baflist')} a{display:block;font-size:14.5px;padding:4px 0;color:var(--footer-tx)}
${s('baflist')} a:hover{color:#fff}
${s('bafim')}{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;
  margin-top:28px;padding-top:15px;border-top:1px solid rgba(255,255,255,.18);
  font-size:12.5px;opacity:.85}
@media(max-width:820px){${s('bacols')}{grid-template-columns:1fr;gap:26px}}

${s('reveal')}{opacity:1}
@media(prefers-reduced-motion:reduce){
  ${s('bawrap')} *{transition:none !important;animation:none !important}
}`;
}

/* A marca nao tem simbolo: a palavra E a marca. Quando falta o arquivo, entra
 * uma caixa vazada, que e a citacao da letra de contorno do logotipo. */
const BA_SIMB = `<svg viewBox="0 0 26 26" width="26" height="26" aria-hidden="true">
<rect x="1.5" y="1.5" width="23" height="23" fill="none" stroke="var(--marca-1,#00549C)"
  stroke-width="3"/>
<rect x="8" y="8" width="10" height="10" fill="var(--marca-2,#111111)"/>
</svg>`;

const BA_LUPA = `<svg viewBox="0 0 20 20" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="9" r="6"/><path d="m13.5 13.5 4 4" stroke-linecap="round"/></svg>`;

function baHeader(ctx, menu) {
  const { site, c, H } = ctx;
  const idMenu = 'banav-' + (site.slug || 'p');
  // a listagem deste portal mora em /categoria/<slug>/, em portugues. Quem monta
  // o caminho e o H.curl, nunca uma string escrita a mao
  const links = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<body>
<header class="${c('batop')}">
<div class="${c('bain')} ${c('babar')}">
<a class="${c('bamarca')}" href="/" aria-label="${H.esc(site.name)}, página inicial"
  style="--marca-1:var(--viva);--marca-2:var(--ink)">${site.logoImg
    ? `<img src="${site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" fetchpriority="high">`
    : `${BA_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
<nav class="${c('banav')}" id="${idMenu}" data-aberto="0" aria-label="Editorias">${links}</nav>
<button class="${c('baham')}" type="button" data-baham aria-expanded="false"
  aria-controls="${idMenu}" aria-label="Abrir o menu de editorias"><i></i></button>
<a class="${c('babusca')}" href="/busca/">${BA_LUPA}Buscar</a>
</div></header>
<script>(function(){var b=document.querySelector('[data-baham]'),n=document.getElementById('${idMenu}');
if(!b||!n)return;b.addEventListener('click',function(){var a=b.getAttribute('aria-expanded')==='true';
b.setAttribute('aria-expanded',a?'false':'true');n.setAttribute('data-aberto',a?'0':'1');
b.setAttribute('aria-label',a?'Abrir o menu de editorias':'Fechar o menu de editorias')})})();</script>`;
}

function baFooter(ctx, menu) {
  const { site, c, H } = ctx;
  const cats = (menu || []).map(x =>
    `<a href="${H.curl(x.slug)}">${H.esc(x.name)}</a>`).join('');
  return `<footer class="${c('bafoot')}"><div class="${c('bain')}">
<div class="${c('bacols')}">
  <div><a class="${c('bafb')}" href="/" aria-label="${H.esc(site.name)}"
      style="--marca-1:#4C9BE0;--marca-2:#FFFFFF">${(site.logoImgDark || site.logoImg)
        ? `<img src="${site.logoImgDark || site.logoImg}" alt="${H.esc(site.name)}" width="${site.logoW}" height="${site.logoH}" loading="lazy">`
        : `${BA_SIMB}<span>${H.esc(site.shortName || site.name)}</span>`}</a>
    <p style="margin:15px 0 0;max-width:42ch;line-height:1.62">${H.esc(site.description || '')}</p></div>
  <div><div class="${c('bafh')}">Editorias</div><div class="${c('baflist')}">${cats}</div></div>
  <div><div class="${c('bafh')}">O portal</div><div class="${c('baflist')}">${H.instLinks()}</div></div>
</div>
<div class="${c('bafim')}"><span>&copy; ${new Date().getFullYear()} ${H.esc(site.name)}</span>
<span>${H.esc(site.tagline || '')}</span></div>
</div></footer>`;
}

/* Caixa de abertura da secao: texto a esquerda, foto a direita. */
function baDestaque(ctx, a, eager, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('bacx')} ${c('badest')} ${c('reveal')}" href="${H.url(a)}">
<span><span class="${c('bakick')}">${H.cat(a)}</span>
<h${n} class="${c('bati')}">${H.esc(a.title)}</h${n}>
${a.dek ? `<span class="${c('badd')}">${H.esc(H.clip(a.dek, 180))}</span>` : ''}
<span class="${c('badt')}">${H.esc(H.dateShort(a.date))}</span></span>
<span class="${c('bafoto')}"><span data-f>${H.pic(a, !!eager)}</span></span>
</a>`;
}

/* Caixa pequena da grade: foto em cima, texto embaixo. */
function baCartao(ctx, a, nivel) {
  const { c, H } = ctx;
  const n = nivel || 3;
  return `<a class="${c('bacx')} ${c('reveal')}" href="${H.url(a)}">
<span class="${c('bamini')}"><span data-f>${H.pic(a, false)}</span></span>
<span class="${c('bakick')}">${H.cat(a)}</span>
<h${n} class="${c('bati')}">${H.esc(a.title)}</h${n}>
<span class="${c('badt')}">${H.esc(H.dateShort(a.date))}</span>
</a>`;
}

function baHome(ctx, arts, menu) {
  const { site, c, H } = ctx;
  const meta = H.homeMeta(site);
  const [abre] = arts;
  const usados = new Set([abre].filter(Boolean).map(a => a.slug));

  const abertura = abre ? `<section class="${c('baabre')}">
<div><span class="${c('bachap')}">${H.cat(abre)}</span>
<h2><a href="${H.url(abre)}">${H.esc(abre.title)}</a></h2>
${abre.dek ? `<p>${H.esc(H.clip(abre.dek, 215))}</p>` : ''}
<div class="${c('bamm')}">${abre.author ? `<b>${H.esc(abre.author)}</b><span>&middot;</span>` : ''}
<time datetime="${H.esc(abre.date)}">${H.esc(H.dateShort(abre.date))}</time></div></div>
<a href="${H.url(abre)}" aria-label="${H.esc(abre.title)}"><span class="${c('bafoto')}">
<span data-f>${H.pic(abre, true)}</span></span></a>
</section>` : '';

  // secoes por editoria de verdade, ordenadas por data. O acervo aqui e pequeno,
  // entao uma secao so ja precisa ficar boa
  const porCat = new Map();
  for (const a of arts) {
    if (usados.has(a.slug)) continue;
    const k = a.category ? a.category.slug : 'noticias';
    if (!porCat.has(k)) porCat.set(k, []);
    porCat.get(k).push(a);
  }

  const secoes = [...porCat.entries()]
    .filter(([, v]) => v.length >= 2)
    .slice(0, 6)
    .map(([cs, v], idx) => {
      const nome = v[0].category ? v[0].category.name : cs;
      const [d, ...resto] = v;
      return `<section class="${c('basec')}">
<div class="${c('bacab')}"><h2>${H.esc(nome)}</h2><span class="${c('bafio')}"></span>
<a class="${c('bamais')}" href="${H.curl(cs)}">Ver tudo</a></div>
${baDestaque(ctx, d, idx === 0)}
${resto.length ? `<div class="${c('bagrade')}">${resto.slice(0, 6).map(a => baCartao(ctx, a)).join('')}</div>` : ''}
</section>`;
    }).join('');

  return `${H.head(ctx, meta)}
${baHeader(ctx, menu)}
<main class="${c('bawrap')}"><div class="${c('bain')}">${H.h1(ctx)}
${abertura}
${secoes}
</div></main>
${baFooter(ctx, menu)}
${H.bodyEnd()}`;
}

function baAssinatura(ctx, art) {
  const { site, c, H } = ctx;
  const nome = (art.author || '').trim();
  if (!nome) return '';
  const e = (site.equipe || []).find(x => x.nome === nome);
  if (!e) return '';
  return `<aside class="${c('baass')}">
<img src="/img/autores/${H.esc(e.slug)}.webp" alt="Ilustração de ${H.esc(e.nome)}"
  width="84" height="84" loading="lazy" decoding="async">
<div>${e.editoria ? `<div class="ed">${H.esc(e.editoria)}</div>` : ''}
<span class="nm">${H.esc(e.nome)}</span>
${e.lead ? `<p>${H.esc(e.lead)}</p>` : ''}
<a class="go" href="/autor/${H.esc(e.slug)}/">Ver tudo de ${H.esc(e.nome.split(' ')[0])}</a></div>
</aside>`;
}

/* A legenda so aparece quando o `alt` descreve a FOTO. Em metade do acervo
 * importado ele e copia do titulo, ou do slug, e ai repetiria o `h1`. */
function baLegenda(ctx, art) {
  const { c, H } = ctx;
  const alt = (art.image && art.image.alt ? String(art.image.alt) : '').trim();
  const t = String(art.title || '').trim();
  const chato = (x) => String(x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const cSlug = chato(art.slug), cAlt = chato(alt);
  const pref = cAlt.length >= 25 && (cSlug.indexOf(cAlt) === 0 || cAlt.indexOf(cSlug) === 0);
  if (!alt || cAlt === chato(t) || cAlt === cSlug || pref) return '';
  return `<p class="${c('baleg')}">${H.esc(alt)}</p>`;
}

/* A linha fina do artigo so aparece quando NAO esta no corpo. A limpeza da
 * importacao tira a frase do proprio texto quando o `excerpt` da origem vem
 * vazio, o que salva o cartao da home; aqui o mesmo campo seria repeticao. */
function baDekVale(art) {
  const d = String(art.dek || '').trim();
  if (!d) return false;
  const nu = (x) => String(x || '').toLowerCase().replace(/<[^>]+>/g, ' ')
    .replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const chave = nu(d).slice(0, 60);
  return !!chave && nu(art.content).indexOf(chave) < 0;
}

function baArticle(ctx, art, menu, related, P) {
  const { c, H } = ctx;
  const rel = (related && related.length) ? `<section class="${c('barel')}">
<h2 class="${c('barotb')}">Leia também</h2>
<div class="${c('bagrade')}">${related.slice(0, 4).map(a => baCartao(ctx, a)).join('')}</div>
</section>` : '';
  return `${H.head(ctx, H.artMeta(ctx, art, P))}
${baHeader(ctx, menu)}
${H.progressBar(ctx)}
<main class="${c('bawrap')}"><div class="${c('bain')}">
<article class="${c('baart')}">
<div class="${c('bacol')}">
${H.crumbs(ctx, art, P)}
<span class="${c('bachap')}"><a href="${H.curl(P.catSlug)}">${H.esc(P.catName)}</a></span>
<h1>${H.esc(art.title)}</h1>
${baDekVale(art) ? `<p class="${c('badek')}">${H.esc(art.dek)}</p>` : ''}
${H.metaRow(ctx, art, P)}
</div>
${P.imgUrl ? `<span class="${c('bahero')}"><span data-f>${H.pic(art, true)}</span></span>
${baLegenda(ctx, art)}` : ''}
<div class="${c('babody')}">${art.content}</div>
${H.share(ctx, P)}
</article>
${baAssinatura(ctx, art)}
${rel}
</div></main>
${baFooter(ctx, menu)}
${H.progressScript(ctx)}
${H.bodyEnd()}`;
}

function baList(ctx, opts) {
  const { c, H } = ctx;
  const menu = ctx.menu || opts.menu;
  const meta = H.listMeta(ctx, opts);
  const itens = opts.items || [];
  // a grade pula o destaque, e nao o repete: `resto`, nunca `itens`
  const [primeiro, ...resto] = itens;
  return `${H.head(ctx, meta)}
${baHeader(ctx, menu)}
<main class="${c('bawrap')}"><div class="${c('bain')}">
<section class="${c('basec')}">
<div class="${c('bacab')}"><h1>${H.esc(opts.title)}</h1><span class="${c('bafio')}"></span></div>
${opts.desc ? `<p class="${c('badescr')}">${H.esc(opts.desc)}</p>` : ''}
${primeiro ? baDestaque(ctx, primeiro, true, 2) : ''}
${resto.length ? `<div class="${c('bagrade')}">${resto.map(a => baCartao(ctx, a, 2)).join('')}</div>` : ''}
</section>
</div></main>
${baFooter(ctx, menu)}
${H.bodyEnd()}`;
}

